(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("thucydides-4-e", [{"sp": "HDR", "t": "Ἱστορίαι (Ζʹ–Ηʹ)"}, {"sp": "HDR", "t": "Βιβλίον Ζʹ", "st": "7"}, {"sp": "N", "t": "ὁ δὲ Γύλιππος καὶ ὁ Πυθὴν ἐκ τοῦ Τάραντος, ἐπεὶ ἐπεσκεύασαν τὰς ναῦς, παρέπλευσαν ἐς Λοκροὺς τοὺς Ἐπιζεφυρίους· καὶ πυνθανόμενοι σαφέστερον ἤδη ὅτι οὐ παντελῶς πω ἀποτετειχισμέναι αἱ Συράκουσαί εἰσιν, ἀλλ’ ἔτι οἷόν τε κατὰ τὰς Ἐπιπολὰς στρατιᾷ ἀφικομένους ἐσελθεῖν, ἐβουλεύοντο εἴτ’ ἐν δεξιᾷ λαβόντες τὴν Σικελίαν διακινδυνεύσωσιν ἐσπλεῦσαι, εἴτ’ ἐν ἀριστερᾷ ἐς Ἱμέραν πρῶτον πλεύσαντες καὶ αὐτούς τε ἐκείνους καὶ στρατιὰν ἄλλην προσλαβόντες, οὓς ἂν πείθωσι, κατὰ γῆν ἔλθωσιν. καὶ ἔδοξεν αὐτοῖς ἐπὶ τῆς Ἱμέρας πλεῖν, ἄλλως τε καὶ τῶν Ἀττικῶν τεσσάρων νεῶν οὔπω παρουσῶν ἐν τῷ Ῥηγίῳ, ἃς ὁ Νικίας ὅμως πυνθανόμενος αὐτοὺς ἐν Λοκροῖς εἶναι ἀπέστειλεν. φθάσαντες δὲ τὴν φυλακὴν ταύτην περαιοῦνται διὰ τοῦ πορθμοῦ, καὶ σχόντες Ῥηγίῳ καὶ Μεσσήνῃ ἀφικνοῦνται ἐς Ἱμέραν. ἐκεῖ δὲ ὄντες τούς τε Ἱμεραίους ἔπεισαν ξυμπολεμεῖν καὶ αὐτούς τε ἕπεσθαι καὶ τοῖς ἐκ τῶν νεῶν τῶν σφετέρων ναύταις ὅσοι μὴ εἶχον ὅπλα παρασχεῖν (τὰς γὰρ ναῦς ἀνείλκυσαν ἐν Ἱμέρᾳ), καὶ τοὺς Σελινουντίους πέμψαντες ἐκέλευον ἀπαντᾶν πανστρατιᾷ ἔς τι χωρίον. πέμψειν δέ τινα αὐτοῖς ὑπέσχοντο στρατιὰν οὐ πολλὴν καὶ οἱ Γελῷοι καὶ τῶν Σικελῶν τινές, οἳ πολὺ προθυμότερον προσχωρεῖν ἑτοῖμοι ἦσαν τοῦ τε Ἀρχωνίδου νεωστὶ τεθνηκότος, ὃς τῶν ταύτῃ Σικελῶν βασιλεύων τινῶν καὶ ὢν οὐκ ἀδύνατος τοῖς Ἀθηναίοις φίλος ἦν, καὶ τοῦ Γυλίππου ἐκ Λακεδαίμονος προθύμως δοκοῦντος ἥκειν. καὶ ὁ μὲν Γύλιππος ἀναλαβὼν τῶν τε σφετέρων ναυτῶν καὶ ἐπιβατῶν τοὺς ὡπλισμένους ἑπτακοσίους μάλιστα, Ἱμεραίους δὲ ὁπλίτας καὶ ψιλοὺς ξυναμφοτέρους χιλίους καὶ ἱππέας ἑκατὸν καὶ Σελινουντίων τέ τινας ψιλοὺς καὶ ἱππέας καὶ Γελῴων ὀλίγους, Σικελῶν τε ἐς χιλίους τοὺς πάντας, ἐχώρει πρὸς τὰς Συρακούσας·", "st": "7.1"}, {"sp": "N", "t": "οἱ δ’ ἐκ τῆς Λευκάδος Κορίνθιοι ταῖς τε ἄλλαις ναυσὶν ὡς εἶχον τάχους ἐβοήθουν καὶ Γογγύλος, εἷς τῶν Κορινθίων ἀρχόντων, μιᾷ νηὶ τελευταῖος ὁρμηθεὶς πρῶτος μὲν ἀφικνεῖται ἐς τὰς Συρακούσας, ὀλίγον δὲ πρὸ Γυλίππου, καὶ καταλαβὼν αὐτοὺς περὶ ἀπαλλαγῆς τοῦ πολέμου μέλλοντας ἐκκλησιάσειν διεκώλυσέ τε καὶ παρεθάρσυνε, λέγων ὅτι νῆές τε ἄλλαι ἔτι προσπλέουσι καὶ Γύλιππος ὁ Κλεανδρίδου Λακεδαιμονίων ἀποστειλάντων ἄρχων. καὶ οἱ μὲν Συρακόσιοι ἐπερρώσθησάν τε καὶ τῷ Γυλίππῳ εὐθὺς πανστρατιᾷ ὡς ἀπαντησόμενοι ἐξῆλθον· ἤδη γὰρ καὶ ἐγγὺς ὄντα ᾐσθάνοντο αὐτόν. ὁ δὲ Ἰέτας τότε τι τεῖχος ἐν τῇ παρόδῳ τῶν Σικελῶν ἑλὼν καὶ ξυνταξάμενος ὡς ἐς μάχην ἀφικνεῖται ἐς τὰς Ἐπιπολάς· καὶ ἀναβὰς κατὰ τὸν Εὐρύηλον, ᾗπερ καὶ οἱ Ἀθηναῖοι τὸ πρῶτον, ἐχώρει μετὰ τῶν Συρακοσίων ἐπὶ τὸ τείχισμα τῶν Ἀθηναίων. ἔτυχε δὲ κατὰ τοῦτο τοῦ καιροῦ ἐλθὼν ἐν ᾧ ἑπτὰ μὲν ἢ ὀκτὼ σταδίων ἤδη ἀπετετέλεστο τοῖς Ἀθηναίοις ἐς τὸν μέγαν λιμένα διπλοῦν τεῖχος, πλὴν κατὰ βραχύ τι τὸ πρὸς τὴν θάλασσαν (τοῦτο δ’ ἔτι ᾠκοδόμουν), τῷ δὲ ἄλλῳ τοῦ κύκλου πρὸς τὸν Τρωγίλον ἐπὶ τὴν ἑτέραν θάλασσαν λίθοι τε παραβεβλημένοι τῷ πλέονι ἤδη ἦσαν, καὶ ἔστιν ἃ καὶ ἡμίεργα, τὰ δὲ καὶ ἐξειργασμένα κατελέλειπτο. παρὰ τοσοῦτον μὲν αἱ Συράκουσαι ἦλθον κινδύνου.", "st": "7.2"}, {"sp": "N", "t": "οἱ δὲ Ἀθηναῖοι αἰφνιδίως τοῦ τε Γυλίππου καὶ τῶν Συρακοσίων σφίσιν ἐπιόντων ἐθορυβήθησαν μὲν τὸ πρῶτον, παρετάξαντο δέ. ὁ δὲ θέμενος τὰ ὅπλα ἐγγὺς κήρυκα προσπέμπει αὐτοῖς λέγοντα, εἰ βούλονται ἐξιέναι ἐκ τῆς Σικελίας πέντε ἡμερῶν λαβόντες τὰ σφέτερα αὐτῶν, ἑτοῖμος εἶναι σπένδεσθαι. οἱ δ’ ἐν ὀλιγωρίᾳ τε ἐποιοῦντο καὶ οὐδὲν ἀποκρινάμενοι ἀπέπεμψαν. καὶ μετὰ τοῦτο ἀντιπαρεσκευάζοντο ἀλλήλοις ὡς ἐς μάχην. καὶ ὁ Γύλιππος ὁρῶν τοὺς Συρακοσίους ταρασσομένους καὶ οὐ ῥᾳδίως ξυντασσομένους, ἐπανῆγε τὸ στρατόπεδον ἐς τὴν εὐρυχωρίαν μᾶλλον. καὶ ὁ Νικίας οὐκ ἐπῆγε τοὺς Ἀθηναίους, ἀλλ’ ἡσύχαζε πρὸς τῷ ἑαυτῶν τείχει. ὡς δ’ ἔγνω ὁ Γύλιππος οὐ προσιόντας αὐτούς, ἀπήγαγε τὴν στρατιὰν ἐπὶ τὴν ἄκραν τὴν Τεμενῖτιν καλουμένην, καὶ αὐτοῦ ηὐλίσαντο. τῇ δ’ ὑστεραίᾳ ἄγων τὴν μὲν πλείστην τῆς στρατιᾶς παρέταξε πρὸς τὰ τείχη τῶν Ἀθηναίων, ὅπως μὴ ἐπιβοηθοῖεν ἄλλοσε, μέρος δέ τι πέμψας πρὸς τὸ φρούριον τὸ Λάβδαλον αἱρεῖ, καὶ ὅσους ἔλαβεν ἐν αὐτῷ πάντας ἀπέκτεινεν· ἦν δὲ οὐκ ἐπιφανὲς τοῖς Ἀθηναίοις τὸ χωρίον. καὶ τριήρης τῇ αὐτῇ ἡμέρᾳ ἁλίσκεται τῶν Ἀθηναίων ὑπὸ τῶν Συρακοσίων ἐφορμοῦσα τῷ λιμένι.", "st": "7.3"}, {"sp": "N", "t": "καὶ μετὰ ταῦτα ἐτείχιζον οἱ Συρακόσιοι καὶ οἱ ξύμμαχοι διὰ τῶν Ἐπιπολῶν ἀπὸ τῆς πόλεως ἀρξάμενοι ἄνω πρὸς τὸ ἐγκάρσιον τεῖχος ἁπλοῦν, ὅπως οἱ Ἀθηναῖοι, εἰ μὴ δύναιντο κωλῦσαι, μηκέτι οἷοί τε ὦσιν ἀποτειχίσαι. καὶ οἵ τε Ἀθηναῖοι ἀνεβεβήκεσαν ἤδη ἄνω, τὸ ἐπὶ θαλάσσῃ τεῖχος ἐπιτελέσαντες, καὶ ὁ Γύλιππος (ἦν γάρ τι τοῖς Ἀθηναίοις τοῦ τείχους ἀσθενές) νυκτὸς ἀναλαβὼν τὴν στρατιὰν ἐπῄει πρὸς αὐτό. οἱ δ’ Ἀθηναῖοι (ἔτυχον γὰρ ἔξω αὐλιζόμενοι) ὡς ᾔσθοντο, ἀντεπῇσαν· ὁ δὲ γνοὺς κατὰ τάχος ἀπήγαγε τοὺς σφετέρους πάλιν. ἐποικοδομήσαντες δὲ αὐτὸ οἱ Ἀθηναῖοι ὑψηλότερον αὐτοὶ μὲν ταύτῃ ἐφύλασσον, τοὺς δὲ ἄλλους ξυμμάχους κατὰ τὸ ἄλλο τείχισμα ἤδη διέταξαν, ᾗπερ ἔμελλον ἕκαστοι φρουρεῖν.", "st": "7.4"}, {"sp": "N", "t": "τῷ δὲ Νικίᾳ ἐδόκει τὸ Πλημμύριον καλούμενον τειχίσαι· ἔστι δὲ ἄκρα ἀντιπέρας τῆς πόλεως, ἥπερ προύχουσα τοῦ μεγάλου λιμένος τὸ στόμα στενὸν ποιεῖ, καὶ εἰ τειχισθείη, ῥᾴων αὐτῷ ἐφαίνετο ἡ ἐσκομιδὴ τῶν ἐπιτηδείων ἔσεσθαι· δι’ ἐλάσσονος γὰρ πρὸς τῷ λιμένι τῷ τῶν Συρακοσίων ἐφορμήσειν σφᾶς, καὶ οὐχ ὥσπερ νῦν ἐκ μυχοῦ τοῦ λιμένος τὰς ἐπαναγωγὰς ποιήσεσθαι, ἤν τι ναυτικῷ κινῶνται. προσεῖχέ τε ἤδη μᾶλλον τῷ κατὰ θάλασσαν πολέμῳ, ὁρῶν τὰ ἐκ τῆς γῆς σφίσιν ἤδη, ἐπειδὴ Γύλιππος ἧκεν, ἀνελπιστότερα ὄντα. διακομίσας οὖν στρατιὰν καὶ τὰς ναῦς ἐξετείχισε τρία φρούρια· καὶ ἐν αὐτοῖς τά τε σκεύη τὰ πλεῖστα ἔκειτο καὶ τὰ πλοῖα ἤδη ἐκεῖ τὰ μεγάλα ὥρμει καὶ αἱ ταχεῖαι νῆες. ὥστε καὶ τῶν πληρωμάτων οὐχ ἥκιστα τότε πρῶτον κάκωσις ἐγένετο· τῷ τε γὰρ ὕδατι σπανίῳ χρώμενοι καὶ οὐκ ἐγγύθεν, καὶ ἐπὶ φρυγανισμὸν ἅμα ὁπότε ἐξέλθοιεν οἱ ναῦται, ὑπὸ τῶν ἱππέων τῶν Συρακοσίων κρατούντων τῆς γῆς διεφθείροντο· τρίτον γὰρ μέρος τῶν ἱππέων τοῖς Συρακοσίοις διὰ τοὺς ἐν τῷ Πλημμυρίῳ, ἵνα μὴ κακουργήσοντες ἐξίοιεν, ἐπὶ τῇ ἐν τῷ Ὀλυμπιείῳ πολίχνῃ ἐτετάχατο. ἐπυνθάνετο δὲ καὶ τὰς λοιπὰς τῶν Κορινθίων ναῦς προσπλεούσας ὁ Νικίας· καὶ πέμπει ἐς φυλακὴν αὐτῶν εἴκοσι ναῦς, αἷς εἴρητο περί τε Λοκροὺς καὶ Ῥήγιον καὶ τὴν προσβολὴν τῆς Σικελίας ναυλοχεῖν αὐτάς.", "st": "7.4"}, {"sp": "N", "t": "ὁ δὲ Γύλιππος ἅμα μὲν ἐτείχιζε τὸ διὰ τῶν Ἐπιπολῶν τεῖχος, τοῖς λίθοις χρώμενος οὓς οἱ Ἀθηναῖοι προπαρεβάλοντο σφίσιν, ἅμα δὲ παρέτασσεν ἐξάγων αἰεὶ πρὸ τοῦ τειχίσματος τοὺς Συρακοσίους καὶ τοὺς ξυμμάχους· καὶ οἱ Ἀθηναῖοι ἀντιπαρετάσσοντο. ἐπειδὴ δὲ ἔδοξε τῷ Γυλίππῳ καιρὸς εἶναι, ἦρχε τῆς ἐφόδου· καὶ ἐν χερσὶ γενόμενοι ἐμάχοντο μεταξὺ τῶν τειχισμάτων, ᾗ τῆς ἵππου τῶν Συρακοσίων οὐδεμία χρῆσις ἦν. καὶ νικηθέντων τῶν Συρακοσίων καὶ τῶν ξυμμάχων καὶ νεκροὺς ὑποσπόνδους ἀνελομένων καὶ τῶν Ἀθηναίων τροπαῖον στησάντων, ὁ Γύλιππος ξυγκαλέσας τὸ στράτευμα οὐκ ἔφη τὸ ἁμάρτημα ἐκείνων, ἀλλ’ ἑαυτοῦ γενέσθαι· τῆς γὰρ ἵππου καὶ τῶν ἀκοντιστῶν τὴν ὠφελίαν τῇ τάξει ἐντὸς λίαν τῶν τειχῶν ποιήσας ἀφελέσθαι· νῦν οὖν αὖθις ἐπάξειν. καὶ διανοεῖσθαι οὕτως ἐκέλευεν αὐτοὺς ὡς τῇ μὲν παρασκευῇ οὐκ ἔλασσον ἕξοντας, τῇ δὲ γνώμῃ οὐκ ἀνεκτὸν ἐσόμενον εἰ μὴ ἀξιώσουσι Πελοποννήσιοί τε ὄντες καὶ Δωριῆς Ἰώνων καὶ νησιωτῶν καὶ ξυγκλύδων ἀνθρώπων κρατήσαντες ἐξελάσασθαι ἐκ τῆς χώρας.", "st": "7.5"}, {"sp": "N", "t": "καὶ μετὰ ταῦτα, ἐπειδὴ καιρὸς ἦν, αὖθις ἐπῆγεν αὐτούς. ὁ δὲ Νικίας καὶ οἱ Ἀθηναῖοι νομίζοντες, καὶ εἰ ἐκεῖνοι μὴ ἐθέλοιεν μάχης ἄρχειν, ἀναγκαῖον εἶναι σφίσι μὴ περιορᾶν παροικοδομούμενον τὸ τεῖχος (ἤδη γὰρ καὶ ὅσον οὐ παρεληλύθει τὴν τῶν Ἀθηναίων τοῦ τείχους τελευτὴν ἡ ἐκείνων τείχισις, καί, εἰ προέλθοι, ταὐτὸν ἤδη ἐποίει αὐτοῖς νικᾶν τε μαχομένοις διὰ παντὸς καὶ μηδὲ μάχεσθαι), ἀντεπῇσαν οὖν τοῖς Συρακοσίοις. καὶ ὁ Γύλιππος τοὺς μὲν ὁπλίτας ἔξω τῶν τειχῶν μᾶλλον ἢ πρότερον προαγαγὼν ξυνέμισγεν αὐτοῖς, τοὺς δ’ ἱππέας καὶ τοὺς ἀκοντιστὰς ἐκ πλαγίου τάξας τῶν Ἀθηναίων κατὰ τὴν εὐρυχωρίαν, ᾗ τῶν τειχῶν ἀμφοτέρων αἱ ἐργασίαι ἔληγον. καὶ προσβαλόντες οἱ ἱππῆς ἐν τῇ μάχῃ τῷ εὐωνύμῳ κέρᾳ τῶν Ἀθηναίων, ὅπερ κατ’ αὐτοὺς ἦν, ἔτρεψαν· καὶ δι’ αὐτὸ καὶ τὸ ἄλλο στράτευμα νικηθὲν ὑπὸ τῶν Συρακοσίων κατηράχθη ἐς τὰ τειχίσματα. καὶ τῇ ἐπιούσῃ νυκτὶ ἔφθασαν παροικοδομήσαντες καὶ παρελθόντες τὴν τῶν Ἀθηναίων οἰκοδομίαν, ὥστε μηκέτι μήτε αὐτοὶ κωλύεσθαι ὑπ’ αὐτῶν, ἐκείνους τε καὶ παντάπασιν ἀπεστερηκέναι, εἰ καὶ κρατοῖεν, μὴ ἂν ἔτι σφᾶς ἀποτειχίσαι.", "st": "7.6"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο αἵ τε τῶν Κορινθίων νῆες καὶ Ἀμπρακιωτῶν καὶ Λευκαδίων ἐσέπλευσαν αἱ ὑπόλοιποι δώδεκα, λαθοῦσαι τὴν τῶν Ἀθηναίων φυλακήν (ἦρχε δ’ αὐτῶν Ἐρασινίδης Κορίνθιος), καὶ ξυνετείχισαν τὸ λοιπὸν τοῖς Συρακοσίοις μέχρι τοῦ ἐγκαρσίου τείχους. καὶ ὁ Γύλιππος ἐς τὴν ἄλλην Σικελίαν ἐπὶ στρατιάν τε ᾤχετο, καὶ ναυτικὴν καὶ πεζὴν ξυλλέξων, καὶ τῶν πόλεων ἅμα προσαξόμενος εἴ τις ἢ μὴ πρόθυμος ἦν ἢ παντάπασιν ἔτι ἀφειστήκει τοῦ πολέμου. πρέσβεις τε ἄλλοι τῶν Συρακοσίων καὶ Κορινθίων ἐς Λακεδαίμονα καὶ Κόρινθον ἀπεστάλησαν, ὅπως στρατιὰ ἔτι περαιωθῇ τρόπῳ ᾧ ἂν ἐν ὁλκάσιν ἢ πλοίοις ἢ ἄλλως ὅπως ἂν προχωρῇ, ὡς καὶ τῶν Ἀθηναίων ἐπιμεταπεμπομένων. οἵ τε Συρακόσιοι ναυτικὸν ἐπλήρουν καὶ ἀνεπειρῶντο ὡς καὶ τούτῳ ἐπιχειρήσοντες, καὶ ἐς τἆλλα πολὺ ἐπέρρωντο.", "st": "7.7"}, {"sp": "N", "t": "ὁ δὲ Νικίας αἰσθόμενος τοῦτο καὶ ὁρῶν καθ’ ἡμέραν ἐπιδιδοῦσαν τήν τε τῶν πολεμίων ἰσχὺν καὶ τὴν σφετέραν ἀπορίαν, ἔπεμπε καὶ αὐτὸς ἐς τὰς Ἀθήνας ἀγγέλλων πολλάκις μὲν καὶ ἄλλοτε καθ’ ἕκαστα τῶν γιγνομένων, μάλιστα δὲ καὶ τότε, νομίζων ἐν δεινοῖς τε εἶναι καί, εἰ μὴ ὡς τάχιστα ἢ σφᾶς μεταπέμψουσιν ἢ ἄλλους μὴ ὀλίγους ἀποστελοῦσιν, οὐδεμίαν εἶναι σωτηρίαν. φοβούμενος δὲ μὴ οἱ πεμπόμενοι ἢ κατὰ τὴν τοῦ λέγειν ἀδυνασίαν ἢ καὶ μνήμης ἐλλιπεῖς γιγνόμενοι ἢ τῷ ὄχλῳ πρὸς χάριν τι λέγοντες οὐ τὰ ὄντα ἀπαγγέλλωσιν, ἔγραψεν ἐπιστολήν, νομίζων οὕτως ἂν μάλιστα τὴν αὑτοῦ γνώμην μηδὲν ἐν τῷ ἀγγέλῳ ἀφανισθεῖσαν μαθόντας τοὺς Ἀθηναίους βουλεύσασθαι περὶ τῆς ἀληθείας. καὶ οἱ μὲν ᾤχοντο φέροντες, οὓς ἀπέστειλε, τὰ γράμματα καὶ ὅσα ἔδει αὐτοὺς εἰπεῖν· ὁ δὲ τὰ κατὰ τὸ στρατόπεδον διὰ φυλακῆς μᾶλλον ἤδη ἔχων ἢ δι’ ἑκουσίων κινδύνων ἐπεμέλετο.", "st": "7.8"}, {"sp": "N", "t": "ἐν δὲ τῷ αὐτῷ θέρει τελευτῶντι καὶ Εὐετίων στρατηγὸς Ἀθηναίων μετὰ Περδίκκου στρατεύσας ἐπ’ Ἀμφίπολιν Θρᾳξὶ πολλοῖς τὴν μὲν πόλιν οὐχ εἷλεν, ἐς δὲ τὸν Στρυμόνα περικομίσας τριήρεις ἐκ τοῦ ποταμοῦ ἐπολιόρκει ὁρμώμενος ἐξ Ἱμεραίου. καὶ τὸ θέρος ἐτελεύτα.", "st": "7.9"}, {"sp": "N", "t": "τοῦ δ’ ἐπιγιγνομένου χειμῶνος ἥκοντες ἐς τὰς Ἀθήνας οἱ παρὰ τοῦ Νικίου ὅσα τε ἀπὸ γλώσσης εἴρητο αὐτοῖς εἶπον, καὶ εἴ τίς τι ἐπηρώτα ἀπεκρίνοντο, καὶ τὴν ἐπιστολὴν ἀπέδοσαν. ὁ δὲ γραμματεὺς ὁ τῆς πόλεως παρελθὼν ἀνέγνω τοῖς Ἀθηναίοις δηλοῦσαν τοιάδε.", "st": "7.10"}, {"sp": "N", "t": "‘τὰ μὲν πρότερον πραχθέντα, ὦ Ἀθηναῖοι, ἐν ἄλλαις πολλαῖς ἐπιστολαῖς ἴστε· νῦν δὲ καιρὸς οὐχ ἧσσον μαθόντας ὑμᾶς ἐν ᾧ ἐσμὲν βουλεύσασθαι. κρατησάντων γὰρ ἡμῶν μάχαις ταῖς πλέοσι Συρακοσίους ἐφ’ οὓς ἐπέμφθημεν καὶ τὰ τείχη οἰκοδομησαμένων ἐν οἷσπερ νῦν ἐσμέν, ἦλθε Γύλιππος Λακεδαιμόνιος στρατιὰν ἔχων ἔκ τε Πελοποννήσου καὶ ἀπὸ τῶν ἐν Σικελίᾳ πόλεων ἔστιν ὧν. καὶ μάχῃ τῇ μὲν πρώτῃ νικᾶται ὑφ’ ἡμῶν, τῇ δ’ ὑστεραίᾳ ἱππεῦσί τε πολλοῖς καὶ ἀκοντισταῖς βιασθέντες ἀνεχωρήσαμεν ἐς τὰ τείχη. νῦν οὖν ἡμεῖς μὲν παυσάμενοι τοῦ περιτειχισμοῦ διὰ τὸ πλῆθος τῶν ἐναντίων ἡσυχάζομεν (οὐδὲ γὰρ ξυμπάσῃ τῇ στρατιᾷ δυναίμεθ’ ἂν χρήσασθαι ἀπανηλωκυίας τῆς φυλακῆς τῶν τειχῶν μέρος τι τοῦ ὁπλιτικοῦ)· οἱ δὲ παρῳκοδομήκασιν ἡμῖν τεῖχος ἁπλοῦν, ὥστε μὴ εἶναι ἔτι περιτειχίσαι αὐτούς, ἢν μή τις τὸ παρατείχισμα τοῦτο πολλῇ στρατιᾷ ἐπελθὼν ἕλῃ. ξυμβέβηκέ τε πολιορκεῖν δοκοῦντας ἡμᾶς ἄλλους αὐτοὺς μᾶλλον, ὅσα γε κατὰ γῆν, τοῦτο πάσχειν· οὐδὲ γὰρ τῆς χώρας ἐπὶ πολὺ διὰ τοὺς ἱππέας ἐξερχόμεθα.", "st": "7.11"}, {"sp": "N", "t": "‘πεπόμφασι δὲ καὶ ἐς Πελοπόννησον πρέσβεις ἐπ’ ἄλλην στρατιάν, καὶ ἐς τὰς ἐν Σικελίᾳ πόλεις Γύλιππος οἴχεται, τὰς μὲν καὶ πείσων ξυμπολεμεῖν ὅσαι νῦν ἡσυχάζουσιν, ἀπὸ δὲ τῶν καὶ στρατιὰν ἔτι πεζὴν καὶ ναυτικοῦ παρασκευήν, ἢν δύνηται, ἄξων. διανοοῦνται γάρ, ὡς ἐγὼ πυνθάνομαι, τῷ τε πεζῷ ἅμα τῶν τειχῶν ἡμῶν πειρᾶν καὶ ταῖς ναυσὶ κατὰ θάλασσαν. καὶ δεινὸν μηδενὶ ὑμῶν δόξῃ εἶναι ὅτι καὶ κατὰ θάλασσαν. τὸ γὰρ ναυτικὸν ἡμῶν, ὅπερ κἀκεῖνοι πυνθάνονται, τὸ μὲν πρῶτον ἤκμαζε καὶ τῶν νεῶν τῇ ξηρότητι καὶ τῶν πληρωμάτων τῇ σωτηρίᾳ· νῦν δὲ αἵ τε νῆες διάβροχοι τοσοῦτον χρόνον ἤδη θαλασσεύουσαι, καὶ τὰ πληρώματα ἔφθαρται. τὰς μὲν γὰρ ναῦς οὐκ ἔστιν ἀνελκύσαντας διαψύξαι διὰ τὸ ἀντιπάλους τῷ πλήθει καὶ ἔτι πλείους τὰς τῶν πολεμίων οὔσας αἰεὶ προσδοκίαν παρέχειν ὡς ἐπιπλεύσονται. φανεραὶ δ’ εἰσὶν ἀναπειρώμεναι, καὶ αἱ ἐπιχειρήσεις ἐπ’ ἐκείνοις καὶ ἀποξηρᾶναι τὰς σφετέρας μᾶλλον ἐξουσία· οὐ γὰρ ἐφορμοῦσιν ἄλλοις.", "st": "7.12"}, {"sp": "N", "t": "ἡμῖν δ’ ἐκ πολλῆς ἂν περιουσίας νεῶν μόλις τοῦτο ὑπῆρχε καὶ μὴ ἀναγκαζομένοις ὥσπερ νῦν πάσαις φυλάσσειν· εἰ γὰρ ἀφαιρήσομέν τι καὶ βραχὺ τῆς τηρήσεως, τὰ ἐπιτήδεια οὐχ ἕξομεν, παρὰ τὴν ἐκείνων πόλιν χαλεπῶς καὶ νῦν ἐσκομιζόμενοι. τὰ δὲ πληρώματα διὰ τόδε ἐφθάρη τε ἡμῖν καὶ ἔτι νῦν φθείρεται, τῶν ναυτῶν [τῶν] μὲν διὰ φρυγανισμὸν καὶ ἁρπαγὴν καὶ ὑδρείαν μακρὰν ὑπὸ τῶν ἱππέων ἀπολλυμένων· οἱ δὲ θεράποντες, ἐπειδὴ ἐς ἀντίπαλα καθεστήκαμεν, αὐτομολοῦσι, καὶ οἱ ξένοι οἱ μὲν ἀναγκαστοὶ ἐσβάντες εὐθὺς κατὰ τὰς πόλεις ἀποχωροῦσιν, οἱ δὲ ὑπὸ μεγάλου μισθοῦ τὸ πρῶτον ἐπαρθέντες καὶ οἰόμενοι χρηματιεῖσθαι μᾶλλον ἢ μαχεῖσθαι, ἐπειδὴ παρὰ γνώμην ναυτικόν τε δὴ καὶ τἆλλα ἀπὸ τῶν πολεμίων ἀνθεστῶτα ὁρῶσιν, οἱ μὲν ἐπ’ αὐτομολίας προφάσει ἀπέρχονται, οἱ δὲ ὡς ἕκαστοι δύνανται (πολλὴ δ’ ἡ Σικελία), εἰσὶ δ’ οἳ καὶ αὐτοὶ ἐμπορευόμενοι ἀνδράποδα Ὑκκαρικὰ ἀντεμβιβάσαι ὑπὲρ σφῶν πείσαντες τοὺς τριηράρχους τὴν ἀκρίβειαν τοῦ ναυτικοῦ ἀφῄρηνται.", "st": "7.13"}, {"sp": "N", "t": "ἐπισταμένοις δ’ ὑμῖν γράφω ὅτι βραχεῖα ἀκμὴ πληρώματος καὶ ὀλίγοι τῶν ναυτῶν οἱ ἐξορμῶντές τε ναῦν καὶ ξυνέχοντες τὴν εἰρεσίαν. τούτων δὲ πάντων ἀπορώτατον τό τε μὴ οἷόν τε εἶναι ταῦτα ἐμοὶ κωλῦσαι τῷ στρατηγῷ (χαλεπαὶ γὰρ αἱ ὑμέτεραι φύσεις ἄρξαι) καὶ ὅτι οὐδ’ ὁπόθεν ἐπιπληρωσόμεθα τὰς ναῦς ἔχομεν, ὃ τοῖς πολεμίοις πολλαχόθεν ὑπάρχει, ἀλλ’ ἀνάγκη ἀφ’ ὧν ἔχοντες ἤλθομεν τά τε ὄντα καὶ ἀπαναλισκόμενα γίγνεσθαι· αἱ γὰρ νῦν οὖσαι πόλεις ξύμμαχοι ἀδύνατοι Νάξος καὶ Κατάνη. εἰ δὲ προσγενήσεται ἓν ἔτι τοῖς πολεμίοις, ὥστε τὰ τρέφοντα ἡμᾶς χωρία τῆς Ἰταλίας, ὁρῶντα ἐν ᾧ τ’ ἐσμὲν καὶ ὑμῶν μὴ ἐπιβοηθούντων, πρὸς ἐκείνους χωρῆσαι, διαπεπολεμήσεται αὐτοῖς ἀμαχεὶ ἐκπολιορκηθέντων ἡμῶν [ὁ πόλεμος].", "st": "7.14"}, {"sp": "N", "t": "‘τούτων ἐγὼ ἡδίω μὲν ἂν εἶχον ὑμῖν ἕτερα ἐπιστέλλειν, οὐ μέντοι χρησιμώτερά γε, εἰ δεῖ σαφῶς εἰδότας τὰ ἐνθάδε βουλεύσασθαι. καὶ ἅμα τὰς φύσεις ἐπιστάμενος ὑμῶν, βουλομένων μὲν τὰ ἥδιστα ἀκούειν, αἰτιωμένων δὲ ὕστερον, ἤν τι ὑμῖν ἀπ’ αὐτῶν μὴ ὁμοῖον ἐκβῇ, ἀσφαλέστερον ἡγησάμην τὸ ἀληθὲς δηλῶσαι.", "st": "7.14"}, {"sp": "N", "t": "καὶ νῦν ὡς ἐφ’ ἃ μὲν ἤλθομεν τὸ πρῶτον καὶ τῶν στρατιωτῶν καὶ τῶν ἡγεμόνων ὑμῖν μὴ μεμπτῶν γεγενημένων, οὕτω τὴν γνώμην ἔχετε· ἐπειδὴ δὲ Σικελία τε ἅπασα ξυνίσταται καὶ ἐκ Πελοποννήσου ἄλλη στρατιὰ προσδόκιμος αὐτοῖς, βουλεύεσθε ἤδη ὡς τῶν γ’ ἐνθάδε μηδὲ τοῖς παροῦσιν ἀνταρκούντων, ἀλλ’ ἢ τούτους μεταπέμπειν δέον ἢ ἄλλην στρατιὰν μὴ ἐλάσσω ἐπιπέμπειν καὶ πεζὴν καὶ ναυτικὴν καὶ χρήματα μὴ ὀλίγα, ἐμοὶ δὲ διάδοχόν τινα, ὡς ἀδύνατός εἰμι διὰ νόσον νεφρῖτιν παραμένειν. ἀξιῶ δ’ ὑμῶν ξυγγνώμης τυγχάνειν· καὶ γὰρ ὅτ’ ἐρρώμην πολλὰ ἐν ἡγεμονίαις ὑμᾶς εὖ ἐποίησα. ὅτι δὲ μέλλετε, ἅμα τῷ ἦρι εὐθὺς καὶ μὴ ἐς ἀναβολὰς πράσσετε, ὡς τῶν πολεμίων τὰ μὲν ἐν Σικελίᾳ δι’ ὀλίγου ποριουμένων, τὰ δ’ ἐκ Πελοποννήσου σχολαίτερον μέν, ὅμως δ’, ἢν μὴ προσέχητε τὴν γνώμην, τὰ μὲν λήσουσιν ὑμᾶς, ὥσπερ καὶ πρότερον, τὰ δὲ φθήσονται.’", "st": "7.15"}, {"sp": "N", "t": "ἡ μὲν τοῦ Νικίου ἐπιστολὴ τοσαῦτα ἐδήλου, οἱ δὲ Ἀθηναῖοι ἀκούσαντες αὐτῆς τὸν μὲν Νικίαν οὐ παρέλυσαν τῆς ἀρχῆς, ἀλλ’ αὐτῷ, ἕως ἂν ἕτεροι ξυνάρχοντες αἱρεθέντες ἀφίκωνται, τῶν αὐτοῦ ἐκεῖ δύο προσείλοντο Μένανδρον καὶ Εὐθύδημον, ὅπως μὴ μόνος ἐν ἀσθενείᾳ ταλαιπωροίη, στρατιὰν δὲ ἄλλην ἐψηφίσαντο πέμπειν καὶ ναυτικὴν καὶ πεζὴν Ἀθηναίων τε ἐκ καταλόγου καὶ τῶν ξυμμάχων. καὶ ξυνάρχοντας αὐτῷ εἵλοντο Δημοσθένη τε τὸν Ἀλκισθένους καὶ Εὐρυμέδοντα τὸν Θουκλέους. καὶ τὸν μὲν Εὐρυμέδοντα εὐθὺς περὶ ἡλίου τροπὰς τὰς χειμερινὰς ἀποπέμπουσιν ἐς τὴν Σικελίαν μετὰ δέκα νεῶν, ἄγοντα εἴκοσι ⟨καὶ ἑκατὸν⟩ τάλαντα ἀργυρίου, καὶ ἅμα ἀγγελοῦντα τοῖς ἐκεῖ ὅτι ἥξει βοήθεια καὶ ἐπιμέλεια αὐτῶν ἔσται·", "st": "7.16"}, {"sp": "N", "t": "ὁ δὲ Δημοσθένης ὑπομένων παρεσκευάζετο τὸν ἔκπλουν ὡς ἅμα τῷ ἦρι ποιησόμενος, στρατιάν τε ἐπαγγέλλων ἐς τοὺς ξυμμάχους καὶ χρήματα αὐτόθεν καὶ ναῦς καὶ ὁπλίτας ἑτοιμάζων. πέμπουσι δὲ καὶ περὶ τὴν Πελοπόννησον οἱ Ἀθηναῖοι εἴκοσι ναῦς, ὅπως φυλάσσοιεν μηδένα ἀπὸ Κορίνθου καὶ τῆς Πελοποννήσου ἐς τὴν Σικελίαν περαιοῦσθαι. οἱ γὰρ Κορίνθιοι, ὡς αὐτοῖς οἱ πρέσβεις ἧκον καὶ τὰ ἐν τῇ Σικελίᾳ βελτίω ἤγγελλον, νομίσαντες οὐκ ἄκαιρον καὶ τὴν προτέραν πέμψιν τῶν νεῶν ποιήσασθαι, πολλῷ μᾶλλον ἐπέρρωντο, καὶ ἐν ὁλκάσι παρεσκευάζοντο αὐτοί τε ἀποστελοῦντες ὁπλίτας ἐς τὴν Σικελίαν καὶ ἐκ τῆς ἄλλης Πελοποννήσου οἱ Λακεδαιμόνιοι τῷ αὐτῷ τρόπῳ πέμψοντες· ναῦς τε οἱ Κορίνθιοι πέντε καὶ εἴκοσιν ἐπλήρουν, ὅπως ναυμαχίας τε ἀποπειράσωσι πρὸς τὴν ἐν τῇ Ναυπάκτῳ φυλακήν, καὶ τὰς ὁλκάδας αὐτῶν ἧσσον οἱ ἐν τῇ Ναυπάκτῳ Ἀθηναῖοι κωλύοιεν ἀπαίρειν, πρὸς τὴν σφετέραν ἀντίταξιν τῶν τριήρων τὴν φυλακὴν ποιούμενοι.", "st": "7.17"}, {"sp": "N", "t": "παρεσκευάζοντο δὲ καὶ τὴν ἐς τὴν Ἀττικὴν ἐσβολὴν οἱ Λακεδαιμόνιοι, ὥσπερ τε προυδέδοκτο αὐτοῖς καὶ τῶν Συρακοσίων καὶ Κορινθίων ἐναγόντων, ἐπειδὴ ἐπυνθάνοντο τὴν ἀπὸ τῶν Ἀθηναίων βοήθειαν ἐς τὴν Σικελίαν, ὅπως δὴ ἐσβολῆς γενομένης διακωλυθῇ. καὶ ὁ Ἀλκιβιάδης προσκείμενος ἐδίδασκε τὴν Δεκέλειαν τειχίζειν καὶ μὴ ἀνιέναι τὸν πόλεμον. μάλιστα δὲ τοῖς Λακεδαιμονίοις ἐγεγένητό τις ῥώμη, διότι τοὺς Ἀθηναίους ἐνόμιζον διπλοῦν τὸν πόλεμον ἔχοντας, πρός τε σφᾶς καὶ Σικελιώτας, εὐκαθαιρετωτέρους ἔσεσθαι, καὶ ὅτι τὰς σπονδὰς προτέρους λελυκέναι ἡγοῦντο αὐτούς· ἐν γὰρ τῷ προτέρῳ πολέμῳ σφέτερον τὸ παρανόμημα μᾶλλον γενέσθαι, ὅτι τε ἐς Πλάταιαν ἦλθον Θηβαῖοι ἐν σπονδαῖς, καὶ εἰρημένον ἐν ταῖς πρότερον ξυνθήκαις ὅπλα μὴ ἐπιφέρειν, ἢν δίκας ἐθέλωσι διδόναι, αὐτοὶ οὐχ ὑπήκουον ἐς δίκας προκαλουμένων τῶν Ἀθηναίων. καὶ διὰ τοῦτο εἰκότως δυστυχεῖν τε ἐνόμιζον, καὶ ἐνεθυμοῦντο τήν τε περὶ Πύλον ξυμφορὰν καὶ εἴ τις ἄλλη αὐτοῖς ἐγένετο. ἐπειδὴ δὲ οἱ Ἀθηναῖοι ταῖς τριάκοντα ναυσὶν ἐξ Ἄργους ὁρμώμενοι Ἐπιδαύρου τέ τι καὶ Πρασιῶν καὶ ἄλλα ἐδῄωσαν καὶ ἐκ Πύλου ἅμα ἐλῃστεύοντο, καὶ ὁσάκις περί του διαφοραὶ γένοιντο τῶν κατὰ τὰς σπονδὰς ἀμφισβητουμένων, ἐς δίκας προκαλουμένων τῶν Λακεδαιμονίων οὐκ ἤθελον ἐπιτρέπειν, τότε δὴ οἱ Λακεδαιμόνιοι νομίσαντες τὸ παρανόμημα, ὅπερ καὶ σφίσι πρότερον ἡμάρτητο, αὖθις ἐς τοὺς Ἀθηναίους τὸ αὐτὸ περιεστάναι, πρόθυμοι ἦσαν ἐς τὸν πόλεμον. καὶ ἐν τῷ χειμῶνι τούτῳ σίδηρόν τε περιήγγελλον κατὰ τοὺς ξυμμάχους καὶ τἆλλα ἐργαλεῖα ἡτοίμαζον ἐς τὸν ἐπιτειχισμόν, καὶ τοῖς ἐν τῇ Σικελίᾳ ἅμα ὡς ἀποπέμψοντες ἐν ταῖς ὁλκάσιν ἐπικουρίαν αὐτοί τε ἐπόριζον καὶ τοὺς ἄλλους Πελοποννησίους προσηνάγκαζον. καὶ ὁ χειμὼν ἐτελεύτα, καὶ ὄγδοον καὶ δέκατον ἔτος τῷ πολέμῳ ἐτελεύτα τῷδε ὃν Θουκυδίδης ξυνέγραψεν.", "st": "7.18"}, {"sp": "N", "t": "τοῦ δ’ ἐπιγιγνομένου ἦρος εὐθὺς ἀρχομένου πρωίτατα δὴ οἱ Λακεδαιμόνιοι καὶ οἱ ξύμμαχοι ἐς τὴν Ἀττικὴν ἐσέβαλον· ἡγεῖτο δὲ Ἆγις ὁ Ἀρχιδάμου Λακεδαιμονίων βασιλεύς. καὶ πρῶτον μὲν τῆς χώρας τὰ περὶ τὸ πεδίον ἐδῄωσαν, ἔπειτα Δεκέλειαν ἐτείχιζον, κατὰ πόλεις διελόμενοι τὸ ἔργον. ἀπέχει δὲ ἡ Δεκέλεια σταδίους μάλιστα τῆς τῶν Ἀθηναίων πόλεως εἴκοσι καὶ ἑκατόν, παραπλήσιον δὲ καὶ οὐ πολλῷ πλέον καὶ ἀπὸ τῆς Βοιωτίας. ἐπὶ δὲ τῷ πεδίῳ καὶ τῆς χώρας τοῖς κρατίστοις ἐς τὸ κακουργεῖν ᾠκοδομεῖτο τὸ τεῖχος, ἐπιφανὲς μέχρι τῆς τῶν Ἀθηναίων πόλεως. καὶ οἱ μὲν ἐν τῇ Ἀττικῇ Πελοποννήσιοι καὶ οἱ ξύμμαχοι ἐτείχιζον, οἱ δ’ ἐν τῇ Πελοποννήσῳ ἀπέστελλον περὶ τὸν αὐτὸν χρόνον ταῖς ὁλκάσι τοὺς ὁπλίτας ἐς τὴν Σικελίαν, Λακεδαιμόνιοι μὲν τῶν τε Εἱλώτων ἐπιλεξάμενοι τοὺς βελτίστους καὶ τῶν νεοδαμωδῶν, ξυναμφοτέρων ἐς ἑξακοσίους ὁπλίτας, καὶ Ἔκκριτον Σπαρτιάτην ἄρχοντα, Βοιωτοὶ δὲ τριακοσίους ὁπλίτας, ὧν ἦρχον Ξένων τε καὶ Νίκων Θηβαῖοι καὶ Ἡγήσανδρος Θεσπιεύς. οὗτοι μὲν οὖν ἐν τοῖς πρῶτοι ὁρμήσαντες ἀπὸ τοῦ Ταινάρου τῆς Λακωνικῆς ἐς τὸ πέλαγος ἀφῆκαν· μετὰ δὲ τούτους Κορίνθιοι οὐ πολλῷ ὕστερον πεντακοσίους ὁπλίτας, τοὺς μὲν ἐξ αὐτῆς Κορίνθου, τοὺς δὲ προσμισθωσάμενοι Ἀρκάδων, καὶ ἄρχοντα Ἀλέξαρχον Κορίνθιον προστάξαντες ἀπέπεμψαν. ἀπέστειλαν δὲ καὶ Σικυώνιοι διακοσίους ὁπλίτας ὁμοῦ τοῖς Κορινθίοις, ὧν ἦρχε Σαργεὺς Σικυώνιος. αἱ δὲ πέντε καὶ εἴκοσι νῆες τῶν Κορινθίων αἱ τοῦ χειμῶνος πληρωθεῖσαι ἀνθώρμουν ταῖς ἐν τῇ Ναυπάκτῳ εἴκοσιν Ἀττικαῖς, ἕωσπερ αὐτοῖς οὗτοι οἱ ὁπλῖται ταῖς ὁλκάσιν ἀπὸ τῆς Πελοποννήσου ἀπῆραν· οὗπερ ἕνεκα καὶ τὸ πρῶτον ἐπληρώθησαν, ὅπως μὴ οἱ Ἀθηναῖοι πρὸς τὰς ὁλκάδας μᾶλλον ἢ πρὸς τὰς τριήρεις τὸν νοῦν ἔχωσιν.", "st": "7.19"}, {"sp": "N", "t": "ἐν δὲ τούτῳ καὶ οἱ Ἀθηναῖοι ἅμα τῆς Δεκελείας τῷ τειχισμῷ καὶ τοῦ ἦρος εὐθὺς ἀρχομένου περί τε Πελοπόννησον ναῦς τριάκοντα ἔστειλαν καὶ Χαρικλέα τὸν Ἀπολλοδώρου ἄρχοντα, ᾧ εἴρητο καὶ ἐς Ἄργος ἀφικομένῳ κατὰ τὸ ξυμμαχικὸν παρακαλεῖν Ἀργείων [τε] ὁπλίτας ἐπὶ τὰς ναῦς, καὶ τὸν Δημοσθένη ἐς τὴν Σικελίαν, ὥσπερ ἔμελλον, ἀπέστελλον ἑξήκοντα μὲν ναυσὶν Ἀθηναίων καὶ πέντε Χίαις, ὁπλίταις δὲ ἐκ καταλόγου Ἀθηναίων διακοσίοις καὶ χιλίοις, καὶ νησιωτῶν ὅσοις ἑκασταχόθεν οἷόν τ’ ἦν πλείστοις χρήσασθαι, καὶ ἐκ τῶν ἄλλων ξυμμάχων τῶν ὑπηκόων, εἴ ποθέν τι εἶχον ἐπιτήδειον ἐς τὸν πόλεμον, ξυμπορίσαντες. εἴρητο δ’ αὐτῷ πρῶτον μετὰ τοῦ Χαρικλέους ἅμα περιπλέοντα ξυστρατεύεσθαι περὶ τὴν Λακωνικήν. καὶ ὁ μὲν Δημοσθένης ἐς τὴν Αἴγιναν προσπλεύσας τοῦ στρατεύματός τε εἴ τι ὑπελέλειπτο περιέμενε καὶ τὸν Χαρικλέα τοὺς Ἀργείους παραλαβεῖν.", "st": "7.20"}, {"sp": "N", "t": "ἐν δὲ τῇ Σικελίᾳ ὑπὸ τοὺς αὐτοὺς χρόνους τούτου τοῦ ἦρος καὶ ὁ Γύλιππος ἧκεν ἐς τὰς Συρακούσας, ἄγων ἀπὸ τῶν πόλεων ὧν ἔπεισε στρατιὰν ὅσην ἑκασταχόθεν πλείστην ἐδύνατο. καὶ ξυγκαλέσας τοὺς Συρακοσίους ἔφη χρῆναι πληροῦν ναῦς ὡς δύνανται πλείστας καὶ ναυμαχίας ἀπόπειραν λαμβάνειν· ἐλπίζειν γὰρ ἀπ’ αὐτοῦ τι ἔργον ἄξιον τοῦ κινδύνου ἐς τὸν πόλεμον κατεργάσεσθαι. ξυνανέπειθε δὲ καὶ ὁ Ἑρμοκράτης οὐχ ἥκιστα, τοῦ ταῖς ναυσὶ μὴ ἀθυμεῖν ἐπιχειρῆσαι πρὸς τοὺς Ἀθηναίους, λέγων οὐδ’ ἐκείνους πάτριον τὴν ἐμπειρίαν οὐδ’ ἀίδιον τῆς θαλάσσης ἔχειν, ἀλλ’ ἠπειρώτας μᾶλλον τῶν Συρακοσίων ὄντας καὶ ἀναγκασθέντας ὑπὸ Μήδων ναυτικοὺς γενέσθαι. καὶ πρὸς ἄνδρας τολμηρούς, οἵους καὶ Ἀθηναίους, τοὺς ἀντιτολμῶντας χαλεπωτάτους ἂν [αὐτοῖς] φαίνεσθαι· ᾧ γὰρ ἐκεῖνοι τοὺς πέλας, οὐ δυνάμει ἔστιν ὅτε προύχοντες, τῷ δὲ θράσει ἐπιχειροῦντες καταφοβοῦσι, καὶ σφᾶς ἂν τὸ αὐτὸ ὁμοίως τοῖς ἐναντίοις ὑποσχεῖν. καὶ Συρακοσίους εὖ εἰδέναι ἔφη τῷ τολμῆσαι ἀπροσδοκήτως πρὸς τὸ Ἀθηναίων ναυτικὸν ἀντιστῆναι πλέον τι διὰ τὸ τοιοῦτον ἐκπλαγέντων αὐτῶν περιγενησομένους ἢ Ἀθηναίους τῇ ἐπιστήμῃ τὴν Συρακοσίων ἀπειρίαν βλάψοντας. ἰέναι οὖν ἐκέλευεν ἐς τὴν πεῖραν τοῦ ναυτικοῦ καὶ μὴ ἀποκνεῖν.", "st": "7.21"}, {"sp": "N", "t": "καὶ οἱ μὲν Συρακόσιοι, τοῦ τε Γυλίππου καὶ Ἑρμοκράτους καὶ εἴ του ἄλλου πειθόντων, ὥρμηντό τε ἐς τὴν ναυμαχίαν καὶ τὰς ναῦς ἐπλήρουν·", "st": "7.21"}, {"sp": "N", "t": "ὁ δὲ Γύλιππος ἐπειδὴ παρεσκευάσατο τὸ ναυτικόν, ἀγαγὼν ὑπὸ νύκτα πᾶσαν τὴν στρατιὰν τὴν πεζὴν αὐτὸς μὲν τοῖς ἐν τῷ Πλημμυρίῳ τείχεσι κατὰ γῆν ἔμελλε προσβαλεῖν, αἱ δὲ τριήρεις τῶν Συρακοσίων ἅμα καὶ ἀπὸ ξυνθήματος πέντε μὲν καὶ τριάκοντα ἐκ τοῦ μεγάλου λιμένος ἐπέπλεον, αἱ δὲ πέντε καὶ τεσσαράκοντα ἐκ τοῦ ἐλάσσονος, οὗ ἦν καὶ τὸ νεώριον αὐτοῖς, [καὶ] περιέπλεον βουλόμενοι πρὸς τὰς ἐντὸς προσμεῖξαι καὶ ἅμα ἐπιπλεῖν τῷ Πλημμυρίῳ, ὅπως οἱ Ἀθηναῖοι ἀμφοτέρωθεν θορυβῶνται. οἱ δ’ Ἀθηναῖοι διὰ τάχους ἀντιπληρώσαντες ἑξήκοντα ναῦς ταῖς μὲν πέντε καὶ εἴκοσι πρὸς τὰς πέντε καὶ τριάκοντα τῶν Συρακοσίων τὰς ἐν τῷ μεγάλῳ λιμένι ἐναυμάχουν, ταῖς δ’ ἐπιλοίποις ἀπήντων ἐπὶ τὰς ἐκ τοῦ νεωρίου περιπλεούσας. καὶ εὐθὺς πρὸ τοῦ στόματος τοῦ μεγάλου λιμένος ἐναυμάχουν, καὶ ἀντεῖχον ἀλλήλοις ἐπὶ πολύ, οἱ μὲν βιάσασθαι βουλόμενοι τὸν ἔσπλουν, οἱ δὲ κωλύειν.", "st": "7.22"}, {"sp": "N", "t": "ἐν τούτῳ δ’ ὁ Γύλιππος τῶν ἐν τῷ Πλημμυρίῳ Ἀθηναίων πρὸς τὴν θάλασσαν ἐπικαταβάντων καὶ τῇ ναυμαχίᾳ τὴν γνώμην προσεχόντων φθάνει προσπεσὼν ἅμα τῇ ἕῳ αἰφνιδίως τοῖς τείχεσι, καὶ αἱρεῖ τὸ μέγιστον πρῶτον, ἔπειτα δὲ καὶ τὰ ἐλάσσω δύο, οὐχ ὑπομεινάντων τῶν φυλάκων, ὡς εἶδον τὸ μέγιστον ῥᾳδίως ληφθέν. καὶ ἐκ μὲν τοῦ πρώτου ἁλόντος χαλεπῶς οἱ ἄνθρωποι, ὅσοι καὶ ἐς τὰ πλοῖα καὶ ὁλκάδα τινὰ κατέφυγον, ἐς τὸ στρατόπεδον ἐξεκομίζοντο· τῶν γὰρ Συρακοσίων ταῖς ἐν τῷ μεγάλῳ λιμένι ναυσὶ κρατούντων τῇ ναυμαχίᾳ ὑπὸ τριήρους μιᾶς καὶ εὖ πλεούσης ἐπεδιώκοντο· ἐπειδὴ δὲ τὰ δύο τειχίσματα ἡλίσκετο, ἐν τούτῳ καὶ οἱ Συρακόσιοι ἐτύγχανον ἤδη νικώμενοι καὶ οἱ ἐξ αὐτῶν φεύγοντες ῥᾷον παρέπλευσαν. αἱ γὰρ τῶν Συρακοσίων αἱ πρὸ τοῦ στόματος νῆες ναυμαχοῦσαι βιασάμεναι τὰς τῶν Ἀθηναίων ναῦς οὐδενὶ κόσμῳ ἐσέπλεον, καὶ ταραχθεῖσαι περὶ ἀλλήλας παρέδοσαν τὴν νίκην τοῖς Ἀθηναίοις· ταύτας τε γὰρ ἔτρεψαν καὶ ὑφ’ ὧν τὸ πρῶτον ἐνικῶντο ἐν τῷ λιμένι. καὶ ἕνδεκα μὲν ναῦς τῶν Συρακοσίων κατέδυσαν, καὶ τοὺς πολλοὺς τῶν ἀνθρώπων ἀπέκτειναν, πλὴν ὅσον ἐκ τριῶν νεῶν οὓς ἐζώγρησαν· τῶν δὲ σφετέρων τρεῖς νῆες διεφθάρησαν. τὰ δὲ ναυάγια ἀνελκύσαντες τῶν Συρακοσίων καὶ τροπαῖον ἐν τῷ νησιδίῳ στήσαντες τῷ πρὸ τοῦ Πλημμυρίου, ἀνεχώρησαν ἐς τὸ ἑαυτῶν στρατόπεδον.", "st": "7.23"}, {"sp": "N", "t": "οἱ δὲ Συρακόσιοι κατὰ μὲν τὴν ναυμαχίαν οὕτως ἐπεπράγεσαν, τὰ δ’ ἐν τῷ Πλημμυρίῳ τείχη εἶχον, καὶ τροπαῖα ἔστησαν αὐτῶν τρία. καὶ τὸ μὲν ἕτερον τοῖν δυοῖν τειχοῖν τοῖν ὕστερον ληφθέντοιν κατέβαλον, τὰ δὲ δύο ἐπισκευάσαντες ἐφρούρουν. ἄνθρωποι δ’ ἐν τῶν τειχῶν τῇ ἁλώσει ἀπέθανον καὶ ἐζωγρήθησαν πολλοί, καὶ χρήματα πολλὰ τὰ ξύμπαντα ἑάλω· ὥσπερ γὰρ ταμιείῳ χρωμένων τῶν Ἀθηναίων τοῖς τείχεσι πολλὰ μὲν ἐμπόρων χρήματα καὶ σῖτος ἐνῆν, πολλὰ δὲ καὶ τῶν τριηράρχων, ἐπεὶ καὶ ἱστία τεσσαράκοντα τριήρων καὶ τἆλλα σκεύη ἐγκατελήφθη καὶ τριήρεις ἀνειλκυσμέναι τρεῖς. μέγιστόν τε καὶ ἐν τοῖς πρῶτον ἐκάκωσε τὸ στράτευμα τὸ τῶν Ἀθηναίων ἡ τοῦ Πλημμυρίου λῆψις· οὐ γὰρ ἔτι οὐδ’ οἱ ἔσπλοι ἀσφαλεῖς ἦσαν τῆς ἐπαγωγῆς τῶν ἐπιτηδείων (οἱ γὰρ Συρακόσιοι ναυσὶν αὐτόθι ἐφορμοῦντες ἐκώλυον, καὶ διὰ μάχης ἤδη ἐγίγνοντο αἱ ἐσκομιδαί), ἔς τε τἆλλα κατάπληξιν παρέσχε καὶ ἀθυμίαν τῷ στρατεύματι.", "st": "7.24"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο ναῦς τε ἐκπέμπουσι δώδεκα οἱ Συρακόσιοι καὶ Ἀγάθαρχον ἐπ’ αὐτῶν Συρακόσιον ἄρχοντα. καὶ αὐτῶν μία μὲν ἐς Πελοπόννησον ᾤχετο, πρέσβεις ἄγουσα οἵπερ τά τε σφέτερα φράσουσιν ὅτι ἐν ἐλπίσιν εἰσὶ καὶ τὸν ἐκεῖ πόλεμον ἔτι μᾶλλον ἐποτρυνοῦσι γίγνεσθαι· αἱ δ’ ἕνδεκα νῆες πρὸς τὴν Ἰταλίαν ἔπλευσαν, πυνθανόμεναι πλοῖα τοῖς Ἀθηναίοις γέμοντα χρημάτων προσπλεῖν. καὶ τῶν τε πλοίων ἐπιτυχοῦσαι τὰ πολλὰ διέφθειραν καὶ ξύλα ναυπηγήσιμα ἐν τῇ Καυλωνιάτιδι κατέκαυσαν, ἃ τοῖς Ἀθηναίοις ἑτοῖμα ἦν. ἔς τε Λοκροὺς μετὰ ταῦτα ἦλθον, καὶ ὁρμουσῶν αὐτῶν κατέπλευσε μία τῶν ὁλκάδων τῶν ἀπὸ Πελοποννήσου ἄγουσα Θεσπιῶν ὁπλίτας· καὶ ἀναλαβόντες αὐτοὺς οἱ Συρακόσιοι ἐπὶ τὰς ναῦς παρέπλεον ἐπ’ οἴκου. φυλάξαντες δ’ αὐτοὺς οἱ Ἀθηναῖοι εἴκοσι ναυσὶ πρὸς τοῖς Μεγάροις μίαν μὲν ναῦν λαμβάνουσιν αὐτοῖς ἀνδράσι, τὰς δ’ ἄλλας οὐκ ἐδυνήθησαν, ἀλλ’ ἀποφεύγουσιν ἐς τὰς Συρακούσας.", "st": "7.25"}, {"sp": "N", "t": "ἐγένετο δὲ καὶ περὶ τῶν σταυρῶν ἀκροβολισμὸς ἐν τῷ λιμένι, οὓς οἱ Συρακόσιοι πρὸ τῶν παλαιῶν νεωσοίκων κατέπηξαν ἐν τῇ θαλάσσῃ, ὅπως αὐτοῖς αἱ νῆες ἐντὸς ὁρμοῖεν καὶ οἱ Ἀθηναῖοι ἐπιπλέοντες μὴ βλάπτοιεν ἐμβάλλοντες. προσαγαγόντες γὰρ ναῦν μυριοφόρον αὐτοῖς οἱ Ἀθηναῖοι, πύργους τε ξυλίνους ἔχουσαν καὶ παραφράγματα, ἔκ τε τῶν ἀκάτων ὤνευον ἀναδούμενοι τοὺς σταυροὺς καὶ ἀνέκλων καὶ κατακολυμβῶντες ἐξέπριον. οἱ δὲ Συρακόσιοι ἀπὸ τῶν νεωσοίκων ἔβαλλον· οἱ δ’ ἐκ τῆς ὁλκάδος ἀντέβαλλον, καὶ τέλος τοὺς πολλοὺς τῶν σταυρῶν ἀνεῖλον οἱ Ἀθηναῖοι. χαλεπωτάτη δ’ ἦν τῆς σταυρώσεως ἡ κρύφιος· ἦσαν γὰρ τῶν σταυρῶν οὓς οὐχ ὑπερέχοντας τῆς θαλάσσης κατέπηξαν, ὥστε δεινὸν ἦν προσπλεῦσαι, μὴ οὐ προϊδών τις ὥσπερ περὶ ἕρμα περιβάλῃ τὴν ναῦν. ἀλλὰ καὶ τούτους κολυμβηταὶ δυόμενοι ἐξέπριον μισθοῦ. ὅμως δ’ αὖθις οἱ Συρακόσιοι ἐσταύρωσαν. πολλὰ δὲ καὶ ἄλλα πρὸς ἀλλήλους οἷον εἰκὸς τῶν στρατοπέδων ἐγγὺς ὄντων καὶ ἀντιτεταγμένων ἐμηχανῶντο καὶ ἀκροβολισμοῖς καὶ πείραις παντοίαις ἐχρῶντο.", "st": "7.25"}, {"sp": "N", "t": "ἔπεμψαν δὲ καὶ ἐς τὰς πόλεις πρέσβεις οἱ Συρακόσιοι Κορινθίων καὶ Ἀμπρακιωτῶν καὶ Λακεδαιμονίων, ἀγγέλλοντας τήν τε τοῦ Πλημμυρίου λῆψιν καὶ τῆς ναυμαχίας πέρι ὡς οὐ τῇ τῶν πολεμίων ἰσχύι μᾶλλον ἢ τῇ σφετέρᾳ ταραχῇ ἡσσηθεῖεν, τά τε ἄλλα [αὖ] δηλώσοντας ὅτι ἐν ἐλπίσιν εἰσὶ καὶ ἀξιώσοντας ξυμβοηθεῖν ἐπ’ αὐτοὺς καὶ ναυσὶ καὶ πεζῷ, ὡς καὶ τῶν Ἀθηναίων προσδοκίμων ὄντων ἄλλῃ στρατιᾷ καί, ἢν φθάσωσιν αὐτοὶ πρότερον διαφθείραντες τὸ παρὸν στράτευμα αὐτῶν, διαπεπολεμησόμενον. καὶ οἱ μὲν ἐν τῇ Σικελίᾳ ταῦτα ἔπρασσον.", "st": "7.25"}, {"sp": "N", "t": "ὁ δὲ Δημοσθένης, ἐπεὶ ξυνελέγη αὐτῷ τὸ στράτευμα ὃ ἔδει ἔχοντα ἐς τὴν Σικελίαν βοηθεῖν, ἄρας ἐκ τῆς Αἰγίνης καὶ πλεύσας πρὸς τὴν Πελοπόννησον τῷ τε Χαρικλεῖ καὶ ταῖς τριάκοντα ναυσὶ τῶν Ἀθηναίων ξυμμίσγει, καὶ παραλαβόντες τῶν Ἀργείων ὁπλίτας ἐπὶ τὰς ναῦς ἔπλεον ἐς τὴν Λακωνικήν· καὶ πρῶτον μὲν τῆς Ἐπιδαύρου τι τῆς Λιμηρᾶς ἐδῄωσαν, ἔπειτα σχόντες ἐς τὰ καταντικρὺ Κυθήρων τῆς Λακωνικῆς, ἔνθα τὸ ἱερὸν τοῦ Ἀπόλλωνός ἐστι, τῆς τε γῆς ἔστιν ἃ ἐδῄωσαν καὶ ἐτείχισαν ἰσθμῶδές τι χωρίον, ἵνα δὴ οἵ τε Εἵλωτες τῶν Λακεδαιμονίων αὐτόσε αὐτομολῶσι καὶ ἅμα λῃσταὶ ἐξ αὐτοῦ, ὥσπερ ἐκ τῆς Πύλου, ἁρπαγὴν ποιῶνται. καὶ ὁ μὲν Δημοσθένης εὐθὺς ἐπειδὴ ξυγκατέλαβε τὸ χωρίον παρέπλει ἐπὶ τῆς Κερκύρας, ὅπως καὶ τῶν ἐκεῖθεν ξυμμάχων παραλαβὼν τὸν ἐς τὴν Σικελίαν πλοῦν ὅτι τάχιστα ποιῆται· ὁ δὲ Χαρικλῆς περιμείνας ἕως τὸ χωρίον ἐξετείχισε καὶ καταλιπὼν φυλακὴν αὐτοῦ ἀπεκομίζετο καὶ αὐτὸς ὕστερον ταῖς τριάκοντα ναυσὶν ἐπ’ οἴκου καὶ οἱ Ἀργεῖοι ἅμα.", "st": "7.26"}, {"sp": "N", "t": "ἀφίκοντο δὲ καὶ Θρᾳκῶν τῶν μαχαιροφόρων τοῦ Διακοῦ γένους ἐς τὰς Ἀθήνας πελτασταὶ ἐν τῷ αὐτῷ θέρει τούτῳ τριακόσιοι καὶ χίλιοι, οὓς ἔδει τῷ Δημοσθένει ἐς τὴν Σικελίαν ξυμπλεῖν. οἱ δ’ Ἀθηναῖοι, ὡς ὕστεροι ἧκον, διενοοῦντο αὐτοὺς πάλιν ὅθεν ἦλθον ἐς Θρᾴκην ἀποπέμπειν. τὸ γὰρ ἔχειν πρὸς τὸν ἐκ τῆς Δεκελείας πόλεμον αὐτοὺς πολυτελὲς ἐφαίνετο· δραχμὴν γὰρ τῆς ἡμέρας ἕκαστος ἐλάμβανεν. ἐπειδὴ γὰρ ἡ Δεκέλεια τὸ μὲν πρῶτον ὑπὸ πάσης τῆς στρατιᾶς ἐν τῷ θέρει τούτῳ τειχισθεῖσα, ὕστερον δὲ φρουραῖς ἀπὸ τῶν πόλεων κατὰ διαδοχὴν χρόνου ἐπιούσαις τῇ χώρᾳ ἐπῳκεῖτο, πολλὰ ἔβλαπτε τοὺς Ἀθηναίους, καὶ ἐν τοῖς πρῶτον χρημάτων τ’ ὀλέθρῳ καὶ ἀνθρώπων φθορᾷ ἐκάκωσε τὰ πράγματα. πρότερον μὲν γὰρ βραχεῖαι γιγνόμεναι αἱ ἐσβολαὶ τὸν ἄλλον χρόνον τῆς γῆς ἀπολαύειν οὐκ ἐκώλυον· τότε δὲ ξυνεχῶς ἐπικαθημένων, καὶ ὁτὲ μὲν καὶ πλεόνων ἐπιόντων, ὁτὲ δ’ ἐξ ἀνάγκης τῆς ἴσης φρουρᾶς καταθεούσης τε τὴν χώραν καὶ λῃστείας ποιουμένης, βασιλέως τε παρόντος τοῦ τῶν Λακεδαιμονίων Ἄγιδος, ὃς οὐκ ἐκ παρέργου τὸν πόλεμον ἐποιεῖτο, μεγάλα οἱ Ἀθηναῖοι ἐβλάπτοντο. τῆς τε γὰρ χώρας ἁπάσης ἐστέρηντο, καὶ ἀνδραπόδων πλέον ἢ δύο μυριάδες ηὐτομολήκεσαν, καὶ τούτων τὸ πολὺ μέρος χειροτέχναι, πρόβατά τε πάντα ἀπωλώλει καὶ ὑποζύγια· ἵπποι τε, ὁσημέραι ἐξελαυνόντων τῶν ἱππέων πρός τε τὴν Δεκέλειαν καταδρομὰς ποιουμένων καὶ κατὰ τὴν χώραν φυλασσόντων, οἱ μὲν ἀπεχωλοῦντο ἐν γῇ ἀποκρότῳ τε καὶ ξυνεχῶς ταλαιπωροῦντες, οἱ δ’ ἐτιτρώσκοντο.", "st": "7.27"}, {"sp": "N", "t": "ἥ τε τῶν ἐπιτηδείων παρακομιδὴ ἐκ τῆς Εὐβοίας, πρότερον ἐκ τοῦ Ὠρωποῦ κατὰ γῆν διὰ τῆς Δεκελείας θάσσων οὖσα, περὶ Σούνιον κατὰ θάλασσαν πολυτελὴς ἐγίγνετο· τῶν τε πάντων ὁμοίως ἐπακτῶν ἐδεῖτο ἡ πόλις, καὶ ἀντὶ τοῦ πόλις εἶναι φρούριον κατέστη. πρὸς γὰρ τῇ ἐπάλξει τὴν μὲν ἡμέραν κατὰ διαδοχὴν οἱ Ἀθηναῖοι φυλάσσοντες, τὴν δὲ νύκτα καὶ ξύμπαντες πλὴν τῶν ἱππέων, οἱ μὲν ἐφ’ ὅπλοις † ποιούμενοι †, οἱ δ’ ἐπὶ τοῦ τείχους, καὶ θέρους καὶ χειμῶνος ἐταλαιπωροῦντο. μάλιστα δ’ αὐτοὺς ἐπίεζεν ὅτι δύο πολέμους ἅμα εἶχον, καὶ ἐς φιλονικίαν καθέστασαν τοιαύτην ἣν πρὶν γενέσθαι ἠπίστησεν ἄν τις ἀκούσας. τὸ γὰρ αὐτοὺς πολιορκουμένους ἐπιτειχισμῷ ὑπὸ Πελοποννησίων μηδ’ ὣς ἀποστῆναι ἐκ Σικελίας, ἀλλ’ ἐκεῖ Συρακούσας τῷ αὐτῷ τρόπῳ ἀντιπολιορκεῖν, πόλιν οὐδὲν ἐλάσσω αὐτήν γε καθ’ αὑτὴν τῆς τῶν Ἀθηναίων, καὶ τὸν παράλογον τοσοῦτον ποιῆσαι τοῖς Ἕλλησι τῆς δυνάμεως καὶ τόλμης, ὅσον κατ’ ἀρχὰς τοῦ πολέμου οἱ μὲν ἐνιαυτόν, οἱ δὲ δύο, οἱ δὲ τριῶν γε ἐτῶν οὐδεὶς πλείω χρόνον ἐνόμιζον περιοίσειν αὐτούς, εἰ οἱ Πελοποννήσιοι ἐσβάλοιεν ἐς τὴν χώραν, ὥστε ἔτει ἑπτακαιδεκάτῳ μετὰ τὴν πρώτην ἐσβολὴν ἦλθον ἐς Σικελίαν ἤδη τῷ πολέμῳ κατὰ πάντα τετρυχωμένοι, καὶ πόλεμον οὐδὲν ἐλάσσω προσανείλοντο τοῦ πρότερον ὑπάρχοντος ἐκ Πελοποννήσου. δι’ ἃ καὶ τότε ὑπό τε τῆς Δεκελείας πολλὰ βλαπτούσης καὶ τῶν ἄλλων ἀναλωμάτων μεγάλων προσπιπτόντων ἀδύνατοι ἐγένοντο τοῖς χρήμασιν. καὶ τὴν εἰκοστὴν ὑπὸ τοῦτον τὸν χρόνον τῶν κατὰ θάλασσαν ἀντὶ τοῦ φόρου τοῖς ὑπηκόοις ἐποίησαν, πλείω νομίζοντες ἂν σφίσι χρήματα οὕτω προσιέναι. αἱ μὲν γὰρ δαπάναι οὐχ ὁμοίως καὶ πρίν, ἀλλὰ πολλῷ μείζους καθέστασαν, ὅσῳ καὶ μείζων ὁ πόλεμος ἦν· αἱ δὲ πρόσοδοι ἀπώλλυντο.", "st": "7.28"}, {"sp": "N", "t": "τοὺς οὖν Θρᾷκας τοὺς τῷ Δημοσθένει ὑστερήσαντας διὰ τὴν παροῦσαν ἀπορίαν τῶν χρημάτων οὐ βουλόμενοι δαπανᾶν εὐθὺς ἀπέπεμπον, προστάξαντες κομίσαι αὐτοὺς Διειτρέφει, καὶ εἰπόντες ἅμα ἐν τῷ παράπλῳ (ἐπορεύοντο γὰρ δι’ Εὐρίπου) καὶ τοὺς πολεμίους, ἤν τι δύνηται, ἀπ’ αὐτῶν βλάψαι. ὁ δὲ ἔς τε τὴν Τάναγραν ἀπεβίβασεν αὐτοὺς καὶ ἁρπαγήν τινα ἐποιήσατο διὰ τάχους καὶ ἐκ Χαλκίδος τῆς Εὐβοίας ἀφ’ ἑσπέρας διέπλευσε τὸν Εὔριπον καὶ ἀποβιβάσας ἐς τὴν Βοιωτίαν ἦγεν αὐτοὺς ἐπὶ Μυκαλησσόν. καὶ τὴν μὲν νύκτα λαθὼν πρὸς τῷ Ἑρμαίῳ ηὐλίσατο (ἀπέχει δὲ τῆς Μυκαλησσοῦ ἑκκαίδεκα μάλιστα σταδίους), ἅμα δὲ τῇ ἡμέρᾳ τῇ πόλει προσέκειτο οὔσῃ οὐ μεγάλῃ, καὶ αἱρεῖ ἀφυλάκτοις τε ἐπιπεσὼν καὶ ἀπροσδοκήτοις μὴ ἄν ποτέ τινας σφίσιν ἀπὸ θαλάσσης τοσοῦτον ἐπαναβάντας ἐπιθέσθαι, τοῦ τείχους ἀσθενοῦς ὄντος καὶ ἔστιν ᾗ καὶ πεπτωκότος, τοῦ δὲ βραχέος ᾠκοδομημένου, καὶ πυλῶν ἅμα διὰ τὴν ἄδειαν ἀνεῳγμένων. ἐσπεσόντες δὲ οἱ Θρᾷκες ἐς τὴν Μυκαλησσὸν τάς τε οἰκίας καὶ τὰ ἱερὰ ἐπόρθουν καὶ τοὺς ἀνθρώπους ἐφόνευον φειδόμενοι οὔτε πρεσβυτέρας οὔτε νεωτέρας ἡλικίας, ἀλλὰ πάντας ἑξῆς, ὅτῳ ἐντύχοιεν, καὶ παῖδας καὶ γυναῖκας κτείνοντες, καὶ προσέτι καὶ ὑποζύγια καὶ ὅσα ἄλλα ἔμψυχα ἴδοιεν· τὸ γὰρ γένος τὸ τῶν Θρᾳκῶν ὁμοῖα τοῖς μάλιστα τοῦ βαρβαρικοῦ, ἐν ᾧ ἂν θαρσήσῃ, φονικώτατόν ἐστιν. καὶ τότε ἄλλη τε ταραχὴ οὐκ ὀλίγη καὶ ἰδέα πᾶσα καθειστήκει ὀλέθρου, καὶ ἐπιπεσόντες διδασκαλείῳ παίδων, ὅπερ μέγιστον ἦν αὐτόθι καὶ ἄρτι ἔτυχον οἱ παῖδες ἐσεληλυθότες, κατέκοψαν πάντας· καὶ ξυμφορὰ τῇ πόλει πάσῃ οὐδεμιᾶς ἥσσων μᾶλλον ἑτέρας ἀδόκητός τε ἐπέπεσεν αὕτη καὶ δεινή.", "st": "7.29"}, {"sp": "N", "t": "οἱ δὲ Θηβαῖοι αἰσθόμενοι ἐβοήθουν, καὶ καταλαβόντες προκεχωρηκότας ἤδη τοὺς Θρᾷκας οὐ πολὺ τήν τε λείαν ἀφείλοντο καὶ αὐτοὺς φοβήσαντες καταδιώκουσιν ἐπὶ τὸν Εὔριπον καὶ τὴν θάλασσαν, οὗ αὐτοῖς τὰ πλοῖα ἃ ἤγαγεν ὥρμει. καὶ ἀποκτείνουσιν αὐτῶν ἐν τῇ ἐσβάσει τοὺς πλείστους οὔτε ἐπισταμένους νεῖν τῶν τε ἐν τοῖς πλοίοις, ὡς ἑώρων τὰ ἐν τῇ γῇ, ὁρμισάντων ἔξω τοξεύματος τὰ πλοῖα, ἐπεὶ ἔν γε τῇ ἄλλῃ ἀναχωρήσει οὐκ ἀτόπως οἱ Θρᾷκες πρὸς τὸ τῶν Θηβαίων ἱππικόν, ὅπερ πρῶτον προσέκειτο, προεκθέοντές τε καὶ ξυστρεφόμενοι ἐν ἐπιχωρίῳ τάξει τὴν φυλακὴν ἐποιοῦντο, καὶ ὀλίγοι αὐτῶν ἐν τούτῳ διεφθάρησαν. μέρος δέ τι καὶ ἐν τῇ πόλει αὐτῇ δι’ ἁρπαγὴν ἐγκαταληφθὲν ἀπώλετο. οἱ δὲ ξύμπαντες τῶν Θρᾳκῶν πεντήκοντα καὶ διακόσιοι ἀπὸ τριακοσίων καὶ χιλίων ἀπέθανον. διέφθειραν δὲ καὶ τῶν Θηβαίων καὶ τῶν ἄλλων οἳ ξυνεβοήθησαν ἐς εἴκοσι μάλιστα ἱππέας τε καὶ ὁπλίτας ὁμοῦ καὶ Θηβαίων τῶν βοιωταρχῶν Σκιρφώνδαν· τῶν δὲ Μυκαλησσίων μέρος τι ἀπανηλώθη. τὰ μὲν κατὰ τὴν Μυκαλησσὸν πάθει χρησαμένην οὐδενὸς ὡς ἐπὶ μεγέθει τῶν κατὰ τὸν πόλεμον ἧσσον ὀλοφύρασθαι ἀξίῳ τοιαῦτα ξυνέβη.", "st": "7.30"}, {"sp": "N", "t": "ὁ δὲ Δημοσθένης τότε ἀποπλέων ἐπὶ τῆς Κερκύρας μετὰ τὴν ἐκ τῆς Λακωνικῆς τείχισιν, ὁλκάδα ὁρμοῦσαν ἐν Φειᾷ τῇ Ἠλείων εὑρών, ἐν ᾗ οἱ Κορίνθιοι ὁπλῖται ἐς τὴν Σικελίαν ἔμελλον περαιοῦσθαι, αὐτὴν μὲν διαφθείρει, οἱ δ’ ἄνδρες ἀποφυγόντες ὕστερον λαβόντες ἄλλην ἔπλεον. καὶ μετὰ τοῦτο ἀφικόμενος ὁ Δημοσθένης ἐς τὴν Ζάκυνθον καὶ Κεφαλληνίαν ὁπλίτας τε παρέλαβε καὶ ἐκ τῆς Ναυπάκτου τῶν Μεσσηνίων μετεπέμψατο καὶ ἐς τὴν ἀντιπέρας ἤπειρον τῆς Ἀκαρνανίας διέβη, ἐς Ἀλύζιάν τε καὶ Ἀνακτόριον, ὃ αὐτοὶ εἶχον. ὄντι δ’ αὐτῷ περὶ ταῦτα ὁ Εὐρυμέδων ἀπαντᾷ ἐκ τῆς Σικελίας ἀποπλέων, ὃς τότε τοῦ χειμῶνος τὰ χρήματα ἄγων τῇ στρατιᾷ ἀπεπέμφθη, καὶ ἀγγέλλει τά τε ἄλλα καὶ ὅτι πύθοιτο κατὰ πλοῦν ἤδη ὢν τὸ Πλημμύριον ὑπὸ τῶν Συρακοσίων ἑαλωκός. ἀφικνεῖται δὲ καὶ Κόνων παρ’ αὐτούς, ὃς ἦρχε Ναυπάκτου, ἀγγέλλων ὅτι αἱ πέντε καὶ εἴκοσι νῆες τῶν Κορινθίων αἱ σφίσιν ἀνθορμοῦσαι οὔτε καταλύουσι τὸν πόλεμον ναυμαχεῖν τε μέλλουσιν· πέμπειν οὖν ἐκέλευεν αὐτοὺς ναῦς, ὡς οὐχ ἱκανὰς οὔσας δυοῖν δεούσας εἴκοσι τὰς ἑαυτῶν πρὸς τὰς ἐκείνων πέντε καὶ εἴκοσι ναυμαχεῖν. τῷ μὲν οὖν Κόνωνι δέκα ναῦς ὁ Δημοσθένης καὶ ὁ Εὐρυμέδων τὰς ἄριστα σφίσι πλεούσας ἀφ’ ὧν αὐτοὶ εἶχον ξυμπέμπουσι πρὸς τὰς ἐν τῇ Ναυπάκτῳ· αὐτοὶ δὲ τὰ περὶ τῆς στρατιᾶς τὸν ξύλλογον ἡτοιμάζοντο, Εὐρυμέδων μὲν ἐς τὴν Κέρκυραν πλεύσας καὶ πέντε καὶ δέκα τε ναῦς πληροῦν κελεύσας αὐτοὺς καὶ ὁπλίτας καταλεγόμενος (ξυνῆρχε γὰρ ἤδη Δημοσθένει ἀποτραπόμενος, ὥσπερ καὶ ᾑρέθη), Δημοσθένης δ’ ἐκ τῶν περὶ τὴν Ἀκαρνανίαν χωρίων σφενδονήτας τε καὶ ἀκοντιστὰς ξυναγείρων.", "st": "7.31"}, {"sp": "N", "t": "οἱ δ’ ἐκ τῶν Συρακουσῶν τότε μετὰ τὴν τοῦ Πλημμυρίου ἅλωσιν πρέσβεις οἰχόμενοι ἐς τὰς πόλεις ἐπειδὴ ἔπεισάν τε καὶ ξυναγείραντες ἔμελλον ἄξειν τὸν στρατόν, ὁ Νικίας προπυθόμενος πέμπει ἐς τῶν Σικελῶν τοὺς τὴν δίοδον ἔχοντας καὶ σφίσι ξυμμάχους, Κεντόριπάς τε καὶ Ἀλικυαίους καὶ ἄλλους, ὅπως μὴ διαφρήσωσι τοὺς πολεμίους, ἀλλὰ ξυστραφέντες κωλύσωσι διελθεῖν· ἄλλῃ γὰρ αὐτοὺς οὐδὲ πειράσειν· Ἀκραγαντῖνοι γὰρ οὐκ ἐδίδοσαν διὰ τῆς ἑαυτῶν ὁδόν. πορευομένων δ’ ἤδη τῶν Σικελιωτῶν οἱ Σικελοί, καθάπερ ἐδέοντο οἱ Ἀθηναῖοι, ἐνέδραν τινὰ τριχῇ ποιησάμενοι, ἀφυλάκτοις τε καὶ ἐξαίφνης ἐπιγενόμενοι διέφθειραν ἐς ὀκτακοσίους μάλιστα καὶ τοὺς πρέσβεις πλὴν ἑνὸς τοῦ Κορινθίου πάντας· οὗτος δὲ τοὺς διαφυγόντας ἐς πεντακοσίους καὶ χιλίους ἐκόμισεν ἐς τὰς Συρακούσας.", "st": "7.32"}, {"sp": "N", "t": "καὶ περὶ τὰς αὐτὰς ἡμέρας καὶ οἱ Καμαριναῖοι ἀφικνοῦνται αὐτοῖς βοηθοῦντες, πεντακόσιοι μὲν ὁπλῖται, τριακόσιοι δὲ ἀκοντισταὶ καὶ τοξόται τριακόσιοι. ἔπεμψαν δὲ καὶ οἱ Γελῷοι ναυτικόν τε ἐς πέντε ναῦς καὶ ἀκοντιστὰς τετρακοσίους καὶ ἱππέας διακοσίους. σχεδὸν γάρ τι ἤδη πᾶσα ἡ Σικελία πλὴν Ἀκραγαντίνων (οὗτοι δ’ οὐδὲ μεθ’ ἑτέρων ἦσαν), οἱ δ’ ἄλλοι ἐπὶ τοὺς Ἀθηναίους μετὰ τῶν Συρακοσίων οἱ πρότερον περιορώμενοι ξυστάντες ἐβοήθουν.", "st": "7.33"}, {"sp": "N", "t": "καὶ οἱ μὲν Συρακόσιοι, ὡς αὐτοῖς τὸ ἐν τοῖς Σικελοῖς πάθος ἐγένετο, ἐπέσχον τὸ εὐθέως τοῖς Ἀθηναίοις ἐπιχειρεῖν· ὁ δὲ Δημοσθένης καὶ Εὐρυμέδων, ἑτοίμης ἤδη τῆς στρατιᾶς οὔσης ἔκ τε τῆς Κερκύρας καὶ ἀπὸ τῆς ἠπείρου, ἐπεραιώθησαν ξυμπάσῃ τῇ στρατιᾷ τὸν Ἰόνιον ἐπ’ ἄκραν Ἰαπυγίαν· καὶ ὁρμηθέντες αὐτόθεν κατίσχουσιν ἐς τὰς Χοιράδας νήσους Ἰαπυγίας, καὶ ἀκοντιστάς τέ τινας τῶν Ἰαπύγων πεντήκοντα καὶ ἑκατὸν τοῦ Μεσσαπίου ἔθνους ἀναβιβάζονται ἐπὶ τὰς ναῦς, καὶ τῷ Ἄρτᾳ, ὅσπερ καὶ τοὺς ἀκοντιστὰς δυνάστης ὢν παρέσχετο αὐτοῖς, ἀνανεωσάμενοί τινα παλαιὰν φιλίαν ἀφικνοῦνται ἐς Μεταπόντιον τῆς Ἰταλίας. καὶ τοὺς Μεταποντίους πείσαντες κατὰ τὸ ξυμμαχικὸν ἀκοντιστάς τε ξυμπέμπειν τριακοσίους καὶ τριήρεις δύο καὶ ἀναλαβόντες ταῦτα παρέπλευσαν ἐς Θουρίαν. καὶ καταλαμβάνουσι νεωστὶ στάσει τοὺς τῶν Ἀθηναίων ἐναντίους ἐκπεπτωκότας· καὶ βουλόμενοι τὴν στρατιὰν αὐτόθι πᾶσαν ἁθροίσαντες εἴ τις ὑπελέλειπτο ἐξετάσαι, καὶ τοὺς Θουρίους πεῖσαι σφίσι ξυστρατεύειν τε ὡς προθυμότατα καί, ἐπειδήπερ ἐν τούτῳ τύχης εἰσί, τοὺς αὐτοὺς ἐχθροὺς καὶ φίλους τοῖς Ἀθηναίοις νομίζειν, περιέμενον ἐν τῇ Θουρίᾳ καὶ ἔπρασσον ταῦτα.", "st": "7.33"}, {"sp": "N", "t": "οἱ δὲ Πελοποννήσιοι περὶ τὸν αὐτὸν χρόνον τοῦτον οἱ ἐν ταῖς πέντε καὶ εἴκοσι ναυσίν, οἵπερ τῶν ὁλκάδων ἕνεκα τῆς ἐς Σικελίαν κομιδῆς ἀνθώρμουν πρὸς τὰς ἐν Ναυπάκτῳ ναῦς, παρασκευασάμενοι ὡς ἐπὶ ναυμαχίᾳ καὶ προσπληρώσαντες ἔτι ναῦς ὥστε ὀλίγῳ ἐλάσσους εἶναι αὐτοῖς τῶν Ἀττικῶν νεῶν, ὁρμίζονται κατὰ Ἐρινεὸν τῆς Ἀχαΐας ἐν τῇ Ῥυπικῇ. καὶ αὐτοῖς τοῦ χωρίου μηνοειδοῦς ὄντος ἐφ’ ᾧ ὥρμουν, ὁ μὲν πεζὸς ἑκατέρωθεν προσβεβοηθηκὼς τῶν τε Κορινθίων καὶ τῶν αὐτόθεν ξυμμάχων ἐπὶ ταῖς προανεχούσαις ἄκραις παρετέτακτο, αἱ δὲ νῆες τὸ μεταξὺ εἶχον ἐμφάρξασαι· ἦρχε δὲ τοῦ ναυτικοῦ Πολυάνθης Κορίνθιος. οἱ δ’ Ἀθηναῖοι ἐκ τῆς Ναυπάκτου τριάκοντα ναυσὶ καὶ τρισίν (ἦρχε δὲ αὐτῶν Δίφιλος) ἐπέπλευσαν αὐτοῖς. καὶ οἱ Κορίνθιοι τὸ μὲν πρῶτον ἡσύχαζον, ἔπειτα ἀρθέντος αὐτοῖς τοῦ σημείου, ἐπεὶ καιρὸς ἐδόκει εἶναι, ὥρμησαν ἐπὶ τοὺς Ἀθηναίους καὶ ἐναυμάχουν. καὶ χρόνον ἀντεῖχον πολὺν ἀλλήλοις. καὶ τῶν μὲν Κορινθίων τρεῖς νῆες διαφθείρονται, τῶν δ’ Ἀθηναίων κατέδυ μὲν οὐδεμία ἁπλῶς, ἑπτὰ δέ τινες ἄπλοι ἐγένοντο ἀντίπρῳροι ἐμβαλλόμεναι καὶ ἀναρραγεῖσαι τὰς παρεξειρεσίας ὑπὸ τῶν Κορινθίων νεῶν ἐπ’ αὐτὸ τοῦτο παχυτέρας τὰς ἐπωτίδας ἐχουσῶν. ναυμαχήσαντες δὲ ἀντίπαλα μὲν καὶ ὡς αὐτοὺς ἑκατέρους ἀξιοῦν νικᾶν, ὅμως δὲ τῶν ναυαγίων κρατησάντων τῶν Ἀθηναίων διά τε τὴν τοῦ ἀνέμου ἄπωσιν αὐτῶν ἐς τὸ πέλαγος καὶ διὰ τὴν τῶν Κορινθίων οὐκέτι ἐπαναγωγήν, διεκρίθησαν ἀπ’ ἀλλήλων, καὶ δίωξις οὐδεμία ἐγένετο, οὐδ’ ἄνδρες οὐδετέρων ἑάλωσαν· οἱ μὲν γὰρ Κορίνθιοι καὶ Πελοποννήσιοι πρὸς τῇ γῇ ναυμαχοῦντες ῥᾳδίως διεσῴζοντο, τῶν δὲ Ἀθηναίων οὐδεμία κατέδυ ναῦς. ἀποπλευσάντων δὲ τῶν Ἀθηναίων ἐς τὴν Ναύπακτον οἱ Κορίνθιοι εὐθὺς τροπαῖον ἔστησαν ὡς νικῶντες, ὅτι πλείους τῶν ἐναντίων ναῦς ἄπλους ἐποίησαν καὶ νομίσαντες αὐτοὶ οὐχ ἡσσᾶσθαι δι’ ὅπερ οὐδ’ οἱ ἕτεροι νικᾶν· οἵ τε γὰρ Κορίνθιοι ἡγήσαντο κρατεῖν εἰ μὴ καὶ πολὺ ἐκρατοῦντο, οἵ τ’ Ἀθηναῖοι ἐνόμιζον ἡσσᾶσθαι ὅτι οὐ πολὺ ἐνίκων. ἀποπλευσάντων δὲ τῶν Πελοποννησίων καὶ τοῦ πεζοῦ διαλυθέντος οἱ Ἀθηναῖοι ἔστησαν τροπαῖον καὶ αὐτοὶ ἐν τῇ Ἀχαΐᾳ ὡς νικήσαντες, ἀπέχον τοῦ Ἐρινεοῦ, ἐν ᾧ οἱ Κορίνθιοι ὥρμουν, ὡς εἴκοσι σταδίους. καὶ ἡ μὲν ναυμαχία οὕτως ἐτελεύτα.", "st": "7.34"}, {"sp": "N", "t": "ὁ δὲ Δημοσθένης καὶ Εὐρυμέδων, ἐπειδὴ ξυστρατεύειν αὐτοῖς οἱ Θούριοι παρεσκευάσθησαν ἑπτακοσίοις μὲν ὁπλίταις, τριακοσίοις δὲ ἀκοντισταῖς, τὰς μὲν ναῦς παραπλεῖν ἐκέλευον ἐπὶ τῆς Κροτωνιάτιδος, αὐτοὶ δὲ τὸν πεζὸν πάντα ἐξετάσαντες πρῶτον ἐπὶ τῷ Συβάρει ποταμῷ ἦγον διὰ τῆς Θουριάδος γῆς. καὶ ὡς ἐγένοντο ἐπὶ τῷ Ὑλίᾳ ποταμῷ καὶ αὐτοῖς οἱ Κροτωνιᾶται προσπέμψαντες εἶπον οὐκ ἂν σφίσι βουλομένοις εἶναι διὰ τῆς γῆς σφῶν τὸν στρατὸν ἰέναι, ἐπικαταβάντες ηὐλίσαντο πρὸς τὴν θάλασσαν καὶ τὴν ἐκβολὴν τοῦ Ὑλίου· καὶ αἱ νῆες αὐτοῖς ἐς τὸ αὐτὸ ἀπήντων. τῇ δ’ ὑστεραίᾳ ἀναβιβασάμενοι παρέπλεον, ἴσχοντες πρὸς ταῖς πόλεσι πλὴν Λοκρῶν, ἕως ἀφίκοντο ἐπὶ Πέτραν τῆς Ῥηγίνης.", "st": "7.35"}, {"sp": "N", "t": "οἱ δὲ Συρακόσιοι ἐν τούτῳ πυνθανόμενοι αὐτῶν τὸν ἐπίπλουν αὖθις ταῖς ναυσὶν ἀποπειρᾶσαι ἐβούλοντο καὶ τῇ ἄλλῃ παρασκευῇ τοῦ πεζοῦ, ἥνπερ ἐπ’ αὐτὸ τοῦτο πρὶν ἐλθεῖν αὐτοὺς φθάσαι βουλόμενοι ξυνέλεγον. παρεσκευάσαντο δὲ τό τε ἄλλο ναυτικὸν ὡς ἐκ τῆς προτέρας ναυμαχίας τι πλέον ἐνεῖδον σχήσοντες, καὶ τὰς πρῴρας τῶν νεῶν ξυντεμόντες ἐς ἔλασσον στεριφωτέρας ἐποίησαν, καὶ τὰς ἐπωτίδας ἐπέθεσαν ταῖς πρῴραις παχείας, καὶ ἀντηρίδας ἀπ’ αὐτῶν ὑπέτειναν πρὸς τοὺς τοίχους ὡς ἐπὶ ἓξ πήχεις ἐντός τε καὶ ἔξωθεν· ᾧπερ τρόπῳ καὶ οἱ Κορίνθιοι πρὸς τὰς ἐν τῇ Ναυπάκτῳ ναῦς ἐπισκευασάμενοι πρῴραθεν ἐναυμάχουν. ἐνόμισαν γὰρ οἱ Συρακόσιοι πρὸς τὰς τῶν Ἀθηναίων ναῦς οὐχ ὁμοίως ἀντινεναυπηγημένας, ἀλλὰ λεπτὰ τὰ πρῴραθεν ἐχούσας διὰ τὸ μὴ ἀντιπρῴροις μᾶλλον αὐτοὺς ἢ ἐκ περίπλου ταῖς ἐμβολαῖς χρῆσθαι, οὐκ ἔλασσον σχήσειν, καὶ τὴν ἐν τῷ μεγάλῳ λιμένι ναυμαχίαν, οὐκ ἐν πολλῷ πολλαῖς ναυσὶν οὖσαν, πρὸς ἑαυτῶν ἔσεσθαι· ἀντιπρῴροις γὰρ ταῖς ἐμβολαῖς χρώμενοι ἀναρρήξειν τὰ πρῴραθεν αὐτοῖς, στερίφοις καὶ παχέσι πρὸς κοῖλα καὶ ἀσθενῆ παίοντες τοῖς ἐμβόλοις. τοῖς δὲ Ἀθηναίοις οὐκ ἔσεσθαι σφῶν ἐν στενοχωρίᾳ οὔτε περίπλουν οὔτε διέκπλουν, ᾧπερ τῆς τέχνης μάλιστα ἐπίστευον· αὐτοὶ γὰρ κατὰ τὸ δυνατὸν τὸ μὲν οὐ δώσειν διεκπλεῖν, τὸ δὲ τὴν στενοχωρίαν κωλύσειν ὥστε μὴ περιπλεῖν. τῇ τε πρότερον ἀμαθίᾳ τῶν κυβερνητῶν δοκούσῃ εἶναι, τὸ ἀντίπρῳρον ξυγκροῦσαι, μάλιστ’ ἂν αὐτοὶ χρήσασθαι· πλεῖστον γὰρ ἐν αὐτῷ σχήσειν· τὴν γὰρ ἀνάκρουσιν οὐκ ἔσεσθαι τοῖς Ἀθηναίοις ἐξωθουμένοις ἄλλοσε ἢ ἐς τὴν γῆν, καὶ ταύτην δι’ ὀλίγου καὶ ἐς ὀλίγον, κατ’ αὐτὸ τὸ στρατόπεδον τὸ ἑαυτῶν· τοῦ δ’ ἄλλου λιμένος αὐτοὶ κρατήσειν, καὶ ξυμφερομένους αὐτούς, ἤν πῃ βιάζωνται, ἐς ὀλίγον τε καὶ πάντας ἐς τὸ αὐτό, προσπίπτοντας ἀλλήλοις ταράξεσθαι (ὅπερ καὶ ἔβλαπτε μάλιστα τοὺς Ἀθηναίους ἐν ἁπάσαις ταῖς ναυμαχίαις, οὐκ οὔσης αὐτοῖς ἐς πάντα τὸν λιμένα τῆς ἀνακρούσεως, ὥσπερ τοῖς Συρακοσίοις)· περιπλεῦσαι δὲ ἐς τὴν εὐρυχωρίαν, σφῶν ἐχόντων τὴν ἐπίπλευσιν ἀπὸ τοῦ πελάγους τε καὶ ἀνάκρουσιν, οὐ δυνήσεσθαι αὐτούς, ἄλλως τε καὶ τοῦ Πλημμυρίου πολεμίου τε αὐτοῖς ἐσομένου καὶ τοῦ στόματος οὐ μεγάλου ὄντος τοῦ λιμένος.", "st": "7.36"}, {"sp": "N", "t": "τοιαῦτα οἱ Συρακόσιοι πρὸς τὴν ἑαυτῶν ἐπιστήμην τε καὶ δύναμιν ἐπινοήσαντες καὶ ἅμα τεθαρσηκότες μᾶλλον ἤδη ἀπὸ τῆς προτέρας ναυμαχίας, ἐπεχείρουν τῷ τε πεζῷ ἅμα καὶ ταῖς ναυσίν. καὶ τὸν μὲν πεζὸν ὀλίγῳ πρότερον τὸν ἐκ τῆς πόλεως Γύλιππος προεξαγαγὼν προσῆγε τῷ τείχει τῶν Ἀθηναίων, καθ’ ὅσον πρὸς τὴν πόλιν αὐτοῦ ἑώρα· καὶ οἱ ἀπὸ τοῦ Ὀλυμπιείου, οἵ τε ὁπλῖται ὅσοι ἐκεῖ ἦσαν καὶ οἱ ἱππῆς καὶ ἡ γυμνητεία τῶν Συρακοσίων ἐκ τοῦ ἐπὶ θάτερα προσῄει τῷ τείχει· αἱ δὲ νῆες μετὰ τοῦτο εὐθὺς ἐπεξέπλεον τῶν Συρακοσίων καὶ ξυμμάχων. καὶ οἱ Ἀθηναῖοι τὸ πρῶτον αὐτοὺς οἰόμενοι τῷ πεζῷ μόνῳ πειράσειν, ὁρῶντες δὲ καὶ τὰς ναῦς ἐπιφερομένας ἄφνω, ἐθορυβοῦντο, καὶ οἱ μὲν ἐπὶ τὰ τείχη καὶ πρὸ τῶν τειχῶν τοῖς προσιοῦσιν ἀντιπαρετάσσοντο, οἱ δὲ πρὸς τοὺς ἀπὸ τοῦ Ὀλυμπιείου καὶ τῶν ἔξω κατὰ τάχος χωροῦντας ἱππέας τε πολλοὺς καὶ ἀκοντιστὰς ἀντεπεξῇσαν, ἄλλοι δὲ τὰς ναῦς ἐπλήρουν καὶ ἅμα ἐπὶ τὸν αἰγιαλὸν παρεβοήθουν, καὶ ἐπειδὴ πλήρεις ἦσαν, ἀντανῆγον πέντε καὶ ἑβδομήκοντα ναῦς· καὶ τῶν Συρακοσίων ἦσαν ὀγδοήκοντα μάλιστα.", "st": "7.37"}, {"sp": "N", "t": "τῆς δὲ ἡμέρας ἐπὶ πολὺ προσπλέοντες καὶ ἀνακρουόμενοι καὶ πειράσαντες ἀλλήλων καὶ οὐδέτεροι δυνάμενοι ἄξιόν τι λόγου παραλαβεῖν, εἰ μὴ ναῦν μίαν ἢ δύο τῶν Ἀθηναίων οἱ Συρακόσιοι καταδύσαντες, διεκρίθησαν· καὶ ὁ πεζὸς ἅμα ἀπὸ τῶν τειχῶν ἀπῆλθεν.", "st": "7.38"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ οἱ μὲν Συρακόσιοι ἡσύχαζον, οὐδὲν δηλοῦντες ὁποῖόν τι τὸ μέλλον ποιήσουσιν· ὁ δὲ Νικίας ἰδὼν ἀντίπαλα τὰ τῆς ναυμαχίας γενόμενα καὶ ἐλπίζων αὐτοὺς αὖθις ἐπιχειρήσειν τούς τε τριηράρχους ἠνάγκαζεν ἐπισκευάζειν τὰς ναῦς, εἴ τίς τι ἐπεπονήκει, καὶ ὁλκάδας προώρμισε πρὸ τοῦ σφετέρου σταυρώματος, ὃ αὐτοῖς πρὸ τῶν νεῶν ἀντὶ λιμένος κλῃστοῦ ἐν τῇ θαλάσσῃ ἐπεπήγει. διαλειπούσας δὲ τὰς ὁλκάδας ὅσον δύο πλέθρα ἀπ’ ἀλλήλων κατέστησεν, ὅπως, εἴ τις βιάζοιτο ναῦς, εἴη κατάφευξις ἀσφαλὴς καὶ πάλιν καθ’ ἡσυχίαν ἔκπλους. παρασκευαζόμενοι δὲ ταῦτα ὅλην τὴν ἡμέραν διετέλεσαν οἱ Ἀθηναῖοι μέχρι νυκτός.", "st": "7.38"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ οἱ Συρακόσιοι τῆς μὲν ὥρας πρωίτερον, τῇ δ’ ἐπιχειρήσει τῇ αὐτῇ τοῦ τε πεζοῦ καὶ τοῦ ναυτικοῦ προσέμισγον τοῖς Ἀθηναίοις, καὶ ἀντικαταστάντες ταῖς ναυσὶ τὸν αὐτὸν τρόπον αὖθις ἐπὶ πολὺ διῆγον τῆς ἡμέρας πειρώμενοι ἀλλήλων, πρὶν δὴ Ἀρίστων ὁ Πυρρίχου Κορίνθιος, ἄριστος ὢν κυβερνήτης τῶν μετὰ Συρακοσίων, πείθει τοὺς σφετέρους τοῦ ναυτικοῦ ἄρχοντας, πέμψαντας ὡς τοὺς ἐν τῇ πόλει ἐπιμελομένους, κελεύειν ὅτι τάχιστα τὴν ἀγορὰν τῶν πωλουμένων παρὰ τὴν θάλασσαν μεταστῆσαι κομίσαντας, καὶ ὅσα τις ἔχει ἐδώδιμα, πάντας ἐκεῖσε φέροντας ἀναγκάσαι πωλεῖν, ὅπως αὐτοῖς ἐκβιβάσαντες τοὺς ναύτας εὐθὺς παρὰ τὰς ναῦς ἀριστοποιήσωνται, καὶ δι’ ὀλίγου αὖθις καὶ αὐθημερὸν ἀπροσδοκήτοις τοῖς Ἀθηναίοις ἐπιχειρῶσιν.", "st": "7.39"}, {"sp": "N", "t": "καὶ οἱ μὲν πεισθέντες ἔπεμψαν ἄγγελον, καὶ ἡ ἀγορὰ παρεσκευάσθη, καὶ οἱ Συρακόσιοι ἐξαίφνης πρύμναν κρουσάμενοι πάλιν πρὸς τὴν πόλιν ἔπλευσαν καὶ εὐθὺς ἐκβάντες αὐτοῦ ἄριστον ἐποιοῦντο· οἱ δ’ Ἀθηναῖοι νομίσαντες αὐτοὺς ὡς ἡσσημένους σφῶν πρὸς τὴν πόλιν ἀνακρούσασθαι, καθ’ ἡσυχίαν ἐκβάντες τά τε ἄλλα διεπράσσοντο καὶ τὰ ἀμφὶ τὸ ἄριστον ὡς τῆς γε ἡμέρας ταύτης οὐκέτι οἰόμενοι ἂν ναυμαχῆσαι. ἐξαίφνης δὲ οἱ Συρακόσιοι πληρώσαντες τὰς ναῦς ἐπέπλεον αὖθις· οἱ δὲ διὰ πολλοῦ θορύβου καὶ ἄσιτοι οἱ πλείους οὐδενὶ κόσμῳ ἐσβάντες μόλις ποτὲ ἀντανήγοντο. καὶ χρόνον μέν τινα ἀπέσχοντο ἀλλήλων φυλασσόμενοι· ἔπειτα οὐκ ἐδόκει τοῖς Ἀθηναίοις ὑπὸ σφῶν αὐτῶν διαμέλλοντας κόπῳ ἁλίσκεσθαι, ἀλλ’ ἐπιχειρεῖν ὅτι τάχιστα, καὶ ἐπιφερόμενοι ἐκ παρακελεύσεως ἐναυμάχουν. οἱ δὲ Συρακόσιοι δεξάμενοι καὶ ταῖς [τε] ναυσὶν ἀντιπρῴροις χρώμενοι, ὥσπερ διενοήθησαν, τῶν ἐμβόλων τῇ παρασκευῇ ἀνερρήγνυσαν τὰς τῶν Ἀθηναίων ναῦς ἐπὶ πολὺ τῆς παρεξειρεσίας, καὶ οἱ ἀπὸ τῶν καταστρωμάτων αὐτοῖς ἀκοντίζοντες μεγάλα ἔβλαπτον τοὺς Ἀθηναίους, πολὺ δ’ ἔτι μείζω οἱ ἐν τοῖς λεπτοῖς πλοίοις περιπλέοντες τῶν Συρακοσίων καὶ ἔς τε τοὺς ταρσοὺς ὑποπίπτοντες τῶν πολεμίων νεῶν καὶ ἐς τὰ πλάγια παραπλέοντες καὶ ἐξ αὐτῶν ἐς τοὺς ναύτας ἀκοντίζοντες.", "st": "7.40"}, {"sp": "N", "t": "τέλος δὲ τούτῳ τῷ τρόπῳ κατὰ κράτος ναυμαχοῦντες οἱ Συρακόσιοι ἐνίκησαν, καὶ οἱ Ἀθηναῖοι τραπόμενοι διὰ τῶν ὁλκάδων τὴν κατάφευξιν ἐποιοῦντο ἐς τὸν ἑαυτῶν ὅρμον. αἱ δὲ τῶν Συρακοσίων νῆες μέχρι μὲν τῶν ὁλκάδων ἐπεδίωκον· ἔπειτα αὐτοὺς αἱ κεραῖαι ὑπὲρ τῶν ἔσπλων αἱ ἀπὸ τῶν ὁλκάδων δελφινοφόροι ἠρμέναι ἐκώλυον. δύο δὲ νῆες τῶν Συρακοσίων ἐπαιρόμεναι τῇ νίκῃ προσέμειξαν αὐτῶν ἐγγὺς καὶ διεφθάρησαν, καὶ ἡ ἑτέρα αὐτοῖς ἀνδράσιν ἑάλω. καταδύσαντες δ’ οἱ Συρακόσιοι τῶν Ἀθηναίων ἑπτὰ ναῦς καὶ κατατραυματίσαντες πολλὰς ἄνδρας τε τοὺς μὲν πολλοὺς ζωγρήσαντες, τοὺς δὲ ἀποκτείναντες ἀπεχώρησαν, καὶ τροπαῖά τε ἀμφοτέρων τῶν ναυμαχιῶν ἔστησαν, καὶ τὴν ἐλπίδα ἤδη ἐχυρὰν εἶχον ταῖς μὲν ναυσὶ καὶ πολὺ κρείσσους εἶναι, ἐδόκουν δὲ καὶ τὸν πεζὸν χειρώσεσθαι.", "st": "7.41"}, {"sp": "N", "t": "καὶ οἱ μὲν ὡς ἐπιθησόμενοι κατ’ ἀμφότερα παρεσκευάζοντο αὖθις, ἐν τούτῳ δὲ Δημοσθένης καὶ Εὐρυμέδων ἔχοντες τὴν ἀπὸ τῶν Ἀθηνῶν βοήθειαν παραγίγνονται, ναῦς τε τρεῖς καὶ ἑβδομήκοντα μάλιστα ξὺν ταῖς ξενικαῖς καὶ ὁπλίτας περὶ πεντακισχιλίους ἑαυτῶν τε καὶ τῶν ξυμμάχων, ἀκοντιστάς τε βαρβάρους καὶ Ἕλληνας οὐκ ὀλίγους, καὶ σφενδονήτας καὶ τοξότας καὶ τὴν ἄλλην παρασκευὴν ἱκανήν. καὶ τοῖς μὲν Συρακοσίοις καὶ ξυμμάχοις κατάπληξις ἐν τῷ αὐτίκα οὐκ ὀλίγη ἐγένετο, εἰ πέρας μηδὲν ἔσται σφίσι τοῦ ἀπαλλαγῆναι τοῦ κινδύνου, ὁρῶντες οὔτε διὰ τὴν Δεκέλειαν τειχιζομένην οὐδὲν ἧσσον στρατὸν ἴσον καὶ παραπλήσιον τῷ προτέρῳ ἐπεληλυθότα τήν τε τῶν Ἀθηναίων δύναμιν πανταχόσε πολλὴν φαινομένην· τῷ δὲ προτέρῳ στρατεύματι τῶν Ἀθηναίων ὡς ἐκ κακῶν ῥώμη τις ἐγεγένητο. ὁ δὲ Δημοσθένης ἰδὼν ὡς εἶχε τὰ πράγματα καὶ νομίσας οὐχ οἷόν τε εἶναι διατρίβειν οὐδὲ παθεῖν ὅπερ ὁ Νικίας ἔπαθεν (ἀφικόμενος γὰρ τὸ πρῶτον ὁ Νικίας φοβερός, ὡς οὐκ εὐθὺς προσέκειτο ταῖς Συρακούσαις, ἀλλ’ ἐν Κατάνῃ διεχείμαζεν, ὑπερώφθη τε καὶ ἔφθασεν αὐτὸν ἐκ τῆς Πελοποννήσου στρατιᾷ ὁ Γύλιππος ἀφικόμενος, ἣν οὐδ’ ἂν μετέπεμψαν οἱ Συρακόσιοι, εἰ ἐκεῖνος εὐθὺς ἐπέκειτο· ἱκανοὶ γὰρ αὐτοὶ οἰόμενοι εἶναι ἅμα τ’ ἂν ἔμαθον ἥσσους ὄντες καὶ ἀποτετειχισμένοι ἂν ἦσαν, ὥστε μηδ’ εἰ μετέπεμψαν ἔτι ὁμοίως ἂν αὐτοὺς ὠφελεῖν), ταῦτα οὖν ἀνασκοπῶν ὁ Δημοσθένης, καὶ γιγνώσκων ὅτι καὶ αὐτὸς ἐν τῷ παρόντι τῇ πρώτῃ ἡμέρᾳ μάλιστα δεινότατός ἐστι τοῖς ἐναντίοις, ἐβούλετο ὅτι τάχος ἀποχρήσασθαι τῇ παρούσῃ τοῦ στρατεύματος ἐκπλήξει. καὶ ὁρῶν τὸ παρατείχισμα τῶν Συρακοσίων, ᾧ ἐκώλυσαν περιτειχίσαι σφᾶς τοὺς Ἀθηναίους, ἁπλοῦν ὂν καί, εἰ κρατήσειέ τις τῶν τε Ἐπιπολῶν τῆς ἀναβάσεως καὶ αὖθις τοῦ ἐν αὐταῖς στρατοπέδου, ῥᾳδίως ἂν αὐτὸ ληφθέν (οὐδὲ γὰρ ὑπομεῖναι ἂν σφᾶς οὐδένα), ἠπείγετο ἐπιθέσθαι τῇ πείρᾳ, καί οἱ ξυντομωτάτην ἡγεῖτο διαπολέμησιν· ἢ γὰρ κατορθώσας ἕξειν Συρακούσας, ἢ ἀπάξειν τὴν στρατιὰν καὶ οὐ τρίψεσθαι ἄλλως Ἀθηναίους τε τοὺς ξυστρατευομένους καὶ τὴν ξύμπασαν πόλιν.", "st": "7.42"}, {"sp": "N", "t": "πρῶτον μὲν οὖν τήν τε γῆν ἐξελθόντες τῶν Συρακοσίων ἔτεμον οἱ Ἀθηναῖοι περὶ τὸν Ἄναπον, καὶ τῷ στρατεύματι ἐπεκράτουν ὥσπερ τὸ πρῶτον, τῷ τε πεζῷ καὶ ταῖς ναυσίν (οὐδὲ γὰρ καθ’ ἕτερα οἱ Συρακόσιοι ἀντεπεξῇσαν ὅτι μὴ τοῖς ἱππεῦσι καὶ ἀκοντισταῖς ἀπὸ τοῦ Ὀλυμπιείου)·", "st": "7.42"}, {"sp": "N", "t": "ἔπειτα μηχαναῖς ἔδοξε τῷ Δημοσθένει πρότερον ἀποπειρᾶσαι τοῦ παρατειχίσματος. ὡς δὲ αὐτῷ προσαγαγόντι κατεκαύθησάν τε ὑπὸ τῶν ἐναντίων ἀπὸ τοῦ τείχους ἀμυνομένων αἱ μηχαναὶ καὶ τῇ ἄλλῃ στρατιᾷ πολλαχῇ προσβάλλοντες ἀπεκρούοντο, οὐκέτι ἐδόκει διατρίβειν, ἀλλὰ πείσας τόν τε Νικίαν καὶ τοὺς ἄλλους ξυνάρχοντας, ὡς ἐπενόει, τὴν ἐπιχείρησιν τῶν Ἐπιπολῶν ἐποιεῖτο. καὶ ἡμέρας μὲν ἀδύνατα ἐδόκει εἶναι λαθεῖν προσελθόντας τε καὶ ἀναβάντας, παραγγείλας δὲ πέντε ἡμερῶν σιτία καὶ τοὺς λιθολόγους καὶ τέκτονας πάντας λαβὼν καὶ ἄλλην παρασκευὴν τοξευμάτων τε καὶ ὅσα ἔδει, ἢν κρατῶσι, τειχίζοντας ἔχειν, αὐτὸς μὲν ἀπὸ πρώτου ὕπνου καὶ Εὐρυμέδων καὶ Μένανδρος ἀναλαβὼν τὴν πᾶσαν στρατιὰν ἐχώρει πρὸς τὰς Ἐπιπολάς, Νικίας δὲ ἐν τοῖς τείχεσιν ὑπελέλειπτο. καὶ ἐπειδὴ ἐγένοντο πρὸς αὐταῖς κατὰ τὸν Εὐρύηλον, ᾗπερ καὶ ἡ προτέρα στρατιὰ τὸ πρῶτον ἀνέβη, λανθάνουσί τε τοὺς φύλακας τῶν Συρακοσίων, καὶ προσβάντες τὸ τείχισμα ὃ ἦν αὐτόθι τῶν Συρακοσίων αἱροῦσι καὶ ἄνδρας τῶν φυλάκων ἀποκτείνουσιν. οἱ δὲ πλείους διαφυγόντες εὐθὺς πρὸς τὰ στρατόπεδα, ἃ ἦν ἐπὶ τῶν Ἐπιπολῶν τρία ἐν προτειχίσμασιν, ἓν μὲν τῶν Συρακοσίων, ἓν δὲ τῶν ἄλλων Σικελιωτῶν, ἓν δὲ τῶν ξυμμάχων, ἀγγέλλουσι τὴν ἔφοδον καὶ τοῖς ἑξακοσίοις τῶν Συρακοσίων, οἳ καὶ πρῶτοι κατὰ τοῦτο τὸ μέρος τῶν Ἐπιπολῶν φύλακες ἦσαν, ἔφραζον. οἱ δ’ ἐβοήθουν τ’ εὐθύς, καὶ αὐτοῖς ὁ Δημοσθένης καὶ οἱ Ἀθηναῖοι ἐντυχόντες ἀμυνομένους προθύμως ἔτρεψαν. καὶ αὐτοὶ μὲν εὐθὺς ἐχώρουν ἐς τὸ πρόσθεν, ὅπως τῇ παρούσῃ ὁρμῇ τοῦ περαίνεσθαι ὧν ἕνεκα ἦλθον μὴ βραδεῖς γένωνται· ἄλλοι δὲ ἀπὸ τῆς πρώτης τὸ παρατείχισμα τῶν Συρακοσίων οὐχ ὑπομενόντων τῶν φυλάκων ᾕρουν τε καὶ τὰς ἐπάλξεις ἀπέσυρον. οἱ δὲ Συρακόσιοι καὶ οἱ ξύμμαχοι καὶ ὁ Γύλιππος καὶ οἱ μετ’ αὐτοῦ ἐβοήθουν ἐκ τῶν προτειχισμάτων, καὶ ἀδοκήτου τοῦ τολμήματος σφίσιν ἐν νυκτὶ γενομένου προσέβαλόν τε τοῖς Ἀθηναίοις ἐκπεπληγμένοι καὶ βιασθέντες ὑπ’ αὐτῶν τὸ πρῶτον ὑπεχώρησαν. προϊόντων δὲ τῶν Ἀθηναίων ἐν ἀταξίᾳ μᾶλλον ἤδη ὡς κεκρατηκότων καὶ βουλομένων διὰ παντὸς τοῦ μήπω μεμαχημένου τῶν ἐναντίων ὡς τάχιστα διελθεῖν, ἵνα μὴ ἀνέντων σφῶν τῆς ἐφόδου αὖθις ξυστραφῶσιν, οἱ Βοιωτοὶ πρῶτοι αὐτοῖς ἀντέσχον καὶ προσβαλόντες ἔτρεψάν τε καὶ ἐς φυγὴν κατέστησαν.", "st": "7.43"}, {"sp": "N", "t": "καὶ ἐνταῦθα ἤδη ἐν πολλῇ ταραχῇ καὶ ἀπορίᾳ ἐγίγνοντο οἱ Ἀθηναῖοι, ἣν οὐδὲ πυθέσθαι ῥᾴδιον ἦν οὐδ’ ἀφ’ ἑτέρων ὅτῳ τρόπῳ ἕκαστα ξυνηνέχθη. ἐν μὲν γὰρ ἡμέρᾳ σαφέστερα μέν, ὅμως δὲ οὐδὲ ταῦτα οἱ παραγενόμενοι πάντα πλὴν τὸ καθ’ ἑαυτὸν ἕκαστος μόλις οἶδεν· ἐν δὲ νυκτομαχίᾳ, ἣ μόνη δὴ στρατοπέδων μεγάλων ἔν γε τῷδε τῷ πολέμῳ ἐγένετο, πῶς ἄν τις σαφῶς τι ᾔδει; ἦν μὲν γὰρ σελήνη λαμπρά, ἑώρων δὲ οὕτως ἀλλήλους ὡς ἐν σελήνῃ εἰκὸς τὴν μὲν ὄψιν τοῦ σώματος προορᾶν, τὴν δὲ γνῶσιν τοῦ οἰκείου ἀπιστεῖσθαι. ὁπλῖται δὲ ἀμφοτέρων οὐκ ὀλίγοι ἐν στενοχωρίᾳ ἀνεστρέφοντο. καὶ τῶν Ἀθηναίων οἱ μὲν ἤδη ἐνικῶντο, οἱ δ’ ἔτι τῇ πρώτῃ ἐφόδῳ ἀήσσητοι ἐχώρουν. πολὺ δὲ καὶ τοῦ ἄλλου στρατεύματος αὐτοῖς τὸ μὲν ἄρτι ἀνεβεβήκει, τὸ δ’ ἔτι προσανῄει, ὥστ’ οὐκ ἠπίσταντο πρὸς ὅτι χρὴ χωρῆσαι. ἤδη γὰρ τὰ πρόσθεν τῆς τροπῆς γεγενημένης ἐτετάρακτο πάντα καὶ χαλεπὰ ἦν ὑπὸ τῆς βοῆς διαγνῶναι. οἵ τε γὰρ Συρακόσιοι καὶ οἱ ξύμμαχοι ὡς κρατοῦντες παρεκελεύοντό τε κραυγῇ οὐκ ὀλίγῃ χρώμενοι, ἀδύνατον ὂν ἐν νυκτὶ ἄλλῳ τῳ σημῆναι, καὶ ἅμα τοὺς προσφερομένους ἐδέχοντο· οἵ τε Ἀθηναῖοι ἐζήτουν τε σφᾶς αὐτοὺς καὶ πᾶν τὸ ἐξ ἐναντίας, καὶ εἰ φίλιον εἴη τῶν ἤδη πάλιν φευγόντων, πολέμιον ἐνόμιζον, καὶ τοῖς ἐρωτήμασι τοῦ ξυνθήματος πυκνοῖς χρώμενοι διὰ τὸ μὴ εἶναι ἄλλῳ τῳ γνωρίσαι σφίσι τε αὐτοῖς θόρυβον πολὺν παρεῖχον ἅμα πάντες ἐρωτῶντες καὶ τοῖς πολεμίοις σαφὲς αὐτὸ κατέστησαν· τὸ δ’ ἐκείνων οὐχ ὁμοίως ἠπίσταντο διὰ τὸ κρατοῦντας αὐτοὺς καὶ μὴ διεσπασμένους ἧσσον ἀγνοεῖσθαι, ὥστ’ εἰ μὲν ἐντύχοιέν τισι κρείσσους ὄντες τῶν πολεμίων, διέφευγον αὐτοὺς ἅτε ἐκείνων ἐπιστάμενοι τὸ ξύνθημα, εἰ δ’ αὐτοὶ μὴ ἀποκρίνοιντο, διεφθείροντο. μέγιστον δὲ καὶ οὐχ ἥκιστα ἔβλαψε καὶ ὁ παιανισμός· ἀπὸ γὰρ ἀμφοτέρων παραπλήσιος ὢν ἀπορίαν παρεῖχεν. οἵ τε γὰρ Ἀργεῖοι καὶ οἱ Κερκυραῖοι καὶ ὅσον Δωρικὸν μετ’ Ἀθηναίων ἦν, ὁπότε παιανίσειαν, φόβον παρεῖχε τοῖς Ἀθηναίοις, οἵ τε πολέμιοι ὁμοίως. ὥστε τέλος ξυμπεσόντες αὑτοῖς κατὰ πολλὰ τοῦ στρατοπέδου, ἐπεὶ ἅπαξ ἐταράχθησαν, φίλοι τε φίλοις καὶ πολῖται πολίταις, οὐ μόνον ἐς φόβον κατέστησαν, ἀλλὰ καὶ ἐς χεῖρας ἀλλήλοις ἐλθόντες μόλις ἀπελύοντο. καὶ διωκόμενοι κατά τε τῶν κρημνῶν [οἱ] πολλοὶ ῥίπτοντες ἑαυτοὺς ἀπώλλυντο, στενῆς οὔσης τῆς ἀπὸ τῶν Ἐπιπολῶν πάλιν καταβάσεως, καὶ ἐπειδὴ ἐς τὸ ὁμαλὸν οἱ σῳζόμενοι ἄνωθεν καταβαῖεν, οἱ μὲν πολλοὶ αὐτῶν καὶ ὅσοι ἦσαν τῶν προτέρων στρατιωτῶν ἐμπειρίᾳ μᾶλλον τῆς χώρας ἐς τὸ στρατόπεδον διεφύγγανον, οἱ δὲ ὕστερον ἥκοντες εἰσὶν οἳ διαμαρτόντες τῶν ὁδῶν κατὰ τὴν χώραν ἐπλανήθησαν· οὕς, ἐπειδὴ ἡμέρα ἐγένετο, οἱ ἱππῆς τῶν Συρακοσίων περιελάσαντες διέφθειραν.", "st": "7.44"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ οἱ μὲν Συρακόσιοι δύο τροπαῖα ἔστησαν, ἐπί τε ταῖς Ἐπιπολαῖς ᾗ ἡ πρόσβασις καὶ κατὰ τὸ χωρίον ᾗ οἱ Βοιωτοὶ πρῶτον ἀντέστησαν, οἱ δ’ Ἀθηναῖοι τοὺς νεκροὺς ὑποσπόνδους ἐκομίσαντο. ἀπέθανον δὲ οὐκ ὀλίγοι αὐτῶν τε καὶ τῶν ξυμμάχων, ὅπλα μέντοι ἔτι πλείω ἢ κατὰ τοὺς νεκροὺς ἐλήφθη· οἱ γὰρ κατὰ τῶν κρημνῶν βιασθέντες ἅλλεσθαι ψιλοὶ [ἄνευ τῶν ἀσπίδων] οἱ μὲν ἀπώλλυντο, οἱ δ’ ἐσώθησαν.", "st": "7.45"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο οἱ μὲν Συρακόσιοι ὡς ἐπὶ ἀπροσδοκήτῳ εὐπραγίᾳ πάλιν αὖ ἀναρρωσθέντες, ὥσπερ καὶ πρότερον, ἐς μὲν Ἀκράγαντα στασιάζοντα πέντε καὶ δέκα ναυσὶ Σικανὸν ἀπέστειλαν, ὅπως ὑπαγάγοιτο τὴν πόλιν, εἰ δύναιτο· Γύλιππος δὲ κατὰ γῆν ἐς τὴν ἄλλην Σικελίαν ᾤχετο αὖθις, ἄξων στρατιὰν ἔτι, ὡς ἐν ἐλπίδι ὢν καὶ τὰ τείχη τῶν Ἀθηναίων αἱρήσειν βίᾳ, ἐπειδὴ τὰ ἐν ταῖς Ἐπιπολαῖς οὕτω ξυνέβη.", "st": "7.46"}, {"sp": "N", "t": "οἱ δὲ τῶν Ἀθηναίων στρατηγοὶ ἐν τούτῳ ἐβουλεύοντο πρός τε τὴν γεγενημένην ξυμφορὰν καὶ πρὸς τὴν παροῦσαν ἐν τῷ στρατοπέδῳ κατὰ πάντα ἀρρωστίαν. τοῖς τε γὰρ ἐπιχειρήμασιν ἑώρων οὐ κατορθοῦντες καὶ τοὺς στρατιώτας ἀχθομένους τῇ μονῇ· νόσῳ τε γὰρ ἐπιέζοντο κατ’ ἀμφότερα, τῆς τε ὥρας τοῦ ἐνιαυτοῦ ταύτης οὔσης ἐν ᾗ ἀσθενοῦσιν ἄνθρωποι μάλιστα, καὶ τὸ χωρίον ἅμα ἐν ᾧ ἐστρατοπεδεύοντο ἑλῶδες καὶ χαλεπὸν ἦν, τά τε ἄλλα ὅτι ἀνέλπιστα αὐτοῖς ἐφαίνετο. τῷ οὖν Δημοσθένει οὐκ ἐδόκει ἔτι χρῆναι μένειν, ἀλλ’ ἅπερ καὶ διανοηθεὶς ἐς τὰς Ἐπιπολὰς διεκινδύνευσεν, ἐπειδὴ ἔσφαλτο, ἀπιέναι ἐψηφίζετο καὶ μὴ διατρίβειν, ἕως ἔτι τὸ πέλαγος οἷόν τε περαιοῦσθαι καὶ τοῦ στρατεύματος ταῖς γοῦν ἐπελθούσαις ναυσὶ κρατεῖν. καὶ τῇ πόλει ὠφελιμώτερον ἔφη εἶναι πρὸς τοὺς ἐν τῇ χώρᾳ σφῶν ἐπιτειχίζοντας τὸν πόλεμον ποιεῖσθαι ἢ Συρακοσίους, οὓς οὐκέτι ῥᾴδιον εἶναι χειρώσασθαι· οὐδ’ αὖ ἄλλως χρήματα πολλὰ δαπανῶντας εἰκὸς εἶναι προσκαθῆσθαι.", "st": "7.47"}, {"sp": "N", "t": "καὶ ὁ μὲν Δημοσθένης τοιαῦτα ἐγίγνωσκεν· ὁ δὲ Νικίας ἐνόμιζε μὲν καὶ αὐτὸς πονηρά σφῶν τὰ πράγματα εἶναι, τῷ δὲ λόγῳ οὐκ ἐβούλετο αὐτὰ ἀσθενῆ ἀποδεικνύναι, οὐδ’ ἐμφανῶς σφᾶς ψηφιζομένους μετὰ πολλῶν τὴν ἀναχώρησιν τοῖς πολεμίοις καταγγέλτους γίγνεσθαι· λαθεῖν γὰρ ἄν, ὁπότε βούλοιντο, τοῦτο ποιοῦντες πολλῷ ἧσσον. τὸ δέ τι καὶ τὰ τῶν πολεμίων, ἀφ’ ὧν ἐπὶ πλέον ἢ οἱ ἄλλοι ᾐσθάνετο αὐτῶν, ἐλπίδος τι ἔτι παρεῖχε πονηρότερα τῶν σφετέρων ἔσεσθαι, ἢν καρτερῶσι προσκαθήμενοι· χρημάτων γὰρ ἀπορίᾳ αὐτοὺς ἐκτρυχώσειν, ἄλλως τε καὶ ἐπὶ πλέον ἤδη ταῖς ὑπαρχούσαις ναυσὶ θαλασσοκρατούντων. καὶ ἦν γάρ τι καὶ ἐν ταῖς Συρακούσαις βουλόμενον τοῖς Ἀθηναίοις τὰ πράγματα ἐνδοῦναι, ἐπεκηρυκεύετο ὡς αὐτὸν καὶ οὐκ εἴα ἀπανίστασθαι. ἃ ἐπιστάμενος τῷ μὲν ἔργῳ ἔτι ἐπ’ ἀμφότερα ἔχων καὶ διασκοπῶν ἀνεῖχε, τῷ δ’ ἐμφανεῖ τότε λόγῳ οὐκ ἔφη ἀπάξειν τὴν στρατιάν. εὖ γὰρ εἰδέναι ὅτι Ἀθηναῖοι σφῶν ταῦτα οὐκ ἀποδέξονται, ὥστε μὴ αὐτῶν ψηφισαμένων ἀπελθεῖν. καὶ γὰρ οὐ τοὺς αὐτοὺς ψηφιεῖσθαί τε περὶ σφῶν [αὐτῶν] καὶ τὰ πράγματα ὥσπερ καὶ αὐτοὶ ὁρῶντας καὶ οὐκ ἄλλων ἐπιτιμήσει ἀκούσαντας γνώσεσθαι, ἀλλ’ ἐξ ὧν ἄν τις εὖ λέγων διαβάλλοι, ἐκ τούτων αὐτοὺς πείσεσθαι. τῶν τε παρόντων στρατιωτῶν πολλοὺς καὶ τοὺς πλείους ἔφη, οἳ νῦν βοῶσιν ὡς ἐν δεινοῖς ὄντες, ἐκεῖσε ἀφικομένους τἀναντία βοήσεσθαι ὡς ὑπὸ χρημάτων καταπροδόντες οἱ στρατηγοὶ ἀπῆλθον. οὔκουν βούλεσθαι αὐτός γε ἐπιστάμενος τὰς Ἀθηναίων φύσεις ἐπ’ αἰσχρᾷ τε αἰτίᾳ καὶ ἀδίκως ὑπ’ Ἀθηναίων ἀπολέσθαι μᾶλλον ἢ ὑπὸ τῶν πολεμίων, εἰ δεῖ, κινδυνεύσας τοῦτο παθεῖν ἰδίᾳ. τά τε Συρακοσίων ἔφη ὅμως ἔτι ἥσσω τῶν σφετέρων εἶναι· καὶ χρήμασι γὰρ αὐτοὺς ξενοτροφοῦντας καὶ ἐν περιπολίοις ἅμα ἀναλίσκοντας καὶ ναυτικὸν πολὺ ἔτι ἐνιαυτὸν ἤδη βόσκοντας τὰ μὲν ἀπορεῖν, τὰ δ’ ἔτι ἀμηχανήσειν· δισχίλιά τε γὰρ τάλαντα ἤδη ἀνηλωκέναι καὶ ἔτι πολλὰ προσοφείλειν, ἤν τε καὶ ὁτιοῦν ἐκλίπωσι τῆς νῦν παρασκευῆς τῷ μὴ διδόναι τροφήν, φθερεῖσθαι αὐτῶν τὰ πράγματα, ἐπικουρικὰ μᾶλλον ἢ δι’ ἀνάγκης ὥσπερ τὰ σφέτερα ὄντα. τρίβειν οὖν ἔφη χρῆναι προσκαθημένους καὶ μὴ χρήμασιν, ὧν πολὺ κρείσσους εἰσί, νικηθέντας ἀπιέναι.", "st": "7.48"}, {"sp": "N", "t": "ὁ μὲν Νικίας τοσαῦτα λέγων ἰσχυρίζετο, αἰσθόμενος τὰ ἐν ταῖς Συρακούσαις ἀκριβῶς καὶ τὴν τῶν χρημάτων ἀπορίαν καὶ ὅτι ἦν αὐτόθι πολὺ τὸ βουλόμενον τοῖς Ἀθηναίοις γίγνεσθαι τὰ πράγματα καὶ ἐπικηρυκευόμενον πρὸς αὐτὸν ὥστε μὴ ἀπανίστασθαι, καὶ ἅμα ταῖς γοῦν ναυσὶ μᾶλλον ἢ πρότερον ἐθάρσησε κρατήσειν. ὁ δὲ Δημοσθένης περὶ μὲν τοῦ προσκαθῆσθαι οὐδ’ ὁπωσοῦν ἐνεδέχετο· εἰ δὲ δεῖ μὴ ἀπάγειν τὴν στρατιὰν ἄνευ Ἀθηναίων ψηφίσματος, ἀλλὰ τρίβειν αὐτοῦ, ἔφη χρῆναι ἢ ἐς τὴν Θάψον ἀναστάντας τοῦτο ποιεῖν ἢ ἐς τὴν Κατάνην, ὅθεν τῷ τε πεζῷ ἐπὶ πολλὰ τῆς χώρας ἐπιόντες θρέψονται πορθοῦντες τὰ τῶν πολεμίων καὶ ἐκείνους βλάψουσι, ταῖς τε ναυσὶν ἐν πελάγει καὶ οὐκ ἐν στενοχωρίᾳ, ἣ πρὸς τῶν πολεμίων μᾶλλόν ἐστι, τοὺς ἀγῶνας ποιήσονται, ἀλλ’ ἐν εὐρυχωρίᾳ, ἐν ᾗ τά τε τῆς ἐμπειρίας χρήσιμα σφῶν ἔσται καὶ ἀναχωρήσεις καὶ ἐπίπλους οὐκ ἐκ βραχέος καὶ περιγραπτοῦ ὁρμώμενοί τε καὶ καταίροντες ἕξουσιν. τό τε ξύμπαν εἰπεῖν, οὐδενὶ τρόπῳ οἱ ἔφη ἀρέσκειν ἐν τῷ αὐτῷ ἔτι μένειν, ἀλλ’ ὅτι τάχιστα ἤδη ἐξανίστασθαι καὶ μὴ μέλλειν. καὶ ὁ Εὐρυμέδων αὐτῷ ταῦτα ξυνηγόρευεν. ἀντιλέγοντος δὲ τοῦ Νικίου ὄκνος τις καὶ μέλλησις ἐνεγένετο καὶ ἅμα ὑπόνοια μή τι καὶ πλέον εἰδὼς ὁ Νικίας ἰσχυρίζηται. καὶ οἱ μὲν Ἀθηναῖοι τούτῳ τῷ τρόπῳ διεμέλλησάν τε καὶ κατὰ χώραν ἔμενον.", "st": "7.49"}, {"sp": "N", "t": "ὁ δὲ Γύλιππος καὶ ὁ Σικανὸς ἐν τούτῳ παρῆσαν ἐς τὰς Συρακούσας, ὁ μὲν Σικανὸς ἁμαρτὼν τοῦ Ἀκράγαντος (ἐν Γέλᾳ γὰρ ὄντος αὐτοῦ ἔτι ἡ τοῖς Συρακοσίοις στάσις [ἐς] φιλία ἐξεπεπτώκει)· ὁ δὲ Γύλιππος ἄλλην τε στρατιὰν πολλὴν ἔχων ἦλθεν ἀπὸ τῆς Σικελίας καὶ τοὺς ἐκ τῆς Πελοποννήσου τοῦ ἦρος ἐν ταῖς ὁλκάσιν ὁπλίτας ἀποσταλέντας, ἀφικομένους ἀπὸ τῆς Λιβύης ἐς Σελινοῦντα. ἀπενεχθέντες γὰρ ἐς Λιβύην, καὶ δόντων Κυρηναίων τριήρεις δύο καὶ τοῦ πλοῦ ἡγεμόνας, καὶ ἐν τῷ παράπλῳ Εὐεσπερίταις πολιορκουμένοις ὑπὸ Λιβύων ξυμμαχήσαντες καὶ νικήσαντες τοὺς Λίβυς, καὶ αὐτόθεν παραπλεύσαντες ἐς Νέαν πόλιν Καρχηδονιακὸν ἐμπόριον, ὅθενπερ Σικελία ἐλάχιστον δυοῖν ἡμερῶν καὶ νυκτὸς πλοῦν ἀπέχει, καὶ ἀπ’ αὐτοῦ περαιωθέντες ἀφίκοντο ἐς Σελινοῦντα. καὶ οἱ μὲν Συρακόσιοι εὐθὺς αὐτῶν ἐλθόντων παρεσκευάζοντο ὡς ἐπιθησόμενοι κατ’ ἀμφότερα αὖθις τοῖς Ἀθηναίοις καὶ ναυσὶ καὶ πεζῷ· οἱ δὲ τῶν Ἀθηναίων στρατηγοὶ ὁρῶντες στρατιάν τε ἄλλην προσγεγενημένην αὐτοῖς καὶ τὰ ἑαυτῶν ἅμα οὐκ ἐπὶ τὸ βέλτιον χωροῦντα, ἀλλὰ καθ’ ἡμέραν τοῖς πᾶσι χαλεπώτερον ἴσχοντα, μάλιστα δὲ τῇ ἀσθενείᾳ τῶν ἀνθρώπων πιεζόμενα, μετεμέλοντό τε πρότερον οὐκ ἀναστάντες καὶ ὡς αὐτοῖς οὐδὲ ὁ Νικίας ἔτι ὁμοίως ἐνηντιοῦτο, ἀλλ’ ἢ μὴ φανερῶς γε ἀξιῶν ψηφίζεσθαι, προεῖπον ὡς ἐδύναντο ἀδηλότατα ἔκπλουν ἐκ τοῦ στρατοπέδου πᾶσι, καὶ παρασκευάσασθαι ὅταν τις σημήνῃ. καὶ μελλόντων αὐτῶν, ἐπειδὴ ἑτοῖμα ἦν, ἀποπλεῖν ἡ σελήνη ἐκλείπει· ἐτύγχανε γὰρ πασσέληνος οὖσα. καὶ οἱ Ἀθηναῖοι οἵ τε πλείους ἐπισχεῖν ἐκέλευον τοὺς στρατηγοὺς ἐνθύμιον ποιούμενοι, καὶ ὁ Νικίας (ἦν γάρ τι καὶ ἄγαν θειασμῷ τε καὶ τῷ τοιούτῳ προσκείμενος) οὐδ’ ἂν διαβουλεύσασθαι ἔτι ἔφη πρίν, ὡς οἱ μάντεις ἐξηγοῦντο, τρὶς ἐννέα ἡμέρας μεῖναι, ὅπως ἂν πρότερον κινηθείη. καὶ τοῖς μὲν Ἀθηναίοις μελλήσασι διὰ τοῦτο ἡ μονὴ ἐγεγένητο.", "st": "7.50"}, {"sp": "N", "t": "οἱ δὲ Συρακόσιοι καὶ αὐτοὶ τοῦτο πυθόμενοι πολλῷ μᾶλλον ἐπηρμένοι ἦσαν μὴ ἀνιέναι τὰ τῶν Ἀθηναίων, ὡς καὶ αὐτῶν κατεγνωκότων ἤδη μηκέτι κρεισσόνων εἶναι σφῶν μήτε ταῖς ναυσὶ μήτε τῷ πεζῷ (οὐ γὰρ ἂν τὸν ἔκπλουν ἐπιβουλεῦσαι), καὶ ἅμα οὐ βουλόμενοι αὐτοὺς ἄλλοσέ ποι τῆς Σικελίας καθεζομένους χαλεπωτέρους εἶναι προσπολεμεῖν, ἀλλ’ αὐτοῦ ὡς τάχιστα καὶ ἐν ᾧ σφίσι ξυμφέρει ἀναγκάσαι αὐτοὺς ναυμαχεῖν. τὰς οὖν ναῦς ἐπλήρουν καὶ ἀνεπειρῶντο ἡμέρας ὅσαι αὐτοῖς ἐδόκουν ἱκαναὶ εἶναι. ἐπειδὴ δὲ καιρὸς ἦν, τῇ μὲν προτέρᾳ πρὸς τὰ τείχη τῶν Ἀθηναίων προσέβαλλον, καὶ ἐπεξελθόντος μέρους τινὸς οὐ πολλοῦ καὶ τῶν ὁπλιτῶν καὶ τῶν ἱππέων κατά τινας πύλας ἀπολαμβάνουσί τε τῶν ὁπλιτῶν τινὰς καὶ τρεψάμενοι καταδιώκουσιν· οὔσης δὲ στενῆς τῆς ἐσόδου οἱ Ἀθηναῖοι ἵππους τε ἑβδομήκοντα ἀπολλύασι καὶ τῶν ὁπλιτῶν οὐ πολλούς.", "st": "7.51"}, {"sp": "N", "t": "καὶ ταύτῃ μὲν τῇ ἡμέρᾳ ἀπεχώρησεν ἡ στρατιὰ τῶν Συρακοσίων· τῇ δ’ ὑστεραίᾳ ταῖς τε ναυσὶν ἐκπλέουσιν οὔσαις ἓξ καὶ ἑβδομήκοντα καὶ τῷ πεζῷ ἅμα πρὸς τὰ τείχη ἐχώρουν. οἱ δ’ Ἀθηναῖοι ἀντανῆγον ναυσὶν ἓξ καὶ ὀγδοήκοντα καὶ προσμείξαντες ἐναυμάχουν. καὶ τὸν Εὐρυμέδοντα ἔχοντα τὸ δεξιὸν κέρας τῶν Ἀθηναίων καὶ βουλόμενον περικλῄσασθαι τὰς ναῦς τῶν ἐναντίων καὶ ἐπεξάγοντα τῷ πλῷ πρὸς τὴν γῆν μᾶλλον, νικήσαντες οἱ Συρακόσιοι καὶ οἱ ξύμμαχοι τὸ μέσον πρῶτον τῶν Ἀθηναίων ἀπολαμβάνουσι κἀκεῖνον ἐν τῷ κοίλῳ καὶ μυχῷ τοῦ λιμένος καὶ αὐτόν τε διαφθείρουσι καὶ τὰς μετ’ αὐτοῦ ναῦς ἐπισπομένας· ἔπειτα δὲ καὶ τὰς πάσας ἤδη ναῦς τῶν Ἀθηναίων κατεδίωκόν τε καὶ ἐξεώθουν ἐς τὴν γῆν.", "st": "7.52"}, {"sp": "N", "t": "ὁ δὲ Γύλιππος ὁρῶν τὰς ναῦς τῶν πολεμίων νικωμένας καὶ ἔξω τῶν σταυρωμάτων καὶ τοῦ ἑαυτῶν στρατοπέδου καταφερομένας, βουλόμενος διαφθείρειν τοὺς ἐκβαίνοντας καὶ τὰς ναῦς ῥᾷον τοὺς Συρακοσίους ἀφέλκειν τῆς γῆς φιλίας οὔσης, παρεβοήθει ἐπὶ τὴν χηλὴν μέρος τι ἔχων τῆς στρατιᾶς. καὶ αὐτοὺς οἱ Τυρσηνοί (οὗτοι γὰρ ἐφύλασσον τοῖς Ἀθηναίοις ταύτῃ) ὁρῶντες ἀτάκτως προσφερομένους, ἐπεκβοηθήσαντες καὶ προσπεσόντες τοῖς πρώτοις τρέπουσι καὶ ἐσβάλλουσιν ἐς τὴν λίμνην τὴν Λυσιμέλειαν καλουμένην. ὕστερον δὲ πλέονος ἤδη τοῦ στρατεύματος παρόντος τῶν Συρακοσίων καὶ ξυμμάχων καὶ οἱ Ἀθηναῖοι ἐπιβοηθήσαντες καὶ δείσαντες περὶ ταῖς ναυσὶν ἐς μάχην τε κατέστησαν πρὸς αὐτοὺς καὶ νικήσαντες ἐπεδίωξαν καὶ ὁπλίτας τε οὐ πολλοὺς ἀπέκτειναν καὶ τὰς ναῦς τὰς μὲν πολλὰς διέσωσάν τε καὶ ξυνήγαγον κατὰ τὸ στρατόπεδον, δυοῖν δὲ δεούσας εἴκοσιν οἱ Συρακόσιοι καὶ οἱ ξύμμαχοι ἔλαβον αὐτῶν καὶ τοὺς ἄνδρας πάντας ἀπέκτειναν. καὶ ἐπὶ τὰς λοιπὰς ἐμπρῆσαι βουλόμενοι ὁλκάδα παλαιὰν κληματίδων καὶ δᾳδὸς γεμίσαντες (ἦν γὰρ ἐπὶ τοὺς Ἀθηναίους ὁ ἄνεμος οὔριος) ἀφεῖσαν [τὴν ναῦν] πῦρ ἐμβαλόντες. καὶ οἱ Ἀθηναῖοι δείσαντες περὶ ταῖς ναυσὶν ἀντεμηχανήσαντό τε σβεστήρια κωλύματα καὶ παύσαντες τήν τε φλόγα καὶ τὸ μὴ προσελθεῖν ἐγγὺς τὴν ὁλκάδα τοῦ κινδύνου ἀπηλλάγησαν.", "st": "7.53"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο Συρακόσιοι μὲν τῆς τε ναυμαχίας τροπαῖον ἔστησαν καὶ τῆς ἄνω τῆς πρὸς τῷ τείχει ἀπολήψεως τῶν ὁπλιτῶν, ὅθεν καὶ τοὺς ἵππους ἔλαβον, Ἀθηναῖοι δὲ ἧς τε οἱ Τυρσηνοὶ τροπῆς ἐποιήσαντο τῶν πεζῶν ἐς τὴν λίμνην καὶ ἧς αὐτοὶ τῷ ἄλλῳ στρατοπέδῳ.", "st": "7.54"}, {"sp": "N", "t": "γεγενημένης δὲ τῆς νίκης τοῖς Συρακοσίοις λαμπρᾶς ἤδη καὶ τοῦ ναυτικοῦ (πρότερον μὲν γὰρ ἐφοβοῦντο τὰς μετὰ τοῦ Δημοσθένους ναῦς ἐπελθούσας) οἱ μὲν Ἀθηναῖοι ἐν παντὶ δὴ ἀθυμίας ἦσαν καὶ ὁ παράλογος αὐτοῖς μέγας ἦν, πολὺ δὲ μείζων ἔτι τῆς στρατείας ὁ μετάμελος. πόλεσι γὰρ ταύταις μόναις ἤδη ὁμοιοτρόποις ἐπελθόντες, δημοκρατουμέναις τε, ὥσπερ καὶ αὐτοί, καὶ ναῦς καὶ ἵππους καὶ μεγέθη ἐχούσαις, οὐ δυνάμενοι ἐπενεγκεῖν οὔτ’ ἐκ πολιτείας τι μεταβολῆς τὸ διάφορον αὐτοῖς, ᾧ προσήγοντο ἄν, οὔτ’ ἐκ παρασκευῆς πολλῷ κρείσσονος, σφαλλόμενοι δὲ τὰ πλείω, τά τε πρὸ αὐτῶν ἠπόρουν, καὶ ἐπειδή γε καὶ ταῖς ναυσὶν ἐκρατήθησαν, ὃ οὐκ ἂν ᾤοντο, πολλῷ δὴ μᾶλλον ἔτι.", "st": "7.55"}, {"sp": "N", "t": "οἱ δὲ Συρακόσιοι τόν τε λιμένα εὐθὺς παρέπλεον ἀδεῶς καὶ τὸ στόμα αὐτοῦ διενοοῦντο κλῄσειν, ὅπως μηκέτι, μηδ’ εἰ βούλοιντο, λάθοιεν αὐτοὺς οἱ Ἀθηναῖοι ἐκπλεύσαντες. οὐ γὰρ περὶ τοῦ αὐτοὶ σωθῆναι μόνον ἔτι τὴν ἐπιμέλειαν ἐποιοῦντο, ἀλλὰ καὶ ὅπως ἐκείνους κωλύσουσι, νομίζοντες ὅπερ ἦν, ἀπό τε τῶν παρόντων πολὺ σφῶν καθυπέρτερα τὰ πράγματα εἶναι καί, εἰ δύναιντο κρατῆσαι Ἀθηναίων τε καὶ τῶν ξυμμάχων καὶ κατὰ γῆν καὶ κατὰ θάλασσαν, καλὸν σφίσιν ἐς τοὺς Ἕλληνας τὸ ἀγώνισμα φανεῖσθαι· τούς τε γὰρ ἄλλους Ἕλληνας εὐθὺς τοὺς μὲν ἐλευθεροῦσθαι, τοὺς δὲ φόβου ἀπολύεσθαι (οὐ γὰρ ἔτι δυνατὴν ἔσεσθαι τὴν ὑπόλοιπον Ἀθηναίων δύναμιν τὸν ὕστερον ἐπενεχθησόμενον πόλεμον ἐνεγκεῖν), καὶ αὐτοὶ δόξαντες αὐτῶν αἴτιοι εἶναι ὑπό τε τῶν ἄλλων ἀνθρώπων καὶ ὑπὸ τῶν ἔπειτα πολὺ θαυμασθήσεσθαι. καὶ ἦν δὲ ἄξιος ὁ ἀγὼν κατά τε ταῦτα καὶ ὅτι οὐχὶ Ἀθηναίων μόνον περιεγίγνοντο, ἀλλὰ καὶ τῶν ἄλλων πολλῶν ξυμμάχων, καὶ οὐδ’ αὐτοὶ αὖ μόνον, ἀλλὰ καὶ μετὰ τῶν ξυμβοηθησάντων σφίσιν, ἡγεμόνες τε γενόμενοι μετὰ Κορινθίων καὶ Λακεδαιμονίων καὶ τὴν σφετέραν πόλιν ἐμπαρασχόντες προκινδυνεῦσαί τε καὶ τοῦ ναυτικοῦ μέγα μέρος προκόψαντες. ἔθνη γὰρ πλεῖστα δὴ ἐπὶ μίαν πόλιν ταύτην ξυνῆλθε, πλήν γε δὴ τοῦ ξύμπαντος λόγου τοῦ ἐν τῷδε τῷ πολέμῳ πρὸς τὴν Ἀθηναίων τε πόλιν καὶ Λακεδαιμονίων.", "st": "7.56"}, {"sp": "N", "t": "τοσοίδε γὰρ ἑκάτεροι ἐπὶ Σικελίαν τε καὶ περὶ Σικελίας, τοῖς μὲν ξυγκτησόμενοι τὴν χώραν ἐλθόντες, τοῖς δὲ ξυνδιασώσοντες, ἐπὶ Συρακούσας ἐπολέμησαν, οὐ κατὰ δίκην τι μᾶλλον οὐδὲ κατὰ ξυγγένειαν μετ’ ἀλλήλων στάντες, ἀλλ’ ὡς ἑκάστοις τῆς ξυντυχίας ἢ κατὰ τὸ ξυμφέρον ἢ ἀνάγκῃ ἔσχεν. Ἀθηναῖοι μὲν αὐτοὶ Ἴωνες ἐπὶ Δωριᾶς Συρακοσίους ἑκόντες ἦλθον, καὶ αὐτοῖς τῇ αὐτῇ φωνῇ καὶ νομίμοις ἔτι χρώμενοι Λήμνιοι καὶ Ἴμβριοι καὶ Αἰγινῆται, οἳ τότε Αἴγιναν εἶχον, καὶ ἔτι Ἑστιαιῆς οἱ ἐν Εὐβοίᾳ Ἑστίαιαν οἰκοῦντες ἄποικοι ὄντες ξυνεστράτευσαν. τῶν δ’ ἄλλων οἱ μὲν ὑπήκοοι, οἱ δ’ ἀπὸ ξυμμαχίας αὐτόνομοι, εἰσὶ δὲ καὶ οἳ μισθοφόροι ξυνεστράτευον. καὶ τῶν μὲν ὑπηκόων καὶ φόρου ὑποτελῶν Ἐρετριῆς καὶ Χαλκιδῆς καὶ Στυρῆς καὶ Καρύστιοι ἀπ’ Εὐβοίας ἦσαν, ἀπὸ δὲ νήσων Κεῖοι καὶ Ἄνδριοι καὶ Τήνιοι, ἐκ δ’ Ἰωνίας Μιλήσιοι καὶ Σάμιοι καὶ Χῖοι. τούτων Χῖοι οὐχ ὑποτελεῖς ὄντες φόρου, ναῦς δὲ παρέχοντες αὐτόνομοι ξυνέσποντο. καὶ τὸ πλεῖστον Ἴωνες ὄντες οὗτοι πάντες καὶ ἀπ’ Ἀθηναίων πλὴν Καρυστίων (οὗτοι δ’ εἰσὶ Δρύοπες), ὑπήκοοι δ’ ὄντες καὶ ἀνάγκῃ ὅμως Ἴωνές γε ἐπὶ Δωριᾶς ἠκολούθουν. πρὸς δ’ αὐτοῖς Αἰολῆς, Μηθυμναῖοι μὲν ναυσὶ καὶ οὐ φόρῳ ὑπήκοοι, Τενέδιοι δὲ καὶ Αἴνιοι ὑποτελεῖς. οὗτοι δὲ Αἰολῆς Αἰολεῦσι τοῖς κτίσασι Βοιωτοῖς ⟨τοῖς⟩ μετὰ Συρακοσίων κατ’ ἀνάγκην ἐμάχοντο, Πλαταιῆς δὲ καταντικρὺ Βοιωτοὶ Βοιωτοῖς μόνοι εἰκότως κατὰ τὸ ἔχθος. Ῥόδιοι δὲ καὶ Κυθήριοι Δωριῆς ἀμφότεροι, οἱ μὲν Λακεδαιμονίων ἄποικοι Κυθήριοι ἐπὶ Λακεδαιμονίους τοὺς ἅμα Γυλίππῳ μετ’ Ἀθηναίων ὅπλα ἔφερον, Ῥόδιοι δὲ Ἀργεῖοι γένος Συρακοσίοις μὲν Δωριεῦσι, Γελῴοις δὲ καὶ ἀποίκοις ἑαυτῶν οὖσι μετὰ Συρακοσίων στρατευομένοις ἠναγκάζοντο πολεμεῖν. τῶν τε περὶ Πελοπόννησον νησιωτῶν Κεφαλλῆνες μὲν καὶ Ζακύνθιοι αὐτόνομοι μέν, κατὰ δὲ τὸ νησιωτικὸν μᾶλλον κατειργόμενοι, ὅτι θαλάσσης ἐκράτουν οἱ Ἀθηναῖοι, ξυνείποντο· Κερκυραῖοι δὲ οὐ μόνον Δωριῆς, ἀλλὰ καὶ Κορίνθιοι σαφῶς ἐπὶ Κορινθίους τε καὶ Συρακοσίους, τῶν μὲν ἄποικοι ὄντες, τῶν δὲ ξυγγενεῖς, ἀνάγκῃ μὲν ἐκ τοῦ εὐπρεποῦς, βουλήσει δὲ κατὰ ἔχθος τὸ Κορινθίων οὐχ ἧσσον εἵποντο. καὶ οἱ Μεσσήνιοι νῦν καλούμενοι ἐκ Ναυπάκτου καὶ ἐκ Πύλου τότε ὑπ’ Ἀθηναίων ἐχομένης ἐς τὸν πόλεμον παρελήφθησαν. καὶ ἔτι Μεγαρέων φυγάδες οὐ πολλοὶ Μεγαρεῦσι Σελινουντίοις οὖσι κατὰ ξυμφορὰν ἐμάχοντο. τῶν δὲ ἄλλων ἑκούσιος μᾶλλον ἡ στρατεία ἐγίγνετο ἤδη. Ἀργεῖοι μὲν γὰρ οὐ τῆς ξυμμαχίας ἕνεκα μᾶλλον ἢ τῆς Λακεδαιμονίων τε ἔχθρας καὶ τῆς παραυτίκα ἕκαστοι ἰδίας ὠφελίας Δωριῆς ἐπὶ Δωριᾶς μετὰ Ἀθηναίων Ἰώνων ἠκολούθουν, Μαντινῆς δὲ καὶ ἄλλοι Ἀρκάδων μισθοφόροι ἐπὶ τοὺς αἰεὶ πολεμίους σφίσιν ἀποδεικνυμένους ἰέναι εἰωθότες καὶ τότε τοὺς μετὰ Κορινθίων ἐλθόντας Ἀρκάδας οὐδὲν ἧσσον διὰ κέρδος ἡγούμενοι πολεμίους, Κρῆτες δὲ καὶ Αἰτωλοὶ μισθῷ καὶ οὗτοι πεισθέντες· ξυνέβη δὲ τοῖς Κρησὶ τὴν Γέλαν Ῥοδίοις ξυγκτίσαντας μὴ ξὺν τοῖς ἀποίκοις, ἀλλ’ ἐπὶ τοὺς ἀποίκους ἑκόντας μετὰ μισθοῦ ἐλθεῖν. καὶ Ἀκαρνάνων τινὲς ἅμα μὲν κέρδει, τὸ δὲ πλέον Δημοσθένους φιλίᾳ καὶ Ἀθηναίων εὐνοίᾳ ξύμμαχοι ὄντες ἐπεκούρησαν. καὶ οἵδε μὲν τῷ Ἰονίῳ κόλπῳ ὁριζόμενοι· Ἰταλιωτῶν δὲ Θούριοι καὶ Μεταπόντιοι ἐν τοιαύταις ἀνάγκαις τότε στασιωτικῶν καιρῶν κατειλημμένοι ξυνεστράτευον, καὶ Σικελιωτῶν Νάξιοι καὶ Καταναῖοι, βαρβάρων δὲ Ἐγεσταῖοί τε, οἵπερ ἐπηγάγοντο, καὶ Σικελῶν τὸ πλέον, καὶ τῶν ἔξω Σικελίας Τυρσηνῶν τέ τινες κατὰ διαφορὰν Συρακοσίων καὶ Ἰάπυγες μισθοφόροι. τοσάδε μὲν μετὰ Ἀθηναίων ἔθνη ἐστράτευον.", "st": "7.57"}, {"sp": "N", "t": "Συρακοσίοις δὲ ἀντεβοήθησαν Καμαριναῖοι μὲν ὅμοροι ὄντες καὶ Γελῷοι οἰκοῦντες μετ’ αὐτούς, ἔπειτα Ἀκραγαντίνων ἡσυχαζόντων ἐν τῷ ἐπ’ ἐκεῖνα ἱδρυμένοι Σελινούντιοι. καὶ οἵδε μὲν τῆς Σικελίας τὸ πρὸς Λιβύην μέρος τετραμμένον νεμόμενοι, Ἱμεραῖοι δὲ ἀπὸ τοῦ πρὸς τὸν Τυρσηνικὸν πόντον μορίου, ἐν ᾧ καὶ μόνοι Ἕλληνες οἰκοῦσιν· οὗτοι δὲ καὶ ἐξ αὐτοῦ μόνοι ἐβοήθησαν. καὶ Ἑλληνικὰ μὲν ἔθνη τῶν ἐν Σικελίᾳ τοσάδε, Δωριῆς τε καὶ [οἱ] αὐτόνομοι πάντες, ξυνεμάχουν, βαρβάρων δὲ Σικελοὶ μόνοι ὅσοι μὴ ἀφέστασαν πρὸς τοὺς Ἀθηναίους· τῶν δ’ ἔξω Σικελίας Ἑλλήνων Λακεδαιμόνιοι μὲν ἡγεμόνα Σπαρτιάτην παρεχόμενοι, νεοδαμώδεις δὲ τοὺς ἄλλους καὶ Εἵλωτας [δύναται δὲ τὸ νεοδαμῶδες ἐλεύθερον ἤδη εἶναι], Κορίνθιοι δὲ καὶ ναυσὶ καὶ πεζῷ μόνοι παραγενόμενοι καὶ Λευκάδιοι καὶ Ἀμπρακιῶται κατὰ τὸ ξυγγενές, ἐκ δὲ Ἀρκαδίας μισθοφόροι ὑπὸ Κορινθίων ἀποσταλέντες καὶ Σικυώνιοι ἀναγκαστοὶ στρατεύοντες, καὶ τῶν ἔξω Πελοποννήσου Βοιωτοί. πρὸς δὲ τοὺς ἐπελθόντας τούτους οἱ Σικελιῶται αὐτοὶ πλῆθος πλέον κατὰ πάντα παρέσχοντο ἅτε μεγάλας πόλεις οἰκοῦντες· καὶ γὰρ ὁπλῖται πολλοὶ καὶ νῆες καὶ ἵπποι καὶ ὁ ἄλλος ὅμιλος ἄφθονος ξυνελέγη. καὶ πρὸς ἅπαντας αὖθις ὡς εἰπεῖν τοὺς ἄλλους Συρακόσιοι αὐτοὶ πλείω ἐπορίσαντο διὰ μέγεθός τε πόλεως καὶ ὅτι ἐν μεγίστῳ κινδύνῳ ἦσαν.", "st": "7.58"}, {"sp": "N", "t": "καὶ αἱ μὲν ἑκατέρων ἐπικουρίαι τοσαίδε ξυνελέγησαν, καὶ τότε ἤδη πᾶσαι ἀμφοτέροις παρῆσαν καὶ οὐκέτι οὐδὲν οὐδετέροις ἐπῆλθεν.", "st": "7.59"}, {"sp": "N", "t": "οἱ δ’ οὖν Συρακόσιοι καὶ οἱ ξύμμαχοι εἰκότως ἐνόμισαν καλὸν ἀγώνισμα σφίσιν εἶναι ἐπὶ τῇ γεγενημένῃ νίκῃ τῆς ναυμαχίας ἑλεῖν τε τὸ στρατόπεδον ἅπαν τῶν Ἀθηναίων τοσοῦτον ὄν, καὶ μηδὲ καθ’ ἕτερα αὐτούς, μήτε διὰ θαλάσσης μήτε τῷ πεζῷ, διαφυγεῖν. ἔκλῃον οὖν τόν τε λιμένα εὐθὺς τὸν μέγαν, ἔχοντα τὸ στόμα ὀκτὼ σταδίων μάλιστα, τριήρεσι πλαγίαις καὶ πλοίοις καὶ ἀκάτοις ἐπ’ ἀγκυρῶν ὁρμίζοντες, καὶ τἆλλα, ἢν ἔτι ναυμαχεῖν οἱ Ἀθηναῖοι τολμήσωσι, παρεσκευάζοντο, καὶ ὀλίγον οὐδὲν ἐς οὐδὲν ἐπενόουν.", "st": "7.59"}, {"sp": "N", "t": "τοῖς δὲ Ἀθηναίοις τήν τε ἀπόκλῃσιν ὁρῶσι καὶ τὴν ἄλλην διάνοιαν αὐτῶν αἰσθομένοις βουλευτέα ἐδόκει. καὶ ξυνελθόντες οἵ τε στρατηγοὶ καὶ οἱ ταξίαρχοι πρὸς τὴν παροῦσαν ἀπορίαν τῶν τε ἄλλων καὶ ὅτι τὰ ἐπιτήδεια οὔτε αὐτίκα ἔτι εἶχον (προπέμψαντες γὰρ ἐς Κατάνην ὡς ἐκπλευσόμενοι ἀπεῖπον μὴ ἐπάγειν) οὔτε τὸ λοιπὸν ἔμελλον ἕξειν, εἰ μὴ ναυκρατήσουσιν, ἐβουλεύσαντο τὰ μὲν τείχη τὰ ἄνω ἐκλιπεῖν, πρὸς δ’ αὐταῖς ταῖς ναυσὶν ἀπολαβόντες διατειχίσματι ὅσον οἷόν τε ἐλάχιστον τοῖς τε σκεύεσι καὶ τοῖς ἀσθενοῦσιν ἱκανὸν γενέσθαι, τοῦτο μὲν φρουρεῖν, ἀπὸ δὲ τοῦ ἄλλου πεζοῦ τὰς ναῦς ἁπάσας, ὅσαι ἦσαν καὶ δυναταὶ καὶ ἀπλοώτεραι, πάντα τινὰ ἐσβιβάζοντες πληρῶσαι, καὶ διαναυμαχήσαντες, ἢν μὲν νικῶσιν, ἐς Κατάνην κομίζεσθαι, ἢν δὲ μή, ἐμπρήσαντες τὰς ναῦς πεζῇ ξυνταξάμενοι ἀποχωρεῖν ᾗ ἂν τάχιστα μέλλωσί τινος χωρίου ἢ βαρβαρικοῦ ἢ Ἑλληνικοῦ φιλίου ἀντιλήψεσθαι. καὶ οἱ μέν, ὡς ἔδοξεν αὐτοῖς ταῦτα, καὶ ἐποίησαν· ἔκ τε γὰρ τῶν ἄνω τειχῶν ὑποκατέβησαν καὶ τὰς ναῦς ἐπλήρωσαν πάσας, ἀναγκάσαντες ἐσβαίνειν ὅστις καὶ ὁπωσοῦν ἐδόκει ἡλικίας μετέχων ἐπιτήδειος εἶναι. καὶ ξυνεπληρώθησαν νῆες αἱ πᾶσαι δέκα μάλιστα καὶ ἑκατόν· τοξότας τε ἐπ’ αὐτὰς πολλοὺς καὶ ἀκοντιστὰς τῶν τε Ἀκαρνάνων καὶ τῶν ἄλλων ξένων ἐσεβίβαζον, καὶ τἆλλα ὡς οἷόν τ’ ἦν ἐξ ἀναγκαίου τε καὶ τοιαύτης διανοίας ἐπορίσαντο. ὁ δὲ Νικίας, ἐπειδὴ τὰ πολλὰ ἑτοῖμα ἦν, ὁρῶν τοὺς στρατιώτας τῷ τε παρὰ τὸ εἰωθὸς πολὺ ταῖς ναυσὶ κρατηθῆναι ἀθυμοῦντας καὶ διὰ τὴν τῶν ἐπιτηδείων σπάνιν ὡς τάχιστα βουλομένους διακινδυνεύειν, ξυγκαλέσας ἅπαντας παρεκελεύσατό τε πρῶτον καὶ ἔλεξε τοιάδε.", "st": "7.60"}, {"sp": "N", "t": "‘ἄνδρες στρατιῶται Ἀθηναίων τε καὶ τῶν ἄλλων ξυμμάχων, ὁ μὲν ἀγὼν ὁ μέλλων ὁμοίως κοινὸς ἅπασιν ἔσται περί τε σωτηρίας καὶ πατρίδος ἑκάστοις οὐχ ἧσσον ἢ τοῖς πολεμίοις· ἢν γὰρ κρατήσωμεν νῦν ταῖς ναυσίν, ἔστι τῳ τὴν ὑπάρχουσάν που οἰκείαν πόλιν ἐπιδεῖν. ἀθυμεῖν δὲ οὐ χρὴ οὐδὲ πάσχειν ὅπερ οἱ ἀπειρότατοι τῶν ἀνθρώπων, οἳ τοῖς πρώτοις ἀγῶσι σφαλέντες ἔπειτα διὰ παντὸς τὴν ἐλπίδα τοῦ φόβου ὁμοίαν ταῖς ξυμφοραῖς ἔχουσιν. ἀλλ’ ὅσοι τε Ἀθηναίων πάρεστε, πολλῶν ἤδη πολέμων ἔμπειροι ὄντες, καὶ ὅσοι τῶν ξυμμάχων, ξυστρατευόμενοι αἰεί, μνήσθητε τῶν ἐν τοῖς πολέμοις παραλόγων, καὶ τὸ τῆς τύχης κἂν μεθ’ ἡμῶν ἐλπίσαντες στῆναι καὶ ὡς ἀναμαχούμενοι ἀξίως τοῦδε τοῦ πλήθους, ὅσον αὐτοὶ ὑμῶν αὐτῶν ἐφορᾶτε, παρασκευάζεσθε.", "st": "7.61"}, {"sp": "N", "t": "‘ἃ δὲ ἀρωγὰ ἐνείδομεν ἐπὶ τῇ τοῦ λιμένος στενότητι πρὸς τὸν μέλλοντα ὄχλον τῶν νεῶν ἔσεσθαι καὶ πρὸς τὴν ἐκείνων ἐπὶ τῶν καταστρωμάτων παρασκευήν, οἷς πρότερον ἐβλαπτόμεθα, πάντα καὶ ἡμῖν νῦν ἐκ τῶν παρόντων μετὰ τῶν κυβερνητῶν ἐσκεμμένα ἡτοίμασται. καὶ γὰρ τοξόται πολλοὶ καὶ ἀκοντισταὶ ἐπιβήσονται καὶ ὄχλος, ᾧ ναυμαχίαν μὲν ποιούμενοι ἐν πελάγει οὐκ ἂν ἐχρώμεθα διὰ τὸ βλάπτειν ἂν τὸ τῆς ἐπιστήμης τῇ βαρύτητι τῶν νεῶν, ἐν δὲ τῇ ἐνθάδε ἠναγκασμένῃ ἀπὸ τῶν νεῶν πεζομαχίᾳ πρόσφορα ἔσται. ηὕρηται δ’ ἡμῖν ὅσα χρὴ ἀντιναυπηγῆσαι, καὶ πρὸς τὰς τῶν ἐπωτίδων αὐτοῖς παχύτητας, ᾧπερ δὴ μάλιστα ἐβλαπτόμεθα, χειρῶν σιδηρῶν ἐπιβολαί, αἳ σχήσουσι τὴν πάλιν ἀνάκρουσιν τῆς προσπεσούσης νεώς, ἢν τὰ ἐπὶ τούτοις οἱ ἐπιβάται ὑπουργῶσιν. ἐς τοῦτο γὰρ δὴ ἠναγκάσμεθα ὥστε πεζομαχεῖν ἀπὸ τῶν νεῶν, καὶ τὸ μήτε αὐτοὺς ἀνακρούεσθαι μήτ’ ἐκείνους ἐᾶν ὠφέλιμον φαίνεται, ἄλλως τε καὶ τῆς γῆς, πλὴν ὅσον ἂν ὁ πεζὸς ἡμῶν ἐπέχῃ, πολεμίας οὔσης.", "st": "7.62"}, {"sp": "N", "t": "‘ὧν χρὴ μεμνημένους διαμάχεσθαι ὅσον ἂν δύνησθε καὶ μὴ ἐξωθεῖσθαι ἐς αὐτήν, ἀλλὰ ξυμπεσούσης νηὶ νεὼς μὴ πρότερον ἀξιοῦν ἀπολύεσθαι ἢ τοὺς ἀπὸ τοῦ πολεμίου καταστρώματος ὁπλίτας ἀπαράξητε. καὶ ταῦτα τοῖς ὁπλίταις οὐχ ἧσσον τῶν ναυτῶν παρακελεύομαι, ὅσῳ τῶν ἄνωθεν μᾶλλον τὸ ἔργον τοῦτο· ὑπάρχει δ’ ἡμῖν ἔτι νῦν γε τὰ πλείω τῷ πεζῷ ἐπικρατεῖν. τοῖς δὲ ναύταις παραινῶ καὶ ἐν τῷ αὐτῷ τῷδε καὶ δέομαι μὴ ἐκπεπλῆχθαί τι ταῖς ξυμφοραῖς ἄγαν, τήν τε παρασκευὴν ἀπὸ τῶν καταστρωμάτων βελτίω νῦν ἔχοντας καὶ τὰς ναῦς πλείους, ἐκείνην τε τὴν ἡδονὴν ἐνθυμεῖσθαι ὡς ἀξία ἐστὶ διασώσασθαι, οἳ τέως Ἀθηναῖοι νομιζόμενοι καὶ μὴ ὄντες ἡμῶν τῆς τε φωνῆς τῇ ἐπιστήμῃ καὶ τῶν τρόπων τῇ μιμήσει ἐθαυμάζεσθε κατὰ τὴν Ἑλλάδα, καὶ τῆς ἀρχῆς τῆς ἡμετέρας οὐκ ἔλασσον κατὰ τὸ ὠφελεῖσθαι ἔς τε τὸ φοβερὸν τοῖς ὑπηκόοις καὶ τὸ μὴ ἀδικεῖσθαι πολὺ πλέον μετείχετε. ὥστε κοινωνοὶ μόνοι ἐλευθέρως ἡμῖν τῆς ἀρχῆς ὄντες δικαίως [ἂν] αὐτὴν νῦν μὴ καταπροδίδοτε, καταφρονήσαντες δὲ Κορινθίων τε, οὓς πολλάκις νενικήκατε, καὶ Σικελιωτῶν, ὧν οὐδ’ ἀντιστῆναι οὐδεὶς ἕως ἤκμαζε τὸ ναυτικὸν ἡμῖν ἠξίωσεν, ἀμύνασθε αὐτούς, καὶ δείξατε ὅτι καὶ μετ’ ἀσθενείας καὶ ξυμφορῶν ἡ ὑμετέρα ἐπιστήμη κρείσσων ἐστὶν ἑτέρας εὐτυχούσης ῥώμης.", "st": "7.63"}, {"sp": "N", "t": "τούς τε Ἀθηναίους ὑμῶν πάλιν αὖ καὶ τάδε ὑπομιμνῄσκω, ὅτι οὔτε ναῦς ἐν τοῖς νεωσοίκοις ἄλλας ὁμοίας ταῖσδε οὔτε ὁπλιτῶν ἡλικίαν ὑπελίπετε, εἴ τε ξυμβήσεταί τι ἄλλο ἢ τὸ κρατεῖν ὑμῖν, τούς τε ἐνθάδε πολεμίους εὐθὺς ἐπ’ ἐκεῖνα πλευσομένους καὶ τοὺς ἐκεῖ ὑπολοίπους ἡμῶν ἀδυνάτους ἐσομένους τούς τε αὐτοῦ καὶ τοὺς ἐπελθόντας ἀμύνασθαι. καὶ οἱ μὲν ἂν ὑπὸ Συρακοσίοις εὐθὺς γίγνοισθε, οἷς αὐτοὶ ἴστε οἵᾳ γνώμῃ ἐπήλθετε, οἱ δὲ ἐκεῖ ὑπὸ Λακεδαιμονίοις. ὥστε ἐν ἑνὶ τῷδε ὑπὲρ ἀμφοτέρων ἀγῶνι καθεστῶτες καρτερήσατε, εἴπερ ποτέ, καὶ ἐνθυμεῖσθε καθ’ ἑκάστους τε καὶ ξύμπαντες ὅτι οἱ ἐν ταῖς ναυσὶν ὑμῶν νῦν ἐσόμενοι καὶ πεζοὶ τοῖς Ἀθηναίοις εἰσὶ καὶ νῆες καὶ ἡ ὑπόλοιπος πόλις καὶ τὸ μέγα ὄνομα τῶν Ἀθηνῶν, περὶ ὧν, εἴ τίς τι ἕτερος ἑτέρου προφέρει ἢ ἐπιστήμῃ ἢ εὐψυχίᾳ, οὐκ ἂν ἐν ἄλλῳ μᾶλλον καιρῷ ἀποδειξάμενος αὐτός τε αὑτῷ ὠφέλιμος γένοιτο καὶ τοῖς ξύμπασι σωτήριος.’", "st": "7.64"}, {"sp": "N", "t": "ὁ μὲν Νικίας τοσαῦτα παρακελευσάμενος εὐθὺς ἐκέλευε πληροῦν τὰς ναῦς. τῷ δὲ Γυλίππῳ καὶ τοῖς Συρακοσίοις παρῆν μὲν αἰσθάνεσθαι, ὁρῶσι καὶ αὐτὴν τὴν παρασκευήν, ὅτι ναυμαχήσουσιν οἱ Ἀθηναῖοι, προηγγέλθη δ’ αὐτοῖς καὶ ἡ ἐπιβολὴ τῶν σιδηρῶν χειρῶν, καὶ πρός τε τἆλλα ἐξηρτύσαντο ὡς ἕκαστα καὶ πρὸς τοῦτο· τὰς γὰρ πρῴρας καὶ τῆς νεὼς ἄνω ἐπὶ πολὺ κατεβύρσωσαν, ὅπως ἂν ἀπολισθάνοι καὶ μὴ ἔχοι ἀντιλαβὴν ἡ χεὶρ ἐπιβαλλομένη. καὶ ἐπειδὴ πάντα ἑτοῖμα ἦν, παρεκελεύσαντο ἐκείνοις οἵ τε στρατηγοὶ καὶ Γύλιππος καὶ ἔλεξαν τοιάδε.", "st": "7.65"}, {"sp": "N", "t": "‘ὅτι μὲν καλὰ τὰ προειργασμένα καὶ ὑπὲρ καλῶν τῶν μελλόντων ὁ ἀγὼν ἔσται, ὦ Συρακόσιοι καὶ ξύμμαχοι, οἵ τε πολλοὶ δοκεῖτε ἡμῖν εἰδέναι (οὐδὲ γὰρ ἂν οὕτως αὐτῶν προθύμως ἀντελάβεσθε), καὶ εἴ τις μὴ ἐπὶ ὅσον δεῖ ᾔσθηται, σημανοῦμεν. Ἀθηναίους γὰρ ἐς τὴν χώραν τήνδε ἐλθόντας πρῶτον μὲν ἐπὶ τῆς Σικελίας καταδουλώσει, ἔπειτ’, εἰ κατορθώσειαν, καὶ τῆς Πελοποννήσου καὶ τῆς ἄλλης Ἑλλάδος, καὶ ἀρχὴν τὴν ἤδη μεγίστην τῶν τε πρὶν Ἑλλήνων καὶ τῶν νῦν κεκτημένους, πρῶτοι ἀνθρώπων ὑποστάντες τῷ ναυτικῷ, ᾧπερ πάντα κατέσχον, τὰς μὲν νενικήκατε ἤδη ναυμαχίας, τὴν δ’ ἐκ τοῦ εἰκότος νῦν νικήσετε. ἄνδρες γὰρ ἐπειδὰν ᾧ ἀξιοῦσι προύχειν κολουθῶσι, τό γ’ ὑπόλοιπον αὐτῶν τῆς δόξης ἀσθενέστερον αὐτὸ ἑαυτοῦ ἐστὶν ἢ εἰ μηδ’ ᾠήθησαν τὸ πρῶτον, καὶ τῷ παρ’ ἐλπίδα τοῦ αὐχήματος σφαλλόμενοι καὶ παρὰ ἰσχὺν τῆς δυνάμεως ἐνδιδόασιν· ὃ νῦν Ἀθηναίους εἰκὸς πεπονθέναι.", "st": "7.66"}, {"sp": "N", "t": "ἡμῶν δὲ τό τε ὑπάρχον πρότερον, ᾧπερ καὶ ἀνεπιστήμονες ἔτι ὄντες ἀπετολμήσαμεν, βεβαιότερον νῦν, καὶ τῆς δοκήσεως προσγεγενημένης αὐτῷ, τὸ κρατίστους εἶναι εἰ τοὺς κρατίστους ἐνικήσαμεν, διπλασία ἑκάστου ἡ ἐλπίς· τὰ δὲ πολλὰ πρὸς τὰς ἐπιχειρήσεις ἡ μεγίστη ἐλπὶς μεγίστην καὶ τὴν προθυμίαν παρέχεται.", "st": "7.67"}, {"sp": "N", "t": "‘τά τε τῆς ἀντιμιμήσεως αὐτῶν τῆς παρασκευῆς ἡμῶν τῷ μὲν ἡμετέρῳ τρόπῳ ξυνήθη τέ ἐστι καὶ οὐκ ἀνάρμοστοι πρὸς ἕκαστον αὐτῶν ἐσόμεθα· οἱ δ’, ἐπειδὰν πολλοὶ μὲν ὁπλῖται ἐπὶ τῶν καταστρωμάτων παρὰ τὸ καθεστηκὸς ὦσι, πολλοὶ δὲ καὶ ἀκοντισταὶ χερσαῖοι ὡς εἰπεῖν Ἀκαρνᾶνές τε καὶ ἄλλοι ἐπὶ ναῦς ἀναβάντες, οἳ οὐδ’ ὅπως καθεζομένους χρὴ τὸ βέλος ἀφεῖναι εὑρήσουσι, πῶς οὐ σφαλοῦσί τε τὰς ναῦς καὶ ἐν σφίσιν αὐτοῖς πάντες οὐκ ἐν τῷ ἑαυτῶν τρόπῳ κινούμενοι ταράξονται; ἐπεὶ καὶ τῷ πλήθει τῶν νεῶν οὐκ ὠφελήσονται, εἴ τις καὶ τόδε ὑμῶν, ὅτι οὐκ ἴσαις ναυμαχήσει, πεφόβηται· ἐν ὀλίγῳ γὰρ πολλαὶ ἀργότεραι μὲν ἐς τὸ δρᾶν τι ὧν βούλονται ἔσονται, ῥᾷσται δὲ ἐς τὸ βλάπτεσθαι ἀφ’ ὧν ἡμῖν παρεσκεύασται. τὸ δ’ ἀληθέστατον γνῶτε ἐξ ὧν ἡμεῖς οἰόμεθα σαφῶς πεπύσθαι· ὑπερβαλλόντων γὰρ αὐτοῖς τῶν κακῶν καὶ βιαζόμενοι ὑπὸ τῆς παρούσης ἀπορίας ἐς ἀπόνοιαν καθεστήκασιν οὐ παρασκευῆς πίστει μᾶλλον ἢ τύχης ἀποκινδυνεῦσαι οὕτως ὅπως δύνανται, ἵν’ ἢ βιασάμενοι ἐκπλεύσωσιν ἢ κατὰ γῆν μετὰ τοῦτο τὴν ἀποχώρησιν ποιῶνται, ὡς τῶν γε παρόντων οὐκ ἂν πράξαντες χεῖρον.", "st": "7.67"}, {"sp": "N", "t": "πρὸς οὖν ἀταξίαν τε τοιαύτην καὶ τύχην ἀνδρῶν ἑαυτὴν παραδεδωκυῖαν πολεμιωτάτων ὀργῇ προσμείξωμεν, καὶ νομίσωμεν ἅμα μὲν νομιμώτατον εἶναι πρὸς τοὺς ἐναντίους οἳ ἂν ὡς ἐπὶ τιμωρίᾳ τοῦ προσπεσόντος δικαιώσωσιν ἀποπλῆσαι τῆς γνώμης τὸ θυμούμενον, ἅμα δὲ ἐχθροὺς ἀμύνασθαι ἐκγενησόμενον ἡμῖν καὶ τὸ λεγόμενόν που ἥδιστον εἶναι. ὡς δὲ ἐχθροὶ καὶ ἔχθιστοι, πάντες ἴστε, οἵ γε ἐπὶ τὴν ἡμετέραν ἦλθον δουλωσόμενοι, ἐν ᾧ, εἰ κατώρθωσαν, ἀνδράσι μὲν ἂν τἄλγιστα προσέθεσαν, παισὶ δὲ καὶ γυναιξὶ τὰ ἀπρεπέστατα, πόλει δὲ τῇ πάσῃ τὴν αἰσχίστην ἐπίκλησιν. ἀνθ’ ὧν μὴ μαλακισθῆναί τινα πρέπει μηδὲ τὸ ἀκινδύνως ἀπελθεῖν αὐτοὺς κέρδος νομίσαι. τοῦτο μὲν γὰρ καὶ ἐὰν κρατήσωσιν ὁμοίως δράσουσιν· τὸ δὲ πραξάντων ἐκ τοῦ εἰκότος ἃ βουλόμεθα τούσδε τε κολασθῆναι καὶ τῇ πάσῃ Σικελίᾳ καρπουμένῃ καὶ πρὶν ἐλευθερίαν βεβαιοτέραν παραδοῦναι, καλὸς ὁ ἀγών. καὶ κινδύνων οὗτοι σπανιώτατοι οἳ ἂν ἐλάχιστα ἐκ τοῦ σφαλῆναι βλάπτοντες πλεῖστα διὰ τὸ εὐτυχῆσαι ὠφελῶσιν.’", "st": "7.68"}, {"sp": "N", "t": "καὶ οἱ μὲν τῶν Συρακοσίων στρατηγοὶ καὶ Γύλιππος τοιαῦτα καὶ αὐτοὶ τοῖς σφετέροις στρατιώταις παρακελευσάμενοι ἀντεπλήρουν τὰς ναῦς εὐθὺς ἐπειδὴ καὶ τοὺς Ἀθηναίους ᾐσθάνοντο. ὁ δὲ Νικίας ὑπὸ τῶν παρόντων ἐκπεπληγμένος καὶ ὁρῶν οἷος ὁ κίνδυνος καὶ ὡς ἐγγὺς ἤδη [ἦν], ἐπειδὴ καὶ ὅσον οὐκ ἔμελλον ἀνάγεσθαι, καὶ νομίσας, ὅπερ πάσχουσιν ἐν τοῖς μεγάλοις ἀγῶσι, πάντα τε ἔργῳ ἔτι σφίσιν ἐνδεᾶ εἶναι καὶ λόγῳ αὐτοῖς οὔπω ἱκανὰ εἰρῆσθαι, αὖθις τῶν τριηράρχων ἕνα ἕκαστον ἀνεκάλει, πατρόθεν τε ἐπονομάζων καὶ αὐτοὺς ὀνομαστὶ καὶ φυλήν, ἀξιῶν τό τε καθ’ ἑαυτόν, ᾧ ὑπῆρχε λαμπρότητός τι, μὴ προδιδόναι τινὰ καὶ τὰς πατρικὰς ἀρετάς, ὧν ἐπιφανεῖς ἦσαν οἱ πρόγονοι, μὴ ἀφανίζειν, πατρίδος τε τῆς ἐλευθερωτάτης ὑπομιμνῄσκων καὶ τῆς ἐν αὐτῇ ἀνεπιτάκτου πᾶσιν ἐς τὴν δίαιταν ἐξουσίας, ἄλλα τε λέγων ὅσα ἐν τῷ τοιούτῳ ἤδη τοῦ καιροῦ ὄντες ἄνθρωποι οὐ πρὸς τὸ δοκεῖν τινὶ ἀρχαιολογεῖν φυλαξάμενοι εἴποιεν ἄν, καὶ ὑπὲρ ἁπάντων παραπλήσια ἔς τε γυναῖκας καὶ παῖδας καὶ θεοὺς πατρῴους προφερόμενα, ἀλλ’ ἐπὶ τῇ παρούσῃ ἐκπλήξει ὠφέλιμα νομίζοντες ἐπιβοῶνται.", "st": "7.69"}, {"sp": "N", "t": "καὶ ὁ μὲν οὐχ ἱκανὰ μᾶλλον ἢ καὶ ἀναγκαῖα νομίσας παρῃνῆσθαι, ἀποχωρήσας ἦγε τὸν πεζὸν πρὸς τὴν θάλασσαν καὶ παρέταξεν ὡς ἐπὶ πλεῖστον ἐδύνατο, ὅπως ὅτι μεγίστη τοῖς ἐν ταῖς ναυσὶν ὠφελία ἐς τὸ θαρσεῖν γίγνοιτο· ὁ δὲ Δημοσθένης καὶ Μένανδρος καὶ Εὐθύδημος (οὗτοι γὰρ ἐπὶ τὰς ναῦς τῶν Ἀθηναίων στρατηγοὶ ἐπέβησαν) ἄραντες ἀπὸ τοῦ ἑαυτῶν στρατοπέδου εὐθὺς ἔπλεον πρὸς τὸ ζεῦγμα τοῦ λιμένος καὶ τὸν παραλειφθέντα διέκπλουν, βουλόμενοι βιάσασθαι ἐς τὸ ἔξω.", "st": "7.69"}, {"sp": "N", "t": "προεξαγαγόμενοι δὲ οἱ Συρακόσιοι καὶ οἱ ξύμμαχοι ναυσὶ παραπλησίαις τὸν ἀριθμὸν καὶ πρότερον, κατά τε τὸν ἔκπλουν μέρει αὐτῶν ἐφύλασσον καὶ κατὰ τὸν ἄλλον κύκλῳ λιμένα, ὅπως πανταχόθεν ἅμα προσπίπτοιεν τοῖς Ἀθηναίοις, καὶ ὁ πεζὸς ἅμα αὐτοῖς παρεβοήθει ᾗπερ καὶ αἱ νῆες κατίσχοιεν. ἦρχον δὲ τοῦ ναυτικοῦ τοῖς Συρακοσίοις Σικανὸς μὲν καὶ Ἀγάθαρχος, κέρας ἑκάτερος τοῦ παντὸς ἔχων, Πυθὴν δὲ καὶ οἱ Κορίνθιοι τὸ μέσον. ἐπειδὴ δὲ οἱ ἄλλοι Ἀθηναῖοι προσέμισγον τῷ ζεύγματι, τῇ μὲν πρώτῃ ῥύμῃ ἐπιπλέοντες ἐκράτουν τῶν τεταγμένων νεῶν πρὸς αὐτῷ καὶ ἐπειρῶντο λύειν τὰς κλῄσεις· μετὰ δὲ τοῦτο πανταχόθεν σφίσι τῶν Συρακοσίων καὶ ξυμμάχων ἐπιφερομένων οὐ πρὸς τῷ ζεύγματι ἔτι μόνον ἡ ναυμαχία, ἀλλὰ καὶ κατὰ τὸν λιμένα ἐγίγνετο, καὶ ἦν καρτερὰ καὶ οἵα οὐχ ἑτέρα τῶν προτέρων. πολλὴ μὲν γὰρ ἑκατέροις προθυμία ἀπὸ τῶν ναυτῶν ἐς τὸ ἐπιπλεῖν ὁπότε κελευσθείη ἐγίγνετο, πολλὴ δὲ ἡ ἀντιτέχνησις τῶν κυβερνητῶν καὶ ἀγωνισμὸς πρὸς ἀλλήλους· οἵ τε ἐπιβάται ἐθεράπευον, ὁπότε προσπέσοι ναῦς νηί, μὴ λείπεσθαι τὰ ἀπὸ τοῦ καταστρώματος τῆς ἄλλης τέχνης· πᾶς τέ τις ἐν ᾧ προσετέτακτο αὐτὸς ἕκαστος ἠπείγετο πρῶτος φαίνεσθαι. ξυμπεσουσῶν δὲ ἐν ὀλίγῳ πολλῶν νεῶν (πλεῖσται γὰρ δὴ αὗται ἐν ἐλαχίστῳ ἐναυμάχησαν· βραχὺ γὰρ ἀπέλιπον ξυναμφότεραι διακόσιαι γενέσθαι) αἱ μὲν ἐμβολαὶ διὰ τὸ μὴ εἶναι τὰς ἀνακρούσεις καὶ διέκπλους ὀλίγαι ἐγίγνοντο, αἱ δὲ προσβολαί, ὡς τύχοι ναῦς νηὶ προσπεσοῦσα ἢ διὰ τὸ φεύγειν ἢ ἄλλῃ ἐπιπλέουσα, πυκνότεραι ἦσαν. καὶ ὅσον μὲν χρόνον προσφέροιτο ναῦς, οἱ ἀπὸ τῶν καταστρωμάτων τοῖς ἀκοντίοις καὶ τοξεύμασι καὶ λίθοις ἀφθόνως ἐπ’ αὐτὴν ἐχρῶντο· ἐπειδὴ δὲ προσμείξειαν, οἱ ἐπιβάται ἐς χεῖρας ἰόντες ἐπειρῶντο ταῖς ἀλλήλων ναυσὶν ἐπιβαίνειν. ξυνετύγχανέ τε πολλαχοῦ διὰ τὴν στενοχωρίαν τὰ μὲν ἄλλοις ἐμβεβληκέναι, τὰ δὲ αὐτοὺς ἐμβεβλῆσθαι, δύο τε περὶ μίαν καὶ ἔστιν ᾗ καὶ πλείους ναῦς κατ’ ἀνάγκην ξυνηρτῆσθαι, καὶ τοῖς κυβερνήταις τῶν μὲν φυλακήν, τῶν δ’ ἐπιβουλήν, μὴ καθ’ ἓν ἕκαστον, κατὰ πολλὰ δὲ πανταχόθεν, περιεστάναι, καὶ τὸν κτύπον μέγαν ἀπὸ πολλῶν νεῶν ξυμπιπτουσῶν ἔκπληξίν τε ἅμα καὶ ἀποστέρησιν τῆς ἀκοῆς ὧν οἱ κελευσταὶ φθέγγοιντο παρέχειν. πολλὴ γὰρ δὴ ἡ παρακέλευσις καὶ βοὴ ἀφ’ ἑκατέρων τοῖς κελευσταῖς κατά τε τὴν τέχνην καὶ πρὸς τὴν αὐτίκα φιλονικίαν ἐγίγνετο, τοῖς μὲν Ἀθηναίοις βιάζεσθαί τε τὸν ἔκπλουν ἐπιβοῶντες καὶ περὶ τῆς ἐς τὴν πατρίδα σωτηρίας νῦν, εἴ ποτε καὶ αὖθις, προθύμως ἀντιλαβέσθαι, τοῖς δὲ Συρακοσίοις καὶ ξυμμάχοις καλὸν εἶναι κωλῦσαί τε αὐτοὺς διαφυγεῖν καὶ τὴν οἰκείαν ἑκάστους πατρίδα νικήσαντας ἐπαυξῆσαι. καὶ οἱ στρατηγοὶ προσέτι ἑκατέρων, εἴ τινά που ὁρῷεν μὴ κατ’ ἀνάγκην πρύμναν κρουόμενον, ἀνακαλοῦντες ὀνομαστὶ τὸν τριήραρχον ἠρώτων, οἱ μὲν Ἀθηναῖοι εἰ τὴν πολεμιωτάτην γῆν οἰκειοτέραν ἤδη τῆς οὐ δι’ ὀλίγου πόνου κεκτημένης θαλάσσης ἡγούμενοι ὑποχωροῦσιν, οἱ δὲ Συρακόσιοι εἰ οὓς σαφῶς ἴσασι προθυμουμένους Ἀθηναίους παντὶ τρόπῳ διαφυγεῖν, τούτους αὐτοὶ φεύγοντας φεύγουσιν.", "st": "7.70"}, {"sp": "N", "t": "ὅ τε ἐκ τῆς γῆς πεζὸς ἀμφοτέρων ἰσορρόπου τῆς ναυμαχίας καθεστηκυίας πολὺν τὸν ἀγῶνα καὶ ξύστασιν τῆς γνώμης εἶχε, φιλονικῶν μὲν ὁ αὐτόθεν περὶ τοῦ πλέονος ἤδη καλοῦ, δεδιότες δὲ οἱ ἐπελθόντες μὴ τῶν παρόντων ἔτι χείρω πράξωσιν. πάντων γὰρ δὴ ἀνακειμένων τοῖς Ἀθηναίοις ἐς τὰς ναῦς ὅ τε φόβος ἦν ὑπὲρ τοῦ μέλλοντος οὐδενὶ ἐοικώς, καὶ διὰ τὸ ⟨ἀνώμαλον⟩ τῆς ναυμαχίας ἀνώμαλον καὶ τὴν ἔποψιν ἐκ τῆς γῆς ἠναγκάζοντο ἔχειν. δι’ ὀλίγου γὰρ οὔσης τῆς θέας καὶ οὐ πάντων ἅμα ἐς τὸ αὐτὸ σκοπούντων, εἰ μέν τινες ἴδοιέν πῃ τοὺς σφετέρους ἐπικρατοῦντας, ἀνεθάρσησάν τε ἂν καὶ πρὸς ἀνάκλησιν θεῶν μὴ στερῆσαι σφᾶς τῆς σωτηρίας ἐτρέποντο, οἱ δ’ ἐπὶ τὸ ἡσσώμενον βλέψαντες ὀλοφυρμῷ τε ἅμα μετὰ βοῆς ἐχρῶντο καὶ ἀπὸ τῶν δρωμένων τῆς ὄψεως καὶ τὴν γνώμην μᾶλλον τῶν ἐν τῷ ἔργῳ ἐδουλοῦντο· ἄλλοι δὲ καὶ πρὸς ἀντίπαλόν τι τῆς ναυμαχίας ἀπιδόντες, διὰ τὸ ἀκρίτως ξυνεχὲς τῆς ἁμίλλης καὶ τοῖς σώμασιν αὐτοῖς ἴσα τῇ δόξῃ περιδεῶς ξυναπονεύοντες ἐν τοῖς χαλεπώτατα διῆγον· αἰεὶ γὰρ παρ’ ὀλίγον ἢ διέφευγον ἢ ἀπώλλυντο. ἦν τε ἐν τῷ αὐτῷ στρατεύματι τῶν Ἀθηναίων, ἕως ἀγχώμαλα ἐναυμάχουν, πάντα ὁμοῦ ἀκοῦσαι, ὀλοφυρμὸς βοή, νικῶντες κρατούμενοι, ἄλλα ὅσα ἐν μεγάλῳ κινδύνῳ μέγα στρατόπεδον πολυειδῆ ἀναγκάζοιτο φθέγγεσθαι. παραπλήσια δὲ καὶ οἱ ἐπὶ τῶν νεῶν αὐτοῖς ἔπασχον, πρίν γε δὴ οἱ Συρακόσιοι καὶ οἱ ξύμμαχοι ἐπὶ πολὺ ἀντισχούσης τῆς ναυμαχίας ἔτρεψάν τε τοὺς Ἀθηναίους καὶ ἐπικείμενοι λαμπρῶς, πολλῇ κραυγῇ καὶ διακελευσμῷ χρώμενοι, κατεδίωκον ἐς τὴν γῆν. τότε δὲ ὁ μὲν ναυτικὸς στρατὸς ἄλλος ἄλλῃ, ὅσοι μὴ μετέωροι ἑάλωσαν, κατενεχθέντες ἐξέπεσον ἐς τὸ στρατόπεδον· ὁ δὲ πεζὸς οὐκέτι διαφόρως, ἀλλ’ ἀπὸ μιᾶς ὁρμῆς οἰμωγῇ τε καὶ στόνῳ πάντες δυσανασχετοῦντες τὰ γιγνόμενα, οἱ μὲν ἐπὶ τὰς ναῦς παρεβοήθουν, οἱ δὲ πρὸς τὸ λοιπὸν τοῦ τείχους ἐς φυλακήν, ἄλλοι δὲ καὶ οἱ πλεῖστοι ἤδη περὶ σφᾶς αὐτοὺς καὶ ὅπῃ σωθήσονται διεσκόπουν. ἦν τε ἐν τῷ παραυτίκα οὐδεμιᾶς δὴ τῶν ξυμπασῶν ἐλάσσων ἔκπληξις. παραπλήσιά τε ἐπεπόνθεσαν καὶ ἔδρασαν αὐτοὶ ἐν Πύλῳ· διαφθαρεισῶν γὰρ τῶν νεῶν τοῖς Λακεδαιμονίοις προσαπώλλυντο αὐτοῖς καὶ οἱ ἐν τῇ νήσῳ ἄνδρες διαβεβηκότες, καὶ τότε τοῖς Ἀθηναίοις ἀνέλπιστον ἦν τὸ κατὰ γῆν σωθήσεσθαι, ἢν μή τι παρὰ λόγον γίγνηται.", "st": "7.71"}, {"sp": "N", "t": "γενομένης δ’ ἰσχυρᾶς τῆς ναυμαχίας καὶ πολλῶν νεῶν ἀμφοτέροις καὶ ἀνθρώπων ἀπολομένων οἱ Συρακόσιοι καὶ οἱ ξύμμαχοι ἐπικρατήσαντες τά τε ναυάγια καὶ τοὺς νεκροὺς ἀνείλοντο, καὶ ἀποπλεύσαντες πρὸς τὴν πόλιν τροπαῖον ἔστησαν, οἱ δ’ Ἀθηναῖοι ὑπὸ μεγέθους τῶν παρόντων κακῶν νεκρῶν μὲν πέρι ἢ ναυαγίων οὐδὲ ἐπενόουν αἰτῆσαι ἀναίρεσιν, τῆς δὲ νυκτὸς ἐβουλεύοντο εὐθὺς ἀναχωρεῖν. Δημοσθένης δὲ Νικίᾳ προσελθὼν γνώμην ἐποιεῖτο πληρώσαντας ἔτι τὰς λοιπὰς τῶν νεῶν βιάσασθαι, ἢν δύνωνται, ἅμα ἕῳ τὸν ἔκπλουν, λέγων ὅτι πλείους ἔτι αἱ λοιπαί εἰσι νῆες χρήσιμαι σφίσιν ἢ τοῖς πολεμίοις· ἦσαν γὰρ τοῖς μὲν Ἀθηναίοις περίλοιποι ὡς ἑξήκοντα, τοῖς δ’ ἐναντίοις ἐλάσσους ἢ πεντήκοντα. καὶ ξυγχωροῦντος Νικίου τῇ γνώμῃ καὶ βουλομένων πληροῦν αὐτῶν οἱ ναῦται οὐκ ἤθελον ἐσβαίνειν διὰ τὸ καταπεπλῆχθαί τε τῇ ἥσσῃ καὶ μὴ ἂν ἔτι οἴεσθαι κρατῆσαι.", "st": "7.72"}, {"sp": "N", "t": "καὶ οἱ μὲν ὡς κατὰ γῆν ἀναχωρήσοντες ἤδη ξύμπαντες τὴν γνώμην εἶχον, Ἑρμοκράτης δὲ ὁ Συρακόσιος ὑπονοήσας αὐτῶν τὴν διάνοιαν καὶ νομίσας δεινὸν εἶναι εἰ τοσαύτη στρατιὰ κατὰ γῆν ὑποχωρήσασα καὶ καθεζομένη ποι τῆς Σικελίας βουλήσεται αὖθις σφίσι τὸν πόλεμον ποιεῖσθαι, ἐσηγεῖται ἐλθὼν τοῖς ἐν τέλει οὖσιν ὡς οὐ χρεὼν ἀποχωρῆσαι τῆς νυκτὸς αὐτοὺς περιιδεῖν, λέγων ταῦτα ἃ καὶ αὐτῷ ἐδόκει, ἀλλὰ ἐξελθόντας ἤδη πάντας Συρακοσίους καὶ τοὺς ξυμμάχους τάς τε ὁδοὺς ἀποικοδομῆσαι καὶ τὰ στενόπορα τῶν χωρίων προδιαλαβόντας φυλάσσειν. οἱ δὲ ξυνεγίγνωσκον μὲν καὶ αὐτοὶ οὐχ ἧσσον ταῦτα ἐκείνου, καὶ ἐδόκει ποιητέα εἶναι, τοὺς δὲ ἀνθρώπους ἄρτι ἀσμένους ἀπὸ ναυμαχίας τε μεγάλης ἀναπεπαυμένους καὶ ἅμα ἑορτῆς οὔσης (ἔτυχε γὰρ αὐτοῖς Ἡρακλεῖ ταύτην τὴν ἡμέραν θυσία οὖσα) οὐ δοκεῖν ἂν ῥᾳδίως ἐθελῆσαι ὑπακοῦσαι· ὑπὸ γὰρ τοῦ περιχαροῦς τῆς νίκης πρὸς πόσιν τετράφθαι τοὺς πολλοὺς ἐν τῇ ἑορτῇ, καὶ πάντα μᾶλλον ἐλπίζειν ἂν σφῶν πείθεσθαι αὐτοὺς ἢ ὅπλα λαβόντας ἐν τῷ παρόντι ἐξελθεῖν. ὡς δὲ τοῖς ἄρχουσι ταῦτα λογιζομένοις ἐφαίνετο ἄπορα καὶ οὐκέτι ἔπειθεν αὐτοὺς ὁ Ἑρμοκράτης, αὐτὸς ἐπὶ τούτοις τάδε μηχανᾶται, δεδιὼς μὴ οἱ Ἀθηναῖοι καθ’ ἡσυχίαν προφθάσωσιν ἐν τῇ νυκτὶ διελθόντες τὰ χαλεπώτατα τῶν χωρίων. πέμπει τῶν ἑταίρων τινὰς τῶν ἑαυτοῦ μετὰ ἱππέων πρὸς τὸ τῶν Ἀθηναίων στρατόπεδον, ἡνίκα ξυνεσκόταζεν· οἳ προσελάσαντες ἐξ ὅσου τις ἔμελλεν ἀκούσεσθαι καὶ ἀνακαλεσάμενοί τινας ὡς ὄντες τῶν Ἀθηναίων ἐπιτήδειοι (ἦσαν γάρ τινες τῷ Νικίᾳ διάγγελοι τῶν ἔνδοθεν) ἐκέλευον φράζειν Νικίᾳ μὴ ἀπάγειν τῆς νυκτὸς τὸ στράτευμα ὡς Συρακοσίων τὰς ὁδοὺς φυλασσόντων, ἀλλὰ καθ’ ἡσυχίαν τῆς ἡμέρας παρασκευασάμενον ἀποχωρεῖν. καὶ οἱ μὲν εἰπόντες ἀπῆλθον, καὶ οἱ ἀκούσαντες διήγγειλαν τοῖς στρατηγοῖς τῶν Ἀθηναίων·", "st": "7.73"}, {"sp": "N", "t": "οἱ δὲ πρὸς τὸ ἄγγελμα ἐπέσχον τὴν νύκτα, νομίσαντες οὐκ ἀπάτην εἶναι. καὶ ἐπειδὴ καὶ ὣς οὐκ εὐθὺς ὥρμησαν, ἔδοξεν αὐτοῖς καὶ τὴν ἐπιοῦσαν ἡμέραν περιμεῖναι, ὅπως ξυσκευάσαιντο ὡς ἐκ τῶν δυνατῶν οἱ στρατιῶται ὅτι χρησιμώτατα, καὶ τὰ μὲν ἄλλα πάντα καταλιπεῖν, ἀναλαβόντες δὲ αὐτὰ ὅσα περὶ τὸ σῶμα ἐς δίαιταν ὑπῆρχεν ἐπιτήδεια ἀφορμᾶσθαι. Συρακόσιοι δὲ καὶ Γύλιππος τῷ μὲν πεζῷ προεξελθόντες τάς τε ὁδοὺς τὰς κατὰ τὴν χώραν, ᾗ εἰκὸς ἦν τοὺς Ἀθηναίους ἰέναι, ἀπεφάργνυσαν καὶ τῶν ῥείθρων καὶ [τῶν] ποταμῶν τὰς διαβάσεις ἐφύλασσον καὶ ἐς ὑποδοχὴν τοῦ στρατεύματος ὡς κωλύσοντες ᾗ ἐδόκει ἐτάσσοντο· ταῖς δὲ ναυσὶ προσπλεύσαντες τὰς ναῦς τῶν Ἀθηναίων ἀπὸ τοῦ αἰγιαλοῦ ἀφεῖλκον (ἐνέπρησαν δέ τινας ὀλίγας, ὥσπερ διενοήθησαν, αὐτοὶ οἱ Ἀθηναῖοι), τὰς δ’ ἄλλας καθ’ ἡσυχίαν οὐδενὸς κωλύοντος ὡς ἑκάστην ποι ἐκπεπτωκυῖαν ἀναδησάμενοι ἐκόμιζον ἐς τὴν πόλιν.", "st": "7.74"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο, ἐπειδὴ ἐδόκει τῷ Νικίᾳ καὶ τῷ Δημοσθένει ἱκανῶς παρεσκευάσθαι, καὶ ἡ ἀνάστασις ἤδη τοῦ στρατεύματος τρίτῃ ἡμέρᾳ ἀπὸ τῆς ναυμαχίας ἐγίγνετο. δεινὸν οὖν ἦν οὐ καθ’ ἓν μόνον τῶν πραγμάτων, ὅτι τάς τε ναῦς ἀπολωλεκότες πάσας ἀπεχώρουν καὶ ἀντὶ μεγάλης ἐλπίδος καὶ αὐτοὶ καὶ ἡ πόλις κινδυνεύοντες, ἀλλὰ καὶ ἐν τῇ ἀπολείψει τοῦ στρατοπέδου ξυνέβαινε τῇ τε ὄψει ἑκάστῳ ἀλγεινὰ καὶ τῇ γνώμῃ αἰσθέσθαι. τῶν τε γὰρ νεκρῶν ἀτάφων ὄντων, ὁπότε τις ἴδοι τινὰ τῶν ἐπιτηδείων κείμενον, ἐς λύπην μετὰ φόβου καθίστατο, καὶ οἱ ζῶντες καταλειπόμενοι τραυματίαι τε καὶ ἀσθενεῖς πολὺ τῶν τεθνεώτων τοῖς ζῶσι λυπηρότεροι ἦσαν καὶ τῶν ἀπολωλότων ἀθλιώτεροι. πρὸς γὰρ ἀντιβολίαν καὶ ὀλοφυρμὸν τραπόμενοι ἐς ἀπορίαν καθίστασαν, ἄγειν τε σφᾶς ἀξιοῦντες καὶ ἕνα ἕκαστον ἐπιβοώμενοι, εἴ τινά πού τις ἴδοι ἢ ἑταίρων ἢ οἰκείων, τῶν τε ξυσκήνων ἤδη ἀπιόντων ἐκκρεμαννύμενοι καὶ ἐπακολουθοῦντες ἐς ὅσον δύναιντο, εἴ τῳ δὲ προλίποι ἡ ῥώμη καὶ τὸ σῶμα, οὐκ ἄνευ ὀλίγων ἐπιθειασμῶν καὶ οἰμωγῆς ὑπολειπόμενοι, ὥστε δάκρυσι πᾶν τὸ στράτευμα πλησθὲν καὶ ἀπορίᾳ τοιαύτῃ μὴ ῥᾳδίως ἀφορμᾶσθαι, καίπερ ἐκ πολεμίας τε καὶ μείζω ἢ κατὰ δάκρυα τὰ μὲν πεπονθότας ἤδη, τὰ δὲ περὶ τῶν ἐν ἀφανεῖ δεδιότας μὴ πάθωσιν. κατήφειά τέ τις ἅμα καὶ κατάμεμψις σφῶν αὐτῶν πολλὴ ἦν. οὐδὲν γὰρ ἄλλο ἢ πόλει ἐκπεπολιορκημένῃ ἐῴκεσαν ὑποφευγούσῃ, καὶ ταύτῃ οὐ σμικρᾷ· μυριάδες γὰρ τοῦ ξύμπαντος ὄχλου οὐκ ἐλάσσους τεσσάρων ἅμα ἐπορεύοντο. καὶ τούτων οἵ τε ἄλλοι πάντες ἔφερον ὅτι τις ἐδύνατο ἕκαστος χρήσιμον, καὶ οἱ ὁπλῖται καὶ οἱ ἱππῆς παρὰ τὸ εἰωθὸς αὐτοὶ τὰ σφέτερα αὐτῶν σιτία ὑπὸ τοῖς ὅπλοις, οἱ μὲν ἀπορίᾳ ἀκολούθων, οἱ δὲ ἀπιστίᾳ· ἀπηυτομολήκεσαν γὰρ πάλαι τε καὶ οἱ πλεῖστοι παραχρῆμα. ἔφερον δὲ οὐδὲ ταῦτα ἱκανά· σῖτος γὰρ οὐκέτι ἦν ἐν τῷ στρατοπέδῳ. καὶ μὴν ἡ ἄλλη αἰκία καὶ ἡ ἰσομοιρία τῶν κακῶν, ἔχουσά τινα ὅμως τὸ μετὰ πολλῶν κούφισιν, οὐδ’ ὣς ῥᾳδία ἐν τῷ παρόντι ἐδοξάζετο, ἄλλως τε καὶ ἀπὸ οἵας λαμπρότητος καὶ αὐχήματος τοῦ πρώτου ἐς οἵαν τελευτὴν καὶ ταπεινότητα ἀφῖκτο. μέγιστον γὰρ δὴ τὸ διάφορον τοῦτο [τῷ] Ἑλληνικῷ στρατεύματι ἐγένετο, οἷς ἀντὶ μὲν τοῦ ἄλλους δουλωσομένους ἥκειν αὐτοὺς τοῦτο μᾶλλον δεδιότας μὴ πάθωσι ξυνέβη ἀπιέναι, ἀντὶ δ’ εὐχῆς τε καὶ παιάνων, μεθ’ ὧν ἐξέπλεον, πάλιν τούτων τοῖς ἐναντίοις ἐπιφημίσμασιν ἀφορμᾶσθαι, πεζούς τε ἀντὶ ναυβατῶν πορευομένους καὶ ὁπλιτικῷ προσέχοντας μᾶλλον ἢ ναυτικῷ. ὅμως δὲ ὑπὸ μεγέθους τοῦ ἐπικρεμαμένου ἔτι κινδύνου πάντα ταῦτα αὐτοῖς οἰστὰ ἐφαίνετο.", "st": "7.75"}, {"sp": "N", "t": "ὁρῶν δὲ ὁ Νικίας τὸ στράτευμα ἀθυμοῦν καὶ ἐν μεγάλῃ μεταβολῇ ὄν, ἐπιπαριὼν ὡς ἐκ τῶν ὑπαρχόντων ἐθάρσυνέ τε καὶ παρεμυθεῖτο, βοῇ τε χρώμενος ἔτι μᾶλλον ἑκάστοις καθ’ οὓς γίγνοιτο ὑπὸ προθυμίας καὶ βουλόμενος ὡς ἐπὶ πλεῖστον γεγωνίσκων ὠφελεῖν τι.", "st": "7.76"}, {"sp": "N", "t": "‘καὶ ἐκ τῶν παρόντων, ὦ Ἀθηναῖοι καὶ ξύμμαχοι, ἐλπίδα χρὴ ἔχειν (ἤδη τινὲς καὶ ἐκ δεινοτέρων ἢ τοιῶνδε ἐσώθησαν), μηδὲ καταμέμφεσθαι ὑμᾶς ἄγαν αὐτοὺς μήτε ταῖς ξυμφοραῖς μήτε ταῖς παρὰ τὴν ἀξίαν νῦν κακοπαθίαις. κἀγώ τοι οὐδενὸς ὑμῶν οὔτε ῥώμῃ προφέρων (ἀλλ’ ὁρᾶτε δὴ ὡς διάκειμαι ὑπὸ τῆς νόσου) οὔτ’ εὐτυχίᾳ δοκῶν που ὕστερός του εἶναι κατά τε τὸν ἴδιον βίον καὶ ἐς τὰ ἄλλα, νῦν ἐν τῷ αὐτῷ κινδύνῳ τοῖς φαυλοτάτοις αἰωροῦμαι· καίτοι πολλὰ μὲν ἐς θεοὺς νόμιμα δεδιῄτημαι, πολλὰ δὲ ἐς ἀνθρώπους δίκαια καὶ ἀνεπίφθονα. ἀνθ’ ὧν ἡ μὲν ἐλπὶς ὅμως θρασεῖα τοῦ μέλλοντος, αἱ δὲ ξυμφοραὶ οὐ κατ’ ἀξίαν δὴ φοβοῦσιν. τάχα δὲ ἂν καὶ λωφήσειαν· ἱκανὰ γὰρ τοῖς τε πολεμίοις ηὐτύχηται, καὶ εἴ τῳ θεῶν ἐπίφθονοι ἐστρατεύσαμεν, ἀποχρώντως ἤδη τετιμωρήμεθα. ἦλθον γάρ που καὶ ἄλλοι τινὲς ἤδη ἐφ’ ἑτέρους, καὶ ἀνθρώπεια δράσαντες ἀνεκτὰ ἔπαθον. καὶ ἡμᾶς εἰκὸς νῦν τά τε ἀπὸ τοῦ θεοῦ ἐλπίζειν ἠπιώτερα ἕξειν (οἴκτου γὰρ ἀπ’ αὐτῶν ἀξιώτεροι ἤδη ἐσμὲν ἢ φθόνοθυ), καὶ ὁρῶντες ὑμᾶς αὐτοὺς οἷοι ὁπλῖται ἅμα καὶ ὅσοι ξυντεταγμένοι χωρεῖτε μὴ καταπέπληχθε ἄγαν, λογίζεσθε δὲ ὅτι αὐτοί τε πόλις εὐθύς ἐστε ὅποι ἂν καθέζησθε καὶ ἄλλη οὐδεμία ὑμᾶς τῶν ἐν Σικελίᾳ οὔτ’ ἂν ἐπιόντας δέξαιτο ῥᾳδίως οὔτ’ ἂν ἱδρυθέντας που ἐξαναστήσειεν. τὴν δὲ πορείαν ὥστ’ ἀσφαλῆ καὶ εὔτακτον εἶναι αὐτοὶ φυλάξατε, μὴ ἄλλο τι ἡγησάμενος ἕκαστος ἢ ἐν ᾧ ἂν ἀναγκασθῇ χωρίῳ μάχεσθαι, τοῦτο καὶ πατρίδα καὶ τεῖχος κρατήσας ἕξειν. σπουδὴ δὲ ὁμοίως καὶ νύκτα καὶ ἡμέραν ἔσται τῆς ὁδοῦ· τὰ γὰρ ἐπιτήδεια βραχέα ἔχομεν, καὶ ἢν ἀντιλαβώμεθά του φιλίου χωρίου τῶν Σικελῶν (οὗτοι γὰρ ἡμῖν διὰ τὸ Συρακοσίων δέος ἔτι βέβαιοι εἰσίν), ἤδη νομίζετε ἐν τῷ ἐχυρῷ εἶναι. προπέπεμπται δ’ ὡς αὐτούς, καὶ ἀπαντᾶν εἰρημένον καὶ σιτία ἄλλα κομίζειν. ‘τό τε ξύμπαν γνῶτε, ὦ ἄνδρες στρατιῶται, ἀναγκαῖόν τε ὂν ὑμῖν ἀνδράσιν ἀγαθοῖς γίγνεσθαι ὡς μὴ ὄντος χωρίου ἐγγὺς ὅποι ἂν μαλακισθέντες σωθείητε καί, ἢν νῦν διαφύγητε τοὺς πολεμίους, οἵ τε ἄλλοι τευξόμενοι ὧν ἐπιθυμεῖτέ που ἐπιδεῖν καὶ οἱ Ἀθηναῖοι τὴν μεγάλην δύναμιν τῆς πόλεως καίπερ πεπτωκυῖαν ἐπανορθώσοντες· ἄνδρες γὰρ πόλις, καὶ οὐ τείχη οὐδὲ νῆες ἀνδρῶν κεναί.’", "st": "7.77"}, {"sp": "N", "t": "ὁ μὲν Νικίας τοιάδε παρακελευόμενος ἅμα ἐπῄει τὸ στράτευμα, καὶ εἴ πῃ ὁρῴη διεσπασμένον καὶ μὴ ἐν τάξει χωροῦν ξυνάγων καὶ καθιστάς, καὶ ὁ Δημοσθένης οὐδὲν ἧσσον τοῖς καθ’ ἑαυτὸν τοιαῦτά τε καὶ παραπλήσια λέγων. τὸ δὲ ἐχώρει ἐν πλαισίῳ τεταγμένον, πρῶτον μὲν ἡγούμενον τὸ Νικίου, ἐφεπόμενον δὲ τὸ Δημοσθένους· τοὺς δὲ σκευοφόρους καὶ τὸν πλεῖστον ὄχλον ἐντὸς εἶχον οἱ ὁπλῖται. καὶ ἐπειδή [τε] ἐγένοντο ἐπὶ τῇ διαβάσει τοῦ Ἀνάπου ποταμοῦ, ηὗρον ἐπ’ αὐτῷ παρατεταγμένους τῶν Συρακοσίων καὶ ξυμμάχων, καὶ τρεψάμενοι αὐτοὺς καὶ κρατήσαντες τοῦ πόρου ἐχώρουν ἐς τὸ πρόσθεν· οἱ δὲ Συρακόσιοι παριππεύοντές τε προσέκειντο καὶ ἐσακοντίζοντες οἱ ψιλοί.", "st": "7.78"}, {"sp": "N", "t": "καὶ ταύτῃ μὲν τῇ ἡμέρᾳ προελθόντες σταδίους ὡς τεσσαράκοντα ηὐλίσαντο πρὸς λόφῳ τινὶ οἱ Ἀθηναῖοι· τῇ δ’ ὑστεραίᾳ πρῲ ἐπορεύοντο καὶ προῆλθον ὡς εἴκοσι σταδίους, καὶ κατέβησαν ἐς χωρίον ἄπεδόν τι καὶ αὐτοῦ ἐστρατοπεδεύσαντο, βουλόμενοι ἔκ τε τῶν οἰκιῶν λαβεῖν τι ἐδώδιμον (ᾠκεῖτο γὰρ ὁ χῶρος) καὶ ὕδωρ μετὰ σφῶν αὐτῶν φέρεσθαι αὐτόθεν· ἐν γὰρ τῷ πρόσθεν ἐπὶ πολλὰ στάδια, ᾗ ἔμελλον ἰέναι, οὐκ ἄφθονον ἦν. οἱ δὲ Συρακόσιοι ἐν τούτῳ προελθόντες τὴν δίοδον τὴν ἐν τῷ πρόσθεν ἀπετείχιζον· ἦν δὲ λόφος καρτερὸς καὶ ἑκατέρωθεν αὐτοῦ χαράδρα κρημνώδης, ἐκαλεῖτο δὲ Ἀκραῖον λέπας.", "st": "7.78"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ οἱ Ἀθηναῖοι προῇσαν, καὶ οἱ τῶν Συρακοσίων καὶ ξυμμάχων αὐτοὺς ἱππῆς καὶ ἀκοντισταὶ ὄντες πολλοὶ ἑκατέρωθεν ἐκώλυον καὶ ἐσηκόντιζόν τε καὶ παρίππευον. καὶ χρόνον μὲν πολὺν ἐμάχοντο οἱ Ἀθηναῖοι, ἔπειτα ἀνεχώρησαν πάλιν ἐς τὸ αὐτὸ στρατόπεδον. καὶ τὰ ἐπιτήδεια οὐκέτι ὁμοίως εἶχον· οὐ γὰρ ἔτι ἀποχωρεῖν οἷόν τ’ ἦν ὑπὸ τῶν ἱππέων.", "st": "7.78"}, {"sp": "N", "t": "πρῲ δὲ ἄραντες ἐπορεύοντο αὖθις, καὶ ἐβιάσαντο πρὸς τὸν λόφον ἐλθεῖν τὸν ἀποτετειχισμένον, καὶ ηὗρον πρὸ ἑαυτῶν ὑπὲρ τοῦ ἀποτειχίσματος τὴν πεζὴν στρατιὰν παρατεταγμένην οὐκ ἐπ’ ὀλίγων ἀσπίδων· στενὸν γὰρ ἦν τὸ χωρίον. καὶ προσβαλόντες οἱ Ἀθηναῖοι ἐτειχομάχουν, καὶ βαλλόμενοι ὑπὸ πολλῶν ἀπὸ τοῦ λόφου ἐπάντους ὄντος (διικνοῦντο γὰρ ῥᾷον οἱ ἄνωθεν) καὶ οὐ δυνάμενοι βιάσασθαι ἀνεχώρουν πάλιν καὶ ἀνεπαύοντο. ἔτυχον δὲ καὶ βρονταί τινες ἅμα γενόμεναι καὶ ὕδωρ, οἷα τοῦ ἔτους πρὸς μετόπωρον ἤδη ὄντος φιλεῖ γίγνεσθαι· ἀφ’ ὧν οἱ Ἀθηναῖοι μᾶλλον ἔτι ἠθύμουν καὶ ἐνόμιζον ἐπὶ τῷ σφετέρῳ ὀλέθρῳ καὶ ταῦτα πάντα γίγνεσθαι. ἀναπαυομένων δ’ αὐτῶν ὁ Γύλιππος καὶ οἱ Συρακόσιοι πέμπουσι μέρος τι τῆς στρατιᾶς ἀποτειχιοῦντας αὖ ἐκ τοῦ ὄπισθεν αὐτοὺς ᾗ προεληλύθεσαν· ἀντιπέμψαντες δὲ κἀκεῖνοι σφῶν αὐτῶν τινὰς διεκώλυσαν. καὶ μετὰ ταῦτα πάσῃ τῇ στρατιᾷ ἀναχωρήσαντες πρὸς τὸ πεδίον μᾶλλον οἱ Ἀθηναῖοι ηὐλίσαντο. τῇ δ’ ὑστεραίᾳ προυχώρουν, καὶ οἱ Συρακόσιοι προσέβαλλόν τε πανταχῇ αὐτοῖς κύκλῳ καὶ πολλοὺς κατετραυμάτιζον, καὶ εἰ μὲν ἐπίοιεν οἱ Ἀθηναῖοι, ὑπεχώρουν, εἰ δ’ ἀναχωροῖεν, ἐπέκειντο, καὶ μάλιστα τοῖς ὑστάτοις προσπίπτοντες, εἴ πως κατὰ βραχὺ τρεψάμενοι πᾶν τὸ στράτευμα φοβήσειαν. καὶ ἐπὶ πολὺ μὲν τοιούτῳ τρόπῳ ἀντεῖχον οἱ Ἀθηναῖοι, ἔπειτα προελθόντες πέντε ἢ ἓξ σταδίους ἀνεπαύοντο ἐν τῷ πεδίῳ· ἀνεχώρησαν δὲ καὶ οἱ Συρακόσιοι ἀπ’ αὐτῶν ἐς τὸ ἑαυτῶν στρατόπεδον.", "st": "7.79"}, {"sp": "N", "t": "τῆς δὲ νυκτὸς τῷ Νικίᾳ καὶ Δημοσθένει ἐδόκει, ἐπειδὴ κακῶς σφίσι τὸ στράτευμα εἶχε τῶν τε ἐπιτηδείων πάντων ἀπορίᾳ ἤδη, καὶ κατατετραυματισμένοι ἦσαν πολλοὶ ἐν πολλαῖς προσβολαῖς τῶν πολεμίων γεγενημέναις, πυρὰ καύσαντας ὡς πλεῖστα ἀπάγειν τὴν στρατιάν, μηκέτι τὴν αὐτὴν ὁδὸν ᾗ διενοήθησαν, ἀλλὰ τοὐναντίον ἢ οἱ Συρακόσιοι ἐτήρουν, πρὸς τὴν θάλασσαν. ἦν δὲ ἡ ξύμπασα ὁδὸς αὕτη οὐκ ἐπὶ Κατάνης τῷ στρατεύματι, ἀλλὰ κατὰ τὸ ἕτερον μέρος τῆς Σικελίας τὸ πρὸς Καμάριναν καὶ Γέλαν καὶ τὰς ταύτῃ πόλεις καὶ Ἑλληνίδας καὶ βαρβάρους. καύσαντες οὖν πυρὰ πολλὰ ἐχώρουν ἐν τῇ νυκτί. καὶ αὐτοῖς, οἷον φιλεῖ καὶ πᾶσι στρατοπέδοις, μάλιστα δὲ τοῖς μεγίστοις, φόβοι καὶ δείματα ἐγγίγνεσθαι, ἄλλως τε καὶ ἐν νυκτί τε καὶ διὰ πολεμίας καὶ ἀπὸ πολεμίων οὐ πολὺ ἀπεχόντων ἰοῦσιν, ἐμπίπτει ταραχή· καὶ τὸ μὲν Νικίου στράτευμα, ὥσπερ ἡγεῖτο, ξυνέμενέ τε καὶ προύλαβε πολλῷ, τὸ δὲ Δημοσθένους, τὸ ἥμισυ μάλιστα καὶ πλέον, ἀπεσπάσθη τε καὶ ἀτακτότερον ἐχώρει. ἅμα δὲ τῇ ἕῳ ἀφικνοῦνται ὅμως πρὸς τὴν θάλασσαν, καὶ ἐσβάντες ἐς τὴν ὁδὸν τὴν Ἑλωρίνην καλουμένην ἐπορεύοντο, ὅπως, ἐπειδὴ γένοιντο ἐπὶ τῷ ποταμῷ τῷ Κακυπάρει, παρὰ τὸν ποταμὸν ἴοιεν ἄνω διὰ μεσογείας· ἤλπιζον γὰρ καὶ τοὺς Σικελοὺς ταύτῃ οὓς μετεπέμψαντο ἀπαντήσεσθαι. ἐπειδὴ δ’ ἐγένοντο ἐπὶ τῷ ποταμῷ, ηὗρον καὶ ἐνταῦθα φυλακήν τινα τῶν Συρακοσίων ἀποτειχίζουσάν τε καὶ ἀποσταυροῦσαν τὸν πόρον. καὶ βιασάμενοι αὐτὴν διέβησάν τε τὸν ποταμὸν καὶ ἐχώρουν αὖθις πρὸς ἄλλον ποταμὸν τὸν Ἐρινεόν· ταύτῃ γὰρ οἱ ἡγεμόνες ἐκέλευον.", "st": "7.80"}, {"sp": "N", "t": "ἐν τούτῳ δ’ οἱ Συρακόσιοι καὶ οἱ ξύμμαχοι, ὡς ἥ τε ἡμέρα ἐγένετο καὶ ἔγνωσαν τοὺς Ἀθηναίους ἀπεληλυθότας, ἐν αἰτίᾳ τε οἱ πολλοὶ τὸν Γύλιππον εἶχον ἑκόντα ἀφεῖναι τοὺς Ἀθηναίους, καὶ κατὰ τάχος διώκοντες, ᾗ οὐ χαλεπῶς ᾐσθάνοντο κεχωρηκότας, καταλαμβάνουσι περὶ ἀρίστου ὥραν. καὶ ὡς προσέμειξαν τοῖς μετὰ τοῦ Δημοσθένους ὑστέροις τ’ οὖσι καὶ σχολαίτερον καὶ ἀτακτότερον χωροῦσιν, ὡς τῆς νυκτὸς τότε ξυνεταράχθησαν, εὐθὺς προσπεσόντες ἐμάχοντο, καὶ οἱ ἱππῆς τῶν Συρακοσίων ἐκυκλοῦντό τε ῥᾷον αὐτοὺς δίχα δὴ ὄντας καὶ ξυνῆγον ἐς ταὐτό. τὸ δὲ Νικίου στράτευμα ἀπεῖχεν ἐν τῷ πρόσθεν καὶ πεντήκοντα σταδίους· θᾶσσόν τε γὰρ ὁ Νικίας ἦγε, νομίζων οὐ τὸ ὑπομένειν ἐν τῷ τοιούτῳ ἑκόντας εἶναι καὶ μάχεσθαι σωτηρίαν, ἀλλὰ τὸ ὡς τάχιστα ὑποχωρεῖν, τοσαῦτα μαχομένους ὅσα ἀναγκάζονται. ὁ δὲ Δημοσθένης ἐτύγχανέ τε τὰ πλείω ἐν πόνῳ ξυνεχεστέρῳ ὢν διὰ τὸ ὑστέρῳ ἀναχωροῦντι αὐτῷ πρώτῳ ἐπικεῖσθαι τοὺς πολεμίους καὶ τότε γνοὺς τοὺς Συρακοσίους διώκοντας οὐ προυχώρει μᾶλλον ἢ ἐς μάχην ξυνετάσσετο, ἕως ἐνδιατρίβων κυκλοῦταί τε ὑπ’ αὐτῶν καὶ ἐν πολλῷ θορύβῳ αὐτός τε καὶ οἱ μετ’ αὐτοῦ Ἀθηναῖοι ἦσαν· ἀνειληθέντες γὰρ ἔς τι χωρίον ᾧ κύκλῳ μὲν τειχίον περιῆν, ὁδὸς δὲ ἔνθεν [τε] καὶ ἔνθεν, ἐλάας δὲ οὐκ ὀλίγας εἶχεν, ἐβάλλοντο περισταδόν. τοιαύταις δὲ προσβολαῖς καὶ οὐ ξυσταδὸν μάχαις οἱ Συρακόσιοι εἰκότως ἐχρῶντο· τὸ γὰρ ἀποκινδυνεύειν πρὸς ἀνθρώπους ἀπονενοημένους οὐ πρὸς ἐκείνων μᾶλλον ἦν ἔτι ἢ πρὸς τῶν Ἀθηναίων, καὶ ἅμα φειδώ τέ τις ἐγίγνετο ἐπ’ εὐπραγίᾳ ἤδη σαφεῖ μὴ προαναλωθῆναί τῳ, καὶ ἐνόμιζον καὶ ὣς ταύτῃ τῇ ἰδέᾳ καταδαμασάμενοι λήψεσθαι αὐτούς.", "st": "7.81"}, {"sp": "N", "t": "ἐπειδὴ δ’ οὖν δι’ ἡμέρας βάλλοντες πανταχόθεν τοὺς Ἀθηναίους καὶ ξυμμάχους ἑώρων ἤδη τεταλαιπωρημένους τοῖς τε τραύμασι καὶ τῇ ἄλλῃ κακώσει, κήρυγμα ποιοῦνται Γύλιππος καὶ Συρακόσιοι καὶ οἱ ξύμμαχοι πρῶτον μὲν τῶν νησιωτῶν εἴ τις βούλεται ἐπ’ ἐλευθερίᾳ ὡς σφᾶς ἀπιέναι· καὶ ἀπεχώρησάν τινες πόλεις οὐ πολλαί. ἔπειτα δ’ ὕστερον καὶ πρὸς τοὺς ἄλλους ἅπαντας τοὺς μετὰ Δημοσθένους ὁμολογία γίγνεται ὥστε ὅπλα τε παραδοῦναι καὶ μὴ ἀποθανεῖν μηδένα μήτε βιαίως μήτε δεσμοῖς μήτε τῆς ἀναγκαιοτάτης ἐνδείᾳ διαίτης. καὶ παρέδοσαν οἱ πάντες σφᾶς αὐτοὺς ἑξακισχίλιοι, καὶ τὸ ἀργύριον ὃ εἶχον ἅπαν κατέθεσαν ἐσβαλόντες ἐς ἀσπίδας ὑπτίας, καὶ ἐνέπλησαν ἀσπίδας τέσσαρας. καὶ τούτους μὲν εὐθὺς ἀπεκόμιζον ἐς τὴν πόλιν· Νικίας δὲ καὶ οἱ μετ’ αὐτοῦ ταύτῃ τῇ ἡμέρᾳ ἀφικνοῦνται ἐπὶ τὸν ποταμὸν τὸν Ἐρινεόν, καὶ διαβὰς πρὸς μετέωρόν τι καθῖσε τὴν στρατιάν.", "st": "7.82"}, {"sp": "N", "t": "οἱ δὲ Συρακόσιοι τῇ ὑστεραίᾳ καταλαβόντες αὐτὸν ἔλεγον ὅτι οἱ μετὰ Δημοσθένους παραδεδώκοιεν σφᾶς αὐτούς, κελεύοντες κἀκεῖνον τὸ αὐτὸ δρᾶν· ὁ δ’ ἀπιστῶν σπένδεται ἱππέα πέμψαι σκεψόμενον. ὡς δ’ οἰχόμενος ἀπήγγειλε πάλιν παραδεδωκότας, ἐπικηρυκεύεται Γυλίππῳ καὶ Συρακοσίοις εἶναι ἑτοῖμος ὑπὲρ Ἀθηναίων ξυμβῆναι, ὅσα ἀνήλωσαν χρήματα Συρακόσιοι ἐς τὸν πόλεμον, ταῦτα ἀποδοῦναι, ὥστε τὴν μετ’ αὐτοῦ στρατιὰν ἀφεῖναι αὐτούς· μέχρι οὗ δ’ ἂν τὰ χρήματα ἀποδοθῇ, ἄνδρας δώσειν Ἀθηναίων ὁμήρους, ἕνα κατὰ τάλαντον. οἱ δὲ Συρακόσιοι καὶ Γύλιππος οὐ προσεδέχοντο τοὺς λόγους, ἀλλὰ προσπεσόντες καὶ περιστάντες πανταχόθεν ἔβαλλον καὶ τούτους μέχρι ὀψέ. εἶχον δὲ καὶ οὗτοι πονηρῶς σίτου τε καὶ τῶν ἐπιτηδείων ἀπορίᾳ. ὅμως δὲ τῆς νυκτὸς φυλάξαντες τὸ ἡσυχάζον ἔμελλον πορεύσεσθαι. καὶ ἀναλαμβάνουσί τε τὰ ὅπλα καὶ οἱ Συρακόσιοι αἰσθάνονται καὶ ἐπαιάνισαν. γνόντες δὲ οἱ Ἀθηναῖοι ὅτι οὐ λανθάνουσι, κατέθεντο πάλιν πλὴν τριακοσίων μάλιστα ἀνδρῶν· οὗτοι δὲ διὰ τῶν φυλάκων βιασάμενοι ἐχώρουν τῆς νυκτὸς ᾗ ἐδύναντο.", "st": "7.83"}, {"sp": "N", "t": "Νικίας δ’ ἐπειδὴ ἡμέρα ἐγένετο ἦγε τὴν στρατιάν· οἱ δὲ Συρακόσιοι καὶ οἱ ξύμμαχοι προσέκειντο τὸν αὐτὸν τρόπον πανταχόθεν βάλλοντές τε καὶ κατακοντίζοντες. καὶ οἱ Ἀθηναῖοι ἠπείγοντο πρὸς τὸν Ἀσσίναρον ποταμόν, ἅμα μὲν βιαζόμενοι ὑπὸ τῆς πανταχόθεν προσβολῆς ἱππέων τε πολλῶν καὶ τοῦ ἄλλου ὄχλου, οἰόμενοι ῥᾷόν τι σφίσιν ἔσεσθαι, ἢν διαβῶσι τὸν ποταμόν, ἅμα δ’ ὑπὸ τῆς ταλαιπωρίας καὶ τοῦ πιεῖν ἐπιθυμίᾳ. ὡς δὲ γίγνονται ἐπ’ αὐτῷ, ἐσπίπτουσιν οὐδενὶ κόσμῳ ἔτι, ἀλλὰ πᾶς τέ τις διαβῆναι αὐτὸς πρῶτος βουλόμενος καὶ οἱ πολέμιοι ἐπικείμενοι χαλεπὴν ἤδη τὴν διάβασιν ἐποίουν· ἁθρόοι γὰρ ἀναγκαζόμενοι χωρεῖν ἐπέπιπτόν τε ἀλλήλοις καὶ κατεπάτουν, περί τε τοῖς δορατίοις καὶ σκεύεσιν οἱ μὲν εὐθὺς διεφθείροντο, οἱ δὲ ἐμπαλασσόμενοι κατέρρεον. ἐς τὰ ἐπὶ θάτερά τε τοῦ ποταμοῦ παραστάντες οἱ Συρακόσιοι (ἦν δὲ κρημνῶδες) ἔβαλλον ἄνωθεν τοὺς Ἀθηναίους, πίνοντάς τε τοὺς πολλοὺς ἀσμένους καὶ ἐν κοίλῳ ὄντι τῷ ποταμῷ ἐν σφίσιν αὐτοῖς ταρασσομένους. οἵ τε Πελοποννήσιοι ἐπικαταβάντες τοὺς ἐν τῷ ποταμῷ μάλιστα ἔσφαζον. καὶ τὸ ὕδωρ εὐθὺς διέφθαρτο, ἀλλ’ οὐδὲν ἧσσον ἐπίνετό τε ὁμοῦ τῷ πηλῷ ᾑματωμένον καὶ περιμάχητον ἦν τοῖς πολλοῖς.", "st": "7.84"}, {"sp": "N", "t": "τέλος δὲ νεκρῶν τε πολλῶν ἐπ’ ἀλλήλοις ἤδη κειμένων ἐν τῷ ποταμῷ καὶ διεφθαρμένου τοῦ στρατεύματος τοῦ μὲν κατὰ τὸν ποταμόν, τοῦ δὲ καί, εἴ τι διαφύγοι, ὑπὸ τῶν ἱππέων, Νικίας Γυλίππῳ ἑαυτὸν παραδίδωσι, πιστεύσας μᾶλλον αὐτῷ ἢ τοῖς Συρακοσίοις· καὶ ἑαυτῷ μὲν χρήσασθαι ἐκέλευεν ἐκεῖνόν τε καὶ Λακεδαιμονίους ὅτι βούλονται, τοὺς δὲ ἄλλους στρατιώτας παύσασθαι φονεύοντας. καὶ ὁ Γύλιππος μετὰ τοῦτο ζωγρεῖν ἤδη ἐκέλευεν· καὶ τούς τε λοιποὺς ὅσους μὴ ἀπεκρύψαντο (πολλοὶ δὲ οὗτοι ἐγένοντο) ξυνεκόμισαν ζῶντας, καὶ ἐπὶ τοὺς τριακοσίους, οἳ τὴν φυλακὴν διεξῆλθον τῆς νυκτός, πέμψαντες τοὺς διωξομένους ξυνέλαβον. τὸ μὲν οὖν ἁθροισθὲν τοῦ στρατεύματος ἐς τὸ κοινὸν οὐ πολὺ ἐγένετο, τὸ δὲ διακλαπὲν πολύ, καὶ διεπλήσθη πᾶσα Σικελία αὐτῶν, ἅτε οὐκ ἀπὸ ξυμβάσεως ὥσπερ τῶν μετὰ Δημοσθένους ληφθέντων. μέρος δέ τι οὐκ ὀλίγον καὶ ἀπέθανεν· πλεῖστος γὰρ δὴ φόνος οὗτος καὶ οὐδενὸς ἐλάσσων τῶν ἐν τῷ [Σικελικῷ] πολέμῳ τούτῳ ἐγένετο. καὶ ἐν ταῖς ἄλλαις προσβολαῖς ταῖς κατὰ τὴν πορείαν συχναῖς γενομέναις οὐκ ὀλίγοι ἐτεθνήκεσαν. πολλοὶ δὲ ὅμως καὶ διέφυγον, οἱ μὲν καὶ παραυτίκα, οἱ δὲ καὶ δουλεύσαντες καὶ διαδιδράσκοντες ὕστερον· τούτοις δ’ ἦν ἀναχώρησις ἐς Κατάνην.", "st": "7.85"}, {"sp": "N", "t": "ξυναθροισθέντες δὲ οἱ Συρακόσιοι καὶ οἱ ξύμμαχοι, τῶν τε αἰχμαλώτων ὅσους ἐδύναντο πλείστους καὶ τὰ σκῦλα ἀναλαβόντες, ἀνεχώρησαν ἐς τὴν πόλιν. καὶ τοὺς μὲν ἄλλους Ἀθηναίων καὶ τῶν ξυμμάχων ὁπόσους ἔλαβον κατεβίβασαν ἐς τὰς λιθοτομίας, ἀσφαλεστάτην εἶναι νομίσαντες τήρησιν, Νικίαν δὲ καὶ Δημοσθένη ἄκοντος τοῦ Γυλίππου ἀπέσφαξαν. ὁ γὰρ Γύλιππος καλὸν τὸ ἀγώνισμα ἐνόμιζέν οἱ εἶναι ἐπὶ τοῖς ἄλλοις καὶ τοὺς ἀντιστρατήγους κομίσαι Λακεδαιμονίοις. ξυνέβαινε δὲ τὸν μὲν πολεμιώτατον αὐτοῖς εἶναι, Δημοσθένη, διὰ τὰ ἐν τῇ νήσῳ καὶ Πύλῳ, τὸν δὲ διὰ τὰ αὐτὰ ἐπιτηδειότατον· τοὺς γὰρ ἐκ τῆς νήσου ἄνδρας τῶν Λακεδαιμονίων ὁ Νικίας προυθυμήθη, σπονδὰς πείσας τοὺς Ἀθηναίους ποιήσασθαι, ὥστε ἀφεθῆναι. ἀνθ’ ὧν οἵ τε Λακεδαιμόνιοι ἦσαν αὐτῷ προσφιλεῖς κἀκεῖνος οὐχ ἥκιστα διὰ τοῦτο πιστεύσας ἑαυτὸν τῷ Γυλίππῳ παρέδωκεν. ἀλλὰ τῶν Συρακοσίων τινές, ὡς ἐλέγετο, οἱ μὲν δείσαντες, ὅτι πρὸς αὐτὸν ἐκεκοινολόγηντο, μὴ βασανιζόμενος διὰ τὸ τοιοῦτο ταραχὴν σφίσιν ἐν εὐπραγίᾳ ποιήσῃ, ἄλλοι δέ, καὶ οὐχ ἥκιστα οἱ Κορίνθιοι, μὴ χρήμασι δὴ πείσας τινάς, ὅτι πλούσιος ἦν, ἀποδρᾷ καὶ αὖθις σφίσι νεώτερόν τι ἀπ’ αὐτοῦ γένηται, πείσαντες τοὺς ξυμμάχους ἀπέκτειναν αὐτόν. καὶ ὁ μὲν τοιαύτῃ ἢ ὅτι ἐγγύτατα τούτων αἰτίᾳ ἐτεθνήκει, ἥκιστα δὴ ἄξιος ὢν τῶν γε ἐπ’ ἐμοῦ Ἑλλήνων ἐς τοῦτο δυστυχίας ἀφικέσθαι διὰ τὴν πᾶσαν ἐς ἀρετὴν νενομισμένην ἐπιτήδευσιν.", "st": "7.86"}, {"sp": "N", "t": "τοὺς δ’ ἐν ταῖς λιθοτομίαις οἱ Συρακόσιοι χαλεπῶς τοὺς πρώτους χρόνους μετεχείρισαν. ἐν γὰρ κοίλῳ χωρίῳ ὄντας καὶ ὀλίγῳ πολλοὺς οἵ τε ἥλιοι τὸ πρῶτον καὶ τὸ πνῖγος ἔτι ἐλύπει διὰ τὸ ἀστέγαστον καὶ αἱ νύκτες ἐπιγιγνόμεναι τοὐναντίον μετοπωριναὶ καὶ ψυχραὶ τῇ μεταβολῇ ἐς ἀσθένειαν ἐνεωτέριζον, πάντα τε ποιούντων αὐτῶν διὰ στενοχωρίαν ἐν τῷ αὐτῷ καὶ προσέτι τῶν νεκρῶν ὁμοῦ ἐπ’ ἀλλήλοις ξυννενημένων, οἳ ἔκ τε τῶν τραυμάτων καὶ διὰ τὴν μεταβολὴν καὶ τὸ τοιοῦτον ἀπέθνῃσκον, καὶ ὀσμαὶ ἦσαν οὐκ ἀνεκτοί, καὶ λιμῷ ἅμα καὶ δίψῃ ἐπιέζοντο (ἐδίδοσαν γὰρ αὐτῶν ἑκάστῳ ἐπὶ ὀκτὼ μῆνας κοτύλην ὕδατος καὶ δύο κοτύλας σίτου), ἄλλα τε ὅσα εἰκὸς ἐν τῷ τοιούτῳ χωρίῳ ἐμπεπτωκότας κακοπαθῆσαι, οὐδὲν ὅτι οὐκ ἐπεγένετο αὐτοῖς· καὶ ἡμέρας μὲν ἑβδομήκοντά τινας οὕτω διῃτήθησαν ἁθρόοι· ἔπειτα πλὴν Ἀθηναίων καὶ εἴ τινες Σικελιωτῶν ἢ Ἰταλιωτῶν ξυνεστράτευσαν, τοὺς ἄλλους ἀπέδοντο. ἐλήφθησαν δὲ οἱ ξύμπαντες, ἀκριβείᾳ μὲν χαλεπὸν ἐξειπεῖν, ὅμως δὲ οὐκ ἐλάσσους ἑπτακισχιλίων. ξυνέβη τε ἔργον τοῦτο [Ἑλληνικὸν] τῶν κατὰ τὸν πόλεμον τόνδε μέγιστον γενέσθαι, δοκεῖν δ’ ἔμοιγε καὶ ὧν ἀκοῇ Ἑλληνικῶν ἴσμεν, καὶ τοῖς τε κρατήσασι λαμπρότατον καὶ τοῖς διαφθαρεῖσι δυστυχέστατον· κατὰ πάντα γὰρ πάντως νικηθέντες καὶ οὐδὲν ὀλίγον ἐς οὐδὲν κακοπαθήσαντες πανωλεθρίᾳ δὴ τὸ λεγόμενον καὶ πεζὸς καὶ νῆες καὶ οὐδὲν ὅτι οὐκ ἀπώλετο, καὶ ὀλίγοι ἀπὸ πολλῶν ἐπ’ οἴκου ἀπενόστησαν. ταῦτα μὲν τὰ περὶ Σικελίαν γενόμενα.", "st": "7.87"}, {"sp": "HDR", "t": "Βιβλίον Ηʹ", "st": "8"}, {"sp": "N", "t": "ἐς δὲ τὰς Ἀθήνας ἐπειδὴ ἠγγέλθη, ἐπὶ πολὺ μὲν ἠπίστουν καὶ τοῖς πάνυ τῶν στρατιωτῶν ἐξ αὐτοῦ τοῦ ἔργου διαπεφευγόσι καὶ σαφῶς ἀγγέλλουσι, μὴ οὕτω γε ἄγαν πανσυδὶ διεφθάρθαι· ἐπειδὴ δὲ ἔγνωσαν, χαλεποὶ μὲν ἦσαν τοῖς ξυμπροθυμηθεῖσι τῶν ῥητόρων τὸν ἔκπλουν, ὥσπερ οὐκ αὐτοὶ ψηφισάμενοι, ὠργίζοντο δὲ καὶ τοῖς χρησμολόγοις τε καὶ μάντεσι καὶ ὁπόσοι τι τότε αὐτοὺς θειάσαντες ἐπήλπισαν ὡς λήψονται Σικελίαν. πάντα δὲ πανταχόθεν αὐτοὺς ἐλύπει τε καὶ περιειστήκει ἐπὶ τῷ γεγενημένῳ φόβος τε καὶ κατάπληξις μεγίστη δή. ἅμα μὲν γὰρ στερόμενοι καὶ ἰδίᾳ ἕκαστος καὶ ἡ πόλις ὁπλιτῶν τε πολλῶν καὶ ἱππέων καὶ ἡλικίας οἵαν οὐχ ἑτέραν ἑώρων ὑπάρχουσαν ἐβαρύνοντο· ἅμα δὲ ναῦς οὐχ ὁρῶντες ἐν τοῖς νεωσοίκοις ἱκανὰς οὐδὲ χρήματα ἐν τῷ κοινῷ οὐδ’ ὑπηρεσίας ταῖς ναυσὶν ἀνέλπιστοι ἦσαν ἐν τῷ παρόντι σωθήσεσθαι, τούς τε ἀπὸ τῆς Σικελίας πολεμίους εὐθὺς σφίσιν ἐνόμιζον τῷ ναυτικῷ ἐπὶ τὸν Πειραιᾶ πλευσεῖσθαι, ἄλλως τε καὶ τοσοῦτον κρατήσαντας, καὶ τοὺς αὐτόθεν πολεμίους τότε δὴ καὶ διπλασίως πάντα παρεσκευασμένους κατὰ κράτος ἤδη καὶ ἐκ γῆς καὶ ἐκ θαλάσσης ἐπικείσεσθαι, καὶ τοὺς ξυμμάχους σφῶν μετ’ αὐτῶν ἀποστάντας. ὅμως δὲ ὡς ἐκ τῶν ὑπαρχόντων ἐδόκει χρῆναι μὴ ἐνδιδόναι, ἀλλὰ παρασκευάζεσθαι καὶ ναυτικόν, ὅθεν ἂν δύνωνται ξύλα ξυμπορισαμένους, καὶ χρήματα, καὶ τὰ τῶν ξυμμάχων ἐς ἀσφάλειαν ποιεῖσθαι, καὶ μάλιστα τὴν Εὔβοιαν, τῶν τε κατὰ τὴν πόλιν τι ἐς εὐτέλειαν σωφρονίσαι, καὶ ἀρχήν τινα πρεσβυτέρων ἀνδρῶν ἑλέσθαι, οἵτινες περὶ τῶν παρόντων ὡς ἂν καιρὸς ᾖ προβουλεύσουσιν. πάντα τε πρὸς τὸ παραχρῆμα περιδεές, ὅπερ φιλεῖ δῆμος ποιεῖν, ἑτοῖμοι ἦσαν εὐτακτεῖν. καὶ ὡς ἔδοξεν αὐτοῖς, καὶ ἐποίουν ταῦτα, καὶ τὸ θέρος ἐτελεύτα.", "st": "8.1"}, {"sp": "N", "t": "τοῦ δ’ ἐπιγιγνομένου χειμῶνος πρὸς τὴν ἐκ τῆς Σικελίας τῶν Ἀθηναίων μεγάλην κακοπραγίαν εὐθὺς οἱ Ἕλληνες πάντες ἐπηρμένοι ἦσαν, οἱ μὲν μηδετέρων ὄντες ξύμμαχοι, ὡς, ἤν τις καὶ μὴ παρακαλῇ σφᾶς, οὐκ ἀποστατέον ἔτι τοῦ πολέμου εἴη, ἀλλ’ ἐθελοντὶ ἰτέον ἐπὶ τοὺς Ἀθηναίους, νομίσαντες κἂν ἐπὶ σφᾶς ἕκαστοι ἐλθεῖν αὐτούς, εἰ τὰ ἐν τῇ Σικελίᾳ κατώρθωσαν, καὶ ἅμα βραχὺν ἔσεσθαι τὸν λοιπὸν πόλεμον, οὗ μετασχεῖν καλὸν εἶναι, οἱ δ’ αὖ τῶν Λακεδαιμονίων ξύμμαχοι ξυμπροθυμηθέντες ἐπὶ πλέον ἢ πρὶν ἀπαλλάξεσθαι διὰ τάχους πολλῆς ταλαιπωρίας. μάλιστα δὲ οἱ τῶν Ἀθηναίων ὑπήκοοι ἑτοῖμοι ἦσαν καὶ παρὰ δύναμιν αὐτῶν ἀφίστασθαι διὰ τὸ ὀργῶντες κρίνειν τὰ πράγματα καὶ μηδ’ ὑπολείπειν λόγον αὐτοῖς ὡς τό γ’ ἐπιὸν θέρος οἷοί τ’ ἔσονται περιγενέσθαι. ἡ δὲ τῶν Λακεδαιμονίων πόλις πᾶσί τε τούτοις ἐθάρσει καὶ μάλιστα ὅτι οἱ ἐκ τῆς Σικελίας αὐτοῖς ξύμμαχοι πολλῇ δυνάμει, κατ’ ἀνάγκην ἤδη τοῦ ναυτικοῦ προσγεγενημένου, ἅμα τῷ ἦρι ὡς εἰκὸς παρέσεσθαι ἔμελλον. πανταχόθεν τε εὐέλπιδες ὄντες ἀπροφασίστως ἅπτεσθαι διενοοῦντο τοῦ πολέμου, λογιζόμενοι καλῶς τελευτήσαντος αὐτοῦ κινδύνων τε τοιούτων ἀπηλλάχθαι ἂν τὸ λοιπὸν οἷος καὶ ὁ ἀπὸ τῶν Ἀθηναίων περιέστη ἂν αὐτούς, εἰ τὸ Σικελικὸν προσέλαβον, καὶ καθελόντες ἐκείνους αὐτοὶ τῆς πάσης Ἑλλάδος ἤδη ἀσφαλῶς ἡγήσεσθαι.", "st": "8.2"}, {"sp": "N", "t": "εὐθὺς οὖν Ἆγις μὲν ὁ βασιλεὺς αὐτῶν ἐν τῷ χειμῶνι τούτῳ ὁρμηθεὶς στρατῷ τινὶ ἐκ Δεκελείας τά τε τῶν ξυμμάχων ἠργυρολόγησεν ἐς τὸ ναυτικὸν καὶ τραπόμενος ἐπὶ τοῦ Μηλιῶς κόλπου Οἰταίων τε κατὰ τὴν παλαιὰν ἔχθραν τῆς λείας τὴν πολλὴν ἀπολαβὼν χρήματα ἐπράξατο, καὶ Ἀχαιοὺς τοὺς Φθιώτας καὶ τοὺς ἄλλους τοὺς ταύτῃ Θεσσαλῶν ὑπηκόους μεμφομένων καὶ ἀκόντων τῶν Θεσσαλῶν ὁμήρους τέ τινας ἠνάγκασε δοῦναι καὶ χρήματα, καὶ κατέθετο τοὺς ὁμήρους ἐς Κόρινθον, ἔς τε τὴν ξυμμαχίαν ἐπειρᾶτο προσάγειν. Λακεδαιμόνιοι δὲ τὴν πρόσταξιν ταῖς πόλεσιν ἑκατὸν νεῶν τῆς ναυπηγίας ἐποιοῦντο, καὶ ἑαυτοῖς μὲν καὶ Βοιωτοῖς πέντε καὶ εἴκοσιν ἑκατέροις ἔταξαν, Φωκεῦσι δὲ καὶ Λοκροῖς πέντε καὶ δέκα, καὶ Κορινθίοις πέντε καὶ δέκα, Ἀρκάσι δὲ καὶ Πελληνεῦσι καὶ Σικυωνίοις δέκα, Μεγαρεῦσι δὲ καὶ Τροιζηνίοις καὶ Ἐπιδαυρίοις καὶ Ἑρμιονεῦσι δέκα· τά τε ἄλλα παρεσκευάζοντο ὡς εὐθὺς πρὸς τὸ ἔαρ ἑξόμενοι τοῦ πολέμου.", "st": "8.3"}, {"sp": "N", "t": "παρεσκευάζοντο δὲ καὶ Ἀθηναῖοι, ὥσπερ διενοήθησαν, ἐν τῷ αὐτῷ χειμῶνι τούτῳ τήν τε ναυπηγίαν, ξύλα ξυμπορισάμενοι, καὶ Σούνιον τειχίσαντες, ὅπως αὐτοῖς ἀσφάλεια ταῖς σιταγωγοῖς ναυσὶν εἴη τοῦ περίπλου, καὶ τό τε ἐν τῇ Λακωνικῇ τείχισμα ἐκλιπόντες ὃ ἐνῳκοδόμησαν παραπλέοντες ἐς Σικελίαν, καὶ τἆλλα, εἴ πού τι ἐδόκει ἀχρεῖον ἀναλίσκεσθαι, ξυστελλόμενοι ἐς εὐτέλειαν, μάλιστα δὲ τὰ τῶν ξυμμάχων διασκοποῦντες ὅπως μὴ σφῶν ἀποστήσονται.", "st": "8.4"}, {"sp": "N", "t": "πρασσόντων δὲ ταῦτα ἀμφοτέρων καὶ ὄντων οὐδὲν ἄλλο ἢ ὥσπερ ἀρχομένων ἐν κατασκευῇ τοῦ πολέμου, πρῶτοι Εὐβοῆς ὡς Ἆγιν περὶ ἀποστάσεως τῶν Ἀθηναίων ἐπρεσβεύσαντο ἐν τῷ χειμῶνι τούτῳ. ὁ δὲ προσδεξάμενος τοὺς λόγους αὐτῶν μεταπέμπεται ἐκ Λακεδαίμονος Ἀλκαμένη τὸν Σθενελαΐδου καὶ Μέλανθον ἄρχοντας ὡς ἐς τὴν Εὔβοιαν· οἱ δ’ ἦλθον ἔχοντες τῶν νεοδαμωδῶν ὡς τριακοσίους, καὶ παρεσκεύαζεν αὐτοῖς τὴν διάβασιν. ἐν τούτῳ δὲ καὶ Λέσβιοι ἦλθον βουλόμενοι καὶ αὐτοὶ ἀποστῆναι· καὶ ξυμπρασσόντων αὐτοῖς τῶν Βοιωτῶν ἀναπείθεται Ἆγις ὥστε Εὐβοίας μὲν πέρι ἐπισχεῖν, τοῖς δὲ Λεσβίοις παρεσκεύαζε τὴν ἀπόστασιν, Ἀλκαμένη τε ἁρμοστὴν διδούς, ὃς ἐς Εὔβοιαν πλεῖν ἔμελλε, καὶ δέκα μὲν Βοιωτοὶ ναῦς ὑπέσχοντο, δέκα δὲ Ἆγις. καὶ ταῦτα ἄνευ τῆς Λακεδαιμονίων πόλεως ἐπράσσετο· ὁ γὰρ Ἆγις, ὅσον χρόνον ἦν περὶ Δεκέλειαν ἔχων τὴν μεθ’ ἑαυτοῦ δύναμιν, κύριος ἦν καὶ ἀποστέλλειν εἴ ποί τινα ἐβούλετο στρατιὰν καὶ ξυναγείρειν καὶ χρήματα πράσσειν. καὶ πολὺ μᾶλλον ὡς εἰπεῖν κατὰ τοῦτον τὸν καιρὸν αὐτοῦ οἱ ξύμμαχοι ὑπήκουον [ἢ] τῶν ἐν τῇ πόλει Λακεδαιμονίων· δύναμιν γὰρ ἔχων αὐτὸς εὐθὺς ἑκασταχόσε δεινὸς παρῆν.", "st": "8.5"}, {"sp": "N", "t": "καὶ ὁ μὲν τοῖς Λεσβίοις ἔπρασσε, Χῖοι δὲ καὶ Ἐρυθραῖοι ἀποστῆναι καὶ αὐτοὶ ἑτοῖμοι ὄντες πρὸς μὲν Ἆγιν οὐκ ἐτράποντο, ἐς δὲ τὴν Λακεδαίμονα. καὶ παρὰ Τισσαφέρνους, ὃς βασιλεῖ Δαρείῳ τῷ Ἀρταξέρξου στρατηγὸς ἦν τῶν κάτω, πρεσβευτὴς ἅμα μετ’ αὐτῶν παρῆν. ἐπήγετο γὰρ καὶ ὁ Τισσαφέρνης τοὺς Πελοποννησίους καὶ ὑπισχνεῖτο τροφὴν παρέξειν. ὑπὸ βασιλέως γὰρ νεωστὶ ἐτύγχανε πεπραγμένος τοὺς ἐκ τῆς ἑαυτοῦ ἀρχῆς φόρους, οὓς δι’ Ἀθηναίους ἀπὸ τῶν Ἑλληνίδων πόλεων οὐ δυνάμενος πράσσεσθαι ἐπωφείλησεν· τούς τε οὖν φόρους μᾶλλον ἐνόμιζε κομιεῖσθαι κακώσας τοὺς Ἀθηναίους, καὶ ἅμα βασιλεῖ ξυμμάχους Λακεδαιμονίους ποιήσειν, καὶ Ἀμόργην τὸν Πισσούθνου υἱὸν νόθον, ἀφεστῶτα περὶ Καρίαν, ὥσπερ αὐτῷ προσέταξε βασιλεύς, ἢ ζῶντα ἄξειν ἢ ἀποκτενεῖν.", "st": "8.5"}, {"sp": "N", "t": "οἱ μὲν οὖν Χῖοι καὶ Τισσαφέρνης κοινῇ κατὰ τὸ αὐτὸ ἔπρασσον, Καλλίγειτος δὲ ὁ Λαοφῶντος Μεγαρεὺς καὶ Τιμαγόρας ὁ Ἀθηναγόρου Κυζικηνός, φυγάδες τῆς ἑαυτῶν ἀμφότεροι παρὰ Φαρναβάζῳ τῷ Φαρνάκου κατοικοῦντες, ἀφικνοῦνται περὶ τὸν αὐτὸν καιρὸν ἐς τὴν Λακεδαίμονα πέμψαντος Φαρναβάζου, ὅπως ναῦς κομίσειαν ἐς τὸν Ἑλλήσποντον, καὶ αὐτός, εἰ δύναιτο, ἅπερ ὁ Τισσαφέρνης προυθυμεῖτο, τάς τε ἐν τῇ ἑαυτοῦ ἀρχῇ πόλεις ἀποστήσειε τῶν Ἀθηναίων διὰ τοὺς φόρους καὶ ἀφ’ ἑαυτοῦ βασιλεῖ τὴν ξυμμαχίαν τῶν Λακεδαιμονίων ποιήσειεν.", "st": "8.6"}, {"sp": "N", "t": "πρασσόντων δὲ ταῦτα χωρὶς ἑκατέρων, τῶν τε ἀπὸ τοῦ Φαρναβάζου καὶ τῶν ἀπὸ τοῦ Τισσαφέρνους, πολλὴ ἅμιλλα ἐγίγνετο τῶν ἐν τῇ Λακεδαίμονι, ὅπως οἱ μὲν ἐς τὴν Ἰωνίαν καὶ Χίον, οἱ δ’ ἐς τὸν Ἑλλήσποντον πρότερον ναῦς καὶ στρατιὰν πείσουσι πέμπειν. οἱ μέντοι Λακεδαιμόνιοι τὰ τῶν Χίων καὶ Τισσαφέρνους παρὰ πολὺ προσεδέξαντο μᾶλλον· ξυνέπρασσε γὰρ αὐτοῖς καὶ Ἀλκιβιάδης, Ἐνδίῳ ἐφορεύοντι πατρικὸς ἐς τὰ μάλιστα ξένος ὤν, ὅθεν καὶ τοὔνομα Λακωνικὸν ἡ οἰκία αὐτῶν κατὰ τὴν ξενίαν ἔσχεν· Ἔνδιος γὰρ Ἀλκιβιάδου ἐκαλεῖτο. ὅμως δ’ οἱ Λακεδαιμόνιοι πρῶτον κατάσκοπον ἐς τὴν Χίον πέμψαντες Φρῦνιν ἄνδρα περίοικον, εἰ αἵ τε νῆες αὐτοῖς εἰσὶν ὅσασπερ ἔλεγον καὶ τἆλλα εἰ ἡ πόλις ἱκανή ἐστι πρὸς τὴν λεγομένην δόξαν, ἀπαγγείλαντος αὐτοῖς ὡς εἴη ταῦτα ἀληθῆ ἅπερ ἤκουον, τούς τε Χίους καὶ τοὺς Ἐρυθραίους εὐθὺς ξυμμάχους ἐποιήσαντο καὶ τεσσαράκοντα ναῦς ἐψηφίσαντο αὐτοῖς πέμπειν, ὡς ἐκεῖ οὐκ ἔλασσον ἢ ἑξήκοντα ἀφ’ ὧν οἱ Χῖοι ἔλεγον ὑπαρχουσῶν. καὶ τὸ μὲν πρῶτον δέκα τούτων αὐτοὶ ἔμελλον πέμψειν, καὶ Μελαγχρίδαν, ὃς αὐτοῖς ναύαρχος ἦν· ἔπειτα σεισμοῦ γενομένου ἀντὶ τοῦ Μελαγχρίδου Χαλκιδέα ἔπεμπον καὶ ἀντὶ τῶν δέκα νεῶν πέντε παρεσκευάζοντο ἐν τῇ Λακωνικῇ. καὶ ὁ χειμὼν ἐτελεύτα καὶ ἑνὸς δέον εἰκοστὸν ἔτος τῷ πολέμῳ ἐτελεύτα τῷδε ὃν Θουκυδίδης ξυνέγραψεν.", "st": "8.6"}, {"sp": "N", "t": "ἅμα δὲ τῷ ἦρι τοῦ ἐπιγιγνομένου θέρους εὐθὺς ἐπειγομένων τῶν Χίων ἀποστεῖλαι τὰς ναῦς καὶ δεδιότων μὴ οἱ Ἀθηναῖοι τὰ πρασσόμενα αἴσθωνται (πάντες γὰρ κρύφα αὐτῶν ἐπρεσβεύοντο), ἀποπέμπουσιν οἱ Λακεδαιμόνιοι ἐς Κόρινθον ἄνδρας Σπαρτιάτας τρεῖς, ὅπως ἀπὸ τῆς ἑτέρας θαλάσσης ὡς τάχιστα ἐπὶ τὴν πρὸς Ἀθήνας ὑπερενεγκόντες τὰς ναῦς τὸν Ἰσθμὸν κελεύσωσι πλεῖν ἐς Χίον πάσας, καὶ ἃς ὁ Ἆγις παρεσκεύαζεν ἐς τὴν Λέσβον καὶ τὰς ἄλλας· ἦσαν δὲ αἱ ξύμπασαι τῶν ξυμμαχίδων νῆες αὐτόθι μιᾶς δέουσαι τεσσαράκοντα.", "st": "8.7"}, {"sp": "N", "t": "ὁ μὲν οὖν Καλλίγειτος καὶ Τιμαγόρας ὑπὲρ τοῦ Φαρναβάζου οὐκ ἐκοινοῦντο τὸν στόλον ἐς τὴν Χίον, οὐδὲ τὰ χρήματα ἐδίδοσαν ἃ ἦλθον ἔχοντες ἐς τὴν ἀποστολὴν πέντε καὶ εἴκοσι τάλαντα, ἀλλ’ ὕστερον ἐφ’ ἑαυτῶν διενοοῦντο ἄλλῳ στόλῳ πλεῖν· ὁ δὲ Ἆγις ἐπειδὴ ἑώρα τοὺς Λακεδαιμονίους ἐς τὴν Χίον πρῶτον ὡρμημένους, οὐδ’ αὐτὸς ἄλλο τι ἐγίγνωσκεν, ἀλλὰ ξυνελθόντες ἐς Κόρινθον οἱ ξύμμαχοι ἐβουλεύοντο, καὶ ἔδοξε πρῶτον ἐς Χίον αὐτοῖς πλεῖν ἄρχοντα ἔχοντας Χαλκιδέα, ὃς ἐν τῇ Λακωνικῇ τὰς πέντε ναῦς παρεσκεύαζεν, ἔπειτα ἐς Λέσβον καὶ Ἀλκαμένη ἄρχοντα, ὅνπερ καὶ Ἆγις διενοεῖτο, τὸ τελευταῖον δὲ ἐς τὸν Ἑλλήσποντον ἀφικέσθαι (προσετέτακτο δὲ ἐς αὐτὸν ἄρχων Κλέαρχος ὁ Ῥαμφίου), διαφέρειν δὲ τὸν Ἰσθμὸν τὰς ἡμισείας τῶν νεῶν πρῶτον, καὶ εὐθὺς ταύτας ἀποπλεῖν, ὅπως μὴ οἱ Ἀθηναῖοι πρὸς τὰς ἀφορμωμένας μᾶλλον τὸν νοῦν ἔχωσιν ἢ τὰς ὕστερον ἐπιδιαφερομένας. καὶ γὰρ τὸν πλοῦν ταύτῃ ἐκ τοῦ προφανοῦς ἐποιοῦντο, καταφρονήσαντες τῶν Ἀθηναίων ἀδυνασίαν, ὅτι ναυτικὸν οὐδὲν αὐτῶν πολύ πω ἐφαίνετο. ὡς δὲ ἔδοξεν αὐτοῖς, καὶ διεκόμισαν εὐθὺς μίαν καὶ εἴκοσι ναῦς.", "st": "8.8"}, {"sp": "N", "t": "οἱ δὲ Κορίνθιοι, ἐπειγομένων αὐτῶν τὸν πλοῦν, οὐ προυθυμήθησαν ξυμπλεῖν πρὶν τὰ Ἴσθμια, ἃ τότε ἦν, διεορτάσωσιν. Ἆγις δὲ αὐτοῖς ἑτοῖμος ἦν ἐκείνους μὲν μὴ λύειν δὴ τὰς Ἰσθμιάδας σπονδάς, ἑαυτοῦ δὲ τὸν στόλον ἴδιον ποιήσασθαι. οὐ ξυγχωρούντων δὲ τῶν Κορινθίων, ἀλλὰ διατριβῆς ἐγγιγνομένης, οἱ Ἀθηναῖοι ᾐσθάνοντο τὰ τῶν Χίων μᾶλλον, καὶ πέμψαντες ἕνα τῶν στρατηγῶν Ἀριστοκράτη ἐπῃτιῶντο αὐτούς, καὶ ἀρνουμένων τῶν Χίων τὸ πιστὸν ναῦς σφίσι ξυμπέμπειν ἐκέλευον ἐς τὸ ξυμμαχικόν· οἱ δ’ ἔπεμψαν ἑπτά. αἴτιον δ’ ἐγένετο τῆς ἀποστολῆς τῶν νεῶν οἱ μὲν πολλοὶ τῶν Χίων οὐκ εἰδότες τὰ πρασσόμενα, οἱ δὲ ὀλίγοι καὶ ξυνειδότες τό τε πλῆθος οὐ βουλόμενοί πω πολέμιον ἔχειν, πρίν τι καὶ ἰσχυρὸν λάβωσι, καὶ τοὺς Πελοποννησίους οὐκέτι προσδεχόμενοι ἥξειν, ὅτι διέτριβον.", "st": "8.9"}, {"sp": "N", "t": "ἐν δὲ τούτῳ τὰ Ἴσθμια ἐγίγνετο, καὶ οἱ Ἀθηναῖοι (ἐπηγγέλθησαν γάρ) ἐθεώρουν ἐς αὐτά, καὶ κατάδηλα μᾶλλον αὐτοῖς τὰ τῶν Χίων ἐφάνη. καὶ ἐπειδὴ ἀνεχώρησαν, παρεσκευάζοντο εὐθὺς ὅπως μὴ λήσουσιν αὐτοὺς αἱ νῆες ἐκ τῶν Κεγχρειῶν ἀφορμηθεῖσαι. οἱ δὲ μετὰ τὴν ἑορτὴν ἀνήγοντο μιᾷ καὶ εἴκοσι ναυσὶν ἐς τὴν Χίον, ἄρχοντα Ἀλκαμένη ἔχοντες. καὶ αὐτοῖς οἱ Ἀθηναῖοι τὸ πρῶτον ἴσαις ναυσὶ προσπλεύσαντες ὑπῆγον ἐς τὸ πέλαγος. ὡς δ’ ἐπὶ πολὺ οὐκ ἐπηκολούθησαν οἱ Πελοποννήσιοι, ἀλλ’ ἀπετράποντο, ἐπανεχώρησαν καὶ οἱ Ἀθηναῖοι· τὰς γὰρ τῶν Χίων ἑπτὰ ναῦς ἐν τῷ ἀριθμῷ μετὰ σφῶν ἔχοντες οὐ πιστὰς ἐνόμιζον, ἀλλ’ ὕστερον ἄλλας προσπληρώσαντες ἐς ἑπτὰ καὶ τριάκοντα παραπλέοντας αὐτοὺς καταδιώκουσιν ἐς Σπείραιον τῆς Κορινθίας· ἔστι δὲ λιμὴν ἐρῆμος καὶ ἔσχατος πρὸς τὰ μεθόρια τῆς Ἐπιδαυρίας. καὶ μίαν μὲν ναῦν ἀπολλύασι μετέωρον οἱ Πελοποννήσιοι, τὰς δὲ ἄλλας ξυναγαγόντες ὁρμίζουσιν. καὶ προσβαλόντων τῶν Ἀθηναίων καὶ κατὰ θάλασσαν ταῖς ναυσὶ καὶ ἐς τὴν γῆν ἀποβάντων θόρυβός τε ἐγένετο πολὺς καὶ ἄτακτος, καὶ τῶν τε νεῶν τὰς πλείους κατατραυματίζουσιν ἐν τῇ γῇ οἱ Ἀθηναῖοι καὶ τὸν ἄρχοντα Ἀλκαμένη ἀποκτείνουσιν· καὶ αὐτῶν τινὲς ἀπέθανον.", "st": "8.10"}, {"sp": "N", "t": "διακριθέντες δὲ πρὸς μὲν τὰς πολεμίας ναῦς ἐπέταξαν ἐφορμεῖν ἱκανάς, ταῖς δὲ λοιπαῖς ἐς τὸ νησίδιον ὁρμίζονται ἐν ᾧ οὐ πολὺ ἀπέχοντι ἐστρατοπεδεύοντο, καὶ ἐς τὰς Ἀθήνας ἐπὶ βοήθειαν ἔπεμπον. παρῆσαν γὰρ καὶ τοῖς Πελοποννησίοις τῇ ὑστεραίᾳ οἵ τε Κορίνθιοι βοηθοῦντες ἐπὶ τὰς ναῦς καὶ οὐ πολλῷ ὕστερον καὶ οἱ ἄλλοι πρόσχωροι. καὶ ὁρῶντες τὴν φυλακὴν ἐν χωρίῳ ἐρήμῳ ἐπίπονον οὖσαν ἠπόρουν, καὶ ἐπενόησαν μὲν κατακαῦσαι τὰς ναῦς, ἔπειτα δὲ ἔδοξεν αὐτοῖς ἀνελκύσαι καὶ τῷ πεζῷ προσκαθημένους φυλακὴν ἔχειν, ἕως ἄν τις παρατύχῃ διαφυγὴ ἐπιτηδεία. ἔπεμψε δ’ αὐτοῖς καὶ Ἆγις αἰσθόμενος ταῦτα ἄνδρα Σπαρτιάτην Θέρμωνα. τοῖς δὲ Λακεδαιμονίοις πρῶτον μὲν ἠγγέλθη ὅτι αἱ νῆες ἀνηγμέναι εἰσὶν ἐκ τοῦ Ἰσθμοῦ (εἴρητο γάρ, ὅταν γένηται τοῦτο, Ἀλκαμένει ὑπὸ τῶν ἐφόρων ἱππέα πέμψαι), καὶ εὐθὺς τὰς παρὰ σφῶν πέντε ναῦς καὶ Χαλκιδέα ἄρχοντα καὶ Ἀλκιβιάδην μετ’ αὐτοῦ ἐβούλοντο πέμπειν· ἔπειτα ὡρμημένων αὐτῶν τὰ περὶ τὴν ἐν τῷ Σπειραίῳ τῶν νεῶν καταφυγὴν ἠγγέλθη, καὶ ἀθυμήσαντες, ὅτι πρῶτον ἁπτόμενοι τοῦ Ἰωνικοῦ πολέμου ἔπταισαν, τὰς ναῦς τὰς ἐκ τῆς ἑαυτῶν οὐκέτι διενοοῦντο πέμπειν, ἀλλὰ καί τινας προανηγμένας μετακαλεῖν.", "st": "8.11"}, {"sp": "N", "t": "γνοὺς δὲ ὁ Ἀλκιβιάδης πείθει αὖθις Ἔνδιον καὶ τοὺς ἄλλους ἐφόρους μὴ ἀποκνῆσαι τὸν πλοῦν, λέγων ὅτι φθήσονταί τε πλεύσαντες πρὶν τὴν τῶν νεῶν ξυμφορὰν Χίους αἰσθέσθαι, καὶ αὐτὸς ὅταν προσβάλῃ Ἰωνίᾳ, ῥᾳδίως πείσειν τὰς πόλεις ἀφίστασθαι τήν τε τῶν Ἀθηναίων λέγων ἀσθένειαν καὶ τὴν τῶν Λακεδαιμονίων προθυμίαν· πιστότερος γὰρ ἄλλων φανεῖσθαι. Ἐνδίῳ τε αὐτῷ ἰδίᾳ ἔλεγε καλὸν εἶναι δι’ ἐκείνου ἀποστῆσαί τε Ἰωνίαν καὶ βασιλέα ξύμμαχον ποιῆσαι Λακεδαιμονίοις, καὶ μὴ Ἄγιδος τὸ ἀγώνισμα τοῦτο γενέσθαι· ἐτύγχανε γὰρ τῷ Ἄγιδι αὐτὸς διάφορος ὤν. καὶ ὁ μὲν πείσας τούς τε ἄλλους ἐφόρους καὶ Ἔνδιον ἀνήγετο ταῖς πέντε ναυσὶ μετὰ Χαλκιδέως τοῦ Λακεδαιμονίου, καὶ διὰ τάχους τὸν πλοῦν ἐποιοῦντο.", "st": "8.12"}, {"sp": "N", "t": "ἀνεκομίζοντο δὲ ὑπὸ τὸν αὐτὸν χρόνον τοῦτον καὶ αἱ ἀπὸ τῆς Σικελίας Πελοποννησίων ἑκκαίδεκα νῆες αἱ μετὰ Γυλίππου ξυνδιαπολεμήσασαι· καὶ περὶ τὴν Λευκάδα ἀποληφθεῖσαι καὶ κοπεῖσαι ὑπὸ τῶν Ἀττικῶν ἑπτὰ καὶ εἴκοσι νεῶν, ὧν ἦρχεν Ἱπποκλῆς Μενίππου φυλακὴν ἔχων τῶν ἀπὸ τῆς Σικελίας νεῶν, αἱ λοιπαὶ πλὴν μιᾶς διαφυγοῦσαι τοὺς Ἀθηναίους κατέπλευσαν ἐς τὴν Κόρινθον.", "st": "8.13"}, {"sp": "N", "t": "ὁ δὲ Χαλκιδεὺς καὶ ὁ Ἀλκιβιάδης πλέοντες ὅσοις τε ἐπιτύχοιεν ξυνελάμβανον τοῦ μὴ ἐξάγγελτοι γενέσθαι, καὶ προσβαλόντες πρῶτον Κωρύκῳ τῆς ἠπείρου καὶ ἀφέντες ἐνταῦθα αὐτοὺς αὐτοὶ μὲν προξυγγενόμενοι τῶν ξυμπρασσόντων Χίων τισὶ καὶ κελευόντων καταπλεῖν μὴ προειπόντας ἐς τὴν πόλιν, ἀφικνοῦνται αἰφνίδιοι τοῖς Χίοις. καὶ οἱ μὲν πολλοὶ ἐν θαύματι ἦσαν καὶ ἐκπλήξει· τοῖς δ’ ὀλίγοις παρεσκεύαστο ὥστε βουλήν [τε] τυχεῖν ξυλλεγομένην, καὶ γενομένων λόγων ἀπό τε τοῦ Χαλκιδέως καὶ Ἀλκιβιάδου ὡς ἄλλαι [τε] νῆες πολλαὶ προσπλέουσι καὶ τὰ περὶ τῆς πολιορκίας τῶν ἐν τῷ Σπειραίῳ νεῶν οὐ δηλωσάντων, ἀφίστανται Χῖοι καὶ αὖθις Ἐρυθραῖοι Ἀθηναίων. καὶ μετὰ ταῦτα τρισὶ ναυσὶ πλεύσαντες καὶ Κλαζομενὰς ἀφιστᾶσιν. διαβάντες τε εὐθὺς οἱ Κλαζομένιοι ἐς τὴν ἤπειρον τὴν Πολίχναν ἐτείχιζον, εἴ τι δέοι, σφίσιν αὐτοῖς ἐκ τῆς νησῖδος ἐν ᾗ οἰκοῦσι πρὸς ἀναχώρησιν. καὶ οἱ μὲν ἀφεστῶτες ἐν τειχισμῷ τε πάντες ἦσαν καὶ παρασκευῇ πολέμου·", "st": "8.14"}, {"sp": "N", "t": "ἐς δὲ τὰς Ἀθήνας ταχὺ ἀγγελία τῆς Χίου ἀφικνεῖται· καὶ νομίσαντες μέγαν ἤδη καὶ σαφῆ τὸν κίνδυνον σφᾶς περιεστάναι, καὶ τοὺς λοιποὺς ξυμμάχους οὐκ ἐθελήσειν τῆς μεγίστης πόλεως μεθεστηκυίας ἡσυχάζειν, τά τε χίλια τάλαντα, ὧν διὰ παντὸς τοῦ πολέμου ἐγλίχοντο μὴ ἅψασθαι, εὐθὺς ἔλυσαν τὰς ἐπικειμένας ζημίας τῷ εἰπόντι ἢ ἐπιψηφίσαντι ὑπὸ τῆς παρούσης ἐκπλήξεως, καὶ ἐψηφίσαντο κινεῖν καὶ ναῦς πληροῦν οὐκ ὀλίγας, τῶν τε ἐν τῷ Σπειραίῳ ἐφορμουσῶν τὰς μὲν ὀκτὼ ἤδη πέμπειν, αἳ ἀπολιποῦσαι τὴν φυλακὴν τὰς μετὰ Χαλκιδέως διώξασαι καὶ οὐ καταλαβοῦσαι ἀνεκεχωρήκεσαν (ἦρχε δὲ αὐτῶν Στρομβιχίδης Διοτίμου), ἄλλας δὲ οὐ πολὺ ὕστερον βοηθεῖν δώδεκα μετὰ Θρασυκλέους, ἀπολιπούσας καὶ ταύτας τὴν ἐφόρμησιν. τάς τε τῶν Χίων ἑπτὰ ναῦς, αἳ αὐτοῖς ξυνεπολιόρκουν τὰς ἐν τῷ Σπειραίῳ, ἀπαγαγόντες τοὺς μὲν δούλους ἐξ αὐτῶν ἠλευθέρωσαν, τοὺς δ’ ἐλευθέρους κατέδησαν. ἑτέρας δὲ ⟨δέκα⟩ ἀντὶ πασῶν τῶν ἀπελθουσῶν νεῶν ἐς τὴν ἐφόρμησιν τῶν Πελοποννησίων διὰ τάχους πληρώσαντες ἀντέπεμψαν καὶ ἄλλας διενοοῦντο τριάκοντα πληροῦν. καὶ πολλὴ ἦν ἡ προθυμία καὶ ὀλίγον ἐπράσσετο οὐδὲν ἐς τὴν βοήθειαν τὴν ἐπὶ τὴν Χίον.", "st": "8.15"}, {"sp": "N", "t": "ἐν δὲ τούτῳ Στρομβιχίδης ταῖς ὀκτὼ ναυσὶν ἀφικνεῖται ἐς Σάμον, καὶ προσλαβὼν Σαμίαν μίαν ἔπλευσεν ἐς Τέων καὶ ἡσυχάζειν ἠξίου αὐτούς. ἐκ δὲ τῆς Χίου ἐς τὴν Τέων καὶ ὁ Χαλκιδεὺς μετὰ τριῶν καὶ εἴκοσι νεῶν ἐπέπλει καὶ ὁ πεζὸς ἅμα ὁ τῶν Κλαζομενίων καὶ Ἐρυθραίων παρῄει. προαισθόμενος δὲ ὁ Στρομβιχίδης ἐξανήγετο καὶ μετεωρισθεὶς ἐν τῷ πελάγει ὡς ἑώρα τὰς ναῦς πολλὰς τὰς ἀπὸ τῆς Χίου, φυγὴν ἐποιεῖτο ἐπὶ τῆς Σάμου· αἱ δὲ ἐδίωκον. τὸν δὲ πεζὸν οἱ Τήιοι τὸ πρῶτον οὐκ ἐσδεχόμενοι, ὡς ἔφυγον οἱ Ἀθηναῖοι, ἐσηγάγοντο. καὶ ἐπέσχον μὲν οἱ πεζοὶ καὶ Χαλκιδέα ἐκ τῆς διώξεως περιμένοντες· ὡς δὲ ἐχρόνιζε, καθῄρουν αὐτοί τε τὸ τεῖχος ὃ ἀνῳκοδόμησαν οἱ Ἀθηναῖοι τῆς Τηίων πόλεως τὸ πρὸς ἤπειρον, ξυγκαθῄρουν δὲ αὐτοῖς καὶ τῶν βαρβάρων ἐπελθόντες οὐ πολλοί, ὧν ἦρχε Στάγης ὕπαρχος Τισσαφέρνους.", "st": "8.16"}, {"sp": "N", "t": "Χαλκιδεὺς δὲ καὶ Ἀλκιβιάδης ὡς κατεδίωξαν ἐς Σάμον Στρομβιχίδην, ἐκ μὲν τῶν ἐκ Πελοποννήσου νεῶν τοὺς ναύτας ὁπλίσαντες ἐν Χίῳ καταλιμπάνουσιν, ἀντιπληρώσαντες δὲ ταύτας τε ἐκ Χίου καὶ ἄλλας εἴκοσιν ἔπλεον ἐς Μίλητον ὡς ἀποστήσοντες· ἐβούλετο γὰρ ὁ Ἀλκιβιάδης, ὢν ἐπιτήδειος τοῖς προεστῶσι τῶν Μιλησίων, φθάσαι τάς τε ἀπὸ τῆς Πελοποννήσου ναῦς προσαγαγόμενος αὐτοὺς καὶ τοῖς Χίοις καὶ ἑαυτῷ καὶ Χαλκιδεῖ καὶ τῷ ἀποστείλαντι Ἐνδίῳ, ὥσπερ ὑπέσχετο, τὸ ἀγώνισμα προσθεῖναι, ὅτι πλείστας τῶν πόλεων μετὰ τῆς Χίων δυνάμεως καὶ Χαλκιδέως ἀποστήσας. λαθόντες οὖν τὸ πλεῖστον τοῦ πλοῦ καὶ φθάσαντες οὐ πολὺ τόν τε Στρομβιχίδην καὶ τὸν Θρασυκλέα, ὃς ἔτυχεν ἐκ τῶν Ἀθηνῶν δώδεκα ναυσὶν ἄρτι παρὼν καὶ ξυνδιώκων, ἀφιστᾶσι τὴν Μίλητον. καὶ οἱ Ἀθηναῖοι κατὰ πόδας μιᾶς δεούσαις εἴκοσι ναυσὶν ἐπιπλεύσαντες, ὡς αὐτοὺς οὐκ ἐδέχοντο οἱ Μιλήσιοι, ἐν Λάδῃ τῇ ἐπικειμένῃ νήσῳ ἐφώρμουν. καὶ ἡ πρὸς βασιλέα ξυμμαχία Λακεδαιμονίοις ἡ πρώτη Μιλησίων εὐθὺς ἀποστάντων διὰ Τισσαφέρνους καὶ Χαλκιδέως ἐγένετο ἥδε.", "st": "8.17"}, {"sp": "N", "t": "‘ἐπὶ τοῖσδε ξυμμαχίαν ἐποιήσαντο πρὸς βασιλέα καὶ Τισσαφέρνην Λακεδαιμόνιοι καὶ οἱ ξύμμαχοι. ὁπόσην χώραν καὶ πόλεις βασιλεὺς ἔχει καὶ οἱ πατέρες οἱ βασιλέως εἶχον, βασιλέως ἔστω· καὶ ἐκ τούτων τῶν πόλεων ὁπόσα Ἀθηναίοις ἐφοίτα χρήματα ἢ ἄλλο τι, κωλυόντων κοινῇ βασιλεὺς καὶ Λακεδαιμόνιοι καὶ οἱ ξύμμαχοι ὅπως μήτε χρήματα λαμβάνωσιν Ἀθηναῖοι μήτε ἄλλο μηδέν. καὶ τὸν πόλεμον τὸν πρὸς Ἀθηναίους κοινῇ πολεμούντων βασιλεὺς καὶ Λακεδαιμόνιοι καὶ οἱ ξύμμαχοι· καὶ κατάλυσιν τοῦ πολέμου πρὸς Ἀθηναίους μὴ ἐξέστω ποιεῖσθαι, ἢν μὴ ἀμφοτέροις δοκῇ, βασιλεῖ καὶ Λακεδαιμονίοις καὶ τοῖς ξυμμάχοις. ἢν δέ τινες ἀφιστῶνται ἀπὸ βασιλέως, πολέμιοι ὄντων καὶ Λακεδαιμονίοις καὶ τοῖς ξυμμάχοις· καὶ ἤν τινες ἀφιστῶνται ἀπὸ Λακεδαιμονίων καὶ τῶν ξυμμάχων, πολέμιοι ὄντων βασιλεῖ κατὰ ταὐτά.’", "st": "8.18"}, {"sp": "N", "t": "ἡ μὲν ξυμμαχία αὕτη ἐγένετο· μετὰ δὲ ταῦτα οἱ Χῖοι εὐθὺς δέκα ἑτέρας πληρώσαντες ναῦς ἔπλευσαν ἐς Ἄναια, βουλόμενοι περί τε τῶν ἐν Μιλήτῳ πυθέσθαι καὶ τὰς πόλεις ἅμα ἀφιστάναι. καὶ ἐλθούσης παρὰ Χαλκιδέως ἀγγελίας αὐτοῖς ἀποπλεῖν πάλιν, καὶ ὅτι Ἀμόργης παρέσται κατὰ γῆν στρατιᾷ, ἔπλευσαν ἐς Διὸς ἱερόν· καὶ καθορῶσιν ἑκκαίδεκα ναῦς, ἃς ὕστερον ἔτι Θρασυκλέους Διομέδων ἔχων ἀπ’ Ἀθηνῶν προσέπλει. καὶ ὡς εἶδον, ἔφευγον μιᾷ μὲν νηὶ ἐς Ἔφεσον, αἱ δὲ λοιπαὶ ἐπὶ τῆς Τέω. καὶ τέσσαρας μὲν κενὰς οἱ Ἀθηναῖοι λαμβάνουσι τῶν ἀνδρῶν ἐς τὴν γῆν φθασάντων· αἱ δ’ ἄλλαι ἐς τὴν Τηίων πόλιν καταφεύγουσιν. καὶ οἱ μὲν Ἀθηναῖοι ἐπὶ τῆς Σάμου ἀπέπλευσαν, οἱ δὲ Χῖοι ταῖς λοιπαῖς ναυσὶν ἀναγαγόμενοι καὶ ὁ πεζὸς μετ’ αὐτῶν Λέβεδον ἀπέστησαν καὶ αὖθις Αἱράς. καὶ μετὰ τοῦτο ἕκαστοι ἐπ’ οἴκου ἀπεκομίσθησαν, καὶ ὁ πεζὸς καὶ αἱ νῆες.", "st": "8.19"}, {"sp": "N", "t": "ὑπὸ δὲ τοὺς αὐτοὺς χρόνους αἱ ἐν τῷ Σπειραίῳ εἴκοσι νῆες τῶν Πελοποννησίων, καταδιωχθεῖσαι τότε καὶ ἐφορμούμεναι ἴσῳ ἀριθμῷ ὑπὸ Ἀθηναίων, ἐπέκπλουν ποιησάμεναι αἰφνίδιον καὶ κρατήσασαι ναυμαχίᾳ τέσσαράς τε ναῦς λαμβάνουσι τῶν Ἀθηναίων καὶ ἀποπλεύσασαι ἐς Κεγχρειὰς τὸν ἐς τὴν Χίον καὶ τὴν Ἰωνίαν πλοῦν αὖθις παρεσκευάζοντο. καὶ ναύαρχος αὐτοῖς ἐκ Λακεδαίμονος Ἀστύοχος ἐπῆλθεν, ᾧπερ ἐγίγνετο ἤδη πᾶσα ἡ ναυαρχία.", "st": "8.20"}, {"sp": "N", "t": "ἀναχωρήσαντος δὲ τοῦ ἐκ τῆς Τέω πεζοῦ καὶ Τισσαφέρνης αὐτὸς στρατιᾷ παραγενόμενος καὶ ἐπικαθελὼν τὸ ἐν τῇ Τέῳ τεῖχος, εἴ τι ὑπελείφθη, ἀνεχώρησεν. καὶ Διομέδων ἀπελθόντος αὐτοῦ οὐ πολὺ ὕστερον δέκα ναυσὶν Ἀθηναίων ἀφικόμενος ἐσπείσατο Τηίοις ὥστε δέχεσθαι καὶ σφᾶς. καὶ παραπλεύσας ἐπὶ Αἱρὰς καὶ προσβαλών, ὡς οὐκ ἐλάμβανε τὴν πόλιν, ἀπέπλευσεν.", "st": "8.20"}, {"sp": "N", "t": "ἐγένετο δὲ κατὰ τὸν χρόνον τοῦτον καὶ ἡ ἐν Σάμῳ ἐπανάστασις ὑπὸ τοῦ δήμου τοῖς δυνατοῖς μετὰ Ἀθηναίων, οἳ ἔτυχον ἐν τρισὶ ναυσὶ παρόντες. καὶ ὁ δῆμος ὁ Σαμίων ἐς διακοσίους μέν τινας τοὺς πάντας τῶν δυνατωτάτων ἀπέκτεινε, τετρακοσίους δὲ φυγῇ ζημιώσαντες καὶ αὐτοὶ τὴν γῆν αὐτῶν καὶ οἰκίας νειμάμενοι, Ἀθηναίων τε σφίσιν αὐτονομίαν μετὰ ταῦτα ὡς βεβαίοις ἤδη ψηφισαμένων, τὰ λοιπὰ διῴκουν τὴν πόλιν, καὶ τοῖς γεωμόροις μετεδίδοσαν οὔτε ἄλλου οὐδενὸς οὔτε ἐκδοῦναι οὐδ’ ἀγαγέσθαι παρ’ ἐκείνων οὐδ’ ἐς ἐκείνους οὐδενὶ ἔτι τοῦ δήμου ἐξῆν.", "st": "8.21"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα τοῦ αὐτοῦ θέρους οἱ Χῖοι, ὥσπερ ἤρξαντο, οὐδὲν ἀπολείποντες προθυμίας, ἄνευ τε Πελοποννησίων πλήθει παρόντες ἀποστῆσαι τὰς πόλεις καὶ βουλόμενοι ἅμα ὡς πλείστους σφίσι ξυγκινδυνεύειν, στρατεύονται αὐτοί τε τρισκαίδεκα ναυσὶν ἐπὶ τὴν Λέσβον, ὥσπερ εἴρητο ὑπὸ τῶν Λακεδαιμονίων δεύτερον ἐπ’ αὐτὴν ἰέναι καὶ ἐκεῖθεν ἐπὶ τὸν Ἑλλήσποντον, καὶ ὁ πεζὸς ἅμα Πελοποννησίων τε τῶν παρόντων καὶ τῶν αὐτόθεν ξυμμάχων παρῄει ἐπὶ Κλαζομενῶν τε καὶ Κύμης· ἦρχε δ’ αὐτοῦ Εὐάλας Σπαρτιάτης, τῶν δὲ νεῶν Δεινιάδας περίοικος. καὶ αἱ μὲν νῆες καταπλεύσασαι Μήθυμναν πρῶτον ἀφιστᾶσι, καὶ καταλείπονται τέσσαρες νῆες ἐν αὐτῇ· καὶ αὖθις αἱ λοιπαὶ Μυτιλήνην ἀφιστᾶσιν.", "st": "8.22"}, {"sp": "N", "t": "Ἀστύοχος δὲ ὁ Λακεδαιμόνιος ναύαρχος τέσσαρσι ναυσίν, ὥσπερ ὥρμητο, πλέων ἐκ τῶν Κεγχρειῶν ἀφικνεῖται ἐς Χίον. καὶ τρίτην ἡμέραν αὐτοῦ ἥκοντος αἱ Ἀττικαὶ νῆες πέντε καὶ εἴκοσιν ἔπλεον ἐς Λέσβον, ὧν ἦρχε Λέων καὶ Διομέδων· Λέων γὰρ ὕστερον δέκα ναυσὶ προσεβοήθησεν ἐκ τῶν Ἀθηνῶν. ἀναγαγόμενος δὲ καὶ ὁ Ἀστύοχος τῇ αὐτῇ ἡμέρᾳ ἐς ὀψὲ καὶ προσλαβὼν Χίαν ναῦν μίαν ἔπλει ἐς τὴν Λέσβον, ὅπως ὠφελοίη, εἴ τι δύναιτο. καὶ ἀφικνεῖται ἐς τὴν Πύρραν, ἐκεῖθεν δὲ τῇ ὑστεραίᾳ ἐς Ἔρεσον, ἔνθα πυνθάνεται ὅτι ἡ Μυτιλήνη ὑπὸ τῶν Ἀθηναίων αὐτοβοεὶ ἑάλωκεν· οἱ γὰρ Ἀθηναῖοι ὥσπερ ἔπλεον ἀπροσδόκητοι κατασχόντες ἐς τὸν λιμένα τῶν τε Χίων νεῶν ἐκράτησαν καὶ ἀποβάντες τοὺς ἀντιστάντας μάχῃ νικήσαντες τὴν πόλιν ἔσχον. ἃ πυνθανόμενος ὁ Ἀστύοχος τῶν τε Ἐρεσίων καὶ τῶν ἐκ τῆς Μηθύμνης μετ’ Εὐβούλου Χίων νεῶν, αἳ τότε καταλειφθεῖσαι καὶ ὡς ἡ Μυτιλήνη ἑάλω φεύγουσαι περιέτυχον αὐτῷ τρεῖς (μία γὰρ ἑάλω ὑπὸ τῶν Ἀθηναίων), οὐκέτι ἐπὶ τὴν Μυτιλήνην ὥρμησεν, ἀλλὰ τὴν Ἔρεσον ἀποστήσας καὶ ὁπλίσας, καὶ τοὺς ἀπὸ τῶν ἑαυτοῦ νεῶν ὁπλίτας πεζῇ παραπέμπει ἐπὶ τὴν Ἄντισσαν καὶ Μήθυμναν ἄρχοντα Ἐτεόνικον προστάξας· καὶ αὐτὸς ταῖς τε μεθ’ ἑαυτοῦ ναυσὶ καὶ ταῖς τρισὶ ταῖς Χίαις παρέπλει, ἐλπίζων τοὺς Μηθυμναίους θαρσήσειν τε ἰδόντας σφᾶς καὶ ἐμμενεῖν τῇ ἀποστάσει. ὡς δὲ αὐτῷ τὰ ἐν τῇ Λέσβῳ πάντα ἠναντιοῦτο, ἀπέπλευσε τὸν ἑαυτοῦ στρατὸν πεζὸν ἀναλαβὼν ἐς τὴν Χίον. ἀπεκομίσθη δὲ πάλιν κατὰ πόλεις καὶ ὁ τῶν ξυμμάχων πεζός, ὃς ἐπὶ τὸν Ἑλλήσποντον ἐμέλλησεν ἰέναι. καὶ ἀπὸ τῶν ἐν Κεγχρειᾷ ξυμμαχίδων Πελοποννησίων νεῶν ἀφικνοῦνται αὐτοῖς ἓξ μετὰ ταῦτα ἐς τὴν Χίον. οἱ δὲ Ἀθηναῖοι τά τ’ ἐν τῇ Λέσβῳ πάλιν κατεστήσαντο καὶ πλεύσαντες ἐξ αὐτῆς Κλαζομενίων τὴν ἐν τῇ ἠπείρῳ Πολίχναν τειχιζομένην ἑλόντες διεκόμισαν πάλιν αὐτοὺς ἐς τὴν ἐν τῇ νήσῳ πόλιν, πλὴν τῶν αἰτίων τῆς ἀποστάσεως· οὗτοι δὲ ἐς Δαφνοῦντα ἀπῆλθον. καὶ αὖθις Κλαζομεναὶ προσεχώρησαν Ἀθηναίοις.", "st": "8.23"}, {"sp": "N", "t": "τοῦ δ’ αὐτοῦ θέρους οἵ τ’ ἐπὶ Μιλήτῳ Ἀθηναῖοι ταῖς εἴκοσι ναυσὶν ἐν τῇ Λάδῃ ἐφορμοῦντες ἀπόβασιν ποιησάμενοι ἐς Πάνορμον τῆς Μιλησίας Χαλκιδέα τε τὸν Λακεδαιμόνιον ἄρχοντα μετ’ ὀλίγων παραβοηθήσαντα ἀποκτείνουσι καὶ τροπαῖον τρίτῃ ἡμέρᾳ ὕστερον διαπλεύσαντες ἔστησαν, ὃ οἱ Μιλήσιοι ὡς οὐ μετὰ κράτους τῆς γῆς σταθὲν ἀνεῖλον· καὶ Λέων καὶ Διομέδων ἔχοντες τὰς ἐκ Λέσβου Ἀθηναίων ναῦς, ἔκ τε Οἰνουσσῶν τῶν πρὸ Χίου νήσων καὶ ἐκ Σιδούσσης καὶ ἐκ Πτελεοῦ, ἃ ἐν τῇ Ἐρυθραίᾳ εἶχον τείχη, καὶ ἐκ τῆς Λέσβου ὁρμώμενοι τὸν πρὸς τοὺς Χίους πόλεμον ἀπὸ τῶν νεῶν ἐποιοῦντο· εἶχον δ’ ἐπιβάτας τῶν ὁπλιτῶν ἐκ καταλόγου ἀναγκαστούς. καὶ ἔν τε Καρδαμύλῃ ἀποβάντες καὶ ἐν Βολίσκῳ τοὺς προσβοηθήσαντας τῶν Χίων μάχῃ νικήσαντες καὶ πολλοὺς διαφθείραντες ἀνάστατα ἐποίησαν τὰ ταύτῃ χωρία, καὶ ἐν Φάναις αὖθις ἄλλῃ μάχῃ ἐνίκησαν καὶ τρίτῃ ἐν Λευκωνίῳ. καὶ μετὰ τοῦτο οἱ μὲν Χῖοι ἤδη οὐκέτι ἐπεξῇσαν, οἱ δὲ τὴν χώραν καλῶς κατεσκευασμένην καὶ ἀπαθῆ οὖσαν ἀπὸ τῶν Μηδικῶν μέχρι τότε διεπόρθησαν. Χῖοι γὰρ μόνοι μετὰ Λακεδαιμονίους ὧν ἐγὼ ᾐσθόμην ηὐδαιμόνησάν τε ἅμα καὶ ἐσωφρόνησαν, καὶ ὅσῳ ἐπεδίδου ἡ πόλις αὐτοῖς ἐπὶ τὸ μεῖζον, τόσῳ δὲ καὶ ἐκοσμοῦντο ἐχυρώτερον. καὶ οὐδ’ αὐτὴν τὴν ἀπόστασιν, εἰ τοῦτο δοκοῦσι παρὰ τὸ ἀσφαλέστερον πρᾶξαι, πρότερον ἐτόλμησαν ποιήσασθαι ἢ μετὰ πολλῶν τε καὶ ἀγαθῶν ξυμμάχων ἔμελλον ξυγκινδυνεύσειν καὶ τοὺς Ἀθηναίους ᾐσθάνοντο οὐδ’ αὐτοὺς ἀντιλέγοντας ἔτι μετὰ τὴν Σικελικὴν ξυμφορὰν ὡς οὐ πάνυ πονηρά σφῶν [βεβαίως] τὰ πράγματα εἴη· εἰ δέ τι ἐν τοῖς ἀνθρωπείοις τοῦ βίου παραλόγοις ἐσφάλησαν, μετὰ πολλῶν οἷς ταὐτὰ ἔδοξε, τὰ τῶν Ἀθηναίων ταχὺ ξυναναιρεθήσεσθαι, τὴν ἁμαρτίαν ξυνέγνωσαν. εἰργομένοις οὖν αὐτοῖς τῆς θαλάσσης καὶ κατὰ γῆν πορθουμένοις ἐνεχείρησάν τινες πρὸς Ἀθηναίους ἀγαγεῖν τὴν πόλιν· οὓς αἰσθόμενοι οἱ ἄρχοντες αὐτοὶ μὲν ἡσύχασαν, Ἀστύοχον δὲ ἐξ Ἐρυθρῶν τὸν ναύαρχον μετὰ τεσσάρων νεῶν, αἳ παρῆσαν αὐτῷ, κομίσαντες ἐσκόπουν ὅπως μετριώτατα ἢ ὁμήρων λήψει ἢ ἄλλῳ τῳ τρόπῳ καταπαύσουσι τὴν ἐπιβουλήν. καὶ οἱ μὲν ταῦτα ἔπρασσον.", "st": "8.24"}, {"sp": "N", "t": "ἐκ δὲ τῶν Ἀθηνῶν τοῦ αὐτοῦ θέρους τελευτῶντος χίλιοι ὁπλῖται Ἀθηναίων καὶ πεντακόσιοι καὶ χίλιοι Ἀργείων (τοὺς γὰρ πεντακοσίους τῶν Ἀργείων ψιλοὺς ὄντας ὥπλισαν οἱ Ἀθηναῖοι) καὶ χίλιοι τῶν ξυμμάχων ναυσὶ δυοῖν δεούσαις πεντήκοντα, ὧν ἦσαν καὶ ὁπλιταγωγοί, Φρυνίχου καὶ Ὀνομακλέους καὶ Σκιρωνίδου στρατηγούντων κατέπλευσαν ἐς Σάμον, καὶ διαβάντες ἐς Μίλητον ἐστρατοπεδεύσαντο. Μιλήσιοι δὲ ἐξελθόντες αὐτοί τε, ὀκτακόσιοι ὁπλῖται, καὶ οἱ μετὰ Χαλκιδέως ἐλθόντες Πελοποννήσιοι καὶ Τισσαφέρνους τι [ξενικὸν] ἐπικουρικόν, καὶ αὐτὸς Τισσαφέρνης παρὼν καὶ ἡ ἵππος αὐτοῦ, ξυνέβαλον τοῖς Ἀθηναίοις καὶ τοῖς ξυμμάχοις. καὶ οἱ μὲν Ἀργεῖοι τῷ σφετέρῳ αὐτῶν κέρᾳ προεξᾴξαντες καὶ καταφρονήσαντες, ὡς ἐπ’ Ἴωνάς τε καὶ οὐ δεξομένους ἀτακτότερον χωροῦντες, νικῶνται ὑπὸ τῶν Μιλησίων καὶ διαφθείρονται αὐτῶν ὀλίγῳ ἐλάσσους τριακοσίων ἀνδρῶν· Ἀθηναῖοι δὲ τούς τε Πελοποννησίους πρώτους νικήσαντες καὶ τοὺς βαρβάρους καὶ τὸν ἄλλον ὄχλον ὠσάμενοι, τοῖς Μιλησίοις οὐ ξυμμείξαντες, ἀλλ’ ὑποχωρησάντων αὐτῶν ἀπὸ τῆς τῶν Ἀργείων τροπῆς ἐς τὴν πόλιν ὡς ἑώρων τὸ ἄλλο σφῶν ἡσσώμενον, πρὸς αὐτὴν τὴν πόλιν τῶν Μιλησίων κρατοῦντες ἤδη τὰ ὅπλα τίθενται. καὶ ξυνέβη ἐν τῇ μάχῃ ταύτῃ τοὺς Ἴωνας ἀμφοτέρωθεν τῶν Δωριῶν κρατῆσαι· τούς τε γὰρ κατὰ σφᾶς Πελοποννησίους οἱ Ἀθηναῖοι ἐνίκων καὶ τοὺς Ἀργείους οἱ Μιλήσιοι. στήσαντες δὲ τροπαῖον τὸν περιτειχισμὸν ἰσθμώδους ὄντος τοῦ χωρίου οἱ Ἀθηναῖοι παρεσκευάζοντο, νομίζοντες, εἰ προσαγάγοιντο Μίλητον, ῥᾳδίως ἂν σφίσι καὶ τἆλλα προσχωρῆσαι.", "st": "8.25"}, {"sp": "N", "t": "ἐν τούτῳ δὲ περὶ δείλην ἤδη ὀψίαν ἀγγέλλεται αὐτοῖς τὰς ἀπὸ Πελοποννήσου καὶ Σικελίας πέντε καὶ πεντήκοντα ναῦς ὅσον οὐ παρεῖναι. τῶν τε γὰρ Σικελιωτῶν, Ἑρμοκράτους τοῦ Συρακοσίου μάλιστα ἐνάγοντος ξυνεπιλαβέσθαι καὶ τῆς ὑπολοίπου Ἀθηναίων καταλύσεως, εἴκοσι νῆες Συρακοσίων ἦλθον καὶ Σελινούντιαι δύο, αἵ τε ἐκ Πελοποννήσου, ἃς παρεσκευάζοντο, ἑτοῖμαι ἤδη οὖσαι· καὶ Θηριμένει τῷ Λακεδαιμονίῳ ξυναμφότεραι ὡς Ἀστύοχον τὸν ναύαρχον προσταχθεῖσαι κομίσαι, κατέπλευσαν ἐς Λέρον πρῶτον τὴν πρὸ Μιλήτου νῆσον· ἔπειτα ἐκεῖθεν αἰσθόμενοι ἐπὶ Μιλήτῳ ὄντας Ἀθηναίους ἐς τὸν Ἰασικὸν κόλπον πρότερον πλεύσαντες ἐβούλοντο εἰδέναι τὰ περὶ τῆς Μιλήτου. ἐλθόντος δὲ Ἀλκιβιάδου ἵππῳ ἐς Τειχιοῦσσαν τῆς Μιλησίας, οἷπερ τοῦ κόλπου πλεύσαντες ηὐλίσαντο, πυνθάνονται τὰ περὶ τῆς μάχης (παρῆν γὰρ ὁ Ἀλκιβιάδης καὶ ξυνεμάχετο τοῖς Μιλησίοις καὶ Τισσαφέρνει), καὶ αὐτοῖς παρῄνει, εἰ μὴ βούλονται τά τε ἐν Ἰωνίᾳ καὶ τὰ ξύμπαντα πράγματα διολέσαι, ὡς τάχιστα βοηθεῖν Μιλήτῳ καὶ μὴ περιιδεῖν ἀποτειχισθεῖσαν.", "st": "8.26"}, {"sp": "N", "t": "καὶ οἱ μὲν ἅμα τῇ ἕῳ ἔμελλον βοηθήσειν· Φρύνιχος δὲ ὁ τῶν Ἀθηναίων στρατηγός, ὡς ἀπὸ τῆς Λέρου ἐπύθετο τὰ τῶν νεῶν σαφῶς, βουλομένων τῶν ξυναρχόντων ὑπομείναντας διαναυμαχεῖν, οὐκ ἔφη οὔτ’ αὐτὸς ποιήσειν τοῦτο οὔτ’ ἐκείνοις οὐδ’ ἄλλῳ οὐδενὶ ἐς δύναμιν ἐπιτρέψειν. ὅπου γὰρ [ἔξεστιν] ἐν ὑστέρῳ σαφῶς εἰδότας πρὸς ὁπόσας τε ναῦς πολεμίας καὶ ὅσαις πρὸς αὐτὰς ταῖς σφετέραις ἱκανῶς καὶ καθ’ ἡσυχίαν παρασκευασαμένοις ἔσται ἀγωνίσασθαι, οὐδέποτε τῷ αἰσχρῷ ὀνείδει εἴξας ἀλόγως διακινδυνεύσειν. οὐ γὰρ αἰσχρὸν εἶναι Ἀθηναίους ναυτικῷ μετὰ καιροῦ ὑποχωρῆσαι, ἀλλὰ καὶ μετὰ ὁτουοῦν τρόπου αἴσχιον ξυμβήσεσθαι ἢν ἡσσηθῶσιν· καὶ τὴν πόλιν οὐ μόνον τῷ αἰσχρῷ, ἀλλὰ καὶ τῷ μεγίστῳ κινδύνῳ περιπίπτειν, ᾗ μόλις ἐπὶ ταῖς γεγενημέναις ξυμφοραῖς ἐνδέχεσθαι μετὰ βεβαίου παρασκευῆς καθ’ ἑκουσίαν, ἢ πάνυ γε ἀνάγκῃ, προτέρᾳ ποι ἐπιχειρεῖν, ἦ που δὴ μὴ βιαζομένῃ γε πρὸς αὐθαιρέτους κινδύνους ἰέναι. ὡς τάχιστα δὲ ἐκέλευε τούς τε τραυματίας ἀναλαβόντας καὶ τὸν πεζὸν καὶ τῶν σκευῶν ὅσα ἦλθον ἔχοντες, ἃ δ’ ἐκ τῆς πολεμίας εἰλήφασι καταλιπόντας ὅπως κοῦφαι ὦσιν αἱ νῆες, ἀποπλεῖν ἐς Σάμον, κἀκεῖθεν ἤδη ξυναγαγόντας πάσας τὰς ναῦς τοὺς ἐπίπλους, ἤν που καιρὸς ᾖ, ποιεῖσθαι. ὡς δὲ ἔπεισε, καὶ ἔδρασε ταῦτα· καὶ ἔδοξεν οὐκ ἐν τῷ αὐτίκα μᾶλλον ἢ ὕστερον, οὐκ ἐς τοῦτο μόνον, ἀλλὰ καὶ ἐς ὅσα ἄλλα Φρύνιχος κατέστη, οὐκ ἀξύνετος εἶναι. καὶ οἱ μὲν Ἀθηναῖοι ἀφ’ ἑσπέρας εὐθὺς τούτῳ τῷ τρόπῳ ἀτελεῖ τῇ νίκῃ ἀπὸ τῆς Μιλήτου ἀνέστησαν, καὶ οἱ Ἀργεῖοι κατὰ τάχος καὶ πρὸς ὀργὴν τῆς ξυμφορᾶς ἀπέπλευσαν ἐκ τῆς Σάμου ἐπ’ οἴκου·", "st": "8.27"}, {"sp": "N", "t": "οἱ δὲ Πελοποννήσιοι ἅμα τῇ ἕῳ ἐκ τῆς Τειχιούσσης ἄραντες ἐπικατάγονται, καὶ μείναντες ἡμέραν μίαν τῇ ὑστεραίᾳ καὶ τὰς Χίας ναῦς προσλαβόντες τὰς μετὰ Χαλκιδέως τὸ πρῶτον ξυγκαταδιωχθείσας ἐβούλοντο πλεῦσαι ἐπὶ τὰ σκεύη ἃ ἐξείλοντο ἐς Τειχιοῦσσαν πάλιν. καὶ ὡς ἦλθον, Τισσαφέρνης τῷ πεζῷ παρελθὼν πείθει αὐτοὺς ἐπὶ Ἴασον, ἐν ᾗ Ἀμόργης πολέμιος ὢν κατεῖχε, πλεῦσαι. καὶ προσβαλόντες τῇ Ἰάσῳ αἰφνίδιοι καὶ οὐ προσδεχομένων ἀλλ’ ἢ Ἀττικὰς τὰς ναῦς εἶναι αἱροῦσιν· καὶ μάλιστα ἐν τῷ ἔργῳ οἱ Συρακόσιοι ἐπῃνέθησαν. καὶ τόν τε Ἀμόργην ζῶντα λαβόντες, Πισσούθνου νόθον υἱόν, ἀφεστῶτα δὲ βασιλέως, παραδιδόασιν οἱ Πελοποννήσιοι Τισσαφέρνει ἀπαγαγεῖν, εἰ βούλεται, βασιλεῖ, ὥσπερ αὐτῷ προσέταξε, καὶ τὴν Ἴασον διεπόρθησαν καὶ χρήματα πάνυ πολλὰ ἡ στρατιὰ ἔλαβεν· παλαιόπλουτον γὰρ ἦν τὸ χωρίον. τούς τ’ ἐπικούρους τοὺς περὶ τὸν Ἀμόργην παρὰ σφᾶς αὐτοὺς κομίσαντες καὶ οὐκ ἀδικήσαντες ξυνέταξαν, ὅτι ἦσαν οἱ πλεῖστοι ἐκ Πελοποννήσου· τό τε πόλισμα Τισσαφέρνει παραδόντες καὶ τὰ ἀνδράποδα πάντα καὶ δοῦλα καὶ ἐλεύθερα, ὧν καθ’ ἕκαστον στατῆρα Δαρεικὸν παρ’ αὐτοῦ ξυνέβησαν λαβεῖν, ἔπειτα ἀνεχώρησαν ἐς τὴν Μίλητον. καὶ Πεδάριτόν τε τὸν Λέοντος ἐς τὴν Χίον ἄρχοντα Λακεδαιμονίων πεμψάντων ἀποστέλλουσι πεζῇ μέχρι Ἐρυθρῶν ἔχοντα τὸ παρὰ Ἀμόργου ἐπικουρικόν, καὶ ἐς τὴν Μίλητον αὐτοῦ Φίλιππον καθιστᾶσιν. καὶ τὸ θέρος ἐτελεύτα.", "st": "8.28"}, {"sp": "N", "t": "τοῦ δ’ ἐπιγιγνομένου χειμῶνος, ἐπειδὴ τὴν Ἴασον κατεστήσατο ὁ Τισσαφέρνης ἐς φυλακήν, παρῆλθεν ἐς τὴν Μίλητον, καὶ μηνὸς μὲν τροφήν, ὥσπερ ὑπέστη ἐν τῇ Λακεδαίμονι, ἐς δραχμὴν Ἀττικὴν ἑκάστῳ πάσαις ταῖς ναυσὶ διέδωκε, τοῦ δὲ λοιποῦ χρόνου ἐβούλετο τριώβολον διδόναι, ἕως ἂν βασιλέα ἐπέρηται· ἢν δὲ κελεύῃ, δώσειν ἔφη ἐντελῆ τὴν δραχμήν. Ἑρμοκράτους δὲ ἀντειπόντος τοῦ Συρακοσίου στρατηγοῦ (ὁ γὰρ Θηριμένης οὐ ναύαρχος ὤν, ἀλλ’ Ἀστυόχῳ παραδοῦναι τὰς ναῦς ξυμπλέων μαλακὸς ἦν περὶ τοῦ μισθοῦ) ὅμως δὲ παρὰ πέντε ναῦς πλέον ἀνδρὶ ἑκάστῳ ἢ τρεῖς ὀβολοὶ ὡμολογήθησαν. ἐς γὰρ πέντε ναῦς καὶ πεντήκοντα τριάκοντα τάλαντα ἐδίδου τοῦ μηνός· καὶ τοῖς ἄλλοις, ὅσῳ πλείους νῆες ἦσαν τούτου τοῦ ἀριθμοῦ, κατὰ τὸν αὐτὸν λόγον τοῦτον ἐδίδοτο.", "st": "8.29"}, {"sp": "N", "t": "τοῦ δ’ αὐτοῦ χειμῶνος τοῖς ἐν τῇ Σάμῳ Ἀθηναίοις προσαφιγμέναι γὰρ ἦσαν καὶ οἴκοθεν ἄλλαι νῆες πέντε καὶ τριάκοντα καὶ στρατηγοὶ Χαρμῖνος καὶ Στρομβιχίδης καὶ Εὐκτήμων, καὶ τὰς ἀπὸ Χίου καὶ τὰς ἄλλας πάσας ξυναγαγόντες ἐβούλοντο διακληρωσάμενοι ἐπὶ μὲν τῇ Μιλήτῳ τῷ ναυτικῷ ἐφορμεῖν, πρὸς δὲ τὴν Χίον καὶ ναυτικὸν καὶ πεζὸν πέμψαι. καὶ ἐποίησαν οὕτως· Στρομβιχίδης μὲν γὰρ καὶ Ὀνομακλῆς καὶ Εὐκτήμων τριάκοντα ναῦς ἔχοντες καὶ τῶν ἐς Μίλητον ἐλθόντων χιλίων ὁπλιτῶν μέρος ἄγοντες ἐν ναυσὶν ὁπλιταγωγοῖς ἐπὶ Χίον λαχόντες ἔπλεον, οἱ δ’ ἄλλοι ἐν Σάμῳ μένοντες τέσσαρσι καὶ ἑβδομήκοντα ναυσὶν ἐθαλασσοκράτουν καὶ ἐπίπλους τῇ Μιλήτῳ ἐποιοῦντο.", "st": "8.30"}, {"sp": "N", "t": "ὁ δ’ Ἀστύοχος ὡς τότε ἐν τῇ Χίῳ ἔτυχε διὰ τὴν προδοσίαν τοὺς ὁμήρους καταλεγόμενος τούτου μὲν ἐπέσχεν, ἐπειδὴ ᾔσθετο τάς τε μετὰ Θηριμένους ναῦς ἡκούσας καὶ τὰ περὶ τὴν ξυμμαχίαν βελτίω ὄντα, λαβὼν δὲ ναῦς τάς τε Πελοποννησίων δέκα καὶ Χίας δέκα ἀνάγεται, καὶ προσβαλὼν Πτελεῷ καὶ οὐχ ἑλὼν παρέπλευσεν ἐπὶ Κλαζομενὰς καὶ ἐκέλευεν αὐτῶν τοὺς τὰ Ἀθηναίων φρονοῦντας ἀνοικίζεσθαι ἐς τὸν Δαφνοῦντα καὶ προσχωρεῖν σφίσιν· ξυνεκέλευε δὲ καὶ Τάμως Ἰωνίας ὕπαρχος ὤν. ὡς δ’ οὐκ ἐσήκουον, προσβολὴν ποιησάμενος τῇ πόλει οὔσῃ ἀτειχίστῳ καὶ οὐ δυνάμενος ἑλεῖν, ἀπέπλευσεν ἀνέμῳ μεγάλῳ αὐτὸς μὲν ἐς Φώκαιαν καὶ Κύμην, αἱ δὲ ἄλλαι νῆες κατῆραν ἐς τὰς ἐπικειμένας ταῖς Κλαζομεναῖς νήσους, Μαραθοῦσσαν καὶ Πήλην καὶ Δρυμοῦσσαν. καὶ ὅσα ὑπεξέκειτο αὐτόθι τῶν Κλαζομενίων, ἡμέρας ἐμμείναντες διὰ τοὺς ἀνέμους ὀκτὼ τὰ μὲν διήρπασαν καὶ ἀνήλωσαν, τὰ δὲ ἐσβαλόμενοι ἀπέπλευσαν ἐς Φώκαιαν καὶ Κύμην ὡς Ἀστύοχον.", "st": "8.31"}, {"sp": "N", "t": "ὄντος δ’ αὐτοῦ ἐνταῦθα Λεσβίων ἀφικνοῦνται πρέσβεις βουλόμενοι αὖθις ἀποστῆναι· καὶ αὐτὸν μὲν πείθουσιν, ὡς δ’ οἵ τε Κορίνθιοι καὶ οἱ ἄλλοι ξύμμαχοι ἀπρόθυμοι ἦσαν διὰ τὸ πρότερον σφάλμα, ἄρας ἔπλει ἐπὶ τῆς Χίου. καὶ χειμασθεισῶν τῶν νεῶν ὕστερον ἀφικνοῦνται ἄλλαι ἄλλοθεν ἐς τὴν Χίον. καὶ μετὰ τοῦτο Πεδάριτος, τότε παριὼν πεζῇ ἐκ τῆς Μιλήτου, γενόμενος ἐν Ἐρυθραῖς διαπεραιοῦται αὐτός τε καὶ ἡ στρατιὰ ἐς Χίον· ὑπῆρχον δὲ αὐτῷ καὶ ἐκ τῶν πέντε νεῶν στρατιῶται ὑπὸ Χαλκιδέως ἐς πεντακοσίους ξὺν ὅπλοις καταλειφθέντες. ἐπαγγελλομένων δέ τινων Λεσβίων τὴν ἀπόστασιν, προσφέρει τῷ τε Πεδαρίτῳ καὶ τοῖς Χίοις ὁ Ἀστύοχος τὸν λόγον ὡς χρὴ παραγενομένους ταῖς ναυσὶν ἀποστῆσαι τὴν λέσβον· ἢ γὰρ ξυμμάχους πλείους σφᾶς ἕξειν, ἢ τοὺς Ἀθηναίους, ἤν τι σφάλλωνται, κακώσειν. οἱ δ’ οὐκ ἐσήκουον, οὐδὲ τὰς ναῦς ὁ Πεδάριτος ἔφη τῶν Χίων αὐτῷ προήσειν.", "st": "8.32"}, {"sp": "N", "t": "κἀκεῖνος λαβὼν τάς τε τῶν Κορινθίων πέντε καὶ ἕκτην Μεγαρίδα καὶ μίαν Ἑρμιονίδα καὶ ἃς αὐτὸς Λακωνικὰς ἔχων ἦλθεν, ἔπλει ἐπὶ τῆς Μιλήτου πρὸς τὴν ναυαρχίαν, πολλὰ ἀπειλήσας τοῖς Χίοις ἦ μὴν μὴ ἐπιβοηθήσειν, ἤν τι δέωνται. καὶ προσβαλὼν Κωρύκῳ τῆς Ἐρυθραίας ἐνηυλίσατο. οἱ δ’ ἀπὸ τῆς Σάμου Ἀθηναῖοι ἐπὶ τὴν Χίον πλέοντες τῇ στρατιᾷ καὶ αὐτοὶ ἐκ τοῦ ἐπὶ θάτερα λόφου διείργοντο καὶ καθωρμίσαντο καὶ ἐλελήθεσαν ἀλλήλους. ἐλθούσης δὲ παρὰ Πεδαρίτου ὑπὸ νύκτα ἐπιστολῆς ὡς Ἐρυθραίων ἄνδρες αἰχμάλωτοι ἐκ Σάμου ἐπὶ προδοσίᾳ ἐς Ἐρυθρὰς ἥκουσιν ἀφειμένοι, ἀνάγεται ὁ Ἀστύοχος εὐθὺς ἐς τὰς Ἐρυθρὰς πάλιν, καὶ παρὰ τοσοῦτον ἐγένετο αὐτῷ μὴ περιπεσεῖν τοῖς Ἀθηναίοις. διαπλεύσας δὲ καὶ ὁ Πεδάριτος πρὸς αὐτόν, καὶ ἀναζητήσαντες τὰ περὶ τῶν δοκούντων προδιδόναι, ὡς ηὗρον ἅπαν ἐπὶ σωτηρίᾳ τῶν ἀνθρώπων ἐκ τῆς Σάμου προφασισθέν, ἀπολύσαντες τῆς αἰτίας ἀπέπλευσαν ὁ μὲν ἐς τὴν Χίον, ὁ δὲ ἐς τὴν Μίλητον ἐκομίσθη, ὥσπερ διενοεῖτο.", "st": "8.33"}, {"sp": "N", "t": "ἐν τούτῳ δὲ καὶ ἡ τῶν Ἀθηναίων στρατιὰ ταῖς ναυσὶν ἐκ τοῦ Κωρύκου περιπλέουσα κατ’ Ἀργῖνον ἐπιτυγχάνει τρισὶ ναυσὶ τῶν Χίων μακραῖς, καὶ ὡς εἶδον, ἐδίωκον· καὶ χειμών τε μέγας ἐπιγίγνεται καὶ αἱ μὲν τῶν Χίων μόλις καταφεύγουσιν ἐς τὸν λιμένα, αἱ δὲ τῶν Ἀθηναίων αἱ μὲν μάλιστα ὁρμήσασαι τρεῖς διαφθείρονται καὶ ἐκπίπτουσι πρὸς τὴν πόλιν τῶν Χίων, καὶ ἄνδρες οἱ μὲν ἁλίσκονται, οἱ δ’ ἀποθνῄσκουσιν, αἱ δ’ ἄλλαι καταφεύγουσιν ἐς τὸν ὑπὸ τῷ Μίμαντι λιμένα Φοινικοῦντα καλούμενον. ἐντεῦθεν δ’ ὕστερον ἐς τὴν Λέσβον καθορμισάμενοι παρεσκευάζοντο ἐς τὸν τειχισμόν.", "st": "8.34"}, {"sp": "N", "t": "ἐκ δὲ τῆς Πελοποννήσου τοῦ αὐτοῦ χειμῶνος Ἱπποκράτης ὁ Λακεδαιμόνιος ἐκπλεύσας δέκα μὲν Θουρίαις ναυσίν, ὧν ἦρχε Δωριεὺς ὁ Διαγόρου τρίτος αὐτός, μιᾷ δὲ Λακωνικῇ, μιᾷ δὲ Συρακοσίᾳ, καταπλεῖ ἐς Κνίδον· ἡ δ’ ἀφειστήκει ἤδη ὑπὸ Τισσαφέρνους. καὶ αὐτοὺς οἱ ἐν τῇ Μιλήτῳ, ὡς ᾔσθοντο, ἐκέλευον ταῖς μὲν ἡμισείαις τῶν νεῶν Κνίδον φυλάσσειν, ταῖς δὲ περὶ Τριόπιον οὔσαις τὰς ἀπ’ Αἰγύπτου ὁλκάδας προσβαλλούσας ξυλλαμβάνειν· ἔστι δὲ τὸ Τριόπιον ἄκρα τῆς Κνιδίας προύχουσα, Ἀπόλλωνος ἱερόν. πυθόμενοι δὲ οἱ Ἀθηναῖοι καὶ πλεύσαντες ἐκ τῆς Σάμου λαμβάνουσι τὰς ἐπὶ τῷ Τριοπίῳ φρουρούσας ἓξ ναῦς· οἱ δ’ ἄνδρες ἀποφεύγουσιν ἐξ αὐτῶν. καὶ μετὰ τοῦτο ἐς τὴν Κνίδον καταπλεύσαντες καὶ προσβαλόντες τῇ πόλει ἀτειχίστῳ οὔσῃ ὀλίγου εἷλον. τῇ δ’ ὑστεραίᾳ αὖθις προσέβαλλον, καὶ ὡς ἄμεινον φαρξαμένων αὐτῶν ὑπὸ νύκτα καὶ ἐπεσελθόντων αὐτοῖς τῶν ἀπὸ τοῦ Τριοπίου ἐκ τῶν νεῶν διαφυγόντων οὐκέθ’ ὁμοίως ἔβλαπτον, ἀπελθόντες καὶ δῃώσαντες τὴν τῶν Κνιδίων γῆν ἐς τὴν Σάμον ἀπέπλευσαν.", "st": "8.35"}, {"sp": "N", "t": "ὑπὸ δὲ τὸν αὐτὸν χρόνον Ἀστυόχου ἥκοντος ἐς τὴν Μίλητον ἐπὶ τὸ ναυτικὸν οἱ Πελοποννήσιοι εὐπόρως ἔτι εἶχον ἅπαντα τὰ κατὰ τὸ στρατόπεδον· καὶ γὰρ μισθὸς ἐδίδοτο ἀρκούντως καὶ τὰ ἐκ τῆς Ἰάσου μεγάλα χρήματα διαρπασθέντα ὑπῆν τοῖς στρατιώταις, οἵ τε Μιλήσιοι προθύμως τὰ τοῦ πολέμου ἔφερον. πρὸς δὲ τὸν Τισσαφέρνην ἐδόκουν ὅμως τοῖς Πελοποννησίοις αἱ πρῶται ξυνθῆκαι αἱ πρὸς Χαλκιδέα γενόμεναι ἐνδεεῖς εἶναι καὶ οὐ πρὸς σφῶν μᾶλλον, καὶ ἄλλας ἔτι Θηριμένους παρόντος ἐποίουν· καὶ εἰσὶν αἵδε.", "st": "8.36"}, {"sp": "N", "t": "‘ξυνθῆκαι Λακεδαιμονίων καὶ τῶν ξυμμάχων πρὸς βασιλέα Δαρεῖον καὶ τοὺς παῖδας τοὺς βασιλέως καὶ Τισσαφέρνην, σπονδὰς εἶναι καὶ φιλίαν κατὰ τάδε. ὁπόση χώρα καὶ πόλεις βασιλέως εἰσὶ Δαρείου ἢ τοῦ πατρὸς ἦσαν ἢ τῶν προγόνων, ἐπὶ ταύτας μὴ ἰέναι ἐπὶ πολέμῳ μηδὲ κακῷ μηδενὶ μήτε Λακεδαιμονίους μήτε τοὺς ξυμμάχους τοὺς Λακεδαιμονίων, μηδὲ φόρους πράσσεσθαι ἐκ τῶν πόλεων τούτων μήτε Λακεδαιμονίους μήτε τοὺς ξυμμάχους τοὺς Λακεδαιμονίων· μηδὲ Δαρεῖον βασιλέα μηδὲ ὧν βασιλεὺς ἄρχει ἐπὶ Λακεδαιμονίους μηδὲ τοὺς ξυμμάχους ἰέναι ἐπὶ πολέμῳ μηδὲ κακῷ μηδενί. ἢν δέ τι δέωνται Λακεδαιμόνιοι ἢ οἱ ξύμμαχοι βασιλέως ἢ βασιλεὺς Λακεδαιμονίων ἢ τῶν ξυμμάχων, ὅτι ἂν πείθωσιν ἀλλήλους, τοῦτο ποιοῦσι καλῶς ἔχειν. τὸν δὲ πόλεμον τὸν πρὸς Ἀθηναίους καὶ τοὺς ξυμμάχους κοινῇ ἀμφοτέρους πολεμεῖν· ἢν δὲ κατάλυσιν ποιῶνται, κοινῇ ἀμφοτέρους ποιεῖσθαι. ὁπόση δ’ ἂν στρατιὰ ἐν τῇ χώρᾳ τῇ βασιλέως ᾖ μεταπεμψαμένου βασιλέως, τὴν δαπάνην βασιλέα παρέχειν. ἢν δέ τις τῶν πόλεων ὁπόσαι ξυνέθεντο βασιλεῖ ἐπὶ τὴν βασιλέως ἴῃ χώραν, τοὺς ἄλλους κωλύειν καὶ ἀμύνειν βασιλεῖ κατὰ τὸ δυνατόν· καὶ ἤν τις τῶν ἐν τῇ βασιλέως χώρᾳ ἢ ὅσης βασιλεὺς ἄρχει ἐπὶ τὴν Λακεδαιμονίων ἴῃ ἢ τῶν ξυμμάχων, βασιλεὺς κωλυέτω καὶ ἀμυνέτω κατὰ τὸ δυνατόν.’", "st": "8.37"}, {"sp": "N", "t": "μετὰ δὲ ταύτας τὰς ξυνθήκας Θηριμένης μὲν παραδοὺς Ἀστυόχῳ τὰς ναῦς ἀποπλέων ἐν κέλητι ἀφανίζεται, οἱ δ’ ἐκ τῆς Λέσβου Ἀθηναῖοι ἤδη διαβεβηκότες ἐς τὴν Χίον τῇ στρατιᾷ καὶ κρατοῦντες καὶ γῆς καὶ θαλάσσης Δελφίνιον ἐτείχιζον, χωρίον ἄλλως τε ἐκ γῆς καρτερὸν καὶ λιμένας ἔχον καὶ τῆς τῶν Χίων πόλεως οὐ πολὺ ἀπέχον. οἱ δὲ Χῖοι ἐν πολλαῖς ταῖς πρὶν μάχαις πεπληγμένοι, καὶ ἄλλως ἐν σφίσιν αὐτοῖς οὐ πάνυ εὖ διακείμενοι, ἀλλὰ καὶ τῶν μετὰ Τυδέως τοῦ Ἴωνος ἤδη ὑπὸ Πεδαρίτου ἐπ’ ἀττικισμῷ τεθνεώτων καὶ τῆς ἄλλης πόλεως κατ’ ἀνάγκην ἐς ὀλίγους κατεχομένης ὑπόπτως διακείμενοι ἀλλήλοις ἡσύχαζον, καὶ οὔτ’ αὐτοὶ διὰ ταῦτα οὔθ’ οἱ μετὰ Πεδαρίτου ἐπίκουροι ἀξιόμαχοι αὐτοῖς ἐφαίνοντο. ἐς μέντοι τὴν Μίλητον ἔπεμπον κελεύοντες σφίσι τὸν Ἀστύοχον βοηθεῖν· ὡς δ’ οὐκ ἐσήκουεν, ἐπιστέλλει περὶ αὐτοῦ ἐς τὴν Λακεδαίμονα ὁ Πεδάριτος ὡς ἀδικοῦντος. καὶ τὰ μὲν ἐν τῇ Χίῳ ἐς τοῦτο καθειστήκει τοῖς Ἀθηναίοις· αἱ δ’ ἐκ τῆς Σάμου νῆες αὐτοῖς ἐπίπλους μὲν ἐποιοῦντο ταῖς ἐν τῇ Μιλήτῳ, ἐπεὶ δὲ μὴ ἀντανάγοιεν, ἀναχωροῦντες πάλιν ἐς τὴν Σάμον ἡσύχαζον.", "st": "8.38"}, {"sp": "N", "t": "ἐκ δὲ τῆς Πελοποννήσου ἐν τῷ αὐτῷ χειμῶνι αἱ τῷ Φαρναβάζῳ [ὑπὸ] Καλλιγείτου τοῦ Μεγαρέως καὶ Τιμαγόρου τοῦ Κυζικηνοῦ πρασσόντων παρασκευασθεῖσαι ὑπὸ Λακεδαιμονίων ἑπτὰ καὶ εἴκοσι νῆες ἄρασαι ἔπλεον ἐπὶ Ἰωνίας περὶ ἡλίου τροπάς, καὶ ἄρχων ἐπέπλει αὐτῶν Ἀντισθένης Σπαρτιάτης. ξυνέπεμψαν δὲ οἱ Λακεδαιμόνιοι καὶ ἕνδεκα ἄνδρας Σπαρτιατῶν ξυμβούλους Ἀστυόχῳ, ὧν εἷς ἦν Λίχας ὁ Ἀρκεσιλάου· καὶ εἴρητο αὐτοῖς ἐς Μίλητον ἀφικομένους τῶν τε ἄλλων ξυνεπιμέλεσθαι ᾗ μέλλει ἄριστα ἕξειν, καὶ τὰς ναῦς ταύτας ἢ αὐτὰς ἢ πλείους ἢ καὶ ἐλάσσους ἐς τὸν Ἑλλήσποντον ὡς Φαρνάβαζον, ἢν δοκῇ, ἀποπέμπειν, Κλέαρχον τὸν Ῥαμφίου, ὃς ξυνέπλει, ἄρχοντα προστάξαντας, καὶ Ἀστύοχον, ἢν δοκῇ τοῖς ἕνδεκα ἀνδράσι, παύειν τῆς ναυαρχίας, Ἀντισθένη δὲ καθιστάναι· πρὸς γὰρ τὰς τοῦ Πεδαρίτου ἐπιστολὰς ὑπώπτευον αὐτόν. πλέουσαι οὖν αἱ νῆες ἀπὸ Μαλέας πελάγιαι Μήλῳ προσέβαλον, καὶ περιτυχόντες ναυσὶ δέκα Ἀθηναίων τὰς τρεῖς λαμβάνουσι κενὰς καὶ κατακαίουσιν. μετὰ δὲ τοῦτο δεδιότες μὴ αἱ διαφυγοῦσαι τῶν Ἀθηναίων ἐκ τῆς Μήλου νῆες, ὅπερ ἐγένετο, μηνύσωσι τοῖς ἐν τῇ Σάμῳ τὸν ἐπίπλουν αὐτῶν, πρὸς τὴν Κρήτην πλεύσαντες καὶ πλείω τὸν πλοῦν διὰ φυλακῆς ποιησάμενοι ἐς τὴν Καῦνον τῆς Ἀσίας κατῆραν. ἐντεῦθεν δὴ ὡς ἐν ἀσφαλεῖ ὄντες ἀγγελίαν ἔπεμπον ἐπὶ τὰς ἐν τῇ Μιλήτῳ ναῦς τοῦ ξυμπαρακομισθῆναι.", "st": "8.39"}, {"sp": "N", "t": "οἱ δὲ Χῖοι καὶ Πεδάριτος κατὰ τὸν αὐτὸν χρόνον οὐδὲν ἧσσον, καίπερ διαμέλλοντα, τὸν Ἀστύοχον πέμποντες ἀγγέλους ἠξίουν σφίσι πολιορκουμένοις βοηθῆσαι ἁπάσαις ταῖς ναυσὶ καὶ μὴ περιιδεῖν τὴν μεγίστην τῶν ἐν Ἰωνίᾳ ξυμμαχίδων πόλεων ἔκ τε θαλάσσης εἰργομένην καὶ κατὰ γῆν λῃστείαις πορθουμένην. οἱ γὰρ οἰκέται τοῖς Χίοις πολλοὶ ὄντες καὶ μιᾷ γε πόλει πλὴν Λακεδαιμονίων πλεῖστοι γενόμενοι καὶ ἅμα διὰ τὸ πλῆθος χαλεπωτέρως ἐν ταῖς ἀδικίαις κολαζόμενοι, ὡς ἡ στρατιὰ τῶν Ἀθηναίων βεβαίως ἔδοξε μετὰ τείχους ἱδρῦσθαι, εὐθὺς αὐτομολίᾳ τε ἐχώρησαν οἱ πολλοὶ πρὸς αὐτοὺς καὶ τὰ πλεῖστα κακὰ ἐπιστάμενοι τὴν χώραν οὗτοι ἔδρασαν. ἔφασαν οὖν χρῆναι οἱ Χῖοι, ἕως ἔτι ἐλπὶς καὶ δυνατὸν κωλῦσαι, τειχιζομένου τοῦ Δελφινίου καὶ ἀτελοῦς ὄντος καὶ στρατοπέδῳ καὶ ναυσὶν ἐρύματος μείζονος προσπεριβαλλομένου, βοηθῆσαι σφίσιν. ὁ δὲ Ἀστύοχος καίπερ οὐ διανοούμενος διὰ τὴν τότε ἀπειλήν, ὡς ἑώρα καὶ τοὺς ξυμμάχους προθύμους ὄντας, ὥρμητο ἐς τὸ βοηθεῖν.", "st": "8.40"}, {"sp": "N", "t": "ἐν τούτῳ δὲ ἐκ τῆς Καύνου παραγίγνεται ἀγγελία ὅτι αἱ ἑπτὰ καὶ εἴκοσι νῆες καὶ οἱ τῶν Λακεδαιμονίων ξύμβουλοι πάρεισιν· καὶ νομίσας πάντα ὕστερα εἶναι τἆλλα πρὸς τὸ ναῦς τε, ὅπως θαλασσοκρατοῖεν μᾶλλον, τοσαύτας ξυμπαρακομίσαι, καὶ τοὺς Λακεδαιμονίους, οἳ ἧκον κατάσκοποι αὐτοῦ, ἀσφαλῶς περαιωθῆναι, εὐθὺς ἀφεὶς τὸ ἐς τὴν Χίον ἔπλει ἐς τὴν Καῦνον. καὶ ἐς Κῶν τὴν Μεροπίδα ἐν τῷ παράπλῳ ἀποβὰς τήν τε πόλιν ἀτείχιστον οὖσαν καὶ ὑπὸ σεισμοῦ, ὃς αὐτοῖς ἔτυχε μέγιστός γε δὴ ὧν μεμνήμεθα γενόμενος, ξυμπεπτωκυῖαν ἐκπορθεῖ, τῶν ἀνθρώπων ἐς τὰ ὄρη πεφευγότων, καὶ τὴν χώραν καταδρομαῖς λείαν ἐποιεῖτο, πλὴν τῶν ἐλευθέρων· τούτους δὲ ἀφίει. ἐκ δὲ τῆς Κῶ ἀφικόμενος ἐς τὴν Κνίδον νυκτὸς ἀναγκάζεται ὑπὸ τῶν Κνιδίων παραινούντων μὴ ἐκβιβάσαι τοὺς ναύτας, ἀλλ’ ὥσπερ εἶχε πλεῖν εὐθὺς ἐπὶ τὰς τῶν Ἀθηναίων ναῦς εἴκοσιν, ἃς ἔχων Χαρμῖνος εἷς τῶν ἐκ Σάμου στρατηγῶν ἐφύλασσε ταύτας τὰς ἑπτὰ καὶ εἴκοσι ναῦς ἐκ τῆς Πελοποννήσου προσπλεούσας, ἐφ’ ἅσπερ καὶ ὁ Ἀστύοχος παρέπλει. ἐπύθοντο δὲ οἱ ἐν τῇ Σάμῳ ἐκ τῆς Μήλου τὸν ἐπίπλουν αὐτῶν, καὶ ἡ φυλακὴ τῷ Χαρμίνῳ περὶ τὴν Σύμην καὶ Χάλκην καὶ Ῥόδον καὶ περὶ τὴν Λυκίαν ἦν· ἤδη γὰρ ᾐσθάνετο καὶ ἐν τῇ Καύνῳ οὔσας αὐτάς.", "st": "8.41"}, {"sp": "N", "t": "ἐπέπλει οὖν ὥσπερ εἶχε πρὸς τὴν Σύμην ὁ Ἀστύοχος πρὶν ἔκπυστος γενέσθαι, εἴ πως περιλάβοι που μετεώρους τὰς ναῦς. καὶ αὐτῷ ὑετός τε καὶ τὰ ἐκ τοῦ οὐρανοῦ ξυννέφελα ὄντα πλάνησιν τῶν νεῶν ἐν τῷ σκότει καὶ ταραχὴν παρέσχεν. καὶ ἅμα τῇ ἕῳ διεσπασμένου τοῦ ναυτικοῦ καὶ τοῦ μὲν φανεροῦ ἤδη ὄντος τοῖς Ἀθηναίοις τοῦ εὐωνύμου κέρως, τοῦ δὲ ἄλλου περὶ τὴν νῆσον ἔτι πλανωμένου, ἐπανάγονται κατὰ τάχος ὁ Χαρμῖνος καὶ οἱ Ἀθηναῖοι ἐλάσσοσιν ἢ ταῖς εἴκοσι ναυσί, νομίσαντες ἅσπερ ἐφύλασσον ναῦς τὰς ἀπὸ τῆς Καύνου ταύτας εἶναι. καὶ προσπεσόντες εὐθὺς κατέδυσάν τε τρεῖς καὶ κατετραυμάτισαν ἄλλας, καὶ ἐν τῷ ἔργῳ ἐπεκράτουν, μέχρι οὗ ἐπεφάνησαν αὐτοῖς παρὰ δόξαν αἱ πλείους τῶν νεῶν καὶ πανταχόθεν ἀπεκλῄοντο. ἔπειτα δὲ ἐς φυγὴν καταστάντες ἓξ μὲν ναῦς ἀπολλύασι, ταῖς δὲ λοιπαῖς καταφεύγουσιν ἐς τὴν Τευτλοῦσσαν νῆσον, ἐντεῦθεν δὲ ἐς Ἁλικαρνασσόν. μετὰ δὲ τοῦτο οἱ μὲν Πελοποννήσιοι ἐς Κνίδον κατάραντες καὶ ξυμμιγεισῶν τῶν ἐκ τῆς Καύνου ἑπτὰ καὶ εἴκοσι νεῶν αὐτοῖς ξυμπάσαις πλεύσαντες καὶ τροπαῖον ἐν τῇ Σύμῃ στήσαντες πάλιν ἐς τὴν Κνίδον καθωρμίσαντο·", "st": "8.42"}, {"sp": "N", "t": "οἱ δὲ Ἀθηναῖοι ταῖς ἐκ τῆς Σάμου ναυσὶ πάσαις, ὡς ᾔσθοντο τὰ τῆς ναυμαχίας, πλεύσαντες ἐς τὴν Σύμην καὶ ἐπὶ μὲν τὸ ἐν τῇ Κνίδῳ ναυτικὸν οὐχ ὁρμήσαντες, οὐδ’ ἐκεῖνοι ἐπ’ ἐκείνους, λαβόντες δὲ τὰ ἐν τῇ Σύμῃ σκεύη τῶν νεῶν καὶ Λωρύμοις τοῖς ἐν τῇ ἠπείρῳ προσβαλόντες ἀπέπλευσαν ἐς τὴν Σάμον.", "st": "8.43"}, {"sp": "N", "t": "ἅπασαι δ’ ἤδη οὖσαι ἅμα ἐν τῇ Κνίδῳ αἱ τῶν Πελοποννησίων νῆες ἐπεσκευάζοντό τε εἴ τι ἔδει καὶ πρὸς τὸν Τισσαφέρνην (παρεγένετο γάρ) λόγους ἐποιοῦντο οἱ ἕνδεκα ἄνδρες τῶν Λακεδαιμονίων περί τε τῶν ἤδη πεπραγμένων, εἴ τι μὴ ἤρεσκεν αὐτοῖς, καὶ περὶ τοῦ μέλλοντος πολέμου, ὅτῳ τρόπῳ ἄριστα καὶ ξυμφορώτατα ἀμφοτέροις πολεμήσεται. μάλιστα δὲ ὁ Λίχας ἐσκόπει τὰ ποιούμενα, καὶ τὰς σπονδὰς οὐδετέρας, οὔτε τὰς Χαλκιδέως οὔτε τὰς Θηριμένους, ἔφη καλῶς ξυγκεῖσθαι, ἀλλὰ δεινὸν εἶναι εἰ χώρας ὅσης βασιλεὺς καὶ οἱ πρόγονοι ἦρξαν πρότερον, ταύτης καὶ νῦν ἀξιώσει κρατεῖν· ἐνεῖναι γὰρ καὶ νήσους ἁπάσας πάλιν δουλεύειν καὶ Θεσσαλίαν καὶ Λοκροὺς καὶ τὰ μέχρι Βοιωτῶν, καὶ ἀντ’ ἐλευθερίας ἂν Μηδικὴν ἀρχὴν τοῖς Ἕλλησι τοὺς Λακεδαιμονίους περιθεῖναι. ἑτέρας οὖν ἐκέλευε βελτίους σπένδεσθαι, ἢ ταύταις γε οὐ χρήσεσθαι, οὐδὲ τῆς τροφῆς ἐπὶ τούτοις δεῖσθαι οὐδέν. ἀγανακτῶν δὲ ὁ μὲν Τισσαφέρνης ἀπεχώρησεν ἀπ’ αὐτῶν δι’ ὀργῆς καὶ ἄπρακτος,", "st": "8.43"}, {"sp": "N", "t": "οἱ δ’ ἐς τὴν Ῥόδον ἐπικηρυκευομένων ἀπὸ τῶν δυνατωτάτων ἀνδρῶν τὴν γνώμην εἶχον πλεῖν, ἐλπίζοντες νῆσόν τε οὐκ ἀδύνατον καὶ ναυβατῶν πλήθει καὶ πεζῷ προσάξεσθαι, καὶ ἅμα ἡγούμενοι αὐτοὶ ἀπὸ τῆς ὑπαρχούσης ξυμμαχίας δυνατοὶ ἔσεσθαι Τισσαφέρνην μὴ αἰτοῦντες χρήματα τρέφειν τὰς ναῦς. πλεύσαντες οὖν εὐθὺς ἐν τῷ αὐτῷ χειμῶνι ἐκ τῆς Κνίδου καὶ προσβαλόντες Καμείρῳ τῆς Ῥοδίας πρῶτον ναυσὶ τέσσαρσι καὶ ἐνενήκοντα ἐξεφόβησαν μὲν τοὺς πολλοὺς οὐκ εἰδότας τὰ πρασσόμενα, καὶ ἔφευγον, ἄλλως τε καὶ ἀτειχίστου οὔσης τῆς πόλεως· εἶτα ξυγκαλέσαντες οἱ Λακεδαιμόνιοι τούτους τε καὶ τοὺς ἐκ τοῖν δυοῖν πολέοιν, Λίνδου καὶ Ἰηλυσοῦ, Ῥοδίους ἔπεισαν ἀποστῆναι Ἀθηναίων· καὶ προσεχώρησε Ῥόδος Πελοποννησίοις. οἱ δὲ Ἀθηναῖοι κατὰ τὸν καιρὸν τοῦτον ταῖς ἐκ τῆς Σάμου ναυσὶν αἰσθόμενοι ἔπλευσαν μὲν βουλόμενοι φθάσαι καὶ ἐπεφάνησαν πελάγιοι, ὑστερήσαντες δὲ οὐ πολλῷ τὸ μὲν παραχρῆμα ἀπέπλευσαν ἐς Χάλκην, ἐντεῦθεν δ’ ἐς Σάμον, ὕστερον δὲ ἐκ τῆς Χάλκης καὶ ἐκ τῆς Κῶ [καὶ ἐκ τῆς Σάμου] τοὺς ἐπίπλους ποιούμενοι ἐπὶ τὴν Ῥόδον ἐπολέμουν. οἱ δὲ χρήματα μὲν ἐξέλεξαν ἐς δύο καὶ τριάκοντα τάλαντα οἱ Πελοποννήσιοι παρὰ τῶν Ῥοδίων, τὰ δ’ ἄλλα ἡσύχαζον ἡμέρας ὀγδοήκοντα, ἀνελκύσαντες τὰς ναῦς.", "st": "8.44"}, {"sp": "N", "t": "ἐν δὲ τούτῳ καὶ ἔτι πρότερον, πρὶν ἐς τὴν Ῥόδον αὐτοὺς ἀναστῆναι, τάδε ἐπράσσετο. Ἀλκιβιάδης μετὰ τὸν Χαλκιδέως θάνατον καὶ τὴν ἐν Μιλήτῳ μάχην τοῖς Πελοποννησίοις ὕποπτος ὤν, καὶ ἀπ’ αὐτῶν ἀφικομένης ἐπιστολῆς πρὸς Ἀστύοχον ἐκ Λακεδαίμονος ὥστ’ ἀποκτεῖναι (ἦν γὰρ καὶ τῷ Ἄγιδι ἐχθρὸς καὶ ἄλλως ἄπιστος ἐφαίνετο), πρῶτον μὲν ὑποχωρεῖ δείσας παρὰ Τισσαφέρνην, ἔπειτα ἐκάκου πρὸς αὐτὸν ὅσον ἐδύνατο μάλιστα τῶν Πελοποννησίων τὰ πράγματα, καὶ διδάσκαλος πάντων γιγνόμενος τήν τε μισθοφορὰν ξυνέτεμεν, ἀντὶ δραχμῆς Ἀττικῆς ὥστε τριώβολον καὶ τοῦτο μὴ ξυνεχῶς δίδοσθαι, λέγειν κελεύων τὸν Τισσαφέρνην πρὸς αὐτοὺς ὡς Ἀθηναῖοι ἐκ πλέονος χρόνου ἐπιστήμονες ὄντες τοῦ ναυτικοῦ τριώβολον τοῖς ἑαυτῶν διδόασιν, οὐ τοσοῦτον πενίᾳ ὅσον ἵνα αὐτῶν μὴ οἱ ναῦται ἐκ περιουσίας ὑβρίζοντες οἱ μὲν τὰ σώματα χείρω ἔχωσι δαπανῶντες ἐς τοιαῦτα ἀφ’ ὧν ἡ ἀσθένεια ξυμβαίνει, οἱ δὲ τὰς ναῦς ἀπολείπωσιν οὐχ ὑπολιπόντες ἐς ὁμηρείαν τὸν προσοφειλόμενον μισθόν· καὶ τοὺς τριηράρχους καὶ τοὺς στρατηγοὺς τῶν πόλεων ἐδίδασκεν [ὥστε] δόντα χρήματα αὐτὸν πεῖσαι, ὥστε ξυγχωρῆσαι ταῦτα ἑαυτῷ πλὴν τῶν Συρακοσίων· τούτων δὲ Ἑρμοκράτης ἠναντιοῦτο μόνος ὑπὲρ τοῦ παντὸς ξυμμαχικοῦ. τάς τε πόλεις δεομένας χρημάτων ἀπήλασεν αὐτὸς ἀντιλέγων ὑπὲρ τοῦ Τισσαφέρνους ὡς οἱ μὲν Χῖοι ἀναίσχυντοι εἶεν πλουσιώτατοι ὄντες τῶν Ἑλλήνων, ἐπικουρίᾳ δ’ ὅμως σῳζόμενοι ἀξιοῦσι καὶ τοῖς σώμασι καὶ τοῖς χρήμασιν ἄλλους ὑπὲρ τῆς ἐκείνων ἐλευθερίας κινδυνεύειν· τὰς δ’ ἄλλας πόλεις ἔφη ἀδικεῖν, αἳ ἐς Ἀθηναίους πρότερον ἢ ἀποστῆναι ἀνήλουν, εἰ μὴ καὶ νῦν καὶ τοσαῦτα καὶ ἔτι πλείω ὑπὲρ σφῶν αὐτῶν ἐθελήσουσιν ἐσφέρειν. τόν τε Τισσαφέρνην ἀπέφαινε νῦν μέν, τοῖς ἰδίοις χρήμασι πολεμοῦντα, εἰκότως φειδόμενον, ἢν δέ ποτε τροφὴ καταβῇ παρὰ βασιλέως, ἐντελῆ αὐτοῖς ἀποδώσειν τὸν μισθὸν καὶ τὰς πόλεις τὰ εἰκότα ὠφελήσειν.", "st": "8.45"}, {"sp": "N", "t": "παρῄνει δὲ καὶ τῷ Τισσαφέρνει μὴ ἄγαν ἐπείγεσθαι τὸν πόλεμον διαλῦσαι, μηδὲ βουληθῆναι κομίσαντα ἢ ναῦς Φοινίσσας ἅσπερ παρεσκευάζετο ἢ Ἕλλησι πλέοσι μισθὸν πορίζοντα τοῖς αὐτοῖς τῆς τε γῆς καὶ τῆς θαλάσσης τὸ κράτος δοῦναι, ἔχειν δ’ ἀμφοτέρους ἐᾶν δίχα τὴν ἀρχήν, καὶ βασιλεῖ ἐξεῖναι αἰεὶ ἐπὶ τοὺς αὐτῷ λυπηροὺς τοὺς ἑτέρους ἐπάγειν. γενομένης δ’ ἂν καθ’ ἓν τῆς ἐς γῆν καὶ θάλασσαν ἀρχῆς ἀπορεῖν ἂν αὐτὸν οἷς τοὺς κρατοῦντας ξυγκαθαιρήσει, ἢν μὴ αὐτὸς βούληται μεγάλῃ δαπάνῃ καὶ κινδύνῳ ἀναστάς ποτε διαγωνίσασθαι. εὐτελέστερα δὲ τάδ’ εἶναι, βραχεῖ μορίῳ τῆς δαπάνης καὶ ἅμα μετὰ τῆς ἑαυτοῦ ἀσφαλείας αὐτοὺς περὶ ἑαυτοὺς τοὺς Ἕλληνας κατατρῖψαι. ἐπιτηδειοτέρους τε ἔφη τοὺς Ἀθηναίους εἶναι κοινωνοὺς αὐτῷ τῆς ἀρχῆς· ἧσσον γὰρ τῶν κατὰ γῆν ἐφίεσθαι, τὸν λόγον τε ξυμφορώτατον καὶ τὸ ἔργον ἔχοντας πολεμεῖν· τοὺς μὲν γὰρ ξυγκαταδουλοῦν ἂν σφίσι τε αὐτοῖς τὸ τῆς θαλάσσης μέρος καὶ ἐκείνῳ ὅσοι ἐν τῇ βασιλέως Ἕλληνες οἰκοῦσι, τοὺς δὲ τοὐναντίον ἐλευθερώσοντας ἥκειν, καὶ οὐκ εἰκὸς εἶναι Λακεδαιμονίους ἀπὸ μὲν σφῶν τῶν Ἑλλήνων ἐλευθεροῦν νῦν τοὺς Ἕλληνας, ἀπὸ δ’ ἐκείνων [τῶν βαρβάρων], ἢν μή ποτε αὐτοὺς μὴ ἐξέλωσι, μὴ ἐλευθερῶσαι. τρίβειν οὖν ἐκέλευε πρῶτον ἀμφοτέρους, καὶ ἀποτεμόμενον ὡς μέγιστα ἀπὸ τῶν Ἀθηναίων ἔπειτ’ ἤδη τοὺς Πελοποννησίους ἀπαλλάξαι ἐκ τῆς χώρας. καὶ διενοεῖτο τὸ πλέον οὕτως ὁ Τισσαφέρνης, ὅσα γε ἀπὸ τῶν ποιουμένων ἦν εἰκάσαι. τῷ γὰρ Ἀλκιβιάδῃ διὰ ταῦτα ὡς εὖ περὶ τούτων παραινοῦντι προσθεὶς ἑαυτὸν ἐς πίστιν τήν τε τροφὴν κακῶς ἐπόριζε τοῖς Πελοποννησίοις καὶ ναυμαχεῖν οὐκ εἴα, ἀλλὰ καὶ τὰς Φοινίσσας φάσκων ναῦς ἥξειν καὶ ἐκ περιόντος ἀγωνιεῖσθαι ἔφθειρε τὰ πράγματα καὶ τὴν ἀκμὴν τοῦ ναυτικοῦ αὐτῶν ἀφείλετο γενομένην καὶ πάνυ ἰσχυράν, τά τε ἄλλα καταφανέστερον ἢ ὥστε λανθάνειν οὐ προθύμως ξυνεπολέμει.", "st": "8.46"}, {"sp": "N", "t": "ὁ δὲ Ἀλκιβιάδης ταῦτα ἅμα μὲν τῷ Τισσαφέρνει καὶ [τῷ] βασιλεῖ, ὢν παρ’ ἐκείνοις, ἄριστα εἶναι νομίζων παρῄνει, ἅμα δὲ τὴν ἑαυτοῦ κάθοδον ἐς τὴν πατρίδα ἐπιθεραπεύων, εἰδώς, εἰ μὴ διαφθερεῖ αὐτήν, ὅτι ἔσται ποτὲ αὐτῷ πείσαντι κατελθεῖν· πεῖσαι δ’ ἂν ἐνόμιζε μάλιστα ἐκ τοῦ τοιούτου, εἰ Τισσαφέρνης φαίνοιτο αὐτῷ ἐπιτήδειος ὤν· ὅπερ καὶ ἐγένετο. ἐπειδὴ γὰρ ᾔσθοντο αὐτὸν ἰσχύοντα παρ’ αὐτῷ οἱ ἐν τῇ Σάμῳ Ἀθηναίων στρατιῶται, τὰ μὲν καὶ Ἀλκιβιάδου προσπέμψαντος λόγους ἐς τοὺς δυνατωτάτους αὐτῶν ἄνδρας ὥστε μνησθῆναι περὶ αὐτοῦ ἐς τοὺς βελτίστους τῶν ἀνθρώπων ὅτι ἐπ’ ὀλιγαρχίᾳ βούλεται καὶ οὐ πονηρίᾳ οὐδὲ δημοκρατίᾳ τῇ αὐτὸν ἐκβαλούσῃ κατελθὼν καὶ παρασχὼν Τισσαφέρνην φίλον αὐτοῖς ξυμπολιτεύειν, τὸ δὲ πλέον καὶ ἀπὸ σφῶν αὐτῶν οἱ ἐν τῇ Σάμῳ τριήραρχοί τε τῶν Ἀθηναίων καὶ δυνατώτατοι ὥρμηντο ἐς τὸ καταλῦσαι τὴν δημοκρατίαν.", "st": "8.47"}, {"sp": "N", "t": "καὶ ἐκινήθη πρότερον ἐν τῷ στρατοπέδῳ τοῦτο καὶ ἐς τὴν πόλιν ἐντεῦθεν ὕστερον ἦλθεν. τῷ τε Ἀλκιβιάδῃ διαβάντες τινὲς ἐκ τῆς Σάμου ἐς λόγους ἦλθον, καὶ ὑποτείνοντος αὐτοῦ Τισσαφέρνην μὲν πρῶτον, ἔπειτα δὲ καὶ βασιλέα φίλον ποιήσειν, εἰ μὴ δημοκρατοῖντο (οὕτω γὰρ ἂν πιστεῦσαι μᾶλλον βασιλέα), πολλὰς ἐλπίδας εἶχον αὐτοί θ’ ἑαυτοῖς οἱ δυνατώτατοι τῶν πολιτῶν τὰ πράγματα, οἵπερ καὶ ταλαιπωροῦνται μάλιστα, ἐς ἑαυτοὺς περιποιήσειν καὶ τῶν πολεμίων ἐπικρατήσειν. ἔς τε τὴν Σάμον ἐλθόντες ξυνίστασάν τε τῶν ἀνθρώπων τοὺς ἐπιτηδείους ἐς ξυνωμοσίαν καὶ ἐς τοὺς πολλοὺς φανερῶς ἔλεγον ὅτι βασιλεὺς σφίσι φίλος ἔσοιτο καὶ χρήματα παρέξοι Ἀλκιβιάδου τε κατελθόντος καὶ μὴ δημοκρατουμένων. καὶ ὁ μὲν ὄχλος, εἰ καί τι παραυτίκα ἤχθετο τοῖς πρασσομένοις, διὰ τὸ εὔπορον τῆς ἐλπίδος τοῦ παρὰ βασιλέως μισθοῦ ἡσύχαζεν· οἱ δὲ ξυνιστάντες τὴν ὀλιγαρχίαν, ἐπειδὴ τῷ πλήθει ἐκοίνωσαν, αὖθις κἀν σφίσιν αὐτοῖς καὶ τοῦ ἑταιρικοῦ τῷ πλέονι τὰ ἀπὸ τοῦ Ἀλκιβιάδου ἐσκόπουν. καὶ τοῖς μὲν ἄλλοις ἐφαίνετο εὔπορα καὶ πιστά, Φρυνίχῳ δὲ στρατηγῷ ἔτι ὄντι οὐδὲν ἤρεσκεν, ἀλλ’ ὅ τε Ἀλκιβιάδης, ὅπερ καὶ ἦν, οὐδὲν μᾶλλον ὀλιγαρχίας ἢ δημοκρατίας δεῖσθαι ἐδόκει αὐτῷ οὐδ’ ἄλλο τι σκοπεῖσθαι ἢ ὅτῳ τρόπῳ ἐκ τοῦ παρόντος κόσμου τὴν πόλιν μεταστήσας ὑπὸ τῶν ἑταίρων παρακληθεὶς κάτεισι, σφίσι δὲ περιοπτέον εἶναι τοῦτο μάλιστα, ὅπως μὴ στασιάσωσιν· [τῷ] βασιλεῖ τε οὐκ εὔπορον εἶναι καὶ Πελοποννησίων ἤδη ὁμοίως ἐν τῇ θαλάσσῃ ὄντων καὶ πόλεις ἐχόντων ἐν τῇ αὐτοῦ ἀρχῇ οὐ τὰς ἐλαχίστας, Ἀθηναίοις προσθέμενον, οἷς οὐ πιστεύει, πράγματα ἔχειν, ἐξὸν Πελοποννησίους, ὑφ’ ὧν κακὸν οὐδέν πω πέπονθε, φίλους ποιήσασθαι. τάς τε ξυμμαχίδας πόλεις, αἷς ὑπεσχῆσθαι δὴ σφᾶς ὀλιγαρχίαν, ὅτι δὴ καὶ αὐτοὶ οὐ δημοκρατήσονται, εὖ εἰδέναι ἔφη ὅτι οὐδὲν μᾶλλον σφίσιν οὔθ’ αἱ ἀφεστηκυῖαι προσχωρήσονται οὔθ’ αἱ ὑπάρχουσαι βεβαιότεραι ἔσονται· οὐ γὰρ βουλήσεσθαι αὐτοὺς μετ’ ὀλιγαρχίας ἢ δημοκρατίας δουλεύειν μᾶλλον ἢ μεθ’ ὁποτέρου ἂν τύχωσι τούτων ἐλευθέρους εἶναι· τούς τε καλοὺς κἀγαθοὺς ὀνομαζομένους οὐκ ἐλάσσω αὐτοὺς νομίζειν σφίσι πράγματα παρέξειν τοῦ δήμου, ποριστὰς ὄντας καὶ ἐσηγητὰς τῶν κακῶν τῷ δήμῳ, ἐξ ὧν τὰ πλείω αὐτοὺς ὠφελεῖσθαι· καὶ τὸ μὲν ἐπ’ ἐκείνοις εἶναι καὶ ἄκριτοι ἂν καὶ βιαιότερον ἀποθνῄσκειν, τὸν δὲ δῆμον σφῶν τε καταφυγὴν εἶναι καὶ ἐκείνων σωφρονιστήν. καὶ ταῦτα παρ’ αὐτῶν τῶν ἔργων ἐπισταμένας τὰς πόλεις σαφῶς αὐτὸς εἰδέναι ὅτι οὕτω νομίζουσιν. οὔκουν ἑαυτῷ γε τῶν ἀπ’ Ἀλκιβιάδου καὶ ἐν τῷ παρόντι πρασσομένων ἀρέσκειν οὐδέν.", "st": "8.48"}, {"sp": "N", "t": "οἱ δὲ ξυλλεγέντες τῶν ἐν τῇ ξυνωμοσίᾳ, ὥσπερ καὶ τὸ πρῶτον αὐτοῖς ἐδόκει, τά τε παρόντα ἐδέχοντο καὶ ἐς τὰς Ἀθήνας πρέσβεις Πείσανδρον καὶ ἄλλους παρεσκευάζοντο πέμπειν, ὅπως περί τε τῆς τοῦ Ἀλκιβιάδου καθόδου πράσσοιεν καὶ τῆς τοῦ ἐκεῖ δήμου καταλύσεως καὶ τὸν Τισσαφέρνην φίλον τοῖς Ἀθηναίοις ποιήσειαν.", "st": "8.49"}, {"sp": "N", "t": "γνοὺς δὲ ὁ Φρύνιχος ὅτι ἔσοιτο περὶ τῆς τοῦ Ἀλκιβιάδου καθόδου λόγος καὶ ὅτι Ἀθηναῖοι ἐνδέξονται αὐτήν, δείσας πρὸς τὴν ἐναντίωσιν τῶν ὑφ’ αὑτοῦ λεχθέντων μή, ἢν κατέλθῃ, ὡς κωλυτὴν ὄντα κακῶς δρᾷ, τρέπεται ἐπὶ τοιόνδε τι. πέμπει ὡς τὸν Ἀστύοχον τὸν Λακεδαιμονίων ναύαρχον ἔτι ὄντα τότε περὶ τὴν Μίλητον κρύφα ἐπιστείλας ὅτι Ἀλκιβιάδης αὐτῶν τὰ πράγματα φθείρει Τισσαφέρνην Ἀθηναίοις φίλον ποιῶν, καὶ τἆλλα πάντα σαφῶς ἐγγράψας· ξυγγνώμην δὲ εἶναι ἑαυτῷ περὶ ἀνδρὸς πολεμίου καὶ μετὰ τοῦ τῆς πόλεως ἀξυμφόρου κακόν τι βουλεύειν. ὁ δὲ Ἀστύοχος τὸν μὲν Ἀλκιβιάδην ἄλλως τε καὶ οὐκέτι ὁμοίως ἐς χεῖρας ἰόντα οὐδὲ διενοεῖτο τιμωρεῖσθαι, ἀνελθὼν δὲ παρ’ αὐτὸν ἐς Μαγνησίαν καὶ παρὰ Τισσαφέρνην ἅμα λέγει τε αὐτοῖς τὰ ἐπισταλέντα ἐκ τῆς Σάμου καὶ γίγνεται αὐτὸς μηνυτής, προσέθηκέ τε, ὡς ἐλέγετο, ἐπὶ ἰδίοις κέρδεσι Τισσαφέρνει ἑαυτὸν καὶ περὶ τούτων καὶ περὶ τῶν ἄλλων κοινοῦσθαι· διόπερ καὶ [περὶ] τῆς μισθοφορᾶς οὐκ ἐντελοῦς οὔσης μαλακωτέρως ἀνθήπτετο. ὁ δὲ Ἀλκιβιάδης εὐθὺς πέμπει κατὰ Φρυνίχου γράμματα ἐς τὴν Σάμον πρὸς τοὺς ἐν τέλει ὄντας οἷα δέδρακε, καὶ ἀξιῶν αὐτὸν ἀποθνῄσκειν. θορυβούμενος δὲ ὁ Φρύνιχος καὶ πάνυ ἐν τῷ μεγίστῳ κινδύνῳ ὢν διὰ τὸ μήνυμα ἀποστέλλει αὖθις πρὸς τὸν Ἀστύοχον, τά τε πρότερα μεμφόμενος ὅτι οὐ καλῶς ἐκρύφθη καὶ νῦν ὅτι ὅλον τὸ στράτευμα τὸ τῶν Ἀθηναίων ἑτοῖμος εἴη τὸ ἐν τῇ Σάμῳ παρασχεῖν αὐτοῖς διαφθεῖραι, γράψας καθ’ ἕκαστα, ἀτειχίστου οὔσης Σάμου, ᾧ ἂν τρόπῳ αὐτὰ πράξειε, καὶ ὅτι ἀνεπίφθονόν οἱ ἤδη εἴη περὶ τῆς ψυχῆς δι’ ἐκείνους κινδυνεύοντι καὶ τοῦτο καὶ ἄλλο πᾶν δρᾶσαι μᾶλλον ἢ ὑπὸ τῶν ἐχθίστων αὐτὸν διαφθαρῆναι. ὁ δὲ Ἀστύοχος μηνύει καὶ ταῦτα τῷ Ἀλκιβιάδῃ.", "st": "8.50"}, {"sp": "N", "t": "καὶ ὡς προῄσθετο αὐτὸν ὁ Φρύνιχος ἀδικοῦντα καὶ ὅσον οὐ παροῦσαν ἀπὸ τοῦ Ἀλκιβιάδου περὶ τούτων ἐπιστολήν, αὐτὸς προφθάσας τῷ στρατεύματι ἐξάγγελος γίγνεται ὡς οἱ πολέμιοι μέλλουσιν ἀτειχίστου οὔσης τῆς Σάμου καὶ ἅμα τῶν νεῶν οὐ πασῶν ἔνδον ὁρμουσῶν ἐπιθήσεσθαι τῷ στρατοπέδῳ, καὶ ταῦτα σαφῶς πεπυσμένος εἴη, καὶ χρῆναι τειχίζειν τε Σάμον ὡς τάχιστα καὶ τἆλλα ἐν φυλακῇ ἔχειν· ἐστρατήγει δὲ καὶ κύριος ἦν αὐτὸς πράσσων ταῦτα. καὶ οἱ μὲν τὸν τειχισμόν τε παρεσκευάζοντο καὶ ἐκ τοῦ τοιούτου, καὶ ὣς μέλλουσα, Σάμος θᾶσσον ἐτειχίσθη· αἱ δὲ παρὰ τοῦ Ἀλκιβιάδου ἐπιστολαὶ οὐ πολὺ ὕστερον ἧκον ὅτι προδίδοταί τε τὸ στράτευμα ὑπὸ Φρυνίχου καὶ οἱ πολέμιοι μέλλουσιν ἐπιθήσεσθαι. δόξας δὲ ὁ Ἀλκιβιάδης οὐ πιστὸς εἶναι, ἀλλὰ τὰ ἀπὸ τῶν πολεμίων προειδὼς τῷ Φρυνίχῳ ὡς ξυνειδότι κατ’ ἔχθραν ἀνατιθέναι, οὐδὲν ἔβλαψεν αὐτόν, ἀλλὰ καὶ ξυνεμαρτύρησε μᾶλλον ταὐτὰ ἐσαγγείλας.", "st": "8.51"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο Ἀλκιβιάδης μὲν Τισσαφέρνην παρεσκεύαζε καὶ ἀνέπειθεν ὅπως φίλος ἔσται τοῖς Ἀθηναίοις, δεδιότα μὲν τοὺς Πελοποννησίους, ὅτι πλέοσι ναυσὶ τῶν Ἀθηναίων παρῆσαν, βουλόμενον δὲ ὅμως, εἰ δύναιτό πως, πεισθῆναι, ἄλλως τε καὶ ἐπειδὴ τὴν ἐν τῇ Κνίδῳ διαφορὰν περὶ τῶν Θηριμένους σπονδῶν ᾔσθετο τῶν Πελοποννησίων (ἤδη γὰρ κατὰ τοῦτον τὸν καιρὸν ἐν τῇ Ῥόδῳ ὄντων αὐτῶν ἐγεγένητο)· ἐν ᾗ τὸν τοῦ Ἀλκιβιάδου λόγον πρότερον εἰρημένον περὶ τοῦ ἐλευθεροῦν τοὺς Λακεδαιμονίους τὰς ἁπάσας πόλεις ἐπηλήθευσεν ὁ Λίχας, οὐ φάσκων ἀνεκτὸν εἶναι ξυγκεῖσθαι κρατεῖν βασιλέα τῶν πόλεων ὧν ποτὲ καὶ πρότερον ἢ αὐτὸς ἢ οἱ πατέρες ἦρχον. καὶ ὁ μὲν Ἀλκιβιάδης, ἅτε περὶ μεγάλων ἀγωνιζόμενος, προθύμως τὸν Τισσαφέρνην θεραπεύων προσέκειτο·", "st": "8.52"}, {"sp": "N", "t": "οἱ δὲ μετὰ τοῦ Πεισάνδρου πρέσβεις τῶν Ἀθηναίων ἀποσταλέντες ἐκ τῆς Σάμου ἀφικόμενοι ἐς τὰς Ἀθήνας λόγους ἐποιοῦντο ἐν τῷ δήμῳ κεφαλαιοῦντες ἐκ πολλῶν, μάλιστα δὲ ὡς ἐξείη αὐτοῖς Ἀλκιβιάδην καταγαγοῦσι καὶ μὴ τὸν αὐτὸν τρόπον δημοκρατουμένοις βασιλέα τε ξύμμαχον ἔχειν καὶ Πελοποννησίων περιγενέσθαι. ἀντιλεγόντων δὲ πολλῶν καὶ ἄλλων περὶ τῆς δημοκρατίας καὶ τῶν Ἀλκιβιάδου ἅμα ἐχθρῶν διαβοώντων ὡς δεινὸν εἴη εἰ τοὺς νόμους βιασάμενος κάτεισι, καὶ Εὐμολπιδῶν καὶ Κηρύκων περὶ τῶν μυστικῶν δι’ ἅπερ ἔφυγε μαρτυρομένων καὶ ἐπιθειαζόντων μὴ κατάγειν, ὁ Πείσανδρος παρελθὼν πρὸς πολλὴν ἀντιλογίαν καὶ σχετλιασμὸν ἠρώτα ἕνα ἕκαστον παράγων τῶν ἀντιλεγόντων, εἴ τινα ἐλπίδα ἔχει σωτηρίας τῇ πόλει, Πελοποννησίων ναῦς τε οὐκ ἐλάσσους σφῶν ἐν τῇ θαλάσσῃ ἀντιπρῴρους ἐχόντων καὶ πόλεις ξυμμαχίδας πλείους, βασιλέως τε αὐτοῖς καὶ Τισσαφέρνους χρήματα παρεχόντων, σφίσι τε οὐκέτι ὄντων, εἰ μή τις πείσει βασιλέα μεταστῆναι παρὰ σφᾶς. ὁπότε δὲ μὴ φαῖεν ἐρωτώμενοι, ἐνταῦθα δὴ σαφῶς ἔλεγεν αὐτοῖς ὅτι ‘τοῦτο τοίνυν οὐκ ἔστιν ἡμῖν γενέσθαι, εἰ μὴ πολιτεύσομεν τε σωφρονέστερον καὶ ἐς ὀλίγους μᾶλλον τὰς ἀρχὰς ποιήσομεν, ἵνα πιστεύῃ ἡμῖν βασιλεύς, καὶ μὴ περὶ πολιτείας τὸ πλέον βουλεύσομεν ἐν τῷ παρόντι ἢ περὶ σωτηρίας (ὕστερον γὰρ ἐξέσται ἡμῖν καὶ μεταθέσθαι, ἢν μή τι ἀρέσκῃ), Ἀλκιβιάδην τε κατάξομεν, ὃς μόνος τῶν νῦν οἷός τε τοῦτο κατεργάσασθαι.’", "st": "8.53"}, {"sp": "N", "t": "ὁ δὲ δῆμος τὸ μὲν πρῶτον ἀκούων χαλεπῶς ἔφερε τὸ περὶ τῆς ὀλιγαρχίας· σαφῶς δὲ διδασκόμενος ὑπὸ τοῦ Πεισάνδρου μὴ εἶναι ἄλλην σωτηρίαν, δείσας καὶ ἅμα ἐπελπίζων ὡς καὶ μεταβαλεῖται, ἐνέδωκεν. καὶ ἐψηφίσαντο πλεύσαντα τὸν Πείσανδρον καὶ δέκα ἄνδρας μετ’ αὐτοῦ πράσσειν ὅπῃ [ἂν] αὐτοῖς δοκοίη ἄριστα ἕξειν τά τε πρὸς τὸν Τισσαφέρνην καὶ τὸν Ἀλκιβιάδην. ἅμα τε διαβαλόντος καὶ Φρύνιχον τοῦ Πεισάνδρου παρέλυσεν ὁ δῆμος τῆς ἀρχῆς καὶ τὸν ξυνάρχοντα Σκιρωνίδην, ἀντέπεμψαν δὲ στρατηγοὺς ἐπὶ τὰς ναῦς Διομέδοντα καὶ Λέοντα. τὸν δὲ Φρύνιχον ὁ Πείσανδρος φάσκων Ἴασον προδοῦναι καὶ Ἀμόργην διέβαλεν, οὐ νομίζων ἐπιτήδειον εἶναι τοῖς πρὸς τὸν Ἀλκιβιάδην πρασσομένοις. καὶ ὁ μὲν Πείσανδρος τάς τε ξυνωμοσίας, αἵπερ ἐτύγχανον πρότερον ἐν τῇ πόλει οὖσαι ἐπὶ δίκαις καὶ ἀρχαῖς, ἁπάσας ἐπελθὼν καὶ παρακελευσάμενος ὅπως ξυστραφέντες καὶ κοινῇ βουλευσάμενοι καταλύσουσι τὸν δῆμον, καὶ τἆλλα παρασκευάσας ἐπὶ τοῖς παροῦσιν ὥστε μηκέτι διαμέλλεσθαι, αὐτὸς μετὰ τῶν δέκα ἀνδρῶν τὸν πλοῦν ὡς τὸν Τισσαφέρνην ποιεῖται.", "st": "8.54"}, {"sp": "N", "t": "ὁ δὲ Λέων καὶ ὁ Διομέδων ἐν τῷ αὐτῷ χειμῶνι ἀφιγμένοι ἤδη ἐπὶ τὰς τῶν Ἀθηναίων ναῦς ἐπίπλουν τῇ Ῥόδῳ ἐποιήσαντο. καὶ τὰς μὲν ναῦς καταλαμβάνουσιν ἀνειλκυσμένας τῶν Πελοποννησίων, ἐς δὲ τὴν γῆν ἀπόβασίν τινα ποιησάμενοι καὶ τοὺς προσβοηθήσαντας Ῥοδίων νικήσαντες μάχῃ ἀπεχώρησαν ἐς τὴν Χάλκην, καὶ τὸν πόλεμον ἐντεῦθεν μᾶλλον ⟨ἢ⟩ ἐκ τῆς Κῶ ἐποιοῦντο· εὐφυλακτότερα γὰρ αὐτοῖς ἐγίγνετο, εἴ ποι ἀπαίροι τὸ τῶν Πελοποννησίων ναυτικόν.", "st": "8.55"}, {"sp": "N", "t": "ἦλθε δ’ ἐς τὴν Ῥόδον καὶ Ξενοφαντίδας Λάκων παρὰ Πεδαρίτου ἐκ Χίου, λέγων ὅτι τὸ τεῖχος τῶν Ἀθηναίων ἤδη ἐπιτετέλεσται, καὶ εἰ μὴ βοηθήσουσι πάσαις ταῖς ναυσίν, ἀπολεῖται τὰ ἐν Χίῳ πράγματα. οἱ δὲ διενοοῦντο βοηθήσειν. ἐν τούτῳ δὲ ὁ Πεδάριτος αὐτός τε καὶ τὸ περὶ αὑτὸν ἐπικουρικὸν ἔχων καὶ τοὺς Χίους πανστρατιᾷ προσβαλὼν τῶν Ἀθηναίων τῷ περὶ τὰς ναῦς ἐρύματι αἱρεῖ τέ τι αὐτοῦ καὶ νεῶν τινῶν ἀνειλκυσμένων ἐκράτησεν· ἐπεκβοηθησάντων δὲ τῶν Ἀθηναίων καὶ τρεψαμένων τοὺς Χίους πρώτους νικᾶται καὶ τὸ ἄλλο τὸ περὶ τὸν Πεδάριτον, καὶ αὐτὸς ἀποθνῄσκει καὶ τῶν Χίων πολλοὶ καὶ ὅπλα ἐλήφθη πολλά.", "st": "8.55"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα οἱ μὲν Χῖοι ἔκ τε γῆς καὶ θαλάσσης ἔτι μᾶλλον ἢ πρότερον ἐπολιορκοῦντο καὶ ὁ λιμὸς αὐτόθι ἦν μέγας· οἱ δὲ περὶ τὸν Πείσανδρον Ἀθηναίων πρέσβεις ἀφικόμενοι ὡς τὸν Τισσαφέρνην λόγους ποιοῦνται περὶ τῆς ὁμολογίας. Ἀλκιβιάδης δέ (οὐ γὰρ αὐτῷ πάνυ τὰ ἀπὸ Τισσαφέρνους βέβαια ἦν, φοβουμένου τοὺς Πελοποννησίους μᾶλλον καὶ ἔτι βουλομένου, καθάπερ καὶ ὑπ’ ἐκείνου ἐδιδάσκετο, τρίβειν ἀμφοτέρους) τρέπεται ἐπὶ τοιόνδε εἶδος ὥστε τὸν Τισσαφέρνην ὡς μέγιστα αἰτοῦντα παρὰ τῶν Ἀθηναίων μὴ ξυμβῆναι. δοκεῖ δέ μοι καὶ ὁ Τισσαφέρνης τὸ αὐτὸ βουληθῆναι, αὐτὸς μὲν διὰ τὸ δέος, ὁ δὲ Ἀλκιβιάδης, ἐπειδὴ ἑώρα ἐκεῖνον καὶ ὣς οὐ ξυμβησείοντα, δοκεῖν τοῖς Ἀθηναίοις ἐβούλετο μὴ ἀδύνατος εἶναι πεῖσαι, ἀλλ’ ὡς πεπεισμένῳ Τισσαφέρνει καὶ βουλομένῳ προσχωρῆσαι τοὺς Ἀθηναίους μὴ ἱκανὰ διδόναι. ᾔτει γὰρ τοσαῦτα ὑπερβάλλων ὁ Ἀλκιβιάδης, λέγων αὐτὸς ὑπὲρ παρόντος τοῦ Τισσαφέρνους, ὥστε τὸ τῶν Ἀθηναίων, καίπερ ἐπὶ πολὺ ὅτι αἰτοίη ξυγχωρούντων, ὅμως αἴτιον γενέσθαι· Ἰωνίαν τε γὰρ πᾶσαν ἠξίου δίδοσθαι καὶ αὖθις νήσους τε τὰς ἐπικειμένας καὶ ἄλλα, οἷς οὐκ ἐναντιουμένων τῶν Ἀθηναίων τέλος ἐν τῇ τρίτῃ ἤδη ξυνόδῳ, δείσας μὴ πάνυ φωραθῇ ἀδύνατος ὤν, ναῦς ἠξίου ἐᾶν βασιλέα ποιεῖσθαι καὶ παραπλεῖν τὴν ἑαυτοῦ γῆν ὅπῃ ἂν καὶ ὅσαις ἂν βούληται. ἐνταῦθα δὴ οὐκέτι … ἀλλ’ ἄπορα νομίσαντες οἱ Ἀθηναῖοι καὶ ὑπὸ τοῦ Ἀλκιβιάδου ἐξηπατῆσθαι, δι’ ὀργῆς ἀπελθόντες κομίζονται ἐς τὴν Σάμον.", "st": "8.56"}, {"sp": "N", "t": "Τισσαφέρνης δὲ εὐθὺς μετὰ ταῦτα καὶ ἐν τῷ αὐτῷ χειμῶνι παρέρχεται ἐς τὴν Καῦνον, βουλόμενος τοὺς Πελοποννησίους πάλιν τε κομίσαι ἐς τὴν Μίλητον καὶ ξυνθήκας ἔτι ἄλλας ποιησάμενος, ἃς ἂν δύνηται, τροφήν τε παρέχειν καὶ μὴ παντάπασιν ἐκπεπολεμῶσθαι, δεδιὼς μή, ἢν ἀπορῶσι πολλαῖς ναυσὶ τῆς τροφῆς, ἢ τοῖς Ἀθηναίοις ἀναγκασθέντες ναυμαχεῖν ἡσσηθῶσιν ἢ κενωθεισῶν τῶν νεῶν ἄνευ ἑαυτοῦ γένηται τοῖς Ἀθηναίοις ἃ βούλονται. ἔτι δὲ ἐφοβεῖτο μάλιστα μὴ τῆς τροφῆς ζητήσει πορθήσωσι τὴν ἤπειρον. πάντων οὖν τούτων λογισμῷ καὶ προνοίᾳ, ὥσπερ ἐβούλετο ἐπανισοῦν τοὺς Ἕλληνας πρὸς ἀλλήλους, μεταπεμψάμενος οὖν τοὺς Πελοποννησίους τροφήν τε αὐτοῖς δίδωσι καὶ σπονδὰς τρίτας τάσδε σπένδεται.", "st": "8.57"}, {"sp": "N", "t": "‘τρίτῳ καὶ δεκάτῳ ἔτει Δαρείου βασιλεύοντος, ἐφορεύοντος δὲ Ἀλεξιππίδα ἐν Λακεδαίμονι, ξυνθῆκαι ἐγένοντο ἐν Μαιάνδρου πεδίῳ Λακεδαιμονίων καὶ τῶν ξυμμάχων πρὸς Τισσαφέρνην καὶ Ἱεραμένη καὶ τοὺς Φαρνάκου παῖδας περὶ τῶν βασιλέως πραγμάτων καὶ Λακεδαιμονίων καὶ τῶν ξυμμάχων. χώραν τὴν βασιλέως, ὅση τῆς Ἀσίας ἐστί, βασιλέως εἶναι· καὶ περὶ τῆς χώρας τῆς ἑαυτοῦ βουλευέτω βασιλεὺς ὅπως βούλεται. Λακεδαιμονίους δὲ καὶ τοὺς ξυμμάχους μὴ ἰέναι ἐπὶ χώραν τὴν βασιλέως ἐπὶ κακῷ μηδενί, μηδὲ βασιλέα ἐπὶ τὴν Λακεδαιμονίων χώραν μηδὲ τῶν ξυμμάχων ἐπὶ κακῷ μηδενί. ἢν δέ τις Λακεδαιμονίων ἢ τῶν ξυμμάχων ἐπὶ κακῷ ἴῃ ἐπὶ τὴν βασιλέως χώραν, Λακεδαιμονίους καὶ τοὺς ξυμμάχους κωλύειν· καὶ ἤν τις ἐκ τῆς βασιλέως ἴῃ ἐπὶ κακῷ ἐπὶ Λακεδαιμονίους ἢ τοὺς ξυμμάχους, βασιλεὺς κωλυέτω. τροφὴν δὲ ταῖς ναυσὶ ταῖς νῦν παρούσαις Τισσαφέρνην παρέχειν κατὰ τὰ ξυγκείμενα μέχρι ἂν αἱ νῆες αἱ βασιλέως ἔλθωσιν· Λακεδαιμονίους δὲ καὶ τοὺς ξυμμάχους, ἐπὴν αἱ βασιλέως νῆες ἀφίκωνται, τὰς ἑαυτῶν ναῦς, ἢν βούλωνται, τρέφειν ἐφ’ ἑαυτοῖς εἶναι. ἢν δὲ παρὰ Τισσαφέρνους λαμβάνειν ἐθέλωσι τὴν τροφήν, Τισσαφέρνην παρέχειν, Λακεδαιμονίους δὲ καὶ τοὺς ξυμμάχους τελευτῶντος τοῦ πολέμου τὰ χρήματα Τισσαφέρνει ἀποδοῦναι ὁπόσα ἂν λάβωσιν. ἐπὴν δὲ αἱ βασιλέως νῆες ἀφίκωνται, αἵ τε Λακεδαιμονίων νῆες καὶ αἱ τῶν ξυμμάχων καὶ αἱ βασιλέως κοινῇ τὸν πόλεμον πολεμούντων καθ’ ὅτι ἂν Τισσαφέρνει δοκῇ καὶ Λακεδαιμονίοις καὶ τοῖς ξυμμάχοις. ἢν δὲ καταλύειν βούλωνται πρὸς Ἀθηναίους, ἐν ὁμοίῳ καταλύεσθαι.’", "st": "8.58"}, {"sp": "N", "t": "αἱ μὲν σπονδαὶ αὗται ἐγένοντο, καὶ μετὰ ταῦτα παρεσκευάζετο Τισσαφέρνης τάς τε Φοινίσσας ναῦς ἄξων, ὥσπερ εἴρητο, καὶ τἆλλα ὅσαπερ ὑπέσχετο, καὶ ἐβούλετο παρασκευαζόμενος γοῦν δῆλος εἶναι·", "st": "8.59"}, {"sp": "N", "t": "Βοιωτοὶ δὲ τελευτῶντος ἤδη τοῦ χειμῶνος Ὠρωπὸν εἷλον προδοσίᾳ, Ἀθηναίων ἐμφρουρούντων. ξυνέπραξαν δὲ Ἐρετριῶν τε ἄνδρες καὶ αὐτῶν Ὠρωπίων, ἐπιβουλεύοντες ἀπόστασιν τῆς Εὐβοίας· ἐπὶ γὰρ τῇ Ἐρετρίᾳ τὸ χωρίον ὂν ἀδύνατα ἦν Ἀθηναίων ἐχόντων μὴ οὐ μεγάλα βλάπτειν καὶ Ἐρέτριαν καὶ τὴν ἄλλην Εὔβοιαν. ἔχοντες οὖν ἤδη τὸν Ὠρωπὸν ἀφικνοῦνται ἐς Ῥόδον οἱ Ἐρετριῆς, ἐπικαλούμενοι ἐς τὴν Εὔβοιαν τοὺς Πελοποννησίους. οἱ δὲ πρὸς τὴν τῆς Χίου κακουμένης βοήθειαν μᾶλλον ὥρμηντο, καὶ ἄραντες πάσαις ταῖς ναυσὶν ἐκ τῆς Ῥόδου ἔπλεον. καὶ γενόμενοι περὶ τὸ Τριόπιον καθορῶσι τὰς τῶν Ἀθηναίων ναῦς πελαγίας ἀπὸ τῆς Χάλκης πλεούσας· καὶ ὡς οὐδέτεροι ἀλλήλοις ἐπέπλεον, ἀφικνοῦνται οἱ μὲν ἐς τὴν Σάμον, οἱ δὲ ἐς τὴν Μίλητον, καὶ ἑώρων οὐκέτι ἄνευ ναυμαχίας οἷόν τε εἶναι ἐς τὴν Χίον βοηθῆσαι. καὶ ὁ χειμὼν ἐτελεύτα οὗτος, καὶ εἰκοστὸν ἔτος τῷ πολέμῳ ἐτελεύτα τῷδε ὃν Θουκυδίδης ξυνέγραψεν.", "st": "8.60"}, {"sp": "N", "t": "τοῦ δ’ ἐπιγιγνομένου θέρους ἅμα τῷ ἦρι εὐθὺς ἀρχομένῳ Δερκυλίδας τε ἀνὴρ Σπαρτιάτης στρατιὰν ἔχων οὐ πολλὴν παρεπέμφθη πεζῇ ἐφ’ Ἑλλησπόντου Ἄβυδον ἀποστήσων (εἰσὶ δὲ Μιλησίων ἄποικοι), καὶ οἱ Χῖοι, ἐν ὅσῳ αὐτοῖς ὁ Ἀστύοχος ἠπόρει ὅπως βοηθήσοι, ναυμαχῆσαι πιεζόμενοι τῇ πολιορκίᾳ ἠναγκάσθησαν. ἔτυχον δὲ ἔτι ἐν Ῥόδῳ ὄντος Ἀστυόχου ἐκ τῆς Μιλήτου Λέοντά τε ἄνδρα Σπαρτιάτην, ὃς Ἀντισθένει ἐπιβάτης ξυνεξῆλθε, τοῦτον κεκομισμένοι μετὰ τὸν Πεδαρίτου θάνατον ἄρχοντα καὶ ναῦς δώδεκα, αἳ ἔτυχον φύλακες Μιλήτου οὖσαι, ὧν ἦσαν Θούριαι πέντε καὶ Συρακόσιαι τέσσαρες καὶ μία Ἀναιῖτις καὶ μία Μιλησία καὶ Λέοντος μία. ἐπεξελθόντων δὲ τῶν Χίων πανδημεὶ καὶ καταλαβόντων τι ἐρυμνὸν χωρίον καὶ τῶν νεῶν αὐτοῖς ἅμα ἓξ καὶ τριάκοντα ἐπὶ τὰς τῶν Ἀθηναίων δύο καὶ τριάκοντα ἀναγαγομένων ἐναυμάχησαν· καὶ καρτερᾶς γενομένης ναυμαχίας οὐκ ἔλασσον ἔχοντες ἐν τῷ ἔργῳ οἱ Χῖοι καὶ οἱ ξύμμαχοι (ἤδη γὰρ καὶ ὀψὲ ἦν) ἀνεχώρησαν ἐς τὴν πόλιν.", "st": "8.61"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο εὐθὺς τοῦ Δερκυλίδου πεζῇ ἐκ τῆς Μιλήτου παρεξελθόντος Ἄβυδος ἐν τῷ Ἑλλησπόντῳ ἀφίσταται πρὸς Δερκυλίδαν καὶ Φαρνάβαζον, καὶ Λάμψακος δυοῖν ἡμέραιν ὕστερον. Στρομβιχίδης δὲ ἐκ τῆς Χίου πυθόμενος κατὰ τάχος βοηθήσας ναυσὶν Ἀθηναίων τέσσαρσι καὶ εἴκοσιν, ὧν καὶ στρατιώτιδες ἦσαν ὁπλίτας ἄγουσαι, ἐπεξελθόντων τῶν Λαμψακηνῶν μάχῃ κρατήσας καὶ αὐτοβοεὶ Λάμψακον ἀτείχιστον οὖσαν ἑλών, καὶ σκεύη μὲν καὶ ἀνδράποδα ἁρπαγὴν ποιησάμενος, τοὺς δ’ ἐλευθέρους πάλιν κατοικίσας, ἐπ’ Ἄβυδον ἦλθεν. καὶ ὡς οὔτε προσεχώρουν οὔτε προσβάλλων ἐδύνατο ἑλεῖν, ἐς τὸ ἀντιπέρας τῆς Ἀβύδου ἀποπλεύσας Σηστὸν πόλιν τῆς Χερσονήσου, ἥν ποτε Μῆδοι εἶχον, καθίστατο φρούριον καὶ φυλακὴν τοῦ παντὸς Ἑλλησπόντου.", "st": "8.62"}, {"sp": "N", "t": "ἐν τούτῳ δὲ οἱ Χῖοί τε θαλασσοκράτορες μᾶλλον ἐγένοντο καὶ οἱ ἐν τῇ Μιλήτῳ καὶ ὁ Ἀστύοχος πυθόμενος τὰ περὶ τῆς ναυμαχίας καὶ τὸν Στρομβιχίδην καὶ τὰς ναῦς ἀπεληλυθότα ἐθάρσησεν. καὶ παραπλεύσας δυοῖν νεοῖν Ἀστύοχος ἐς Χίον κομίζει αὐτόθεν τὰς ναῦς καὶ ξυμπάσαις ἤδη ἐπίπλουν ποιεῖται ἐπὶ τὴν Σάμον· καὶ ὡς αὐτῷ διὰ τὸ ἀλλήλοις ὑπόπτως ἔχειν οὐκ ἀντανήγοντο, ἀπέπλευσε πάλιν ἐς τὴν Μίλητον.", "st": "8.63"}, {"sp": "N", "t": "ὑπὸ γὰρ τοῦτον τὸν χρόνον καὶ ἔτι πρότερον ἡ ἐν ταῖς Ἀθήναις δημοκρατία κατελέλυτο. ἐπειδὴ γὰρ οἱ περὶ τὸν Πείσανδρον πρέσβεις παρὰ τοῦ Τισσαφέρνους ἐς τὴν Σάμον ἦλθον, τά τε ἐν αὐτῷ τῷ στρατεύματι ἔτι βεβαιότερον κατέλαβον καὶ αὐτῶν τῶν Σαμίων προυτρέψαντο τοὺς δυνατωτάτους ὥστε πειρᾶσθαι μετὰ σφῶν ὀλιγαρχηθῆναι, καίπερ ἐπαναστάντας αὐτοὺς ἀλλήλοις ἵνα μὴ ὀλιγαρχῶνται· καὶ ἐν σφίσιν αὐτοῖς ἅμα οἱ ἐν τῇ Σάμῳ τῶν Ἀθηναίων κοινολογούμενοι ἐσκέψαντο Ἀλκιβιάδην μέν, ἐπειδήπερ οὐ βούλεται, ἐᾶν (καὶ γὰρ οὐκ ἐπιτήδειον αὐτὸν εἶναι ἐς ὀλιγαρχίαν ἐλθεῖν), αὐτοὺς δὲ ἐπὶ σφῶν αὐτῶν, ὡς ἤδη καὶ κινδυνεύοντας, ὁρᾶν ὅτῳ τρόπῳ μὴ ἀνεθήσεται τὰ πράγματα, καὶ τὰ τοῦ πολέμου ἅμα ἀντέχειν καὶ ἐσφέρειν αὐτοὺς ἐκ τῶν ἰδίων οἴκων προθύμως χρήματα καὶ ἤν τι ἄλλο δέῃ, ὡς οὐκέτι ἄλλοις ἢ σφίσιν αὐτοῖς ταλαιπωροῦντας.", "st": "8.63"}, {"sp": "N", "t": "παρακελευσάμενοι οὖν τοιαῦτα τὸν μὲν Πείσανδρον εὐθὺς τότε καὶ τῶν πρέσβεων τοὺς ἡμίσεις ἀπέστελλον ἐπ’ οἴκου πράξοντας τἀκεῖ, καὶ εἴρητο αὐτοῖς τῶν ὑπηκόων πόλεων αἷς ἂν προσσχῶσιν ὀλιγαρχίαν καθιστάναι· τοὺς δ’ ἡμίσεις ἐς τἆλλα τὰ ὑπήκοα χωρία ἄλλους ἄλλῃ διέπεμπον, καὶ Διειτρέφη ὄντα περὶ Χίον, ᾑρημένον δὲ ἐς τὰ ἐπὶ Θρᾴκης ἄρχειν, ἀπέστελλον ἐπὶ τὴν ἀρχήν. καὶ ἀφικόμενος ἐς τὴν Θάσον τὸν δῆμον κατέλυσεν. καὶ ἀπελθόντος αὐτοῦ οἱ Θάσιοι δευτέρῳ μηνὶ μάλιστα τὴν πόλιν ἐτείχιζον, ὡς τῆς μὲν μετ’ Ἀθηναίων ἀριστοκρατίας οὐδὲν ἔτι προσδεόμενοι, τὴν δ’ ἀπὸ Λακεδαιμονίων ἐλευθερίαν ὁσημέραι προσδεχόμενοι· καὶ γὰρ καὶ φυγὴ αὐτῶν ἔξω ἦν ὑπὸ τῶν Ἀθηναίων παρὰ τοῖς Πελοποννησίοις, καὶ αὕτη μετὰ τῶν ἐν τῇ πόλει ἐπιτηδείων κατὰ κράτος ἔπρασσε ναῦς τε κομίσαι καὶ τὴν Θάσον ἀποστῆσαι. ξυνέβη οὖν αὐτοῖς μάλιστα ἃ ἐβούλοντο, τὴν πόλιν τε ἀκινδύνως ὀρθοῦσθαι καὶ τὸν ἐναντιωσόμενον δῆμον καταλελύσθαι. περὶ μὲν οὖν τὴν Θάσον τἀναντία τοῖς τὴν ὀλιγαρχίαν καθιστᾶσι τῶν Ἀθηναίων ἐγένετο, δοκεῖν δέ μοι καὶ ἐν ἄλλοις πολλοῖς τῶν ὑπηκόων· σωφροσύνην γὰρ λαβοῦσαι αἱ πόλεις καὶ ἄδειαν τῶν πρασσομένων ἐχώρησαν ἐπὶ τὴν ἄντικρυς ἐλευθερίαν τῆς ἀπὸ τῶν Ἀθηναίων ὑπούλου εὐνομίας οὐ προτιμήσαντες.", "st": "8.64"}, {"sp": "N", "t": "οἱ δὲ ἀμφὶ τὸν Πείσανδρον παραπλέοντές τε, ὥσπερ ἐδέδοκτο, τοὺς δήμους ἐν ταῖς πόλεσι κατέλυον, καὶ ἅμα ἔστιν ἀφ’ ὧν χωρίων καὶ ὁπλίτας ἔχοντες σφίσιν αὐτοῖς ξυμμάχους ἦλθον ἐς τὰς Ἀθήνας. καὶ καταλαμβάνουσι τὰ πλεῖστα τοῖς ἑταίροις προειργασμένα. καὶ γὰρ Ἀνδροκλέα τέ τινα τοῦ δήμου μάλιστα προεστῶτα ξυστάντες τινὲς τῶν νεωτέρων κρύφα ἀποκτείνουσιν, ὅσπερ καὶ τὸν Ἀλκιβιάδην οὐχ ἥκιστα ἐξήλασε, καὶ αὐτὸν κατ’ ἀμφότερα, τῆς τε δημαγωγίας ἕνεκα καὶ οἰόμενοι τῷ Ἀλκιβιάδῃ ὡς κατιόντι καὶ τὸν Τισσαφέρνην φίλον ποιήσοντι χαριεῖσθαι, μᾶλλόν τι διέφθειραν· καὶ ἄλλους τινὰς ἀνεπιτηδείους τῷ αὐτῷ τρόπῳ κρύφα ἀνήλωσαν. λόγος τε ἐκ τοῦ φανεροῦ προείργαστο αὐτοῖς ὡς οὔτε μισθοφορητέον εἴη ἄλλους ἢ τοὺς στρατευομένους οὔτε μεθεκτέον τῶν πραγμάτων πλέοσιν ἢ πεντακισχιλίοις, καὶ τούτοις οἳ ἂν μάλιστα τοῖς τε χρήμασι καὶ τοῖς σώμασιν ὠφελεῖν οἷοί τε ὦσιν.", "st": "8.65"}, {"sp": "N", "t": "ἦν δὲ τοῦτο εὐπρεπὲς πρὸς τοὺς πλείους, ἐπεὶ ἕξειν γε τὴν πόλιν οἵπερ καὶ μεθίστασαν ἔμελλον. δῆμος μέντοι ὅμως ἔτι καὶ βουλὴ ἡ ἀπὸ τοῦ κυάμου ξυνελέγετο· ἐβούλευον δὲ οὐδὲν ὅτι μὴ τοῖς ξυνεστῶσι δοκοίη, ἀλλὰ καὶ οἱ λέγοντες ἐκ τούτων ἦσαν καὶ τὰ ῥηθησόμενα πρότερον αὐτοῖς προύσκεπτο. ἀντέλεγέ τε οὐδεὶς ἔτι τῶν ἄλλων, δεδιὼς καὶ ὁρῶν πολὺ τὸ ξυνεστηκός· εἰ δέ τις καὶ ἀντείποι, εὐθὺς ἐκ τρόπου τινὸς ἐπιτηδείου ἐτεθνήκει, καὶ τῶν δρασάντων οὔτε ζήτησις οὔτ’ εἰ ὑποπτεύοιντο δικαίωσις ἐγίγνετο, ἀλλ’ ἡσυχίαν εἶχεν ὁ δῆμος καὶ κατάπληξιν τοιαύτην ὥστε κέρδος ὁ μὴ πάσχων τι βίαιον, εἰ καὶ σιγῴη, ἐνόμιζεν. καὶ τὸ ξυνεστηκὸς πολὺ πλέον ἡγούμενοι εἶναι ἢ ὅσον ἐτύγχανεν ὂν ἡσσῶντο ταῖς γνώμαις, καὶ ἐξευρεῖν αὐτὸ ἀδύνατοι ὄντες διὰ τὸ μέγεθος τῆς πόλεως καὶ διὰ τὴν ἀλλήλων ἀγνωσίαν οὐκ εἶχον [αὐτοὶ ἐξευρεῖν]. κατὰ δὲ ταὐτὸ τοῦτο καὶ προσολοφύρασθαί τινι ἀγανακτήσαντα, ὥστε ἀμύνασθαι ἐπιβουλεύσαντα, ἀδύνατον ἦν· ἢ γὰρ ἀγνῶτα ἂν ηὗρεν ᾧ ἐρεῖ ἢ γνώριμον ἄπιστον. ἀλλήλοις γὰρ ἅπαντες ὑπόπτως προσῇσαν οἱ τοῦ δήμου, ὡς μετέχοντά τινα τῶν γιγνομένων. ἐνῆσαν γὰρ καὶ οὓς οὐκ ἄν ποτέ τις ᾤετο ἐς ὀλιγαρχίαν τραπέσθαι· καὶ τὸ ἄπιστον οὗτοι μέγιστον πρὸς τοὺς πολλοὺς ἐποίησαν καὶ πλεῖστα ἐς τὴν τῶν ὀλίγων ἀσφάλειαν ὠφέλησαν, βέβαιον τὴν ἀπιστίαν τῷ δήμῳ πρὸς ἑαυτὸν καταστήσαντες.", "st": "8.66"}, {"sp": "N", "t": "ἐν τούτῳ οὖν τῷ καιρῷ οἱ περὶ τὸν Πείσανδρον ἐλθόντες εὐθὺς τῶν λοιπῶν εἴχοντο. καὶ πρῶτον μὲν τὸν δῆμον ξυλλέξαντες εἶπον γνώμην δέκα ἄνδρας ἑλέσθαι ξυγγραφέας αὐτοκράτορας, τούτους δὲ ξυγγράψαντας γνώμην ἐσενεγκεῖν ἐς τὸν δῆμον ἐς ἡμέραν ῥητὴν καθ’ ὅτι ἄριστα ἡ πόλις οἰκήσεται· ἔπειτα ἐπειδὴ ἡ ἡμέρα ἐφῆκε, ξυνέκλῃσαν τὴν ἐκκλησίαν ἐς τὸν Κολωνόν (ἔστι δὲ ἱερὸν Ποσειδῶνος ἔξω πόλεως ἀπέχον σταδίους μάλιστα δέκα), καὶ ἐσήνεγκαν οἱ ξυγγραφῆς ἄλλο μὲν οὐδέν, αὐτὸ δὲ τοῦτο, ἐξεῖναι μὲν Ἀθηναίων ἀνατεὶ εἰπεῖν γνώμην ἣν ἄν τις βούληται· ἢν δέ τις τὸν εἰπόντα ἢ γράψηται παρανόμων ἢ ἄλλῳ τῳ τρόπῳ βλάψῃ, μεγάλας ζημίας ἐπέθεσαν. ἐνταῦθα δὴ λαμπρῶς ἐλέγετο ἤδη μήτε ἀρχὴν ἄρχειν μηδεμίαν ἔτι ἐκ τοῦ αὐτοῦ κόσμου μήτε μισθοφορεῖν προέδρους τε ἑλέσθαι πέντε ἄνδρας, τούτους δὲ ἑλέσθαι ἑκατὸν ἄνδρας, καὶ τῶν ἑκατὸν ἕκαστον πρὸς ἑαυτὸν τρεῖς· ἐλθόντας δὲ αὐτοὺς τετρακοσίους ὄντας ἐς τὸ βουλευτήριον ἄρχειν ὅπῃ ἂν ἄριστα γιγνώσκωσιν αὐτοκράτορας, καὶ τοὺς πεντακισχιλίους δὲ ξυλλέγειν ὁπόταν αὐτοῖς δοκῇ.", "st": "8.67"}, {"sp": "N", "t": "ἦν δὲ ὁ μὲν τὴν γνώμην ταύτην εἰπὼν Πείσανδρος, καὶ τἆλλα ἐκ τοῦ προφανοῦς προθυμότατα ξυγκαταλύσας τὸν δῆμον· ὁ μέντοι ἅπαν τὸ πρᾶγμα ξυνθεὶς ὅτῳ τρόπῳ κατέστη ἐς τοῦτο καὶ ἐκ πλείστου ἐπιμεληθεὶς Ἀντιφῶν ἦν ἀνὴρ Ἀθηναίων τῶν καθ’ ἑαυτὸν ἀρετῇ τε οὐδενὸς ὕστερος καὶ κράτιστος ἐνθυμηθῆναι γενόμενος καὶ ἃ γνοίη εἰπεῖν, καὶ ἐς μὲν δῆμον οὐ παριὼν οὐδ’ ἐς ἄλλον ἀγῶνα ἑκούσιος οὐδένα, ἀλλ’ ὑπόπτως τῷ πλήθει διὰ δόξαν δεινότητος διακείμενος, τοὺς μέντοι ἀγωνιζομένους καὶ ἐν δικαστηρίῳ καὶ ἐν δήμῳ πλεῖστα εἷς ἀνήρ, ὅστις ξυμβουλεύσαιτό τι, δυνάμενος ὠφελεῖν. καὶ αὐτός τε, ἐπειδὴ † μετέστη ἡ δημοκρατία καὶ ἐς ἀγῶνας κατέστη † τὰ τῶν τετρακοσίων ἐν ὑστέρῳ μεταπεσόντα ὑπὸ τοῦ δήμου ἐκακοῦτο †, ἄριστα φαίνεται τῶν μέχρι ἐμοῦ ὑπὲρ αὐτῶν τούτων αἰτιαθείς, ὡς ξυγκατέστησε, θανάτου δίκην ἀπολογησάμενος. παρέσχε δὲ καὶ ὁ Φρύνιχος ἑαυτὸν πάντων διαφερόντως προθυμότατον ἐς τὴν ὀλιγαρχίαν, δεδιὼς τὸν Ἀλκιβιάδην καὶ ἐπιστάμενος εἰδότα αὐτὸν ὅσα ἐν τῇ Σάμῳ πρὸς τὸν Ἀστύοχον ἔπραξε, νομίζων οὐκ ἄν ποτε αὐτὸν κατὰ τὸ εἰκὸς ὑπ’ ὀλιγαρχίας κατελθεῖν· πολύ τε πρὸς τὰ δεινά, ἐπειδήπερ ὑπέστη, φερεγγυώτατος ἐφάνη. καὶ Θηραμένης ὁ τοῦ Ἅγνωνος ἐν τοῖς ξυγκαταλύουσι τὸν δῆμον πρῶτος ἦν, ἀνὴρ οὔτε εἰπεῖν οὔτε γνῶναι ἀδύνατος. ὥστε ἀπ’ ἀνδρῶν πολλῶν καὶ ξυνετῶν πραχθὲν τὸ ἔργον οὐκ ἀπεικότως καίπερ μέγα ὂν προυχώρησεν· χαλεπὸν γὰρ ἦν τὸν Ἀθηναίων δῆμον ἐπ’ ἔτει ἑκατοστῷ μάλιστα ἐπειδὴ οἱ τύραννοι κατελύθησαν ἐλευθερίας παῦσαι, καὶ οὐ μόνον μὴ ὑπήκοον ὄντα, ἀλλὰ καὶ ὑπὲρ ἥμισυ τοῦ χρόνου τούτου αὐτὸν ἄλλων ἄρχειν εἰωθότα.", "st": "8.68"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἡ ἐκκλησία οὐδενὸς ἀντειπόντος, ἀλλὰ κυρώσασα ταῦτα διελύθη, τοὺς τετρακοσίους ἤδη ὕστερον τρόπῳ τοιῷδε ἐς τὸ βουλευτήριον ἐσήγαγον. ἦσαν [δ’] Ἀθηναῖοι πάντες αἰεὶ οἱ μὲν ἐπὶ τείχει, οἱ δ’ ἐν τάξει, τῶν ἐν Δεκελείᾳ πολεμίων ἕνεκα ἐφ’ ὅπλοις· τῇ οὖν ἡμέρᾳ ἐκείνῃ τοὺς μὲν μὴ ξυνειδότας εἴασαν ὥσπερ εἰώθεσαν ἀπελθεῖν, τοῖς δ’ ἐν τῇ ξυνωμοσίᾳ εἴρητο ἡσυχῇ μὴ ἐπ’ αὐτοῖς τοῖς ὅπλοις, ἀλλ’ ἄπωθεν περιμένειν, καὶ ἤν τις ἐνιστῆται τοῖς ποιουμένοις, λαβόντας τὰ ὅπλα μὴ ἐπιτρέπειν. ἦσαν δὲ καὶ Ἄνδριοι καὶ Τήνιοι καὶ Καρυστίων τριακόσιοι καὶ Αἰγινητῶν τῶν ἐποίκων, οὓς Ἀθηναῖοι ἔπεμψαν οἰκήσοντας, ἐπ’ αὐτὸ τοῦτο ἥκοντες ἐν τοῖς ἑαυτῶν ὅπλοις, οἷς ταὐτὰ προείρητο. τούτων δὲ διατεταγμένων οὕτως ἐλθόντες οἱ τετρακόσιοι μετὰ ξιφιδίου ἀφανοῦς ἕκαστος, καὶ οἱ εἴκοσι καὶ ἑκατὸν μετ’ αὐτῶν [Ἕλληνες] νεανίσκοι, οἷς ἐχρῶντο εἴ τί που δέοι χειρουργεῖν, ἐπέστησαν τοῖς ἀπὸ τοῦ κυάμου βουλευταῖς οὖσιν ἐν τῷ βουλευτηρίῳ καὶ εἶπον αὐτοῖς ἐξιέναι λαβοῦσι τὸν μισθόν· ἔφερον δὲ αὐτοῖς τοῦ ὑπολοίπου χρόνου παντὸς αὐτοὶ καὶ ἐξιοῦσιν ἐδίδοσαν.", "st": "8.69"}, {"sp": "N", "t": "ὡς δὲ τούτῳ τῷ τρόπῳ ἥ τε βουλὴ οὐδὲν ἀντειποῦσα ὑπεξῆλθε καὶ οἱ ἄλλοι πολῖται οὐδὲν ἐνεωτέριζον, ἀλλ’ ἡσύχαζον, οἱ [δὲ] τετρακόσιοι ἐσελθόντες ἐς τὸ βουλευτήριον τότε μὲν πρυτάνεις τε σφῶν αὐτῶν ἀπεκλήρωσαν καὶ ὅσα πρὸς τοὺς θεοὺς εὐχαῖς καὶ θυσίαις καθιστάμενοι ἐς τὴν ἀρχὴν ἐχρήσαντο, ὕστερον δὲ πολὺ μεταλλάξαντες τῆς τοῦ δήμου διοικήσεως (πλὴν τοὺς φεύγοντας οὐ κατῆγον τοῦ Ἀλκιβιάδου ἕνεκα) τά τε ἄλλα ἔνεμον κατὰ κράτος τὴν πόλιν. καὶ ἄνδρας τέ τινας ἀπέκτειναν οὐ πολλούς, οἳ ἐδόκουν ἐπιτήδειοι εἶναι ὑπεξαιρεθῆναι, καὶ ἄλλους ἔδησαν, τοὺς δὲ καὶ μετεστήσαντο· πρός τε Ἆγιν τὸν Λακεδαιμονίων βασιλέα ὄντα ἐν τῇ Δεκελείᾳ ἐπεκηρυκεύοντο, λέγοντες διαλλαγῆναι βούλεσθαι καὶ εἰκὸς εἶναι αὐτὸν σφίσι καὶ οὐκέτι τῷ ἀπίστῳ δήμῳ μᾶλλον ξυγχωρεῖν.", "st": "8.70"}, {"sp": "N", "t": "ὁ δὲ νομίζων τὴν πόλιν οὐχ ἡσυχάζειν, οὐδ’ εὐθὺς οὕτω τὸν δῆμον τὴν παλαιὰν ἐλευθερίαν παραδώσειν, εἴ τε στρατιὰν πολλὴν ἴδοι σφῶν, οὐκ ἂν ἡσυχάζειν, οὐδ’ ἐν τῷ παρόντι πάνυ τι πιστεύων μὴ οὐκέτι ταράσσεσθαι αὐτούς, τοῖς μὲν ἀπὸ τῶν τετρακοσίων ἐλθοῦσιν οὐδὲν ξυμβατικὸν ἀπεκρίνατο, προσμεταπεμψάμενος δὲ ἐκ Πελοποννήσου στρατιὰν πολλὴν οὐ πολλῷ ὕστερον καὶ αὐτὸς τῇ ἐκ τῆς Δεκελείας φρουρᾷ μετὰ τῶν ἐλθόντων κατέβη πρὸς αὐτὰ τὰ τείχη τῶν Ἀθηναίων, ἐλπίσας ἢ ταραχθέντας αὐτοὺς μᾶλλον ἂν χειρωθῆναι σφίσιν ᾗ βούλονται ἢ καὶ αὐτοβοεὶ ἂν διὰ τὸν ἔνδοθέν τε καὶ ἔξωθεν κατὰ τὸ εἰκὸς γενησόμενον θόρυβον· τῶν γὰρ μακρῶν τειχῶν διὰ τὴν κατ’ αὐτὰ ἐρημίαν λήψεως οὐκ ἂν ἁμαρτεῖν. ὡς δὲ προσέμειξέ τε ἐγγὺς καὶ οἱ Ἀθηναῖοι τὰ μὲν ἔνδοθεν οὐδ’ ὁπωστιοῦν ἐκίνησαν, τοὺς δὲ ἱππέας ἐκπέμψαντες καὶ μέρος τι τῶν ὁπλιτῶν καὶ ψιλῶν καὶ τοξοτῶν ἄνδρας τε κατέβαλον αὐτῶν διὰ τὸ ἐγγὺς προσελθεῖν καὶ ὅπλων τινῶν καὶ νεκρῶν ἐκράτησαν, οὕτω δὴ γνοὺς ἀπήγαγε πάλιν τὴν στρατιάν. καὶ αὐτὸς μὲν καὶ οἱ μετ’ αὐτοῦ κατὰ χώραν ἐν τῇ Δεκελείᾳ ἔμενον, τοὺς δ’ ἐπελθόντας ὀλίγας τινὰς ἡμέρας ἐν τῇ γῇ μείναντας ἀπέπεμψεν ἐπ’ οἴκου. μετὰ δὲ τοῦτο παρά τε τὸν Ἆγιν ἐπρεσβεύοντο οἱ τετρακόσιοι οὐδὲν ἧσσον, κἀκείνου μᾶλλον ἤδη προσδεχομένου καὶ παραινοῦντος ἐκπέμπουσι καὶ ἐς τὴν Λακεδαίμονα περὶ ξυμβάσεως πρέσβεις, βουλόμενοι διαλλαγῆναι.", "st": "8.71"}, {"sp": "N", "t": "πέμπουσι δὲ καὶ ἐς τὴν Σάμον δέκα ἄνδρας παραμυθησομένους τὸ στρατόπεδον καὶ διδάξοντας ὡς οὐκ ἐπὶ βλάβῃ τῆς πόλεως καὶ τῶν πολιτῶν ἡ ὀλιγαρχία κατέστη, ἀλλ’ ἐπὶ σωτηρίᾳ τῶν ξυμπάντων πραγμάτων, πεντακισχίλιοί τε ὅτι εἶεν καὶ οὐ τετρακόσιοι μόνον οἱ πράσσοντες· καίτοι οὐ πώποτε Ἀθηναίους διὰ τὰς στρατείας καὶ τὴν ὑπερόριον ἀσχολίαν ἐς οὐδὲν πρᾶγμα οὕτω μέγα ἐλθεῖν βουλεύσοντας ἐν ᾧ πεντακισχιλίους ξυνελθεῖν. ἄλλα τ’ ἐπιστείλαντες τὰ πρέποντα εἰπεῖν ἀπέπεμψαν αὐτοὺς εὐθὺς μετὰ τὴν ἑαυτῶν κατάστασιν, δείσαντες μή, ὅπερ ἐγένετο, ναυτικὸς ὄχλος οὔτ’ αὐτὸς μένειν ἐν τῷ ὀλιγαρχικῷ κόσμῳ ἐθέλῃ, σφᾶς τε μὴ ἐκεῖθεν ἀρξαμένου τοῦ κακοῦ μεταστήσωσιν.", "st": "8.72"}, {"sp": "N", "t": "ἐν γὰρ τῇ Σάμῳ ἐνεωτερίζετο ἤδη τὰ περὶ τὴν ὀλιγαρχίαν, καὶ ξυνέβη τοιάδε γενέσθαι ὑπ’ αὐτὸν τὸν χρόνον τοῦτον ὅνπερ οἱ τετρακόσιοι ξυνίσταντο. οἱ γὰρ τότε τῶν Σαμίων ἐπαναστάντες τοῖς δυνατοῖς καὶ ὄντες δῆμος μεταβαλλόμενοι αὖθις καὶ πεισθέντες ὑπό τε τοῦ Πεισάνδρου, ὅτε ἦλθε, καὶ τῶν ἐν τῇ Σάμῳ ξυνεστώτων Ἀθηναίων ἐγένοντό τε ἐς τριακοσίους ξυνωμόται καὶ ἔμελλον τοῖς ἄλλοις ὡς δήμῳ ὄντι ἐπιθήσεσθαι. καὶ Ὑπέρβολόν τέ τινα τῶν Ἀθηναίων, μοχθηρὸν ἄνθρωπον, ὠστρακισμένον οὐ διὰ δυνάμεως καὶ ἀξιώματος φόβον, ἀλλὰ διὰ πονηρίαν καὶ αἰσχύνην τῆς πόλεως, ἀποκτείνουσι μετὰ Χαρμίνου τε ἑνὸς τῶν στρατηγῶν καί τινων τῶν παρὰ σφίσιν Ἀθηναίων, πίστιν διδόντες αὐτοῖς, καὶ ἄλλα μετ’ αὐτῶν τοιαῦτα ξυνέπραξαν, τοῖς τε πλέοσιν ὥρμηντο ἐπιτίθεσθαι. οἱ δὲ αἰσθόμενοι τῶν τε στρατηγῶν Λέοντι καὶ Διομέδοντι (οὗτοι γὰρ οὐχ ἑκόντες διὰ τὸ τιμᾶσθαι ὑπὸ τοῦ δήμου ἔφερον τὴν ὀλιγαρχίαν) τὸ μέλλον σημαίνουσι καὶ Θρασυβούλῳ καὶ Θρασύλῳ, τῷ μὲν τριηραρχοῦντι, τῷ δὲ ὁπλιτεύοντι, καὶ ἄλλοις οἳ ἐδόκουν αἰεὶ μάλιστα ἐναντιοῦσθαι τοῖς ξυνεστῶσιν· καὶ οὐκ ἠξίουν περιιδεῖν αὐτοὺς σφᾶς τε διαφθαρέντας καὶ Σάμον Ἀθηναίοις ἀλλοτριωθεῖσαν, δι’ ἣν μόνον [μέχρι νῦν] ἡ ἀρχὴ αὐτοῖς ἐς τοῦτο ξυνέμεινεν. οἱ δὲ ἀκούσαντες τῶν τε στρατιωτῶν ἕνα ἕκαστον μετῇσαν μὴ ἐπιτρέπειν, καὶ οὐχ ἥκιστα τοὺς Παράλους, ἄνδρας Ἀθηναίους τε καὶ ἐλευθέρους πάντας ἐν τῇ νηὶ πλέοντας καὶ αἰεὶ δήποτε ὀλιγαρχίᾳ καὶ μὴ παρούσῃ ἐπικειμένους· ὅ τε Λέων καὶ ὁ Διομέδων αὐτοῖς ναῦς τινάς, ὁπότε ποι πλέοιεν, κατέλειπον φύλακας. ὥστε ἐπειδὴ αὐτοῖς ἐπετίθεντο οἱ τριακόσιοι, βοηθησάντων πάντων τούτων, μάλιστα δὲ τῶν Παράλων, περιεγένοντο οἱ τῶν Σαμίων πλέονες, καὶ τριάκοντα μέν τινας ἀπέκτειναν τῶν τριακοσίων, τρεῖς δὲ τοὺς αἰτιωτάτους φυγῇ ἐζημίωσαν· τοῖς δ’ ἄλλοις οὐ μνησικακοῦντες δημοκρατούμενοι τὸ λοιπὸν ξυνεπολίτευον.", "st": "8.73"}, {"sp": "N", "t": "τὴν δὲ Πάραλον ναῦν καὶ Χαιρέαν ἐπ’ αὐτῆς τὸν Ἀρχεστράτου, ἄνδρα Ἀθηναῖον, γενόμενον ἐς τὴν μετάστασιν πρόθυμον, ἀποπέμπουσιν οἵ τε Σάμιοι καὶ οἱ στρατιῶται κατὰ τάχος ἐς τὰς Ἀθήνας ἀπαγγελοῦντα τὰ γεγενημένα· οὐ γὰρ ᾔδεσάν πω τοὺς τετρακοσίους ἄρχοντας. καὶ καταπλευσάντων αὐτῶν εὐθέως τῶν μὲν Παράλων τινὰς οἱ τετρακόσιοι δύο ἢ τρεῖς ἔδησαν, τοὺς δὲ ἄλλους ἀφελόμενοι τὴν ναῦν καὶ μετεμβιβάσαντες ἐς ἄλλην στρατιῶτιν ναῦν ἔταξαν φρουρεῖν περὶ Εὔβοιαν. ὁ δὲ Χαιρέας εὐθὺς διαλαθών πως, ὡς εἶδε τὰ παρόντα, πάλιν ἐς τὴν Σάμον ἐλθὼν ἀγγέλλει τοῖς στρατιώταις ἐπὶ τὸ μεῖζον πάντα δεινώσας τὰ ἐκ τῶν Ἀθηνῶν, ὡς πληγαῖς τε πάντας ζημιοῦσι καὶ ἀντειπεῖν ἔστιν οὐδὲν πρὸς τοὺς ἔχοντας τὴν πολιτείαν, καὶ ὅτι αὐτῶν καὶ γυναῖκες καὶ παῖδες ὑβρίζονται, καὶ διανοοῦνται, ὁπόσοι ἐν Σάμῳ στρατεύονται μὴ ὄντες τῆς σφετέρας γνώμης, τούτων πάντων τοὺς προσήκοντας λαβόντες εἴρξειν, ἵνα, ἢν μὴ ὑπακούσωσι, τεθνήκωσιν· καὶ ἄλλα πολλὰ ἐπικαταψευδόμενος ἔλεγεν.", "st": "8.74"}, {"sp": "N", "t": "οἱ δὲ ἀκούοντες ἐπὶ τοὺς τὴν ὀλιγαρχίαν μάλιστα ποιήσαντας καὶ ἔτι τῶν ἄλλων τοὺς μετασχόντας τὸ μὲν πρῶτον ὥρμησαν βάλλειν, ἔπειτα μέντοι ὑπὸ τῶν διὰ μέσου κωλυθέντες καὶ διδαχθέντες μὴ τῶν πολεμίων ἀντιπρῴρων ἐγγὺς ἐφορμούντων ἀπολέσωσι τὰ πράγματα, ἐπαύσαντο. μετὰ δὲ τοῦτο λαμπρῶς ἤδη ἐς δημοκρατίαν βουλόμενοι μεταστῆσαι τὰ ἐν τῇ Σάμῳ ὅ τε Θρασύβουλος ὁ τοῦ Λύκου καὶ Θράσυλος (οὗτοι γὰρ μάλιστα προειστήκεσαν τῆς μεταβολῆς) ὥρκωσαν πάντας τοὺς στρατιώτας τοὺς μεγίστους ὅρκους, καὶ αὐτοὺς τοὺς ἐκ τῆς ὀλιγαρχίας μάλιστα, ἦ μὴν δημοκρατήσεσθαί τε καὶ ὁμονοήσειν καὶ τὸν πρὸς Πελοποννησίους πόλεμον προθύμως διοίσειν καὶ τοῖς τετρακοσίοις πολέμιοί τε ἔσεσθαι καὶ οὐδὲν ἐπικηρυκεύσεσθαι. ξυνώμνυσαν δὲ καὶ Σαμίων πάντες τὸν αὐτὸν ὅρκον οἱ ἐν τῇ ἡλικίᾳ, καὶ τὰ πράγματα πάντα καὶ τὰ ἀποβησόμενα ἐκ τῶν κινδύνων ξυνεκοινώσαντο οἱ στρατιῶται τοῖς Σαμίοις, νομίζοντες οὔτε ἐκείνοις ἀποστροφὴν σωτηρίας οὔτε σφίσιν εἶναι, ἀλλ’, ἐάν τε οἱ τετρακόσιοι κρατήσωσιν ἐάν τε οἱ ἐκ Μιλήτου πολέμιοι, διαφθαρήσεσθαι.", "st": "8.75"}, {"sp": "N", "t": "ἐς φιλονικίαν τε καθέστασαν τὸν χρόνον τοῦτον οἱ μὲν τὴν πόλιν ἀναγκάζοντες δημοκρατεῖσθαι, οἱ δὲ τὸ στρατόπεδον ὀλιγαρχεῖσθαι. ἐποίησαν δὲ καὶ ἐκκλησίαν εὐθὺς οἱ στρατιῶται, ἐν ᾗ τοὺς μὲν προτέρους στρατηγούς, καὶ εἴ τινα τῶν τριηράρχων ὑπώπτευον, ἔπαυσαν, ἄλλους δὲ ἀνθείλοντο καὶ τριηράρχους καὶ στρατηγούς, ὧν Θρασύβουλός τε καὶ Θράσυλος ὑπῆρχον. καὶ παραινέσεις ἄλλας τε ἐποιοῦντο ἐν σφίσιν αὐτοῖς ἀνιστάμενοι καὶ ὡς οὐ δεῖ ἀθυμεῖν ὅτι ἡ πόλις αὐτῶν ἀφέστηκεν· τοὺς γὰρ ἐλάσσους ἀπὸ σφῶν τῶν πλεόνων καὶ ἐς πάντα ποριμωτέρων μεθεστάναι. ἐχόντων γὰρ σφῶν τὸ πᾶν ναυτικόν, τάς τε ἄλλας πόλεις ὧν ἄρχουσιν ἀναγκάσειν τὰ χρήματα ὁμοίως διδόναι καὶ εἰ ἐκεῖθεν ὡρμῶντο (πόλιν τε γὰρ σφίσιν ὑπάρχειν Σάμον οὐκ ἀσθενῆ, ἀλλ’ ἣ παρ’ ἐλάχιστον δὴ ἦλθε τὸ Ἀθηναίων κράτος τῆς θαλάσσης, ὅτε ἐπολέμησεν, ἀφελέσθαι, τούς τε πολεμίους ἐκ τοῦ αὐτοῦ χωρίου ἀμυνεῖσθαι οὗπερ καὶ πρότερον), καὶ δυνατώτεροι εἶναι σφεῖς ἔχοντες τὰς ναῦς πορίζεσθαι τὰ ἐπιτήδεια τῶν ἐν τῇ πόλει. καὶ δι’ ἑαυτοὺς δὲ ἐν τῇ Σάμῳ προκαθημένους καὶ πρότερον αὐτοὺς κρατεῖν τοῦ ἐς τὸν Πειραιᾶ ἔσπλου, καὶ νῦν ἐς τοιοῦτον καταστήσονται μὴ βουλομένων σφίσι πάλιν τὴν πολιτείαν ἀποδοῦναι, ὥστε αὐτοὶ δυνατώτεροι εἶναι εἴργειν ἐκείνους τῆς θαλάσσης ἢ ὑπ’ ἐκείνων εἴργεσθαι. βραχύ τέ τι εἶναι καὶ οὐδενὸς ἄξιον ὃ πρὸς τὸ περιγίγνεσθαι τῶν πολεμίων ἡ πόλις σφίσι χρήσιμος ἦν, καὶ οὐδὲν ἀπολωλεκέναι, οἵ γε μήτε ἀργύριον εἶχον ἔτι πέμπειν, ἀλλ’ αὐτοὶ ἐπορίζοντο οἱ στρατιῶται, μήτε βούλευμα χρηστόν, οὗπερ ἕνεκα πόλις στρατοπέδων κρατεῖ· ἀλλὰ καὶ ἐν τούτοις τοὺς μὲν ἡμαρτηκέναι τοὺς πατρίους νόμους καταλύσαντας, αὐτοὶ δὲ σῴζειν καὶ ἐκείνους πειράσεσθαι προσαναγκάζειν, ὥστε οὐδὲ τούτους, οἵπερ ἂν βουλεύοιέν τι χρηστόν, παρὰ σφίσι χείρους εἶναι. Ἀλκιβιάδην τε, ἢν αὐτῷ ἄδειάν τε καὶ κάθοδον ποιήσωσιν, ἄσμενον τὴν παρὰ βασιλέως ξυμμαχίαν παρέξειν. τό τε μέγιστον, ἢν ἁπάντων σφάλλωνται, εἶναι αὐτοῖς τοσοῦτον ἔχουσι ναυτικὸν πολλὰς τὰς ἀποχωρήσεις ἐν αἷς καὶ πόλεις καὶ γῆν εὑρήσουσιν.", "st": "8.76"}, {"sp": "N", "t": "τοιαῦτα ἐν ἀλλήλοις ἐκκλησιάσαντες καὶ παραθαρσύναντες σφᾶς αὐτοὺς καὶ τὰ τοῦ πολέμου παρεσκευάζοντο οὐδὲν ἧσσον. οἱ δὲ ἀπὸ τῶν τετρακοσίων πεμφθέντες ἐς τὴν Σάμον [οἱ δέκα πρεσβευταὶ] ὡς ταῦτα ἐν τῇ Δήλῳ ἤδη ὄντες ᾐσθάνοντο, ἡσύχαζον αὐτοῦ.", "st": "8.77"}, {"sp": "N", "t": "ὑπὸ δὲ τὸν χρόνον τοῦτον καὶ οἱ ἐν τῇ Μιλήτῳ τῶν Πελοποννησίων ἐν τῷ ναυτικῷ στρατιῶται κατὰ σφᾶς αὐτοὺς διεβόων ὡς ὑπό τε Ἀστυόχου καὶ Τισσαφέρνους φθείρεται τὰ πράγματα, τοῦ μὲν οὐκ ἐθέλοντος οὔτε πρότερον ναυμαχεῖν, ἕως ἔτι αὐτοί τε ἔρρωντο μᾶλλον καὶ τὸ ναυτικὸν τῶν Ἀθηναίων ὀλίγον ἦν, οὔτε νῦν, ὅτε στασιάζειν τε λέγονται καὶ αἱ νῆες αὐτῶν οὐδέπω ἐν τῷ αὐτῷ εἰσίν, ἀλλὰ τὰς παρὰ Τισσαφέρνους Φοινίσσας ναῦς μένοντες, ἄλλως ὄνομα καὶ οὐκ ἔργον, κινδυνεύσειν διατριβῆναι· τὸν δ’ αὖ Τισσαφέρνην τάς τε ναῦς ταύτας οὐ κομίζειν, καὶ τροφὴν ὅτι οὐ ξυνεχῶς οὐδ’ ἐντελῆ διδοὺς κακοῖ τὸ ναυτικόν. οὔκουν ἔφασαν χρῆναι μέλλειν ἔτι, ἀλλὰ διαναυμαχεῖν.", "st": "8.78"}, {"sp": "N", "t": "καὶ μάλιστα οἱ Συρακόσιοι ἐνῆγον. αἰσθόμενοι δὲ οἱ ξύμμαχοι καὶ ὁ Ἀστύοχος τὸν θροῦν, καὶ δόξαν αὐτοῖς ἀπὸ ξυνόδου ὥστε διαναυμαχεῖν, ἐπειδὴ καὶ ἐσηγγέλλετο αὐτοῖς ἡ ἐν τῇ Σάμῳ ταραχή, ἄραντες ταῖς ναυσὶ πάσαις οὔσαις δώδεκα καὶ ἑκατὸν καὶ τοὺς Μιλησίους πεζῇ κελεύσαντες ἐπὶ τῆς Μυκάλης παριέναι ἔπλεον ὡς πρὸς τὴν Μυκάλην. οἱ δὲ Ἀθηναῖοι ταῖς ἐκ Σάμου ναυσὶ δυοῖν καὶ ὀγδοήκοντα, αἳ ἔτυχον ἐν Γλαύκῃ τῆς Μυκάλης ὁρμοῦσαι (διέχει δὲ ὀλίγον ταύτῃ ἡ Σάμος τῆς ἠπείρου πρὸς τὴν Μυκάλην), ὡς εἶδον τὰς τῶν Πελοποννησίων ναῦς προσπλεούσας, ὑπεχώρησαν ἐς τὴν Σάμον, οὐ νομίσαντες τῷ πλήθει διακινδυνεῦσαι περὶ τοῦ παντὸς ἱκανοὶ εἶναι. καὶ ἅμα (προῄσθοντο γὰρ αὐτοὺς ἐκ τῆς Μιλήτου ναυμαχησείοντας) προσεδέχοντο καὶ τὸν Στρομβιχίδην ἐκ τοῦ Ἑλλησπόντου σφίσι ταῖς ἐκ τῆς Χίου ναυσὶν ἐπ’ Ἀβύδου ἀφικομέναις προσβοηθήσειν· προυπέπεμπτο γὰρ αὐτῷ ἄγγελος. καὶ οἱ μὲν οὕτως ἐπὶ τῆς Σάμου ἀνεχώρησαν, οἱ δὲ Πελοποννήσιοι καταπλεύσαντες ἐπὶ τῆς Μυκάλης ἐστρατοπεδεύσαντο, καὶ τῶν Μιλησίων καὶ τῶν πλησιοχώρων ὁ πεζός. καὶ τῇ ὑστεραίᾳ μελλόντων αὐτῶν ἐπιπλεῖν τῇ Σάμῳ ἀγγέλλεται ὁ Στρομβιχίδης ταῖς ἀπὸ τοῦ Ἑλλησπόντου ναυσὶν ἀφιγμένος· καὶ εὐθὺς ἀπέπλεον πάλιν ἐπὶ τῆς Μιλήτου. οἱ δὲ Ἀθηναῖοι προσγενομένων σφίσι τῶν νεῶν ἐπίπλουν αὐτοὶ ποιοῦνται τῇ Μιλήτῳ ναυσὶν ὀκτὼ καὶ ἑκατὸν βουλόμενοι διαναυμαχῆσαι· καὶ ὡς οὐδεὶς αὐτοῖς ἀντανήγετο, ἀπέπλευσαν πάλιν ἐς τὴν Σάμον.", "st": "8.79"}, {"sp": "N", "t": "ἐν δὲ τῷ αὐτῷ θέρει μετὰ τοῦτο εὐθὺς οἱ Πελοποννήσιοι, ἐπειδὴ ἁθρόαις ταῖς ναυσὶν οὐκ ἀξιόμαχοι νομίσαντες εἶναι οὐκ ἀντανήγοντο, ἀπορήσαντες ὁπόθεν τοσαύταις ναυσὶ χρήματα ἕξουσιν, ἄλλως τε καὶ Τισσαφέρνους κακῶς διδόντος, ἀποστέλλουσιν ὡς τὸν Φαρνάβαζον, ὥσπερ καὶ τὸ πρῶτον ἐκ τῆς Πελοποννήσου προσετάχθη, Κλέαρχον τὸν Ῥαμφίου ἔχοντα ναῦς τεσσαράκοντα. ἐπεκαλεῖτό τε γὰρ αὐτοὺς ὁ Φαρνάβαζος καὶ τροφὴν ἑτοῖμος ἦν παρέχειν, καὶ ἅμα καὶ τὸ Βυζάντιον ἐπεκηρυκεύετο αὐτοῖς ἀποστῆναι. καὶ αἱ μὲν τῶν Πελοποννησίων αὗται νῆες ἀπάρασαι ἐς τὸ πέλαγος, ὅπως λάθοιεν ἐν τῷ πλῷ τοὺς Ἀθηναίους, χειμασθεῖσαι, καὶ αἱ μὲν Δήλου λαβόμεναι αἱ πλείους μετὰ Κλεάρχου καὶ ὕστερον πάλιν ἐλθοῦσαι ἐς Μίλητον (Κλέαρχος δὲ κατὰ γῆν αὖθις ἐς τὸν Ἑλλήσποντον κομισθεὶς ἦρχεν), αἱ δὲ μετὰ Ἑλίξου τοῦ Μεγαρέως στρατηγοῦ δέκα ἐς τὸν Ἑλλήσποντον διασωθεῖσαι Βυζάντιον ἀφιστᾶσιν. καὶ μετὰ ταῦτα οἱ ἐκ τῆς Σάμου πέμπουσιν αἰσθόμενοι νεῶν βοήθειαν καὶ φυλακὴν ἐς τὸν Ἑλλήσποντον, καί τις καὶ ναυμαχία βραχεῖα γίγνεται πρὸ τοῦ Βυζαντίου ναυσὶν ὀκτὼ πρὸς ὀκτώ.", "st": "8.80"}, {"sp": "N", "t": "οἱ δὲ προεστῶτες ἐν τῇ Σάμῳ καὶ μάλιστα Θρασύβουλος, αἰεί γε τῆς αὐτῆς γνώμης ἐχόμενος, ἐπειδὴ μετέστησε τὰ πράγματα, ὥστε κατάγειν Ἀλκιβιάδην, [καὶ] τέλος ἀπ’ ἐκκλησίας ἔπεισε τὸ πλῆθος τῶν στρατιωτῶν, καὶ ψηφισαμένων αὐτῶν Ἀλκιβιάδῃ κάθοδον καὶ ἄδειαν πλεύσας ὡς τὸν Τισσαφέρνην κατῆγεν ἐς τὴν Σάμον τὸν Ἀλκιβιάδην, νομίζων μόνην σωτηρίαν εἰ Τισσαφέρνην αὐτοῖς μεταστήσειεν ἀπὸ Πελοποννησίων. γενομένης δὲ ἐκκλησίας τήν τε ἰδίαν ξυμφορὰν τῆς φυγῆς ἐπῃτιάσατο καὶ ἀνωλοφύρατο ὁ Ἀλκιβιάδης, καὶ περὶ τῶν πολιτικῶν πολλὰ εἰπὼν ἐς ἐλπίδας τε αὐτοὺς οὐ σμικρὰς τῶν μελλόντων καθίστη, καὶ ὑπερβάλλων ἐμεγάλυνε τὴν ἑαυτοῦ δύναμιν παρὰ τῷ Τισσαφέρνει, ἵνα οἵ τε οἴκοι τὴν ὀλιγαρχίαν ἔχοντες φοβοῖντο αὐτὸν καὶ μᾶλλον αἱ ξυνωμοσίαι διαλυθεῖεν καὶ οἱ ἐν τῇ Σάμῳ τιμιώτερόν τε αὐτὸν ἄγοιεν καὶ αὐτοὶ ἐπὶ πλέον θαρσοῖεν, οἵ τε πολέμιοι τῷ Τισσαφέρνει ὡς μάλιστα διαβάλλοιντο καὶ [ἀπὸ] τῶν ὑπαρχουσῶν ἐλπίδων ἐκπίπτοιεν. ὑπισχνεῖτο δ’ οὖν τάδε μέγιστα ἐπικομπῶν ὁ Ἀλκιβιάδης, ὡς Τισσαφέρνης αὐτῷ ὑπεδέξατο ἦ μήν, ἕως ἄν τι τῶν ἑαυτοῦ λείπηται, ἢν Ἀθηναίοις πιστεύσῃ, μὴ ἀπορήσειν αὐτοὺς τροφῆς, οὐδ’ ἢν δέῃ τελευτῶντα τὴν ἑαυτοῦ στρωμνὴν ἐξαργυρῶσαι, τάς τε ἐν Ἀσπένδῳ ἤδη οὔσας Φοινίκων ναῦς κομιεῖν Ἀθηναίοις καὶ οὐ Πελοποννησίοις· πιστεῦσαι δ’ ἂν μόνως Ἀθηναίοις, εἰ σῶς αὐτὸς κατελθὼν αὐτῷ ἀναδέξαιτο.", "st": "8.81"}, {"sp": "N", "t": "οἱ δὲ ἀκούοντες ταῦτά τε καὶ ἄλλα πολλὰ στρατηγόν τε αὐτὸν εὐθὺς εἵλοντο μετὰ τῶν προτέρων καὶ τὰ πράγματα πάντα ἀνετίθεσαν, τήν τε παραυτίκα ἐλπίδα ἕκαστος τῆς τε σωτηρίας καὶ τῆς τῶν τετρακοσίων τιμωρίας οὐδενὸς ἂν ἠλλάξαντο, καὶ ἑτοῖμοι ἤδη ἦσαν διὰ τὸ αὐτίκα τούς τε παρόντας πολεμίους ἐκ τῶν λεχθέντων καταφρονεῖν καὶ πλεῖν ἐπὶ τὸν Πειραιᾶ. ὁ δὲ τὸ μὲν ἐπὶ τὸν Πειραιᾶ πλεῖν τοὺς ἐγγυτέρω πολεμίους ὑπολιπόντας καὶ πάνυ διεκώλυσε, πολλῶν ἐπειγομένων, τὰ δὲ τοῦ πολέμου πρῶτον ἔφη, ἐπειδὴ καὶ στρατηγὸς ᾕρητο, πλεύσας ὡς Τισσαφέρνην πράξειν. καὶ ἀπὸ ταύτης τῆς ἐκκλησίας εὐθὺς ᾤχετο, ἵνα δοκῇ πάντα μετ’ ἐκείνου κοινοῦσθαι, καὶ ἅμα βουλόμενος αὐτῷ τιμιώτερός τε εἶναι καὶ ἐνδείκνυσθαι ὅτι καὶ στρατηγὸς ἤδη ᾕρηται καὶ εὖ καὶ κακῶς οἷός τέ ἐστιν αὐτὸν [ἤδη] ποιεῖν. ξυνέβαινε δὲ τῷ Ἀλκιβιάδῃ τῷ μὲν Τισσαφέρνει τοὺς Ἀθηναίους φοβεῖν, ἐκείνοις δὲ τὸν Τισσαφέρνην.", "st": "8.82"}, {"sp": "N", "t": "οἱ δὲ Πελοποννήσιοι ἐν τῇ Μιλήτῳ πυνθανόμενοι τὴν τοῦ Ἀλκιβιάδου κάθοδον, καὶ πρότερον τῷ Τισσαφέρνει ἀπιστοῦντες πολλῷ δὴ μᾶλλον ἔτι διεβέβληντο. ξυνηνέχθη γὰρ αὐτοῖς κατὰ τὸν ἐπὶ τὴν Μίλητον τῶν Ἀθηναίων ἐπίπλουν, ὡς οὐκ ἠθέλησαν ἀνταναγαγόντες ναυμαχῆσαι, πολλῷ ἐς τὴν μισθοδοσίαν τὸν Τισσαφέρνην ἀρρωστότερον γενόμενον καὶ ἐς τὸ μισεῖσθαι ὑπ’ αὐτῶν πρότερον ἔτι τούτων διὰ τὸν Ἀλκιβιάδην ἐπιδεδωκέναι. καὶ ξυνιστάμενοι κατ’ ἀλλήλους οἷάπερ καὶ πρότερον οἱ στρατιῶται ἀνελογίζοντο καί τινες καὶ τῶν ἄλλων τῶν ἀξίων λόγου ἀνθρώπων καὶ οὐ μόνον τὸ στρατιωτικόν, ὡς οὔτε μισθὸν ἐντελῆ πώποτε λάβοιεν, τό τε διδόμενον βραχὺ καὶ οὐδὲ τοῦτο ξυνεχῶς· καὶ εἰ μή τις ἢ διαναυμαχήσει ἢ ἀπαλλάξεται ὅθεν τροφὴν ἕξει, ἀπολείψειν τοὺς ἀνθρώπους τὰς ναῦς· πάντων τε Ἀστύοχον εἶναι αἴτιον ἐπιφέροντα ὀργὰς Τισσαφέρνει διὰ ἴδια κέρδη.", "st": "8.83"}, {"sp": "N", "t": "ὄντων δ’ αὐτῶν ἐν τοιούτῳ ἀναλογισμῷ ξυνηνέχθη καὶ τοιόσδε τις θόρυβος περὶ τὸν Ἀστύοχον. τῶν γὰρ Συρακοσίων καὶ Θουρίων ὅσῳ μάλιστα καὶ ἐλεύθεροι ἦσαν τὸ πλῆθος οἱ ναῦται, τοσούτῳ καὶ θρασύτατα προσπεσόντες τὸν μισθὸν ἀπῄτουν. ὁ δὲ αὐθαδέστερόν τέ τι ἀπεκρίνατο καὶ ἠπείλησε καὶ τῷ γε Δωριεῖ ξυναγορεύοντι τοῖς ἑαυτοῦ ναύταις καὶ ἐπανήρατο τὴν βακτηρίαν. τὸ δὲ πλῆθος τῶν στρατιωτῶν ὡς εἶδον, οἷα δὴ ναῦται, ὥρμησαν ἐκραγέντες ἐπὶ τὸν Ἀστύοχον ὥστε βάλλειν· ὁ δὲ προϊδὼν καταφεύγει ἐπὶ βωμόν τινα. οὐ μέντοι ἐβλήθη γε, ἀλλὰ διελύθησαν ἀπ’ ἀλλήλων. ἔλαβον δὲ καὶ τὸ ἐν τῇ Μιλήτῳ ἐνῳκοδομημένον τοῦ Τισσαφέρνους φρούριον οἱ Μιλήσιοι λάθρᾳ ἐπιπεσόντες, καὶ τοὺς ἐνόντας φύλακας αὐτοῦ ἐκβάλλουσιν· ξυνεδόκει δὲ καὶ τοῖς ἄλλοις ξυμμάχοις ταῦτα καὶ οὐχ ἥκιστα τοῖς Συρακοσίοις. ὁ μέντοι Λίχας οὔτε ἠρέσκετο αὐτοῖς ἔφη τε χρῆναι Τισσαφέρνει καὶ δουλεύειν Μιλησίους καὶ τοὺς ἄλλους τοὺς ἐν τῇ βασιλέως τὰ μέτρια καὶ ἐπιθεραπεύειν, ἕως ἂν τὸν πόλεμον εὖ θῶνται. οἱ δὲ Μιλήσιοι ὠργίζοντό τε αὐτῷ καὶ διὰ ταῦτα καὶ δι’ ἄλλα τοιουτότροπα καὶ νόσῳ ὕστερον ἀποθανόντα αὐτὸν οὐκ εἴασαν θάψαι οὗ ἐβούλοντο οἱ παρόντες τῶν Λακεδαιμονίων.", "st": "8.84"}, {"sp": "N", "t": "κατὰ δὴ τοιαύτην διαφορὰν ὄντων αὐτοῖς τῶν πραγμάτων πρός τε τὸν Ἀστύοχον καὶ τὸν Τισσαφέρνην Μίνδαρος διάδοχος τῆς Ἀστυόχου ναυαρχίας ἐκ Λακεδαίμονος ἐπῆλθε καὶ παραλαμβάνει τὴν ἀρχήν· ὁ δὲ Ἀστύοχος ἀπέπλει. ξυνέπεμψε δὲ καὶ Τισσαφέρνης αὐτῷ πρεσβευτὴν τῶν παρ’ ἑαυτοῦ, Γαυλίτην ὄνομα, Κᾶρα δίγλωσσον, κατηγορήσοντα τῶν τε Μιλησίων περὶ τοῦ φρουρίου καὶ περὶ αὐτοῦ ἅμα ἀπολογησόμενον, εἰδὼς τούς τε Μιλησίους πορευομένους ἐπὶ καταβοῇ τῇ αὑτοῦ μάλιστα καὶ τὸν Ἑρμοκράτη μετ’ αὐτῶν, ὃς ἔμελλε τὸν Τισσαφέρνην ἀποφαίνειν φθείροντα τῶν Πελοποννησίων τὰ πράγματα μετὰ Ἀλκιβιάδου καὶ ἐπαμφοτερίζοντα. ἔχθρα δὲ πρὸς αὐτὸν ἦν αὐτῷ αἰεί ποτε περὶ τοῦ μισθοῦ τῆς ἀποδόσεως· καὶ τὰ τελευταῖα φυγόντος ἐκ Συρακουσῶν τοῦ Ἑρμοκράτους καὶ ἑτέρων ἡκόντων ἐπὶ τὰς ναῦς τῶν Συρακοσίων ἐς τὴν Μίλητον στρατηγῶν, Ποτάμιδος καὶ Μύσκωνος καὶ Δημάρχου, ἐνέκειτο ὁ Τισσαφέρνης φυγάδι ὄντι ἤδη τῷ Ἑρμοκράτει πολλῷ ἔτι μᾶλλον καὶ κατηγόρει ἄλλα τε καὶ ὡς χρήματά ποτε αἰτήσας αὑτὸν καὶ οὐ τυχὼν τὴν ἔχθραν οἱ προθοῖτο. ὁ μὲν οὖν Ἀστύοχος καὶ οἱ Μιλήσιοι καὶ ὁ Ἑρμοκράτης ἀπέπλευσαν ἐς τὴν Λακεδαίμονα. ὁ δὲ Ἀλκιβιάδης διεβεβήκει πάλιν ἤδη παρὰ τοῦ Τισσαφέρνους ἐς τὴν Σάμον.", "st": "8.85"}, {"sp": "N", "t": "καὶ οἱ ἐκ τῆς Δήλου ἀπὸ τῶν τετρακοσίων [πρεσβευταί], οὓς τότε ἔπεμψαν παραμυθησομένους καὶ ἀναδιδάξοντας τοὺς ἐν τῇ Σάμῳ, ἀφικνοῦνται παρόντος τοῦ Ἀλκιβιάδου, καὶ ἐκκλησίας γενομένης λέγειν ἐπεχείρουν. οἱ δὲ στρατιῶται τὸ μὲν πρῶτον οὐκ ἤθελον ἀκούειν, ἀλλ’ ἀποκτείνειν ἐβόων τοὺς τὸν δῆμον καταλύοντας, ἔπειτα μέντοι μόλις ἡσυχάσαντες ἤκουσαν. οἱ δ’ ἀπήγγελλον ὡς οὔτε ἐπὶ διαφθορᾷ τῆς πόλεως ἡ μετάστασις γίγνοιτο, ἀλλ’ ἐπὶ σωτηρίᾳ, οὔθ’ ἵνα τοῖς πολεμίοις παραδοθῇ (ἐξεῖναι γάρ, ὅτε ἐσέβαλον ἤδη σφῶν ἀρχόντων, τοῦτο ποιῆσαι), τῶν τε πεντακισχιλίων ὅτι πάντες ἐν τῷ μέρει μεθέξουσιν, οἵ τε οἰκεῖοι αὐτῶν οὔθ’ ὑβρίζονται, ὥσπερ Χαιρέας διαβάλλων ἀπήγγειλεν, οὔτε κακὸν ἔχουσιν οὐδέν, ἀλλ’ ἐπὶ τοῖς σφετέροις αὐτῶν ἕκαστοι κατὰ χώραν μένουσιν. ἄλλα τε πολλὰ εἰπόντων οὐδὲν μᾶλλον ἐσήκουον, ἀλλ’ ἐχαλέπαινον καὶ γνώμας ἄλλοι ἄλλας ἔλεγον, μάλιστα δὲ ἐπὶ τὸν Πειραιᾶ πλεῖν. καὶ δοκεῖ Ἀλκιβιάδης πρῶτον τότε καὶ οὐδενὸς ἔλασσον τὴν πόλιν ὠφελῆσαι· ὡρμημένων γὰρ τῶν ἐν Σάμῳ Ἀθηναίων πλεῖν ἐπὶ σφᾶς αὐτούς, ἐν ᾧ σαφέστατα Ἰωνίαν καὶ Ἑλλήσποντον εὐθὺς εἶχον οἱ πολέμιοι, κωλυτὴς γενέσθαι. καὶ ἐν τῷ τότε ἄλλος μὲν οὐδ’ ἂν εἷς ἱκανὸς ἐγένετο κατασχεῖν τὸν ὄχλον, ἐκεῖνος δὲ τοῦ τ’ ἐπίπλου ἔπαυσε καὶ τοὺς ἰδίᾳ τοῖς πρέσβεσιν ὀργιζομένους λοιδορῶν ἀπέτρεπεν. αὐτὸς δὲ ἀποκρινάμενος αὐτοῖς ἀπέπεμπεν, ὅτι τοὺς μὲν πεντακισχιλίους οὐ κωλύοι ἄρχειν, τοὺς μέντοι τετρακοσίους ἀπαλλάσσειν ἐκέλευεν αὐτοὺς καὶ καθιστάναι τὴν βουλὴν ὥσπερ καὶ πρότερον, τοὺς πεντακοσίους· εἰ δὲ ἐς εὐτέλειάν τι ξυντέτμηται ὥστε τοὺς στρατευομένους μᾶλλον ἔχειν τροφήν, πάνυ ἐπαινεῖν. καὶ τἆλλα ἐκέλευεν ἀντέχειν καὶ μηδὲν ἐνδιδόναι τοῖς πολεμίοις· πρὸς μὲν γὰρ σφᾶς αὐτοὺς σῳζομένης τῆς πόλεως πολλὴν ἐλπίδα εἶναι καὶ ξυμβῆναι, εἰ δὲ ἅπαξ τὸ ἕτερον σφαλήσεται, ἢ τὸ ἐν Σάμῳ ἢ ἐκεῖνοι, οὐδ’ ὅτῳ διαλλαγήσεταί τις ἔτι ἔσεσθαι.", "st": "8.86"}, {"sp": "N", "t": "παρῆσαν δὲ καὶ Ἀργείων πρέσβεις, ἐπαγγελλόμενοι τῷ ἐν τῇ Σάμῳ τῶν Ἀθηναίων δήμῳ ὥστε βοηθεῖν· ὁ δὲ Ἀλκιβιάδης ἐπαινέσας αὐτοὺς καὶ εἰπὼν ὅταν τις καλῇ παρεῖναι οὕτως ἀπέπεμπεν. ἀφίκοντο δὲ οἱ Ἀργεῖοι μετὰ τῶν Παράλων, οἳ τότε ἐτάχθησαν ἐν τῇ στρατιώτιδι νηὶ ὑπὸ τῶν τετρακοσίων περιπλεῖν Εὔβοιαν, καὶ ἄγοντες Ἀθηναίων ἐς Λακεδαίμονα ἀπὸ τῶν τετρακοσίων [πεμπτοὺς] πρέσβεις, Λαισποδίαν καὶ Ἀριστοφῶντα καὶ Μελησίαν, [οἳ] ἐπειδὴ ἐγένοντο πλέοντες κατ’ Ἄργος, τοὺς μὲν πρέσβεις ξυλλαβόντες τοῖς Ἀργείοις παρέδοσαν ὡς τῶν οὐχ ἥκιστα καταλυσάντων τὸν δῆμον ὄντας, αὐτοὶ δὲ οὐκέτι ἐς τὰς Ἀθήνας ἀφίκοντο, ἀλλ’ ἄγοντες ἐκ τοῦ Ἄργους ἐς τὴν Σάμον τοὺς πρέσβεις ἀφικνοῦνται ᾗπερ εἶχον τριήρει.", "st": "8.86"}, {"sp": "N", "t": "τοῦ δ’ αὐτοῦ θέρους Τισσαφέρνης, κατὰ τὸν καιρὸν τοῦτον ἐν ᾧ μάλιστα διά τε τἆλλα καὶ διὰ τὴν Ἀλκιβιάδου κάθοδον ἤχθοντο αὐτῷ οἱ Πελοποννήσιοι ὡς φανερῶς ἤδη ἀττικίζοντι, βουλόμενος, ὡς ἐδόκει δή, ἀπολύεσθαι πρὸς αὐτοὺς τὰς διαβολάς, παρεσκευάζετο πορεύεσθαι ἐπὶ τὰς Φοινίσσας ναῦς ἐς Ἄσπενδον, καὶ τὸν Λίχαν ξυμπορεύεσθαι ἐκέλευεν· τῇ δὲ στρατιᾷ προστάξειν ἔφη Τάμων ἑαυτοῦ ὕπαρχον, ὥστε τροφὴν ἐν ὅσῳ ἂν αὐτὸς ἀπῇ διδόναι. λέγεται δὲ οὐ κατὰ ταὐτό, οὐδὲ ῥᾴδιον εἰδέναι τίνι γνώμῃ παρῆλθεν ἐς τὴν Ἄσπενδον καὶ παρελθὼν οὐκ ἤγαγε τὰς ναῦς. ὅτι μὲν γὰρ αἱ Φοίνισσαι νῆες ἑπτὰ καὶ τεσσαράκοντα καὶ ἑκατὸν μέχρι Ἀσπένδου ἀφίκοντο σαφές ἐστι, διότι δὲ οὐκ ἦλθον πολλαχῇ εἰκάζεται. οἱ μὲν γὰρ ἵνα διατρίβῃ ἀπελθών, ὥσπερ καὶ διενοήθη, τὰ τῶν Πελοποννησίων (τροφὴν γοῦν οὐδὲν βέλτιον, ἀλλὰ καὶ χεῖρον ὁ Τάμως, ᾧ προσετάχθη, παρεῖχεν), οἱ δὲ ἵνα τοὺς Φοίνικας προαγαγὼν ἐς τὴν Ἄσπενδον ἐκχρηματίσαιτο ἀφείς (καὶ γὰρ ὣς αὐτοῖς οὐδὲν ἔμελλε χρήσεσθαι), ἄλλοι δ’ ὡς καταβοῆς ἕνεκα τῆς ἐς Λακεδαίμονα, τοῦ λέγεσθαι ὡς οὐκ ἀδικεῖ, ἀλλὰ καὶ σαφῶς οἴχεται ἐπὶ τὰς ναῦς ἀληθῶς πεπληρωμένας. ἐμοὶ μέντοι δοκεῖ σαφέστατον εἶναι διατριβῆς ἕνεκα καὶ ἀνοκωχῆς τῶν Ἑλληνικῶν τὸ ναυτικὸν οὐκ ἀγαγεῖν, φθορᾶς μέν, ἐν ὅσῳ παρῄει ἐκεῖσε καὶ διέμελλεν, ἀνισώσεως δέ, ὅπως μηδετέροις προσθέμενος ἰσχυροτέρους ποιήσῃ, ἐπεί, εἴ γε ἐβουλήθη, διαπολεμῆσαι ⟨ἂν⟩ ἐπιφανεὶς δήπου οὐκ ἐνδοιαστῶς· κομίσας γὰρ ἂν Λακεδαιμονίοις τὴν νίκην κατὰ τὸ εἰκὸς ἔδωκεν, οἵ γε καὶ ἐν τῷ παρόντι ἀντιπάλως μᾶλλον ἢ ὑποδεεστέρως τῷ ναυτικῷ ἀνθώρμουν. καταφωρᾷ δὲ μάλιστα καὶ ἣν εἶπε πρόφασιν οὐ κομίσας τὰς ναῦς. ἔφη γὰρ αὐτὰς ἐλάσσους ἢ ὅσας βασιλεὺς ἔταξε ξυλλεγῆναι· ὁ δὲ χάριν ἂν δήπου ἐν τούτῳ μείζω ἔτι ἔσχεν, οὔτ’ ἀναλώσας πολλὰ τῶν βασιλέως τά τε αὐτὰ ἀπ’ ἐλασσόνων πράξας. ἐς δ’ οὖν τὴν Ἄσπενδον ᾑτινιδὴ γνώμῃ ὁ Τισσαφέρνης ἀφικνεῖται καὶ τοῖς Φοίνιξι ξυγγίγνεται· καὶ οἱ Πελοποννήσιοι ἔπεμψαν ὡς ἐπὶ τὰς ναῦς κελεύσαντος αὐτοῦ Φίλιππον ἄνδρα Λακεδαιμόνιον δύο τριήρεσιν.", "st": "8.87"}, {"sp": "N", "t": "Ἀλκιβιάδης δὲ ἐπειδὴ καὶ τὸν Τισσαφέρνην ᾔσθετο παριόντα ἐπὶ τῆς Ἀσπένδου, ἔπλει καὶ αὐτὸς λαβὼν τρεῖς καὶ δέκα ναῦς, ὑποσχόμενος τοῖς ἐν τῇ Σάμῳ ἀσφαλῆ καὶ μεγάλην χάριν (ἢ γὰρ αὐτὸς ἄξειν Ἀθηναίοις τὰς Φοινίσσας ναῦς ἢ Πελοποννησίοις γε κωλύσειν ἐλθεῖν), εἰδώς, ὡς εἰκός, ἐκ πλέονος τὴν Τισσαφέρνους γνώμην ὅτι οὐκ ἄξειν ἔμελλε, καὶ βουλόμενος αὐτὸν τοῖς Πελοποννησίοις ἐς τὴν ἑαυτοῦ καὶ Ἀθηναίων φιλίαν ὡς μάλιστα διαβάλλειν, ὅπως μᾶλλον δι’ αὐτὸ σφίσιν ἀναγκάζοιτο προσχωρεῖν. καὶ ὁ μὲν ἄρας εὐθὺ τῆς Φασήλιδος καὶ Καύνου ἄνω τὸν πλοῦν ἐποιεῖτο.", "st": "8.88"}, {"sp": "N", "t": "οἱ δ’ ἐκ τῆς Σάμου ἀπὸ τῶν τετρακοσίων πεμφθέντες πρέσβεις ἐπειδὴ ἀφικόμενοι ἐς τὰς Ἀθήνας ἀπήγγειλαν τὰ παρὰ τοῦ Ἀλκιβιάδου, ὡς κελεύει τε ἀντέχειν καὶ μηδὲν ἐνδιδόναι τοῖς πολεμίοις, ἐλπίδας τε ὅτι πολλὰς ἔχει κἀκείνοις τὸ στράτευμα διαλλάξειν καὶ Πελοποννησίων περιέσεσθαι, ἀχθομένους καὶ πρότερον τοὺς πολλοὺς τῶν μετεχόντων τῆς ὀλιγαρχίας καὶ ἡδέως ἂν ἀπαλλαγέντας πῃ ἀσφαλῶς τοῦ πράγματος πολλῷ δὴ μᾶλλον ἐπέρρωσαν. καὶ ξυνίσταντό τε ἤδη καὶ τὰ πράγματα διεμέμφοντο, ἔχοντες ἡγεμόνας τῶν πάνυ [στρατηγῶν] τῶν ἐν τῇ ὀλιγαρχίᾳ καὶ ἐν ἀρχαῖς ὄντων, οἷον Θηραμένη τε τὸν Ἅγνωνος καὶ Ἀριστοκράτη τὸν Σκελίου καὶ ἄλλους, οἳ μετέσχον μὲν ἐν τοῖς πρῶτοι τῶν πραγμάτων, φοβούμενοι δέ, ὡς ἔφασαν, τό τε ἐν τῇ Σάμῳ στράτευμα καὶ τὸν Ἀλκιβιάδην σπουδῇ πάνυ, τούς τε ἐς τὴν Λακεδαίμονα πρεσβευομένους [ἔπεμπον], μή τι ἄνευ τῶν πλεόνων κακὸν δράσωσι τὴν πόλιν, οὐ τὸ † ἀπαλλαξείειν τοῦ ἄγαν ἐς ὀλίγους ἐλθεῖν, ἀλλὰ τοὺς πεντακισχιλίους ἔργῳ καὶ μὴ ὀνόματι χρῆναι ἀποδεικνύναι καὶ τὴν πολιτείαν ἰσαιτέραν καθιστάναι. ἦν δὲ τοῦτο μὲν σχῆμα πολιτικὸν τοῦ λόγου αὐτοῖς, κατ’ ἰδίας δὲ φιλοτιμίας οἱ πολλοὶ αὐτῶν τῷ τοιούτῳ προσέκειντο, ἐν ᾧπερ καὶ μάλιστα ὀλιγαρχία ἐκ δημοκρατίας γενομένη ἀπόλλυται· πάντες γὰρ αὐθημερὸν ἀξιοῦσιν οὐχ ὅπως ἴσοι, ἀλλὰ καὶ πολὺ πρῶτος αὐτὸς ἕκαστος εἶναι· ἐκ δὲ δημοκρατίας αἱρέσεως γιγνομένης ῥᾷον τὰ ἀποβαίνοντα ὡς οὐκ ἀπὸ τῶν ὁμοίων ἐλασσούμενός τις φέρει. σαφέστατα δ’ αὐτοὺς ἐπῆρε τὰ ἐν τῇ Σάμῳ τοῦ Ἀλκιβιάδου ἰσχυρὰ ὄντα καὶ ὅτι αὐτοῖς οὐκ ἐδόκει μόνιμον τὸ τῆς ὀλιγαρχίας ἔσεσθαι· ἠγωνίζετο οὖν εἷς ἕκαστος αὐτὸς πρῶτος προστάτης τοῦ δήμου γενέσθαι.", "st": "8.89"}, {"sp": "N", "t": "οἱ δὲ τῶν τετρακοσίων μάλιστα ἐναντίοι ὄντες τῷ τοιούτῳ εἴδει καὶ προεστῶτες Φρύνιχός τε, ὃς καὶ στρατηγήσας ἐν τῇ Σάμῳ [ποτὲ] τῷ Ἀλκιβιάδῃ τότε διηνέχθη, καὶ Ἀρίσταρχος, ἀνὴρ ἐν τοῖς μάλιστα καὶ ἐκ πλείστου ἐναντίος τῷ δήμῳ, καὶ Πείσανδρος καὶ Ἀντιφῶν καὶ ἄλλοι οἱ δυνατώτατοι, πρότερόν τε, ἐπεὶ τάχιστα κατέστησαν καὶ ἐπειδὴ τὰ ἐν τῇ Σάμῳ σφῶν ἐς δημοκρατίαν ἀπέστη, πρέσβεις τε ἀπέστελλον σφῶν ἐς τὴν Λακεδαίμονα καὶ τὴν ὁμολογίαν προυθυμοῦντο καὶ τὸ ἐν τῇ Ἠετιωνείᾳ καλουμένῃ τεῖχος ἐποιοῦντο, πολλῷ τε μᾶλλον ἔτι, ἐπειδὴ καὶ οἱ ἐκ τῆς Σάμου πρέσβεις σφῶν ἦλθον, ὁρῶντες τούς τε πολλοὺς καὶ σφῶν τοὺς δοκοῦντας πρότερον πιστοὺς εἶναι μεταβαλλομένους. καὶ ἀπέστειλαν μὲν Ἀντιφῶντα καὶ Φρύνιχον καὶ ἄλλους δέκα κατὰ τάχος, φοβούμενοι καὶ τὰ αὐτοῦ καὶ τὰ ἐκ τῆς Σάμου, ἐπιστείλαντες παντὶ τρόπῳ ὅστις καὶ ὁπωσοῦν ἀνεκτὸς ξυναλλαγῆναι πρὸς τοὺς Λακεδαιμονίους, ᾠκοδόμουν δὲ ἔτι προθυμότερον τὸ ἐν τῇ Ἠετιωνείᾳ τεῖχος. ἦν δὲ τοῦ τείχους ἡ γνώμη αὕτη, ὡς ἔφη Θηραμένης καὶ οἱ μετ’ αὐτοῦ, οὐχ ἵνα τοὺς ἐν Σάμῳ, ἢν βίᾳ ἐπιπλέωσι, μὴ δέξωνται ἐς τὸν Πειραιᾶ, ἀλλ’ ἵνα τοὺς πολεμίους μᾶλλον, ὅταν βούλωνται, καὶ ναυσὶ καὶ πεζῷ δέξωνται. χηλὴ γάρ ἐστι τοῦ Πειραιῶς ἡ Ἠετιωνεία, καὶ παρ’ αὐτὴν εὐθὺς ὁ ἔσπλους ἐστίν. ἐτειχίζετο οὖν οὕτω ξὺν τῷ πρότερον πρὸς ἤπειρον ὑπάρχοντι τείχει, ὥστε καθεζομένων ἐς αὐτὸ ἀνθρώπων ὀλίγων ἄρχειν τοῦ ἔσπλου· ἐπ’ αὐτὸν γὰρ τὸν ἐπὶ τῷ στόματι τοῦ λιμένος στενοῦ ὄντος τὸν ἕτερον πύργον ἐτελεύτα τό τε παλαιὸν τὸ πρὸς ἤπειρον καὶ τὸ ἐντὸς τὸ καινὸν τεῖχος τειχιζόμενον πρὸς θάλασσαν. διῳκοδόμησαν δὲ καὶ στοάν, ἥπερ ἦν μεγίστη καὶ ἐγγύτατα τούτου εὐθὺς ἐχομένη ἐν τῷ Πειραιεῖ, καὶ ἦρχον αὐτοὶ αὐτῆς, ἐς ἣν καὶ τὸν σῖτον ἠνάγκαζον πάντας τὸν ὑπάρχοντά τε καὶ τὸν ἐσπλέοντα ἐξαιρεῖσθαι καὶ ἐντεῦθεν προαιροῦντας πωλεῖν.", "st": "8.90"}, {"sp": "N", "t": "ταῦτ’ οὖν ἐκ πλέονός τε ὁ Θηραμένης διεθρόει καὶ ἐπειδὴ οἱ ἐκ τῆς Λακεδαίμονος πρέσβεις οὐδὲν πράξαντες ἀνεχώρησαν τοῖς ξύμπασι ξυμβατικόν, φάσκων κινδυνεύσειν τὸ τεῖχος τοῦτο καὶ τὴν πόλιν διαφθεῖραι. ἅμα γὰρ καὶ ἐκ τῆς Πελοποννήσου ἐτύγχανον Εὐβοέων ἐπικαλουμένων κατὰ τὸν αὐτὸν χρόνον τοῦτον δύο καὶ τεσσαράκοντα νῆες, ὧν ἦσαν καὶ ἐκ Τάραντος καὶ Λοκρῶν Ἰταλιώτιδες καὶ Σικελικαί τινες, ὁρμοῦσαι ἤδη ἐπὶ Λᾷ τῆς Λακωνικῆς καὶ παρασκευαζόμεναι τὸν ἐς τὴν Εὔβοιαν πλοῦν (ἦρχε δὲ αὐτῶν Ἀγησανδρίδας Ἀγησάνδρου Σπαρτιάτης)· ἃς ἔφη Θηραμένης οὐκ Εὐβοίᾳ μᾶλλον ἢ τοῖς τειχίζουσι τὴν Ἠετιωνείαν προσπλεῖν, καὶ εἰ μή τις ἤδη φυλάξεται, λήσειν διαφθαρέντας. ἦν δέ τι καὶ τοιοῦτον ἀπὸ τῶν τὴν κατηγορίαν ἐχόντων, καὶ οὐ πάνυ διαβολὴ μόνον τοῦ λόγου. ἐκεῖνοι γὰρ μάλιστα μὲν ἐβούλοντο ὀλιγαρχούμενοι ἄρχειν καὶ τῶν ξυμμάχων, εἰ δὲ μή, τάς τε ναῦς καὶ τὰ τείχη ἔχοντες αὐτονομεῖσθαι, ἐξειργόμενοι δὲ καὶ τούτου μὴ οὖν ὑπὸ τοῦ δήμου γε αὖθις γενομένου αὐτοὶ πρὸ τῶν ἄλλων μάλιστα διαφθαρῆναι, ἀλλὰ καὶ τοὺς πολεμίους ἐσαγαγόμενοι ἄνευ τειχῶν καὶ νεῶν ξυμβῆναι καὶ ὁπωσοῦν τὰ τῆς πόλεως ἔχειν, εἰ τοῖς γε σώμασι σφῶν ἄδεια ἔσται.", "st": "8.91"}, {"sp": "N", "t": "διόπερ καὶ τὸ τεῖχος τοῦτο καὶ πυλίδας ἔχον καὶ ἐσόδους καὶ ἐπεσαγωγὰς τῶν πολεμίων ἐτείχιζόν τε προθύμως καὶ φθῆναι ἐβούλοντο ἐξεργασάμενοι. πρότερον μὲν οὖν κατ’ ὀλίγους τε καὶ κρύφα μᾶλλον τὰ λεγόμενα ἦν· ἐπειδὴ δὲ ὁ Φρύνιχος ἥκων ἐκ τῆς ἐς Λακεδαίμονα πρεσβείας πληγεὶς ὑπ’ ἀνδρὸς τῶν περιπόλων τινὸς ἐξ ἐπιβουλῆς ἐν τῇ ἀγορᾷ πληθούσῃ καὶ οὐ πολὺ ἀπὸ τοῦ βουλευτηρίου ἀπελθὼν ἀπέθανε παραχρῆμα, καὶ ὁ μὲν πατάξας διέφυγεν, ὁ δὲ ξυνεργὸς Ἀργεῖος ἄνθρωπος ληφθεὶς καὶ βασανιζόμενος ὑπὸ τῶν τετρακοσίων οὐδενὸς ὄνομα τοῦ κελεύσαντος εἶπεν οὐδὲ ἄλλο τι ἢ ὅτι εἰδείη πολλοὺς ἀνθρώπους καὶ ἐς τοῦ περιπολάρχου καὶ ἄλλοσε κατ’ οἰκίας ξυνιόντας, τότε δὴ οὐδενὸς γεγενημένου ἀπ’ αὐτοῦ νεωτέρου καὶ ὁ Θηραμένης ἤδη θρασύτερον καὶ Ἀριστοκράτης καὶ ὅσοι ἄλλοι τῶν τετρακοσίων αὐτῶν καὶ τῶν ἔξωθεν ἦσαν ὁμογνώμονες ᾖσαν ἐπὶ τὰ πράγματα. ἅμα γὰρ καὶ ἀπὸ τῆς Λᾶς αἱ νῆες ἤδη περιπεπλευκυῖαι καὶ ὁρμισάμεναι ἐς τὴν Ἐπίδαυρον τὴν Αἴγιναν κατεδεδραμήκεσαν· καὶ οὐκ ἔφη ὁ Θηραμένης εἰκὸς εἶναι ἐπ’ Εὔβοιαν πλεούσας αὐτὰς ἐς Αἴγιναν κατακολπίσαι καὶ πάλιν ἐν Ἐπιδαύρῳ ὁρμεῖν, εἰ μὴ παρακληθεῖσαι ἥκοιεν ἐφ’ οἷσπερ καὶ αὐτὸς αἰεὶ κατηγόρει· οὐκέτι οὖν οἷόν τε εἶναι ἡσυχάζειν. τέλος δὲ πολλῶν καὶ στασιωτικῶν λόγων καὶ ὑποψιῶν προσγενομένων καὶ ἔργῳ ἤδη ἥπτοντο τῶν πραγμάτων· οἱ γὰρ ἐν τῷ Πειραιεῖ τὸ τῆς Ἠετιωνείας τεῖχος ὁπλῖται οἰκοδομοῦντες, ἐν οἷς καὶ ὁ Ἀριστοκράτης ἦν ταξιαρχῶν καὶ τὴν ἑαυτοῦ φυλὴν ἔχων, ξυλλαμβάνουσιν Ἀλεξικλέα στρατηγὸν ὄντα ἐκ τῆς ὀλιγαρχίας καὶ μάλιστα πρὸς τοὺς ἑταίρους τετραμμένον, καὶ ἐς οἰκίαν ἀγαγόντες εἶρξαν. ξυνεπελάβοντο δὲ αὐτοῖς ἅμα καὶ ἄλλοι καὶ Ἕρμων τις τῶν περιπόλων τῶν Μουνιχίασι τεταγμένων ἄρχων· τὸ δὲ μέγιστον, τῶν ὁπλιτῶν τὸ στῖφος ταῦτα ἐβούλετο. ὡς δὲ ἐσηγγέλθη τοῖς τετρακοσίοις (ἔτυχον δὲ ἐν τῷ βουλευτηρίῳ ξυγκαθήμενοι), εὐθύς, πλὴν ὅσοις μὴ βουλομένοις ταῦτ’ ἦν, ἑτοῖμοι ἦσαν ἐς τὰ ὅπλα ἰέναι καὶ τῷ Θηραμένει καὶ τοῖς μετ’ αὐτοῦ ἠπείλουν. ὁ δὲ ἀπολογούμενος ἑτοῖμος ἔφη εἶναι ξυναφαιρησόμενος ἰέναι ἤδη. καὶ παραλαβὼν ἕνα τῶν στρατηγῶν ὃς ἦν αὐτῷ ὁμογνώμων ἐχώρει ἐς τὸν Πειραιᾶ· ἐβοήθει δὲ καὶ Ἀρίσταρχος καὶ τῶν ἱππέων νεανίσκοι. ἦν δὲ θόρυβος πολὺς καὶ ἐκπληκτικός· οἵ τε γὰρ ἐν τῷ ἄστει ἤδη ᾤοντο τόν τε Πειραιᾶ κατειλῆφθαι καὶ τὸν ξυνειλημμένον τεθνάναι, οἵ τε ἐν τῷ Πειραιεῖ τοὺς ἐκ τοῦ ἄστεως ὅσον οὔπω ἐπὶ σφᾶς παρεῖναι. μόλις δὲ τῶν τε πρεσβυτέρων διακωλυόντων τοὺς ἐν τῷ ἄστει διαθέοντας καὶ ἐπὶ τὰ ὅπλα φερομένους καὶ Θουκυδίδου τοῦ Φαρσαλίου τοῦ προξένου τῆς πόλεως παρόντος καὶ προθύμως ἐμποδών τε ἑκάστοις γιγνομένου καὶ ἐπιβοωμένου μὴ ἐφεδρευόντων ἐγγὺς τῶν πολεμίων ἀπολέσαι τὴν πατρίδα, ἡσύχασάν τε καὶ σφῶν αὐτῶν ἀπέσχοντο. καὶ ὁ μὲν Θηραμένης ἐλθὼν ἐς τὸν Πειραιᾶ (ἦν δὲ καὶ αὐτὸς στρατηγός), ὅσον καὶ ἀπὸ βοῆς ἕνεκα, ὠργίζετο τοῖς ὁπλίταις· ὁ δὲ Ἀρίσταρχος καὶ οἱ ἐναντίοι τῷ ἀληθεῖ ἐχαλέπαινον. οἱ δὲ ὁπλῖται ὁμόσε τε ἐχώρουν οἱ πλεῖστοι τῷ ἔργῳ καὶ οὐ μετεμέλοντο, καὶ τὸν Θηραμένη ἠρώτων εἰ δοκεῖ αὐτῷ ἐπ’ ἀγαθῷ τὸ τεῖχος οἰκοδομεῖσθαι καὶ εἰ ἄμεινον εἶναι καθαιρεθέν. ὁ δέ, εἴπερ καὶ ἐκείνοις δοκεῖ καθαιρεῖν, καὶ ἑαυτῷ ἔφη ξυνδοκεῖν. καὶ ἐντεῦθεν εὐθὺς ἀναβάντες οἵ τε ὁπλῖται καὶ πολλοὶ τῶν ἐκ τοῦ Πειραιῶς ἀνθρώπων κατέσκαπτον τὸ τείχισμα. ἦν δὲ πρὸς τὸν ὄχλον ἡ παράκλησις ὡς χρή, ὅστις τοὺς πεντακισχιλίους βούλεται ἄρχειν ἀντὶ τῶν τετρακοσίων, ἰέναι ἐπὶ τὸ ἔργον. ἐπεκρύπτοντο γὰρ ὅμως ἔτι τῶν πεντακισχιλίων τῷ ὀνόματι, μὴ ἄντικρυς δῆμον ὅστις βούλεται ἄρχειν ὀνομάζειν, φοβούμενοι μὴ τῷ ὄντι ὦσι καὶ πρός τινα εἰπών τίς τι ἀγνοίᾳ σφαλῇ. καὶ οἱ τετρακόσιοι διὰ τοῦτο οὐκ ἤθελον τοὺς πεντακισχιλίους οὔτε εἶναι οὔτε μὴ ὄντας δήλους εἶναι, τὸ μὲν καταστῆσαι μετόχους τοσούτους ἄντικρυς ἂν δῆμον ἡγούμενοι, τὸ δ’ αὖ ἀφανὲς φόβον ἐς ἀλλήλους παρέξειν.", "st": "8.92"}, {"sp": "N", "t": "τῇ δ’ ὑστεραίᾳ οἱ μὲν τετρακόσιοι ἐς τὸ βουλευτήριον ὅμως καὶ τεθορυβημένοι ξυνελέγοντο· οἱ δ’ ἐν τῷ Πειραιεῖ ὁπλῖται τόν τε Ἀλεξικλέα ὃν ξυνέλαβον ἀφέντες καὶ τὸ τείχισμα καθελόντες ἐς τὸ πρὸς τῇ Μουνιχίᾳ Διονυσιακὸν θέατρον ἐλθόντες καὶ θέμενοι τὰ ὅπλα ἐξεκλησίασαν, καὶ δόξαν αὐτοῖς εὐθὺς ἐχώρουν ἐς τὸ ἄστυ καὶ ἔθεντο αὖ ἐν τῷ Ἀνακείῳ τὰ ὅπλα. ἐλθόντες δὲ ἀπὸ τῶν τετρακοσίων τινὲς ᾑρημένοι πρὸς αὐτοὺς ἀνὴρ ἀνδρὶ διελέγοντό τε καὶ ἔπειθον οὓς ἴδοιεν ἀνθρώπους ἐπιεικεῖς αὐτούς τε ἡσυχάζειν καὶ τοὺς ἄλλους παρακατέχειν, λέγοντες τούς τε πεντακισχιλίους ἀποφανεῖν, καὶ ἐκ τούτων ἐν μέρει ᾗ ἂν τοῖς πεντακισχιλίοις δοκῇ τοὺς τετρακοσίους ἔσεσθαι, τέως δὲ τὴν πόλιν μηδενὶ τρόπῳ διαφθείρειν μηδ’ ἐς τοὺς πολεμίους ἀνῶσαι. τὸ δὲ πᾶν πλῆθος τῶν ὁπλιτῶν ἀπὸ πολλῶν καὶ πρὸς πολλοὺς λόγων γιγνομένων ἠπιώτερον ἦν ἢ πρότερον καὶ ἐφοβεῖτο μάλιστα περὶ τοῦ παντὸς πολιτικοῦ· ξυνεχώρησάν τε ὥστε ἐς ἡμέραν ῥητὴν ἐκκλησίαν ποιῆσαι ἐν τῷ Διονυσίῳ περὶ ὁμονοίας.", "st": "8.93"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἐπῆλθεν ἡ [ἐν Διονύσου] ἐκκλησία καὶ ὅσον οὐ ξυνειλεγμένοι ἦσαν, ἀγγέλλονται αἱ δύο καὶ τεσσαράκοντα νῆες καὶ ὁ Ἀγησανδρίδας ἀπὸ τῶν Μεγάρων τὴν Σαλαμῖνα παραπλεῖν· καὶ πᾶς τις [τῶν πολλῶν ὁπλιτῶν] αὐτὸ τοῦτο ἐνόμιζεν εἶναι τὸ πάλαι λεγόμενον ὑπὸ Θηραμένους καὶ τῶν μετ’ αὐτοῦ, ὡς ἐς τὸ τείχισμα ἔπλεον αἱ νῆες, καὶ χρησίμως ἐδόκει καταπεπτωκέναι. ὁ δὲ Ἀγησανδρίδας τάχα μέν τι καὶ ἀπὸ ξυγκειμένου λόγου περί τε τὴν Ἐπίδαυρον καὶ ταύτῃ ἀνεστρέφετο, εἰκὸς δ’ αὐτὸν καὶ πρὸς τὸν παρόντα στασιασμὸν τῶν Ἀθηναίων, δι’ ἐλπίδος ὡς κἂν ἐς δέον παραγένοιτο, ταύτῃ ἀνέχειν. οἱ δ’ αὖ Ἀθηναῖοι, ὡς ἠγγέλθη αὐτοῖς, εὐθὺς δρόμῳ ἐς τὸν Πειραιᾶ πανδημεὶ ἐχώρουν, ὡς τοῦ ἰδίου πολέμου μείζονος [ἢ] ἀπὸ τῶν πολεμίων οὐχ ἑκάς, ἀλλὰ πρὸς τῷ λιμένι ὄντος. καὶ οἱ μὲν ἐς τὰς παρούσας ναῦς ἐσέβαινον, οἱ δὲ ἄλλας καθεῖλκον, οἱ δέ τινες ἐπὶ τὰ τείχη καὶ τὸ στόμα τοῦ λιμένος παρεβοήθουν.", "st": "8.94"}, {"sp": "N", "t": "αἱ δὲ τῶν Πελοποννησίων νῆες παραπλεύσασαι καὶ περιβαλοῦσαι Σούνιον ὁρμίζονται μεταξὺ Θορικοῦ τε καὶ Πρασιῶν, ὕστερον δὲ ἀφικνοῦνται ἐς Ὠρωπόν. Ἀθηναῖοι δὲ κατὰ τάχος καὶ ἀξυγκροτήτοις πληρώμασιν ἀναγκασθέντες χρήσασθαι, οἷα πόλεώς τε στασιαζούσης καὶ περὶ τοῦ μεγίστου ἐν τάχει βουλόμενοι βοηθῆσαι (Εὔβοια γὰρ αὐτοῖς ἀποκεκλῃμένης τῆς Ἀττικῆς πάντα ἦν), πέμπουσι Θυμοχάρη στρατηγὸν καὶ ναῦς ἐς Ἐρετρίαν, ὧν ἀφικομένων ξὺν ταῖς πρότερον ἐν Εὐβοίᾳ οὔσαις ἓξ καὶ τριάκοντα ἐγένοντο. καὶ εὐθὺς ναυμαχεῖν ἠναγκάζοντο· ὁ γὰρ Ἀγησανδρίδας ἀριστοποιησάμενος ἐκ τοῦ Ὠρωποῦ ἀνήγαγε τὰς ναῦς· ἀπέχει δὲ μάλιστα ὁ Ὠρωπὸς τῆς τῶν Ἐρετριῶν πόλεως θαλάσσης μέτρον ἑξήκοντα σταδίους. ὡς οὖν ἐπέπλει, εὐθὺς ἐπλήρουν καὶ οἱ Ἀθηναῖοι τὰς ναῦς, οἰόμενοι σφίσι παρὰ ταῖς ναυσὶ τοὺς στρατιώτας εἶναι· οἱ δὲ ἔτυχον οὐκ ἐκ τῆς ἀγορᾶς ἄριστον ἐπισιτιζόμενοι (οὐδὲν γὰρ ἐπωλεῖτο ἀπὸ προνοίας τῶν Ἐρετριῶν), ἀλλ’ ἐκ τῶν ἐπ’ ἔσχατα τοῦ ἄστεως οἰκιῶν, ὅπως σχολῇ πληρουμένων φθάσειαν οἱ πολέμιοι προσπεσόντες καὶ ἐξαναγκάσειαν τοὺς Ἀθηναίους οὕτως ὅπως τύχοιεν ἀνάγεσθαι. σημεῖον δὲ αὐτοῖς ἐς τὸν Ὠρωπὸν ἐκ τῆς Ἐρετρίας, ὁπότε χρὴ ἀνάγεσθαι, ἤρθη. διὰ τοιαύτης δὴ παρασκευῆς οἱ Ἀθηναῖοι ἀναγαγόμενοι καὶ ναυμαχήσαντες ὑπὲρ τοῦ λιμένος τῶν Ἐρετριῶν ὀλίγον μέν τινα χρόνον ὅμως καὶ ἀντέσχον, ἔπειτα ἐς φυγὴν τραπόμενοι καταδιώκονται ἐς τὴν γῆν. καὶ ὅσοι μὲν αὐτῶν πρὸς τὴν πόλιν τῶν Ἐρετριῶν ὡς φιλίαν καταφεύγουσι, χαλεπώτατα ἔπραξαν φονευόμενοι ὑπ’ αὐτῶν· οἳ δὲ ἐς τὸ τείχισμα τὸ ἐν τῇ Ἐρετρίᾳ, ὃ εἶχον αὐτοί, περιγίγνονται καὶ ὅσαι ἐς Χαλκίδα ἀφικνοῦνται τῶν νεῶν. λαβόντες δὲ οἱ Πελοποννήσιοι δύο καὶ εἴκοσι ναῦς τῶν Ἀθηναίων καὶ ἄνδρας τοὺς μὲν ἀποκτείναντες, τοὺς δὲ ζωγρήσαντες τροπαῖον ἔστησαν. καὶ ὕστερον οὐ πολλῷ Εὔβοιάν [τε] ἅπασαν ἀποστήσαντες πλὴν Ὠρεοῦ (ταύτην δὲ αὐτοὶ Ἀθηναῖοι εἶχον) καὶ τἆλλα τὰ περὶ αὐτὴν καθίσταντο.", "st": "8.95"}, {"sp": "N", "t": "τοῖς δὲ Ἀθηναίοις ὡς ἦλθε τὰ περὶ τὴν Εὔβοιαν γεγενημένα, ἔκπληξις μεγίστη δὴ τῶν πρὶν παρέστη. οὔτε γὰρ ἡ ἐν τῇ Σικελίᾳ ξυμφορά, καίπερ μεγάλη τότε δόξασα εἶναι, οὔτε ἄλλο οὐδέν πω οὕτως ἐφόβησεν. ὅπου γὰρ στρατοπέδου τε τοῦ ἐν Σάμῳ ἀφεστηκότος ἄλλων τε νεῶν οὐκ οὐσῶν οὐδὲ τῶν ἐσβησομένων αὐτῶν τε στασιαζόντων καὶ ἄδηλον ὂν ὁπότε σφίσιν αὐτοῖς ξυρράξουσι, τοσαύτη ἡ ξυμφορὰ ἐπεγεγένητο, ἐν ᾗ ναῦς τε καὶ τὸ μέγιστον Εὔβοιαν ἀπωλωλέκεσαν, ἐξ ἧς πλείω ἢ τῆς Ἀττικῆς ὠφελοῦντο, πῶς οὐκ εἰκότως ἠθύμουν; μάλιστα δ’ αὐτοὺς καὶ δι’ ἐγγυτάτου ἐθορύβει, εἰ οἱ πολέμιοι τολμήσουσι νενικηκότες εὐθὺ σφῶν ἐπὶ τὸν Πειραιᾶ ἐρῆμον ὄντα νεῶν πλεῖν· καὶ ὅσον οὐκ ἤδη ἐνόμιζον αὐτοὺς παρεῖναι. ὅπερ ἄν, εἰ τολμηρότεροι ἦσαν, ῥᾳδίως ἂν ἐποίησαν, καὶ ἢ διέστησαν ἂν ἔτι μᾶλλον τὴν πόλιν ἐφορμοῦντες ἤ, εἰ ἐπολιόρκουν μένοντες, καὶ τὰς ἀπ’ Ἰωνίας ναῦς ἠνάγκασαν ἂν καίπερ πολεμίας οὔσας τῇ ὀλιγαρχίᾳ τοῖς σφετέροις οἰκείοις καὶ τῇ ξυμπάσῃ πόλει βοηθῆσαι· καὶ ἐν τούτῳ Ἑλλήσποντός τε ἂν ἦν αὐτοῖς καὶ Ἰωνία καὶ αἱ νῆσοι καὶ τὰ μέχρι Εὐβοίας καὶ ὡς εἰπεῖν ἡ Ἀθηναίων ἀρχὴ πᾶσα. ἀλλ’ οὐκ ἐν τούτῳ μόνῳ Λακεδαιμόνιοι Ἀθηναίοις πάντων δὴ ξυμφορώτατοι προσπολεμῆσαι ἐγένοντο, ἀλλὰ καὶ ἐν ἄλλοις πολλοῖς· διάφοροι γὰρ πλεῖστον ὄντες τὸν τρόπον, οἱ μὲν ὀξεῖς, οἱ δὲ βραδεῖς, καὶ οἱ μὲν ἐπιχειρηταί, οἱ δὲ ἄτολμοι, ἄλλως τε καὶ ἐν ἀρχῇ ναυτικῇ πλεῖστα ὠφέλουν. ἔδειξαν δὲ οἱ Συρακόσιοι· μάλιστα γὰρ ὁμοιότροποι γενόμενοι ἄριστα καὶ προσεπολέμησαν.", "st": "8.96"}, {"sp": "N", "t": "ἐπὶ δ’ οὖν τοῖς ἠγγελμένοις οἱ Ἀθηναῖοι ναῦς τε εἴκοσιν ὅμως ἐπλήρουν καὶ ἐκκλησίαν ξυνέλεγον, μίαν μὲν εὐθὺς τότε πρῶτον ἐς τὴν Πύκνα καλουμένην, οὗπερ καὶ ἄλλοτε εἰώθεσαν, ἐν ᾗπερ καὶ τοὺς τετρακοσίους καταπαύσαντες τοῖς πεντακισχιλίοις ἐψηφίσαντο τὰ πράγματα παραδοῦναι (εἶναι δὲ αὐτῶν ὁπόσοι καὶ ὅπλα παρέχονται) καὶ μισθὸν μηδένα φέρειν μηδεμιᾷ ἀρχῇ· εἰ δὲ μή, ἐπάρατον ἐποιήσαντο. ἐγίγνοντο δὲ καὶ ἄλλαι ὕστερον πυκναὶ ἐκκλησίαι, ἀφ’ ὧν καὶ νομοθέτας καὶ τἆλλα ἐψηφίσαντο ἐς τὴν πολιτείαν. καὶ οὐχ ἥκιστα δὴ τὸν πρῶτον χρόνον ἐπί γε ἐμοῦ Ἀθηναῖοι φαίνονται εὖ πολιτεύσαντες· μετρία γὰρ ἥ τε ἐς τοὺς ὀλίγους καὶ τοὺς πολλοὺς ξύγκρασις ἐγένετο καὶ ἐκ πονηρῶν τῶν πραγμάτων γενομένων τοῦτο πρῶτον ἀνήνεγκε τὴν πόλιν. ἐψηφίσαντο δὲ καὶ Ἀλκιβιάδην καὶ ἄλλους μετ’ αὐτοῦ κατιέναι καὶ παρά τε ἐκεῖνον καὶ παρὰ τὸ ἐν Σάμῳ στρατόπεδον πέμψαντες διεκελεύοντο ἀνθάπτεσθαι τῶν πραγμάτων.", "st": "8.97"}, {"sp": "N", "t": "ἐν δὲ τῇ μεταβολῇ ταύτῃ εὐθὺς οἱ μὲν περὶ τὸν Πείσανδρον καὶ Ἀλεξικλέα καὶ ὅσοι ἦσαν τῆς ὀλιγαρχίας μάλιστα ὑπεξέρχονται ἐς τὴν Δεκέλειαν· Ἀρίσταρχος δὲ αὐτῶν μόνος (ἔτυχε γὰρ καὶ στρατηγῶν) λαβὼν κατὰ τάχος τοξότας τινὰς τοὺς βαρβαρωτάτους ἐχώρει πρὸς τὴν Οἰνόην. ἦν δὲ Ἀθηναίων ἐν μεθορίοις τῆς Βοιωτίας τεῖχος, ἐπολιόρκουν δ’ αὐτὸ διὰ ξυμφορὰν σφίσιν ἐκ τῆς Οἰνόης γενομένην ἀνδρῶν ἐκ Δεκελείας ἀναχωρούντων διαφθορᾶς οἱ Κορίνθιοι ἐθελοντηδόν, προσπαρακαλέσαντες τοὺς Βοιωτούς. κοινολογησάμενος οὖν αὐτοῖς ὁ Ἀρίσταρχος ἀπατᾷ τοὺς ἐν τῇ Οἰνόῃ, λέγων ὡς καὶ οἱ ἐν τῇ πόλει τἆλλα ξυμβεβήκασι Λακεδαιμονίοις, κἀκείνους δεῖ Βοιωτοῖς τὸ χωρίον παραδοῦναι· ἐπὶ τούτοις γὰρ ξυμβεβάσθαι. οἱ δὲ πιστεύσαντες ὡς ἀνδρὶ στρατηγῷ καὶ οὐκ εἰδότες οὐδὲν διὰ τὸ πολιορκεῖσθαι ὑπόσπονδοι ἐξέρχονται. τούτῳ μὲν τῷ τρόπῳ Οἰνόην τε ληφθεῖσαν Βοιωτοὶ κατέλαβον καὶ ἡ ἐν ταῖς Ἀθήναις ὀλιγαρχία καὶ στάσις ἐπαύσατο.", "st": "8.98"}, {"sp": "N", "t": "ὑπὸ δὲ τοὺς αὐτοὺς χρόνους τοῦ θέρους τούτου καὶ οἱ ἐν τῇ Μιλήτῳ Πελοποννήσιοι, ὡς τροφήν τε οὐδεὶς ἐδίδου τῶν ὑπὸ Τισσαφέρνους τότε [ὅτε ἐπὶ τὴν Ἄσπενδον παρῄει] προσταχθέντων, καὶ αἱ Φοίνισσαι νῆες οὐδὲ ὁ Τισσαφέρνης τέως που ἧκον, ὅ τε Φίλιππος ὁ ξυμπεμφθεὶς αὐτῷ ἐπεστάλκει Μινδάρῳ τῷ ναυάρχῳ καὶ ἄλλος Ἱπποκράτης, ἀνὴρ Σπαρτιάτης καὶ ὢν ἐν Φασήλιδι, ὅτι οὔτε αἱ νῆες παρέσοιντο πάντα τε ἀδικοῖντο ὑπὸ Τισσαφέρνους, Φαρνάβαζός τε ἐπεκαλεῖτο αὐτοὺς καὶ ἦν πρόθυμος κομίσας τὰς ναῦς καὶ αὐτὸς τὰς λοιπὰς ἔτι πόλεις τῆς ἑαυτοῦ ἀρχῆς ἀποστῆσαι τῶν Ἀθηναίων, ὥσπερ καὶ ὁ Τισσαφέρνης, ἐλπίζων πλέον τι σχήσειν ἀπ’ αὐτοῦ, οὕτω δὴ ὁ Μίνδαρος πολλῷ κόσμῳ καὶ ἀπὸ παραγγέλματος αἰφνιδίου, ὅπως λάθοι τοὺς ἐν Σάμῳ, ἄρας ἀπὸ τῆς Μιλήτου ναυσὶ τρισὶ καὶ ἑβδομήκοντα ἔπλει ἐπὶ τὸν Ἑλλήσποντον (πρότερον δὲ ἐν τῷ αὐτῷ θέρει τῷδε ἑκκαίδεκα ἐς αὐτὸν νῆες ἐσέπλευσαν, αἳ καὶ τῆς Χερσονήσου τι μέρος κατέδραμον)· χειμασθεὶς δὲ ἀνέμῳ καὶ ἀναγκασθεὶς καταίρει ἐς τὴν Ἴκαρον, καὶ μείνας ἐν αὐτῇ ὑπὸ ἀπλοίας πέντε ἢ ἓξ ἡμέρας ἀφικνεῖται ἐς τὴν Χίον.", "st": "8.99"}, {"sp": "N", "t": "ὁ δὲ Θράσυλος ἐκ τῆς Σάμου, ἐπειδὴ ἐπύθετο αὐτὸν ἐκ τῆς Μιλήτου ἀπηρκότα, ἔπλει καὶ αὐτὸς ναυσὶν εὐθὺς πέντε καὶ πεντήκοντα, ἐπειγόμενος μὴ φθάσῃ ἐς τὸν Ἑλλήσποντον ἐσπλεύσας. αἰσθόμενος δὲ ὅτι ἐν τῇ Χίῳ εἴη καὶ νομίσας αὐτὸν καθέξειν αὐτοῦ, σκοποὺς μὲν κατεστήσατο καὶ ἐν τῇ Λέσβῳ καὶ ἐν τῇ ἀντιπέρας ἠπείρῳ, εἰ ἄρα ποι κινοῖντο αἱ νῆες, ὅπως μὴ λάθοιεν, αὐτὸς δὲ ἐς τὴν Μήθυμναν παραπλεύσας ἄλφιτά τε καὶ τἆλλα ἐπιτήδεια παρασκευάζειν ἐκέλευεν ὡς, ἢν πλείων χρόνος γίγνηται, ἐκ τῆς Λέσβου τοὺς ἐπίπλους τῇ Χίῳ ποιησόμενος. ἅμα δὲ (Ἔρεσος γὰρ τῆς Λέσβου ἀφειστήκει) ἐβούλετο ἐπ’ αὐτὴν πλεύσας, εἰ δύναιτο, ἐξελεῖν. Μηθυμναίων γὰρ οὐχ οἱ ἀδυνατώτατοι φυγάδες διακομίσαντες ἔκ τε τῆς Κύμης προσεταιριστοὺς ὁπλίτας ὡς πεντήκοντα καὶ τῶν ἐκ τῆς ἠπείρου μισθωσάμενοι, ξύμπασιν ὡς τριακοσίοις, Ἀναξάνδρου Θηβαίου κατὰ τὸ ξυγγενὲς ἡγουμένου, προσέβαλον πρῶτον Μηθύμνῃ, καὶ ἀποκρουσθέντες τῆς πείρας διὰ τοὺς ἐκ τῆς Μυτιλήνης Ἀθηναίων φρουροὺς προελθόντας αὖθις ἔξω μάχῃ ἀπωσθέντες καὶ διὰ τοῦ ὄρους κομισθέντες ἀφιστᾶσι τὴν Ἔρεσον. πλεύσας οὖν ὁ Θράσυλος ἐπ’ αὐτὴν πάσαις ταῖς ναυσὶ διενοεῖτο προσβολὴν ποιεῖσθαι· προαφιγμένος δὲ αὐτόσε ἦν καὶ ὁ Θρασύβουλος πέντε ναυσὶν ἐκ τῆς Σάμου, ὡς ἠγγέλθη αὐτοῖς ἡ τῶν φυγάδων αὕτη διάβασις· ὑστερήσας δ’ ἐπὶ τὴν Ἔρεσον ἐφώρμει ἐλθών. προσεγένοντο δὲ καὶ ἐκ τοῦ Ἑλλησπόντου τινὲς δύο νῆες ἐπ’ οἴκου ἀνακομιζόμεναι καὶ Μηθυμναῖαι ⟨πέντε⟩· καὶ αἱ πᾶσαι νῆες παρῆσαν ἑπτὰ καὶ ἑξήκοντα, ἀφ’ ὧν τῷ στρατεύματι παρεσκευάζοντο ὡς κατὰ κράτος μηχαναῖς τε καὶ παντὶ τρόπῳ, ἢν δύνωνται, αἱρήσοντες τὴν Ἔρεσον.", "st": "8.100"}, {"sp": "N", "t": "ὁ δὲ Μίνδαρος ἐν τούτῳ καὶ ἐκ τῆς Χίου τῶν Πελοποννησίων αἱ νῆες ἐπισιτισάμεναι δυοῖν ἡμέραιν καὶ λαβόντες παρὰ τῶν Χίων τρεῖς τεσσαρακοστὰς ἕκαστος Χίας τῇ τρίτῃ διὰ ταχέων ἀπαίρουσιν ἐκ τῆς Χίου ⟨οὐ⟩ πελάγιαι, ἵνα μὴ περιτύχωσι ταῖς ἐν τῇ Ἐρέσῳ ναυσίν, ἀλλὰ ἐν ἀριστερᾷ τὴν Λέσβον ἔχοντες ἔπλεον ἐπὶ τὴν ἤπειρον. καὶ προσβαλόντες τῆς Φωκαΐδος ἐς τὸν ἐν Καρτερίοις λιμένα καὶ ἀριστοποιησάμενοι, παραπλεύσαντες τὴν Κυμαίαν δειπνοποιοῦνται ἐν Ἀργινούσαις τῆς ἠπείρου, ἐν τῷ ἀντιπέρας τῆς Μυτιλήνης. ἐντεῦθεν δὲ ἔτι πολλῆς νυκτὸς παραπλεύσαντες καὶ ἀφικόμενοι τῆς ἠπείρου ἐς Ἁρματοῦντα καταντικρὺ Μηθύμνης, ἀριστοποιησάμενοι διὰ ταχέων παραπλεύσαντες Λεκτὸν καὶ Λάρισαν καὶ Ἁμαξιτὸν καὶ τὰ ταύτῃ χωρία ἀφικνοῦνται ἐς Ῥοίτειον ἤδη τοῦ Ἑλλησπόντου πρωίτερον μέσων νυκτῶν. εἰσὶ δ’ αἳ τῶν νεῶν καὶ ἐς Σίγειον κατῆραν καὶ ἄλλοσε τῶν ταύτῃ χωρίων.", "st": "8.101"}, {"sp": "N", "t": "οἱ δὲ Ἀθηναῖοι ἐν τῇ Σηστῷ δυοῖν δεούσαις εἴκοσι ναυσὶν ὄντες, ὡς αὐτοῖς οἵ τε φρυκτωροὶ ἐσήμαινον καὶ ᾐσθάνοντο τὰ πυρὰ ἐξαίφνης πολλὰ ἐν τῇ πολεμίᾳ φανέντα, ἔγνωσαν ὅτι ἐσπλέουσιν οἱ Πελοποννήσιοι. καὶ τῆς αὐτῆς ταύτης νυκτὸς ὡς εἶχον τάχους ὑπομείξαντες τῇ Χερσονήσῳ παρέπλεον ἐπ’ Ἐλαιοῦντος, βουλόμενοι ἐκπλεῦσαι ἐς τὴν εὐρυχωρίαν τὰς τῶν πολεμίων ναῦς. καὶ τὰς μὲν ἐν Ἀβύδῳ ἑκκαίδεκα ναῦς ἔλαθον, προειρημένης φυλακῆς τῷ φιλίῳ ἐπίπλῳ, ὅπως αὐτῶν ἀνακῶς ἕξουσιν, ἢν ἐκπλέωσιν· τὰς δὲ μετὰ τοῦ Μινδάρου ἅμα τῇ ἕῳ κατιδόντες, τὴν δίωξιν εὐθὺς ποιουμένων οὐ φθάνουσι πάσαις, ἀλλ’ αἱ μὲν πλείους ἐπὶ τῆς Ἴμβρου καὶ Λήμνου διέφυγον, τέσσαρες δὲ τῶν νεῶν αἱ ὕσταται πλέουσαι καταλαμβάνονται παρὰ τὸν Ἐλαιοῦντα. καὶ μίαν μὲν ἐποκείλασαν κατὰ τὸ ἱερὸν τοῦ Πρωτεσιλάου αὐτοῖς ἀνδράσι λαμβάνουσι, δύο δὲ ἑτέρας ἄνευ τῶν ἀνδρῶν· τὴν δὲ μίαν πρὸς τῇ Ἴμβρῳ κενὴν κατακαίουσιν.", "st": "8.102"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο ταῖς τε ἐξ Ἀβύδου ξυμμιγείσαις καὶ ταῖς ἄλλαις ξυμπάσαις ἓξ καὶ ὀγδοήκοντα πολιορκήσαντες Ἐλαιοῦντα ταύτην τὴν ἡμέραν, ὡς οὐ προσεχώρει, ἀπέπλευσαν ἐς Ἄβυδον.", "st": "8.103"}, {"sp": "N", "t": "οἱ δ’ Ἀθηναῖοι ψευσθέντες τῶν σκοπῶν καὶ οὐκ ἂν οἰόμενοι σφᾶς λαθεῖν τὸν παράπλουν τῶν πολεμίων νεῶν, ἀλλὰ καθ’ ἡσυχίαν τειχομαχοῦντες, ὡς ᾔσθοντο, εὐθὺς ἀπολιπόντες τὴν Ἔρεσον κατὰ τάχος ἐβοήθουν ἐς τὸν Ἑλλήσποντον· καὶ δύο τε ναῦς τῶν Πελοποννησίων αἱροῦσιν, αἳ πρὸς τὸ πέλαγος τότε θρασύτερον ἐν τῇ διώξει ἀπάρασαι περιέπεσον αὐτοῖς, καὶ ἡμέρᾳ ὕστερον ἀφικόμενοι ὁρμίζονται ἐς τὸν Ἐλαιοῦντα καὶ τὰς ἐκ τῆς Ἴμβρου ὅσαι κατέφυγον κομίζονται καὶ ἐς τὴν ναυμαχίαν πέντε ἡμέρας παρεσκευάζοντο.", "st": "8.103"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο ἐναυμάχουν τρόπῳ τοιῷδε. οἱ Ἀθηναῖοι παρέπλεον ἐπὶ κέρως ταξάμενοι παρ’ αὐτὴν τὴν γῆν ἐπὶ τῆς Σηστοῦ, οἱ δὲ Πελοποννήσιοι αἰσθόμενοι ἐκ τῆς Ἀβύδου ἀντανῆγον καὶ αὐτοί. καὶ ὡς ἔγνωσαν ναυμαχήσοντες, παρέτειναν τὸ κέρας οἱ μὲν Ἀθηναῖοι παρὰ τὴν Χερσόνησον, ἀρξάμενοι ἀπὸ Ἰδάκου μέχρι Ἀρριανῶν, νῆες ἓξ καὶ ἑβδομήκοντα, οἱ δ’ αὖ Πελοποννήσιοι ἀπὸ Ἀβύδου μέχρι Δαρδάνου, νῆες ἓξ καὶ ὀγδοήκοντα. κέρας δὲ τοῖς μὲν Πελοποννησίοις εἶχον τὸ μὲν δεξιὸν Συρακόσιοι, τὸ δ’ ἕτερον αὐτὸς Μίνδαρος καὶ τῶν νεῶν αἱ ἄριστα πλέουσαι, Ἀθηναίοις δὲ τὸ μὲν ἀριστερὸν Θράσυλος, ὁ δὲ Θρασύβουλος τὸ δεξιόν· οἱ δὲ ἄλλοι στρατηγοὶ ὡς ἕκαστοι διετάξαντο. ἐπειγομένων δὲ τῶν Πελοποννησίων πρότερόν τε ξυμμεῖξαι, καὶ κατὰ μὲν τὸ δεξιὸν τῶν Ἀθηναίων ὑπερσχόντες αὐτοὶ τῷ εὐωνύμῳ ἀποκλῇσαι τοῦ ἔξω αὐτοὺς ἔκπλου, εἰ δύναιντο, κατὰ δὲ τὸ μέσον ἐξῶσαι πρὸς τὴν γῆν οὐχ ἑκὰς οὖσαν, οἱ Ἀθηναῖοι γνόντες, ᾗ μὲν ἐβούλοντο ἀποφάρξασθαι αὐτοὺς οἱ ἐναντίοι, ἀντεπεξῆγον καὶ περιεγίγνοντο τῷ πλῷ, τὸ δ’ εὐώνυμον αὐτοῖς ὑπερεβεβλήκει ἤδη τὴν ἄκραν ἣ Κυνὸς σῆμα καλεῖται. τῷ δὲ μέσῳ, τοιούτου ξυμβαίνοντος, ἀσθενέσι καὶ διεσπασμέναις ταῖς ναυσὶ καθίσταντο, ἄλλως τε καὶ ἐλάσσοσι χρώμενοι τὸ πλῆθος καὶ τοῦ χωρίου τοῦ περὶ τὸ Κυνὸς σῆμα ὀξεῖαν καὶ γωνιώδη τὴν περιβολὴν ἔχοντος, ὥστε τὰ ἐν τῷ ἐπέκεινα αὐτοῦ γιγνόμενα μὴ κάτοπτα εἶναι.", "st": "8.104"}, {"sp": "N", "t": "προσπεσόντες οὖν οἱ Πελοποννήσιοι κατὰ τὸ μέσον ἐξέωσάν τε ἐς τὸ ξηρὸν τὰς ναῦς τῶν Ἀθηναίων καὶ ἐς τὴν γῆν ἐπεξέβησαν, τῷ ἔργῳ πολὺ περισχόντες. ἀμῦναι δὲ τῷ μέσῳ οὔθ’ οἱ περὶ τὸν Θρασύβουλον ἀπὸ τοῦ δεξιοῦ ὑπὸ πλήθους τῶν ἐπικειμένων νεῶν ἐδύναντο οὔθ’ οἱ περὶ τὸν Θράσυλον ἀπὸ τοῦ εὐωνύμου (ἀφανές τε γὰρ ἦν διὰ τὴν ἄκραν τὸ Κυνὸς σῆμα, καὶ ἅμα οἱ Συρακόσιοι καὶ οἱ ἄλλοι οὐκ ἐλάσσους ἐπιτεταγμένοι εἶργον αὐτούς), πρὶν οἱ Πελοποννήσιοι διὰ τὸ κρατήσαντες ἀδεῶς ἄλλοι ἄλλην ναῦν διώκειν ἤρξαντο μέρει τινὶ σφῶν ἀτακτότεροι γενέσθαι. γνόντες δὲ οἱ περὶ τὸν Θρασύβουλον τὰς ἐπὶ σφίσι ναῦς ἐπεχούσας παυσάμενοι τῆς ἐπεξαγωγῆς ἤδη τοῦ κέρως καὶ ἐπαναστρέψαντες εὐθὺς ἠμύναντό τε καὶ τρέπουσι, καὶ τὰς κατὰ τὸ νικῆσαν τῶν Πελοποννησίων μέρος ὑπολαβόντες πεπλανημένας ἔκοπτόν τε καὶ ἐς φόβον τὰς πλείους ἀμαχεὶ καθίστασαν. οἵ τε Συρακόσιοι ἐτύγχανον καὶ αὐτοὶ ἤδη τοῖς περὶ τὸν Θράσυλον ἐνδεδωκότες καὶ μᾶλλον ἐς φυγὴν ὁρμήσαντες, ἐπειδὴ καὶ τοὺς ἄλλους ἑώρων.", "st": "8.105"}, {"sp": "N", "t": "γεγενημένης δὲ τῆς τροπῆς καὶ καταφυγόντων τῶν Πελοποννησίων πρὸς τὸν Μείδιον μάλιστα ποταμὸν τὸ πρῶτον, ὕστερον δὲ ἐς Ἄβυδον, ναῦς μὲν ὀλίγας ἔλαβον οἱ Ἀθηναῖοι (στενὸς γὰρ ὢν ὁ Ἑλλήσποντος βραχείας τὰς ἀποφυγὰς τοῖς ἐναντίοις παρεῖχε), τὴν μέντοι νίκην ταύτην τῆς ναυμαχίας ἐπικαιροτάτην δὴ ἔσχον. φοβούμενοι γὰρ τέως τὸ τῶν Πελοποννησίων ναυτικὸν διά τε τὰ κατὰ βραχὺ σφάλματα καὶ διὰ τὴν ἐν τῇ Σικελίᾳ ξυμφοράν, ἀπηλλάγησαν τοῦ σφᾶς τε αὐτοὺς καταμέμφεσθαι καὶ τοὺς πολεμίους ἔτι ἀξίους του ἐς τὰ ναυτικὰ νομίζειν. ναῦς μέντοι τῶν ἐναντίων λαμβάνουσι Χίας μὲν ὀκτώ, Κορινθίας δὲ πέντε, Ἀμπρακιώτιδας δὲ δύο καὶ Βοιωτίας δύο, Λευκαδίων δὲ καὶ Λακεδαιμονίων καὶ Συρακοσίων καὶ Πελληνέων μίαν ἑκάστων· αὐτοὶ δὲ πέντε καὶ δέκα ναῦς ἀπολλύασιν. στήσαντες δὲ τροπαῖον ἐπὶ τῇ ἄκρᾳ οὗ τὸ Κυνὸς σῆμα καὶ τὰ ναυάγια προσαγαγόμενοι καὶ νεκροὺς τοῖς ἐναντίοις ὑποσπόνδους ἀποδόντες ἀπέστειλαν καὶ ἐς τὰς Ἀθήνας τριήρη ἄγγελον τῆς νίκης. οἱ δὲ ἀφικομένης τῆς νεὼς καὶ ἀνέλπιστον τὴν εὐτυχίαν ἀκούσαντες ἐπί τε ταῖς περὶ τὴν Εὔβοιαν ἄρτι ξυμφοραῖς καὶ κατὰ τὴν στάσιν γεγενημέναις πολὺ ἐπερρώσθησαν καὶ ἐνόμισαν σφίσιν ἔτι δυνατὰ εἶναι τὰ πράγματα, ἢν προθύμως ἀντιλαμβάνωνται, περιγενέσθαι.", "st": "8.106"}, {"sp": "N", "t": "μετὰ δὲ τὴν ναυμαχίαν ἡμέρᾳ τετάρτῃ ὑπὸ σπουδῆς ἐπισκευάσαντες τὰς ναῦς οἱ ἐν τῇ Σηστῷ Ἀθηναῖοι ἔπλεον ἐπὶ Κύζικον ἀφεστηκυῖαν· καὶ κατιδόντες κατὰ Ἁρπάγιον καὶ Πρίαπον τὰς ἀπὸ τοῦ Βυζαντίου ὀκτὼ ναῦς ὁρμούσας, ἐπιπλεύσαντες καὶ μάχῃ κρατήσαντες τοὺς ἐν τῇ γῇ ἔλαβον τὰς ναῦς. ἀφικόμενοι δὲ καὶ ἐπὶ τὴν Κύζικον ἀτείχιστον οὖσαν προσηγάγοντο πάλιν καὶ χρήματα ἀνέπραξαν. ἔπλευσαν δὲ ἐν τούτῳ καὶ οἱ Πελοποννήσιοι ἐκ τῆς Ἀβύδου ἐπὶ τὸν Ἐλαιοῦντα καὶ τῶν σφετέρων νεῶν τῶν αἰχμαλώτων ὅσαι ἦσαν ὑγιεῖς ἐκομίσαντο (τὰς δὲ ἄλλας Ἐλαιούσιοι κατέκαυσαν), καὶ ἐς τὴν Εὔβοιαν ἀπέπεμψαν Ἱπποκράτη καὶ Ἐπικλέα κομιοῦντας τὰς ἐκεῖθεν ναῦς.", "st": "8.107"}, {"sp": "N", "t": "κατέπλευσε δὲ ὑπὸ τοὺς αὐτοὺς χρόνους τούτους καὶ ὁ Ἀλκιβιάδης ταῖς τρισὶ καὶ δέκα ναυσὶν ἀπὸ τῆς Καύνου καὶ Φασήλιδος ἐς τὴν Σάμον, ἀγγέλλων ὅτι τάς τε Φοινίσσας ναῦς ἀποστρέψειε Πελοποννησίοις ὥστε μὴ ἐλθεῖν καὶ τὸν Τισσαφέρνην ὅτι φίλον πεποιήκοι μᾶλλον Ἀθηναίοις ἢ πρότερον. καὶ πληρώσας ναῦς ἐννέα πρὸς αἷς εἶχεν Ἁλικαρνασσέας τε πολλὰ χρήματα ἐξέπραξε καὶ Κῶν ἐτείχισεν. ταῦτα δὲ πράξας καὶ ἄρχοντα ἐν τῇ Κῷ καταστήσας πρὸς τὸ μετόπωρον ἤδη ἐς τὴν Σάμον κατέπλευσεν.", "st": "8.108"}, {"sp": "N", "t": "καὶ ὁ Τισσαφέρνης ἀπὸ τῆς Ἀσπένδου, ὡς ἐπύθετο τὰς τῶν Πελοποννησίων ναῦς ἐκ τῆς Μιλήτου ἐς τὸν Ἑλλήσποντον πεπλευκυίας, ἀναζεύξας ἤλαυνεν ἐπὶ τῆς Ἰωνίας. ὄντων δὲ τῶν Πελοποννησίων ἐν τῷ Ἑλλησπόντῳ, Ἀντάνδριοι (εἰσὶ δὲ Αἰολῆς) παρακομισάμενοι ἐκ τῆς Ἀβύδου πεζῇ διὰ τῆς Ἴδης τοῦ ὄρους ὁπλίτας ἐσηγάγοντο ἐς τὴν πόλιν, ὑπὸ Ἀρσάκου τοῦ Πέρσου Τισσαφέρνους ὑπάρχου ἀδικούμενοι, ὅσπερ καὶ Δηλίους τοὺς Ἀτραμύττιον κατοικήσαντας ὅτε ὑπ’ Ἀθηναίων Δήλου καθάρσεως ἕνεκα ἀνέστησαν, ἔχθραν προσποιησάμενος ἄδηλον καὶ ἐπαγγείλας στρατιὰν αὐτῶν τοῖς βελτίστοις, ἐξαγαγὼν ὡς ἐπὶ φιλίᾳ καὶ ξυμμαχίᾳ, τηρήσας ἀριστοποιουμένους καὶ περιστήσας τοὺς ἑαυτοῦ κατηκόντισεν. φοβούμενοι οὖν αὐτὸν διὰ τοῦτο τὸ ἔργον μήποτε καὶ περὶ σφᾶς τι παρανομήσῃ, καὶ ἄλλα ἐπιβάλλοντος αὐτοῦ ἃ φέρειν οὐκ ἐδύναντο, ἐκβάλλουσι τοὺς φρουροὺς αὐτοῦ ἐκ τῆς ἀκροπόλεως.", "st": "8.108"}, {"sp": "N", "t": "ὁ δὲ Τισσαφέρνης αἰσθόμενος καὶ τοῦτο τῶν Πελοποννησίων τὸ ἔργον καὶ οὐ μόνον τὸ ἐν τῇ Μιλήτῳ καὶ Κνίδῳ (καὶ ἐνταῦθα γὰρ αὐτοῦ ἐξεπεπτώκεσαν οἱ φρουροί), διαβεβλῆσθαί τε νομίσας αὐτοῖς σφόδρα καὶ δείσας μὴ καὶ ἄλλο τι ἔτι βλάπτωσι, καὶ ἅμα ἀχθόμενος εἰ Φαρνάβαζος ἐξ ἐλάσσονος χρόνου καὶ δαπάνης δεξάμενος αὐτοὺς κατορθώσει τι μᾶλλον τῶν πρὸς τοὺς Ἀθηναίους, πορεύεσθαι διενοεῖτο πρὸς αὐτοὺς ἐπὶ τοῦ Ἑλλησπόντου, ὅπως μέμψηταί τε τῶν περὶ τὴν Ἄντανδρον γεγενημένων καὶ τὰς διαβολὰς καὶ περὶ τῶν Φοινισσῶν νεῶν καὶ τῶν ἄλλων ὡς εὐπρεπέστατα ἀπολογήσηται. καὶ ἀφικόμενος πρῶτον ἐς Ἔφεσον θυσίαν ἐποιήσατο τῇ Ἀρτέμιδι. [ὅταν ὁ μετὰ τοῦτο τὸ θέρος χειμὼν τελευτήσῃ, ἓν καὶ εἰκοστὸν ἔτος πληροῦται.]", "st": "8.109"}], []);})();
